<?php

namespace Plugins\Logistik_non_medis;

use Systems\AdminModule;
use Mpdf\HTMLParserMode;

class Admin extends AdminModule
{
    private function _demoModeEnabled(): bool
    {
        return defined('LOGISTIK_NON_MEDIS_DEMO_MODE') && LOGISTIK_NON_MEDIS_DEMO_MODE === true;
    }

    private function _demoPrefix(): string
    {
        return 'DEMO-OPERASIONAL-%';
    }

    private function _useFullProcurementFlow(): bool
    {
        return defined('LOGISTIK_NON_MEDIS_PROCUREMENT_FLOW')
          && strtolower((string)LOGISTIK_NON_MEDIS_PROCUREMENT_FLOW) === 'full';
    }

    private function _getMingguKe(string $tanggal): array
    {
        $timestamp = strtotime($tanggal);
        $dayOfWeek = (int)date('N', $timestamp);
        $startDate = date('Y-m-d', strtotime('-' . ($dayOfWeek - 1) . ' days', $timestamp));
        $endDate = date('Y-m-d', strtotime('+6 days', strtotime($startDate)));

        return [
          'minggu_ke' => (int)date('W', $timestamp),
          'start_date' => $startDate,
          'end_date' => $endDate
        ];
    }

    public function init()
    {
        $this->_initUserRoles();
        $this->_initWaNotificationContacts();
        $this->_initFonnteConfig();
        $this->_initWahaConfig();
        $this->_checkAccessControl();
    }

    private function _initWahaConfig()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_waha_config` (
        `id` tinyint(1) NOT NULL,
        `aktif` tinyint(1) NOT NULL DEFAULT 0,
        `base_url` varchar(255) NOT NULL DEFAULT 'http://127.0.0.1:3000',
        `api_key` varchar(255) DEFAULT NULL,
        `session_name` varchar(100) NOT NULL DEFAULT 'default',
        `delay` tinyint(2) NOT NULL DEFAULT 1,
        `tgl_diperbarui` datetime NOT NULL,
        PRIMARY KEY (`id`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");
        $exists = $this->db('rsns_custom_logistik_non_medis_waha_config')->where('id', 1)->oneArray();
        if (!$exists) {
            $this->db('rsns_custom_logistik_non_medis_waha_config')->save([
              'id' => 1,
              'aktif' => 0,
              'base_url' => 'http://127.0.0.1:3000',
              'api_key' => '',
              'session_name' => 'default',
              'delay' => 1,
              'tgl_diperbarui' => date('Y-m-d H:i:s')
            ]);
        }
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_waha_template` (
        `tipe` varchar(50) NOT NULL,
        `aktif` tinyint(1) NOT NULL DEFAULT 1,
        `pesan` text NOT NULL,
        `tgl_diperbarui` datetime NOT NULL,
        PRIMARY KEY (`tipe`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_waha_send_log` (
        `id` bigint NOT NULL AUTO_INCREMENT,
        `username` varchar(100) NOT NULL,
        `tipe` varchar(50) NOT NULL,
        `no_sppb` varchar(100) DEFAULT NULL,
        `tgl_kirim` datetime NOT NULL,
        `status` varchar(30) NOT NULL DEFAULT 'success',
        `keterangan` text DEFAULT NULL,
        PRIMARY KEY (`id`), KEY `dedupe` (`username`,`tipe`,`no_sppb`,`tgl_kirim`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");
        
        // Task 3.1: Populate default templates if table is empty
        $count = $this->db('rsns_custom_logistik_non_medis_waha_template')->count();
        if ($count == 0) {
            $defaults = $this->_wahaTemplateDefaults();
            $now = date('Y-m-d H:i:s');
            foreach ($defaults as $tipe => $data) {
                $this->db('rsns_custom_logistik_non_medis_waha_template')->save([
                    'tipe' => $tipe,
                    'aktif' => 1,
                    'pesan' => $data['pesan'],
                    'tgl_diperbarui' => $now
                ]);
            }
        }
    }

    private function _initFonnteConfig()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_fonnte_config` (
        `id` tinyint(1) NOT NULL,
        `aktif` tinyint(1) NOT NULL DEFAULT 0,
        `token` varchar(255) DEFAULT NULL,
        `duration` tinyint(2) NOT NULL DEFAULT 1,
        `delay` tinyint(2) NOT NULL DEFAULT 0,
        `tgl_diperbarui` datetime NOT NULL,
        PRIMARY KEY (`id`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");
        $existingColumns = $this->db()->pdo()->query("SHOW COLUMNS FROM rsns_custom_logistik_non_medis_fonnte_config")->fetchAll(\PDO::FETCH_COLUMN);
        foreach (['duration' => 'tinyint(2) NOT NULL DEFAULT 1', 'delay' => 'tinyint(2) NOT NULL DEFAULT 0'] as $column => $definition) {
            if (!in_array($column, $existingColumns, true)) {
                $this->db()->pdo()->exec("ALTER TABLE rsns_custom_logistik_non_medis_fonnte_config ADD COLUMN `$column` $definition");
            }
        }
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_fonnte_template` (
        `tipe` varchar(50) NOT NULL,
        `aktif` tinyint(1) NOT NULL DEFAULT 1,
        `pesan` text NOT NULL,
        `tgl_diperbarui` datetime NOT NULL,
        PRIMARY KEY (`tipe`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_fonnte_send_log` (
        `id` bigint NOT NULL AUTO_INCREMENT,
        `username` varchar(100) NOT NULL,
        `tipe` varchar(50) NOT NULL,
        `no_sppb` varchar(100) DEFAULT NULL,
        `nomor` varchar(30) NOT NULL,
        `tgl_kirim` datetime NOT NULL,
        PRIMARY KEY (`id`), KEY `dedupe` (`username`,`tipe`,`no_sppb`,`tgl_kirim`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");
        foreach ($this->_fonnteTemplateDefaults() as $tipe => $template) {
            if (!$this->db('rsns_custom_logistik_non_medis_fonnte_template')->where('tipe', $tipe)->oneArray()) {
                $this->db('rsns_custom_logistik_non_medis_fonnte_template')->save(['tipe' => $tipe, 'aktif' => 1, 'pesan' => $template['pesan'], 'tgl_diperbarui' => date('Y-m-d H:i:s')]);
            }
        }
        $exists = $this->db('rsns_custom_logistik_non_medis_fonnte_config')->where('id', 1)->oneArray();
        if (!$exists) {
            $legacyToken = trim((string)$this->settings->get('logistik_non_medis', 'fonnte_token'));
            $legacyActive = (string)$this->settings->get('logistik_non_medis', 'fonnte_aktif') === '1';
            if ($legacyToken !== '' || $legacyActive) {
                $this->db('rsns_custom_logistik_non_medis_fonnte_config')->save(['id' => 1, 'aktif' => $legacyActive ? 1 : 0, 'token' => $legacyToken, 'tgl_diperbarui' => date('Y-m-d H:i:s')]);
            }
        }
    }


