    private function _initUserRoles()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_user_roles` (
        `id` int(11) NOT NULL AUTO_INCREMENT,
        `username` varchar(100) NOT NULL,
        `role` varchar(50) NOT NULL,
        `kode_unit` varchar(50) DEFAULT NULL,
        PRIMARY KEY (`id`),
        UNIQUE KEY `username` (`username`)
      ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");

        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_role_permissions` (
        `role` varchar(50) NOT NULL,
        `permissions` text DEFAULT NULL,
        PRIMARY KEY (`role`)
      ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");

        // Check if roles exist
        $check = $this->db('rsns_custom_logistik_non_medis_role_permissions')->count();
        if ($check == 0) {
            $default_roles = [
              'admin' => 'manage,masterbarang,mastervendor,masterunit,masterlokasi,mastersatuan,masterkategori,masterrekanan,mastercoa,pengadaanperencanaan,pengadaanpr,pengadaanvendor,pengadaanpo,pengadaanekatalog,pengadaanpenerimaan,pengadaankontrak,gudangmanage,gudangpenerimaan,gudanglokasi,gudangstok,gudangopname,gudangopnamev2,gudangmetode,gudangrusak,gudangmutasi,distribusisppb,distribusiverifikasi,distribusipacking,distribusiserahterima,distribusitracking,distribusiretur,distribusikuota,asetregistrasi,asetkib,asetpenyusutan,asetpemeliharaan,asetmutasi,asetpenghapusan,asetsensus,laporanstokmutasi,laporanpengadaan,laporandistribusi,laporanaset,laporandashboardkpi,laporaneksporcetak,hakakses',
              'logistik' => 'manage,masterbarang,mastervendor,masterunit,masterlokasi,mastersatuan,masterkategori,masterrekanan,mastercoa,pengadaanperencanaan,pengadaanpr,pengadaanvendor,pengadaanpo,pengadaanekatalog,pengadaanpenerimaan,pengadaankontrak,gudangmanage,gudangpenerimaan,gudanglokasi,gudangstok,gudangopname,gudangopnamev2,gudangmetode,gudangrusak,gudangmutasi,distribusisppb,distribusiverifikasi,distribusipacking,distribusiserahterima,distribusitracking,distribusiretur,distribusikuota,asetregistrasi,asetkib,asetpenyusutan,asetpemeliharaan,asetmutasi,asetpenghapusan,asetsensus,laporanstokmutasi,laporanpengadaan,laporandistribusi,laporanaset,laporandashboardkpi,laporaneksporcetak',
              'gudang' => 'manage,gudangmanage,gudangpenerimaan,gudanglokasi,gudangstok,gudangopname,gudangopnamev2,gudangmetode,gudangrusak,gudangmutasi,distribusisppb,distribusiverifikasi,distribusipacking,distribusiserahterima,distribusitracking,distribusiretur',
              'aset' => 'manage,asetregistrasi,asetkib,asetpenyusutan,asetpemeliharaan,asetmutasi,asetpenghapusan,asetsensus',
              'unit' => 'manage,distribusisppb,distribusiretur,distribusikuota'
            ];
            foreach ($default_roles as $role => $permissions) {
                $this->db('rsns_custom_logistik_non_medis_role_permissions')->save(['role' => $role, 'permissions' => $permissions]);
            }
        }

        $roles_to_check = [
          'kepala_unit' => 'manage,distribusisppb,distribusiverifikasi,distribusikuota',
          'kepala_sie' => 'manage,distribusisppb,distribusiverifikasi,distribusikuota',
          'kepala_bidang' => 'manage,distribusisppb,distribusiverifikasi,distribusikuota'
        ];
        foreach ($roles_to_check as $r => $perms) {
            $exists = $this->db('rsns_custom_logistik_non_medis_role_permissions')->where('role', $r)->oneArray();
            if (!$exists) {
                $this->db('rsns_custom_logistik_non_medis_role_permissions')->save(['role' => $r, 'permissions' => $perms]);
            }
        }

        // Database lama tetap dipakai. Tambahkan izin menu hakakses ke admin
        $adminPermissions = $this->db('rsns_custom_logistik_non_medis_role_permissions')->where('role', 'admin')->oneArray();
        if ($adminPermissions && strpos(',' . ($adminPermissions['permissions'] ?? '') . ',', ',hakakses,') === false) {
            $permissions = $adminPermissions['permissions'] ?? '';
            $permissions = $permissions === '' ? 'hakakses' : $permissions . ',hakakses';
            $this->db('rsns_custom_logistik_non_medis_role_permissions')->where('role', 'admin')->save(['permissions' => $permissions]);
        }

        // Dashboard modul harus selalu menjadi pintu masuk utama, termasuk untuk data role lama.
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = CONCAT('manage,', permissions) WHERE permissions IS NOT NULL AND permissions <> '' AND CONCAT(',', permissions, ',') NOT LIKE '%,manage,%'");
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = 'manage' WHERE permissions IS NULL OR permissions = ''");

        // Otomatis tambahkan izin distribusinonrutin ke role yang sudah memiliki distribusisppb
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = CONCAT(permissions, ',distribusinonrutin') WHERE permissions LIKE '%distribusisppb%' AND permissions NOT LIKE '%distribusinonrutin%'");
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = CONCAT(permissions, ',distribusimendesak') WHERE role IN ('admin','logistik','gudang') AND permissions NOT LIKE '%distribusimendesak%'");

        // Otomatis tambahkan izin rencanabelanja & realisasibelanja ke admin dan logistik
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = CONCAT(permissions, ',rencanabelanja') WHERE role IN ('admin','logistik') AND permissions NOT LIKE '%rencanabelanja%'");
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = CONCAT(permissions, ',realisasibelanja') WHERE role IN ('admin','logistik') AND permissions NOT LIKE '%realisasibelanja%'");

        // Master inventaris berdiri sendiri dari master logistik umum.
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = CONCAT(permissions, ',masterinventaris') WHERE role IN ('admin','logistik','aset') AND permissions NOT LIKE '%masterinventaris%'");
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = CONCAT(permissions, ',konfigurasifonnte') WHERE role IN ('admin','logistik') AND permissions NOT LIKE '%konfigurasifonnte%'");
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = CONCAT(permissions, ',konfigurasiwaha') WHERE role IN ('admin','logistik') AND permissions NOT LIKE '%konfigurasiwaha%'");

        // Rekap cetak permintaan Non Rutin hanya untuk Kabid Umum, Logistik, dan Admin.
        $this->db()->pdo()->exec("UPDATE rsns_custom_logistik_non_medis_role_permissions SET permissions = CONCAT(permissions, ',rekapnonrutin') WHERE role IN ('admin','logistik','kepala_bidang') AND CONCAT(',', permissions, ',') NOT LIKE '%,rekapnonrutin,%'");

        // Check current user role assignment
        $username = $this->core->getUserInfo('username', null, true);
        if ($username) {
            $exists = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
            if (!$exists) {
                // If current user is an admin in mlite, assign them as admin in logistik
                $mlite_role = $this->core->getUserInfo('role', null, true);
                $role = ($mlite_role == 'admin') ? 'admin' : 'unit';
                $this->db('rsns_custom_logistik_non_medis_user_roles')->save([
                  'username' => $username,
                  'role' => $role,
                  'kode_unit' => null
                ]);
            }
        }
    }

    private function _checkAccessControl()
    {
        if (parseURL(1) === 'logistik_non_medis') {
            $method = parseURL(2);
            if (empty($method)) {
                $method = 'manage';
            }

            if (in_array($method, ['css', 'javascript'])) {
                return;
            }

            $username = $this->core->getUserInfo('username', null, true);
            if (!$username) {
                return;
            }

            $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
            $role = $userRoleData['role'] ?? 'unit';

            $permsData = $this->db('rsns_custom_logistik_non_medis_role_permissions')->where('role', $role)->oneArray();
            $permissions = explode(',', $permsData['permissions'] ?? 'manage');

            $permKey = $this->_getPermissionKeyForMethod($method);

            $hasAccess = false;
            if (empty($permKey)) {
                $hasAccess = true;
            } elseif (is_array($permKey)) {
                foreach ($permKey as $pk) {
                    if (in_array($pk, $permissions)) {
                        $hasAccess = true;
                        break;
                    }
                }
            } else {
                $hasAccess = in_array($permKey, $permissions);
            }

            if ($permKey === 'rekapnonrutin' && !$this->_canAccessRekapNonRutin()) {
                $hasAccess = false;
            }

            if (!$hasAccess) {
                if (!empty($_SERVER['HTTP_X_REQUESTED_WITH']) && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) == 'xmlhttprequest') {
                    header('Content-Type: application/json');
                    echo json_encode(['status' => 'error', 'message' => 'Anda tidak memiliki hak akses untuk tindakan ini!']);
                    exit();
                } else {
                    $this->core->setNotify('failure', 'Akses Ditolak: Anda tidak memiliki hak akses ke menu tersebut.');
                    redirect(url([ADMIN, 'logistik_non_medis', 'manage']));
                }
            }
        }
    }

    private function _getPermissionKeyForMethod(string $method)
    {
        $method = strtolower($method);
        if (strpos($method, 'ajaxmasterbarang') !== false || strpos($method, 'ajaxbarangselect2') !== false) {
            return null; // Semua role butuh akses pencarian barang
        }
        if (strpos($method, 'masterinventaris') !== false) {
            return 'masterinventaris';
        }
        if (strpos($method, 'masterbarang') !== false) {
            return 'masterbarang';
        }
        if (strpos($method, 'mastervendor') !== false) {
            return 'mastervendor';
        }
        if (strpos($method, 'masterunit') !== false) {
            return 'masterunit';
        }
        if (strpos($method, 'masterlokasi') !== false) {
            return 'masterlokasi';
        }
        if (strpos($method, 'mastersatuan') !== false) {
            return 'mastersatuan';
        }
        if (strpos($method, 'masterkategori') !== false) {
            return 'masterkategori';
        }
        if (strpos($method, 'masterrekanan') !== false) {
            return 'masterrekanan';
        }
        if (strpos($method, 'mastercoa') !== false) {
            return 'mastercoa';
        }
        if (strpos($method, 'perencanaan') !== false || strpos($method, 'rencanapembelian') !== false) {
            return 'pengadaanperencanaan';
        }
        if ($method === 'pr' || strpos($method, 'ajaxpr') !== false || strpos($method, 'pengadaanpr') !== false) {
            return 'pengadaanpr';
        }
        if (strpos($method, 'manajemenvendor') !== false) {
            return 'pengadaanvendor';
        }
        if ($method === 'po' || strpos($method, 'ajaxpo') !== false || strpos($method, 'pengadaanpo') !== false) {
            return 'pengadaanpo';
        }
        if (strpos($method, 'ekatalog') !== false) {
            return 'pengadaanekatalog';
        }
        if (strpos($method, 'pengadaanpenerimaan') !== false || strpos($method, 'printpenerimaan') !== false || strpos($method, 'printlabel') !== false) {
            return 'pengadaanpenerimaan';
        }
        if (strpos($method, 'pengadaankontrak') !== false) {
            return 'pengadaankontrak';
        }
        if (strpos($method, 'gudangmanage') !== false) {
            return 'gudangmanage';
        }
        if (strpos($method, 'gudangpenerimaan') !== false) {
            return 'gudangpenerimaan';
        }
        if (strpos($method, 'gudanglokasi') !== false || strpos($method, 'relokasi') !== false) {
            return 'gudanglokasi';
        }
        if (strpos($method, 'gudangstok') !== false) {
            return 'gudangstok';
        }
        if (strpos($method, 'gudangmutasi') !== false || strpos($method, 'printmutasi') !== false || strpos($method, 'importmutasicsv') !== false || strpos($method, 'exportmutasicsv') !== false || strpos($method, 'downloadtemplatemutasicsv') !== false) {
            return 'gudangmutasi';
        }
        if (strpos($method, 'gudangopnamev2') !== false || strpos($method, 'opnamev2') !== false) {
            return 'gudangopnamev2';
        }
        if (strpos($method, 'gudangopname') !== false || strpos($method, 'printopname') !== false || strpos($method, 'printrekapopname') !== false) {
            return 'gudangopname';
        }
        if (strpos($method, 'gudangmetode') !== false) {
            return 'gudangmetode';
        }
        if (strpos($method, 'gudangrusak') !== false || strpos($method, 'printbap') !== false || strpos($method, 'suratretur') !== false) {
            return 'gudangrusak';
        }
        if (strpos($method, 'permintaannonrutin') !== false || strpos($method, 'pemenuhannonrutin') !== false || strpos($method, 'generateordernonrutin') !== false) {
            return ['distribusinonrutin', 'pengadaanpr'];
        }
        if (strpos($method, 'sppb') !== false || strpos($method, 'distribusibhp') !== false) {
