    public function navigation()
    {
        $username = $this->core->getUserInfo('username', null, true);
        $role = 'unit';
        if ($username) {
            $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
            if ($userRoleData) {
                $role = $userRoleData['role'];
            } else {
                $role = 'unit';
            }
        }

        $permsData = $this->db('rsns_custom_logistik_non_medis_role_permissions')->where('role', $role)->oneArray();
        $permissions = explode(',', $permsData['permissions'] ?? 'manage');
        if (!$this->_canAccessRekapNonRutin()) {
            $permissions = array_values(array_diff($permissions, ['rekapnonrutin']));
        }

        $menus = [
        'Dashboard'           => 'manage',
        'Master Inventaris'   => 'masterinventaris',
        'Data Barang'         => 'masterbarang',
        'Data Vendor'         => 'mastervendor',
        'Data Unit'           => 'masterunit',
        'Lokasi Gudang'       => 'masterlokasi',
        'Satuan Barang'       => 'mastersatuan',
        'Kategori & Klasifikasi' => 'masterkategori',
        'Data Rekanan Jasa'   => 'masterrekanan',
        'Kode Akun (COA)'     => 'mastercoa',
        'Konfigurasi Fonnte'  => 'konfigurasifonnte',
        'Konfigurasi WAHA'    => 'konfigurasiwaha',
        'Pengadaan Rutin'     => 'pengadaanperencanaan',
        'Pengadaan Non Rutin' => 'permintaannonrutin',
        'Rencana & Realisasi Anggaran' => 'realisasibelanja',
        'Manajemen Vendor'    => 'pengadaanvendor',
        'Purchase Order (PO)' => 'pengadaanpo',
        'E-Katalog'           => 'pengadaanekatalog',
        'Penerimaan'          => 'pengadaanpenerimaan',
        'Manajemen Kontrak'   => 'pengadaankontrak',
        '--- GUDANG ---'      => 'gudangmanage',
        'Barang Masuk'        => 'gudangpenerimaan',
        'Manajemen Lokasi'    => 'gudanglokasi',
        'Pengelolaan Stok'    => 'gudangstok',
        'Stock Opname'        => 'gudangopname',
        'Stok Opname V2'      => 'gudangopnamev2',
        'Metode FIFO / FEFO'  => 'gudangmetode',
        'Barang Rusak'        => 'gudangrusak',
        'Mutasi Antar Gudang' => 'gudangmutasi',
        '--- DISTRIBUSI ---'  => '#',
        'Permintaan Barang (SPPB)' => 'distribusisppb',
        'Distribusi Non Rutin' => 'distribusinonrutin',
        'Permintaan Langsung' => 'distribusimendesak',
        'Verifikasi & Approval' => 'distribusiverifikasi',
        'Picking & Packing'   => 'distribusipacking',
        'Serah Terima Barang' => 'distribusiserahterima',
        'Tracking Pengiriman' => 'distribusitracking',
        'Retur Barang dari Unit' => 'distribusiretur',
        'Kuota & Alokasi Unit' => 'distribusikuota',
        '--- ASET ---'        => '#',
        'Registrasi Aset'     => 'asetregistrasi',
        'Kartu Inventaris (KIB)' => 'asetkib',
        'Penyusutan Aset'     => 'asetpenyusutan',
        'Pemeliharaan Aset'   => 'asetpemeliharaan',
        'Mutasi Aset'         => 'asetmutasi',
        'Penghapusan Aset'    => 'asetpenghapusan',
        'Sensus & Verifikasi Aset' => 'asetsensus',
        '--- LAPORAN & AUDIT ---' => '#',
        'Laporan Stok & Mutasi' => 'laporanstokmutasi',
        'Laporan Pengadaan'    => 'laporanpengadaan',
        'Rekap Cetak Non Rutin' => 'rekapnonrutin',
        'Laporan Distribusi'  => 'laporandistribusi',
        'Laporan Aset'        => 'laporanaset',
        'Laporan Inventaris'  => 'laporaninventaris',
        'Dashboard & KPI'     => 'laporandashboardkpi',
        'Ekspor & Cetak Laporan' => 'laporaneksporcetak',
        ];

        if (in_array('hakakses', $permissions)) {
            $menus['Hak Akses'] = 'hakakses';
        }

        $filtered = [];
        foreach ($menus as $title => $slug) {
            if (strpos($title, '---') === 0) {
                $filtered[$title] = $slug;
                continue;
            }

            if ($slug === 'manage' || in_array($slug, $permissions)) {
                $filtered[$title] = $slug;
            }
        }

        $cleanNav = [];
        $lastHeader = null;
        foreach ($filtered as $title => $slug) {
            if (strpos($title, '---') === 0) {
                $lastHeader = $title;
            } else {
                if ($lastHeader !== null) {
                    $cleanNav[$lastHeader] = $filtered[$lastHeader];
                    $lastHeader = null;
                }
                $cleanNav[$title] = $slug;
            }
        }

        return $cleanNav;
    }

    public function getKonfigurasifonnte()
    {
        $this->_initFonnteConfig();
        $config = $this->db('rsns_custom_logistik_non_medis_fonnte_config')->where('id', 1)->oneArray() ?: [];
        $token = (string)($config['token'] ?? '');
        $duration = max(0, min(10, (int)($config['duration'] ?? 1)));
        $delay = max(0, min(10, (int)($config['delay'] ?? 0)));
        $templateRows = $this->db('rsns_custom_logistik_non_medis_fonnte_template')->toArray();
        $templateMap = [];
        foreach ($templateRows as $row) {
            $templateMap[$row['tipe']] = $row;
        }
        $templates = [];
        foreach ($this->_fonnteTemplateDefaults() as $tipe => $default) {
            $row = $templateMap[$tipe] ?? [];
            $templates[] = ['tipe' => $tipe, 'label' => $default['label'], 'aktif' => !empty($row['aktif']), 'pesan' => (string)($row['pesan'] ?? $default['pesan'])];
        }
        return $this->draw('konfigurasi.fonnte.html', [
          'aktif' => !empty($config['aktif']),
          'token_tersimpan' => $token !== '',
          'token_akhir' => $token !== '' ? substr($token, -4) : '',
          'token_placeholder' => $token !== '' ? 'Token sudah tersimpan - isi hanya untuk mengganti' : 'Masukkan token dari dashboard Fonnte',
          'duration' => $duration,
          'delay' => $delay,
          'templates' => $templates
        ]);
    }

    public function postSaveKonfigurasiFonnte()
    {
        $this->_initFonnteConfig();
        $existing = $this->db('rsns_custom_logistik_non_medis_fonnte_config')->where('id', 1)->oneArray() ?: [];
        $token = trim((string)($_POST['fonnte_token'] ?? ''));
        if ($token === '') {
            $token = (string)($existing['token'] ?? '');
        }
        $duration = max(0, min(10, (int)($_POST['fonnte_duration'] ?? ($existing['duration'] ?? 1))));
        $delay = max(0, min(10, (int)($_POST['fonnte_delay'] ?? ($existing['delay'] ?? 0))));
        $data = ['id' => 1, 'aktif' => isset($_POST['fonnte_aktif']) ? 1 : 0, 'token' => $token, 'duration' => $duration, 'delay' => $delay, 'tgl_diperbarui' => date('Y-m-d H:i:s')];
        if ($existing) {
            $this->db('rsns_custom_logistik_non_medis_fonnte_config')->where('id', 1)->save($data);
        } else {
            $this->db('rsns_custom_logistik_non_medis_fonnte_config')->save($data);
        }
        $this->notify('success', 'Konfigurasi Fonnte telah disimpan');
        redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasifonnte']));
    }

    public function postTestFonnte()
    {
        $this->_initFonnteConfig();
        $config = $this->db('rsns_custom_logistik_non_medis_fonnte_config')->where('id', 1)->oneArray() ?: [];
        $token = trim((string)($config['token'] ?? ''));
        $target = preg_replace('/[^0-9]/', '', (string)($_POST['nomor_tujuan'] ?? ''));
        if (strpos($target, '0') === 0) {
            $target = '62' . substr($target, 1);
        }
        $message = trim((string)($_POST['pesan'] ?? ''));
        $sendOptions = ['duration' => max(0, min(10, (int)($config['duration'] ?? 1))), 'delay' => max(0, min(10, (int)($config['delay'] ?? 0)))];

        if ($token === '') {
            $this->notify('failure', 'Fonnte API Token belum diisi.');
        } elseif (strlen($target) < 10) {
            $this->notify('failure', 'Nomor tujuan tidak valid. Gunakan format 08xxx atau 628xxx.');
        } elseif ($message === '') {
            $this->notify('failure', 'Isi pesan tes tidak boleh kosong.');
        } else {
            $ch = curl_init('https://api.fonnte.com/send');
            curl_setopt_array($ch, [
              CURLOPT_POST => true,
              CURLOPT_POSTFIELDS => http_build_query(array_merge(['target' => $target, 'message' => $message], $sendOptions)),
              CURLOPT_HTTPHEADER => ['Authorization: ' . $token],
              CURLOPT_RETURNTRANSFER => true,
              CURLOPT_CONNECTTIMEOUT => 10,
              CURLOPT_TIMEOUT => 30
            ]);
            $raw = curl_exec($ch);
            $curlError = curl_error($ch);
            $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
            $result = json_decode((string)$raw, true);
            if (is_array($result) && !empty($result['status'])) {
                $this->notify('success', 'Pesan tes berhasil dikirim ke ' . $target . '.');
            } else {
                $reason = $curlError !== '' ? $curlError : (string)($result['reason'] ?? $result['message'] ?? trim((string)$raw));
                if ($reason === '') {
                    $reason = 'Respons tidak dikenal (HTTP ' . $httpCode . ').';
                }
                $this->notify('failure', 'Gagal mengirim pesan tes: ' . substr(strip_tags($reason), 0, 220));
            }
        }
        redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasifonnte']));
    }

    public function postSaveTemplateFonnte()
    {
        $this->_initFonnteConfig();
        $input = $_POST['template'] ?? [];
        foreach ($this->_fonnteTemplateDefaults() as $tipe => $default) {
            $row = $input[$tipe] ?? [];
            $pesan = trim((string)($row['pesan'] ?? $default['pesan']));
            if ($pesan === '') {
                $pesan = $default['pesan'];
            }
            $data = ['tipe' => $tipe, 'aktif' => !empty($row['aktif']) ? 1 : 0, 'pesan' => $pesan, 'tgl_diperbarui' => date('Y-m-d H:i:s')];
            $this->db('rsns_custom_logistik_non_medis_fonnte_template')->where('tipe', $tipe)->save($data);
        }
        $this->notify('success', 'Konfigurasi pesan Fonnte telah disimpan');
        redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasifonnte']) . '#pesan');
    }

    public function postTestTemplateFonnte()
    {
        $this->_initFonnteConfig();
        $config = $this->db('rsns_custom_logistik_non_medis_fonnte_config')->where('id', 1)->oneArray() ?: [];
        $token = trim((string)($config['token'] ?? ''));
        $type = trim((string)($_POST['test_tipe'] ?? ''));
        $target = preg_replace('/[^0-9]/', '', (string)($_POST['test_target'] ?? ''));
        if (strpos($target, '0') === 0) {
            $target = '62' . substr($target, 1);
        }
        $noSppb = trim((string)($_POST['test_no_sppb'] ?? 'TEST-SPPB'));
        $defaults = $this->_fonnteTemplateDefaults();
        $row = $this->db('rsns_custom_logistik_non_medis_fonnte_template')->where('tipe', $type)->oneArray() ?: [];
        $message = trim((string)($row['pesan'] ?? ($defaults[$type]['pesan'] ?? '')));
        $valid = isset($defaults[$type]);
        if ($token === '' || !$valid || strlen($target) < 10 || $message === '') {
            $this->notify('failure', $token === '' ? 'Token Fonnte belum diisi.' : 'Data tes status atau nomor tujuan tidak valid.');
        } else {
            $message = str_replace(['{no_sppb}', '{username}'], [$noSppb, 'TEST'], $message);
            $sendOptions = ['duration' => max(0, min(10, (int)($config['duration'] ?? 1))), 'delay' => max(0, min(10, (int)($config['delay'] ?? 0)))];
            $ch = curl_init('https://api.fonnte.com/send');
            curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => http_build_query(array_merge(['target' => $target, 'message' => $message], $sendOptions)), CURLOPT_HTTPHEADER => ['Authorization: ' . $token], CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 30]);
            $raw = curl_exec($ch);
            $error = curl_error($ch);
            $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
            $result = json_decode((string)$raw, true);
            if (is_array($result) && !empty($result['status'])) {
                $this->notify('success', 'Tes status berhasil dikirim ke ' . $target . '.');
            } else {
                $reason = $error !== '' ? $error : (string)($result['reason'] ?? $result['message'] ?? trim((string)$raw));
                if ($reason === '') {
                    $reason = 'HTTP ' . $code;
                } $this->notify('failure', 'Tes status gagal: ' . substr(strip_tags($reason), 0, 220));
            }
        }
        redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasifonnte']) . '#pesan');
    }

    public function getKonfigurasiwaha()
    {
        $this->_initWahaConfig();
        $config = $this->db('rsns_custom_logistik_non_medis_waha_config')->where('id', 1)->oneArray() ?: [];

        $templateRows = $this->db('rsns_custom_logistik_non_medis_waha_template')->toArray();
        $templates = [];
        
        // Task 3.4: Validate and sanitize database template data
        foreach ($templateRows as $t) {
            // Check for required fields and replace with defaults if corrupted
            if (empty($t['tipe']) || empty($t['pesan'])) {
                error_log("WAHA template corrupted for type " . ($t['tipe'] ?? 'unknown') . ", skipping");
                continue;
            }
            $templates[$t['tipe']] = $t;
        }
        
        // Task 3.2: Ensure all default template types are present with complete data
        foreach ($this->_wahaTemplateDefaults() as $tipe => $default) {
            if (!isset($templates[$tipe])) {
                // Missing template - create with defaults
                $templates[$tipe] = [
                    'tipe' => $tipe, 
                    'aktif' => 1, 
                    'pesan' => $default['pesan'],
                    'tgl_diperbarui' => date('Y-m-d H:i:s')
                ];
            } else {
                // Existing template - validate and fill missing fields
                if (empty($templates[$tipe]['pesan'])) {
                    error_log("WAHA template corrupted for type {$tipe}, using default message");
                    $templates[$tipe]['pesan'] = $default['pesan'];
                }
                if (!isset($templates[$tipe]['aktif'])) {
                    $templates[$tipe]['aktif'] = 1;
                }
            }
            // Always set label from defaults to ensure consistency
            $templates[$tipe]['label'] = $default['label'];
        }

        $apiKey = trim((string)($config['api_key'] ?? ''));
        return $this->draw('konfigurasi.waha.html', [
          'aktif' => !empty($config['aktif']),
          'base_url' => (string)($config['base_url'] ?? 'http://127.0.0.1:3000'),
          'session_name' => (string)($config['session_name'] ?? 'default'),
          'delay' => max(0, min(10, (int)($config['delay'] ?? 1))),
          'api_key_tersimpan' => $apiKey !== '',
          'api_key_akhir' => $apiKey !== '' ? substr($apiKey, -4) : '',
          'api_key_placeholder' => $apiKey !== '' ? 'API key sudah tersimpan - isi hanya untuk mengganti' : 'Masukkan WAHA API key',
          'templates' => $templates
        ]);
    }

    public function postSaveKonfigurasiWaha()
    {
        $this->_initWahaConfig();
        $existing = $this->db('rsns_custom_logistik_non_medis_waha_config')->where('id', 1)->oneArray() ?: [];
        $baseUrl = trim((string)($_POST['waha_base_url'] ?? ($existing['base_url'] ?? 'http://127.0.0.1:3000')));
        $baseUrl = rtrim($baseUrl, '/');
        $apiKey = trim((string)($_POST['waha_api_key'] ?? ''));
        if ($apiKey === '') {
            $apiKey = (string)($existing['api_key'] ?? '');
        }
        $session = preg_replace('/[^A-Za-z0-9_.-]/', '', (string)($_POST['waha_session_name'] ?? ($existing['session_name'] ?? 'default')));
        if ($session === '') {
            $session = 'default';
        }
        $delay = max(0, min(10, (int)($_POST['waha_delay'] ?? ($existing['delay'] ?? 1))));

        if ($baseUrl === '' || !preg_match('~^https?://~i', $baseUrl)) {
            $this->notify('failure', 'Base URL WAHA wajib diawali http:// atau https://.');
        } else {
            $data = [
              'id' => 1,
              'aktif' => isset($_POST['waha_aktif']) ? 1 : 0,
              'base_url' => $baseUrl,
              'api_key' => $apiKey,
              'session_name' => $session,
              'delay' => $delay,
              'tgl_diperbarui' => date('Y-m-d H:i:s')
            ];
            if ($existing) {
                $this->db('rsns_custom_logistik_non_medis_waha_config')->where('id', 1)->save($data);
            } else {
                $this->db('rsns_custom_logistik_non_medis_waha_config')->save($data);
            }
            $this->notify('success', 'Konfigurasi WAHA telah disimpan.');
        }
        redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasiwaha']));
    }

    public function postTestWahaStatus()
    {
        $this->_initWahaConfig();
        $config = $this->db('rsns_custom_logistik_non_medis_waha_config')->where('id', 1)->oneArray() ?: [];
        $apiKey = trim((string)($config['api_key'] ?? ''));
        $baseUrl = rtrim(trim((string)($config['base_url'] ?? '')), '/');
        $session = trim((string)($config['session_name'] ?? 'default'));

        if ($apiKey === '' || $baseUrl === '') {
            $this->notify('failure', 'Base URL dan API key WAHA belum lengkap.');
        } else {
            $result = $this->_wahaRequest('GET', $baseUrl . '/api/sessions/' . rawurlencode($session), $apiKey);
            if ($result['ok']) {
                $body = json_decode($result['body'], true);
                $status = is_array($body) ? (string)($body['status'] ?? '-') : '-';
                $engine = is_array($body) && isset($body['engine']['engine']) ? (string)$body['engine']['engine'] : '-';
                $this->notify('success', 'WAHA terhubung. Session ' . $session . ' status: ' . $status . ' (' . $engine . ').');
            } else {
                $this->notify('failure', 'WAHA gagal dihubungi: ' . $result['message']);
            }
        }
        redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasiwaha']) . '#status');
    }


    public function postSaveTemplateWaha()
    {
        $this->_initWahaConfig();

        foreach ($this->_wahaTemplateDefaults() as $tipe => $default) {
            $aktif = isset($_POST['waha_template_aktif'][$tipe]) ? 1 : 0;
            $pesan = trim((string)($_POST['waha_template_pesan'][$tipe] ?? ''));
            $tgl = date('Y-m-d H:i:s');
            
            $stmt = $this->db()->pdo()->prepare("INSERT INTO `rsns_custom_logistik_non_medis_waha_template` (`tipe`, `aktif`, `pesan`, `tgl_diperbarui`) VALUES (?, ?, ?, ?) ON DUPLICATE KEY UPDATE `aktif`=VALUES(`aktif`), `pesan`=VALUES(`pesan`), `tgl_diperbarui`=VALUES(`tgl_diperbarui`)");
            $stmt->execute([$tipe, $aktif, $pesan, $tgl]);
        }
        $this->notify('success', 'Konfigurasi pesan WAHA telah disimpan');
        redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasiwaha']) . '#pesan');
    }

    public function postTestTemplateWaha()
    {
        $this->_initWahaConfig();
        $config = $this->db('rsns_custom_logistik_non_medis_waha_config')->where('id', 1)->oneArray() ?: [];
        $baseUrl = trim((string)($config['base_url'] ?? ''));
        $apiKey = trim((string)($config['api_key'] ?? ''));
        $session = trim((string)($config['session_name'] ?? 'default'));
        $delay = (int)($config['delay'] ?? 0);
        $target = $this->_normalizeWahaNumber((string)($_POST['waha_template_test_target'] ?? ''));
        $type = (string)($_POST['waha_template_test_type'] ?? '');

        $template = $this->db('rsns_custom_logistik_non_medis_waha_template')->where('tipe', $type)->oneArray() ?: [];
        if (empty($template['pesan'])) {
            $this->notify('failure', 'Template pesan tidak ditemukan atau kosong.');
            redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasiwaha']) . '#pesan');
        }

        $message = str_replace(['{no_sppb}', '{username}'], ['TES-001', 'TestUser'], $template['pesan']);
        $payload = [
          'chatId' => $target . '@c.us',
          'text' => $message,
          'session' => $session
        ];

        $result = $this->_wahaRequest('POST', $baseUrl . '/api/sendText', $apiKey, $payload);
        if ($result['ok']) {
            $this->notify('success', 'Pesan template tes WAHA berhasil dikirim ke ' . $target . '.');
        } else {
            $this->notify('failure', 'Pesan template tes WAHA gagal: ' . $result['message']);
        }
        redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasiwaha']) . '#pesan');
    }

    public function postTestWaha()
    {
        $this->_initWahaConfig();
        $config = $this->db('rsns_custom_logistik_non_medis_waha_config')->where('id', 1)->oneArray() ?: [];
        $apiKey = trim((string)($config['api_key'] ?? ''));
        $baseUrl = rtrim(trim((string)($config['base_url'] ?? '')), '/');
        $session = trim((string)($config['session_name'] ?? 'default'));
        $target = $this->_normalizeWahaNumber((string)($_POST['nomor_tujuan'] ?? ''));
        $message = trim((string)($_POST['pesan'] ?? ''));

        if ($apiKey === '' || $baseUrl === '') {
            $this->notify('failure', 'Base URL dan API key WAHA belum lengkap.');
        } elseif ($target === '') {
            $this->notify('failure', 'Nomor tujuan tidak valid. Gunakan format 08xxx atau 628xxx.');
        } elseif ($message === '') {
            $this->notify('failure', 'Isi pesan tes tidak boleh kosong.');
        } else {
            $payload = ['session' => $session, 'chatId' => $target . '@c.us', 'text' => $message];
            $result = $this->_wahaRequest('POST', $baseUrl . '/api/sendText', $apiKey, $payload);
            if ($result['ok']) {
                $this->notify('success', 'Pesan tes WAHA berhasil dikirim ke ' . $target . '.');
            } else {
                $this->notify('failure', 'Pesan tes WAHA gagal: ' . $result['message']);
            }
        }
        redirect(url([ADMIN, 'logistik_non_medis', 'konfigurasiwaha']) . '#tes');
    }

    private function _normalizeWahaNumber(string $number): string
    {
        $target = preg_replace('/[^0-9]/', '', $number);
        if (strpos($target, '0') === 0) {
            $target = '62' . substr($target, 1);
        }
        if (strlen($target) < 10) {
            return '';
        }
        return $target;
    }

    private function _wahaRequest(string $method, string $url, string $apiKey, array $payload = null): array
    {
        $ch = curl_init($url);
        if (!$ch) {
            return ['ok' => false, 'message' => 'Gagal menyiapkan koneksi.', 'body' => '', 'code' => 0];
        }
        $headers = ['X-Api-Key: ' . $apiKey, 'Accept: application/json'];
        $options = [
          CURLOPT_RETURNTRANSFER => true,
          CURLOPT_CONNECTTIMEOUT => 10,
          CURLOPT_TIMEOUT => 30,
          CURLOPT_CUSTOMREQUEST => strtoupper($method),
          CURLOPT_HTTPHEADER => $headers
        ];
        if ($payload !== null) {
            $headers[] = 'Content-Type: application/json';
            $options[CURLOPT_HTTPHEADER] = $headers;
            $options[CURLOPT_POSTFIELDS] = json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        }
        curl_setopt_array($ch, $options);
        $body = (string)curl_exec($ch);
        $error = curl_error($ch);
        $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
        $ok = $error === '' && $code >= 200 && $code < 300;
        if ($ok) {
            return ['ok' => true, 'message' => 'OK', 'body' => $body, 'code' => $code];
        }
        $parsed = json_decode($body, true);
        $message = $error !== '' ? $error : (string)($parsed['message'] ?? $parsed['error'] ?? trim(strip_tags($body)));
        if ($message === '') {
            $message = 'HTTP ' . $code;
        }
        return ['ok' => false, 'message' => substr($message, 0, 220), 'body' => $body, 'code' => $code];
    }

    public function getHakakses()
    {
        $this->_addHeaderFiles();
        $this->_initUserRoles();

        $roleDataAll = $this->db('rsns_custom_logistik_non_medis_user_roles')->toArray();
        $assignedUsernames = [];
        foreach ($roleDataAll as $rd) {
            $assignedUsernames[] = $rd['username'];
        }
        // Selalu pastikan admin default masuk list
        if (!in_array('admin', $assignedUsernames)) {
            $assignedUsernames[] = 'admin';
        }

        $allUsers = $this->db('mlite_users')->toArray();
        $users = [];
        $unassignedUsers = [];

        foreach ($allUsers as $u) {
            if (in_array($u['username'], $assignedUsernames)) {
                $users[] = $u;
            } else {
                $unassignedUsers[] = $u;
            }
        }

        foreach ($users as &$user) {
            $roleData = $this->db('rsns_custom_logistik_non_medis_user_roles')
                           ->where('username', $user['username'])
                           ->oneArray();
            $user['logistik_role'] = $roleData['role'] ?? 'unit';
            $user['logistik_kode_unit'] = $roleData['kode_unit'] ?? null;

            if (!empty($user['logistik_kode_unit'])) {
                $kodes = explode(',', $user['logistik_kode_unit']);
                $nama_units = [];
                foreach ($kodes as $kd) {
                    $unitInfo = $this->db('rsns_custom_logistik_non_medis_unit')
                                   ->where('kode_unit', trim($kd))
                                   ->oneArray();
                    if ($unitInfo) {
                        $nama = $unitInfo['nama_unit'];
                        if (strpos($nama, $kd) !== false) {
                            $nama_units[] = '<i class="fa fa-building-o"></i> ' . $nama;
                        } else {
                            $nama_units[] = '<i class="fa fa-building-o"></i> ' . $kd . ' - ' . $nama;
                        }
                    }
                }
                if (!empty($nama_units)) {
                    $user['nama_unit'] = implode('<br>', $nama_units);
                } else {
                    $user['nama_unit'] = 'Unit Tidak Ditemukan';
                }
            } else {
                $user['nama_unit'] = '<i class="fa fa-globe"></i> Semua Unit (Logistik/Admin)';
            }
            $waContact = $this->db('rsns_custom_logistik_non_medis_wa_contact')
                            ->where('username', $user['username'])
                            ->oneArray();
            $user['nomor_wa'] = $waContact['nomor_wa'] ?? '';
            $user['wa_aktif'] = (int)($waContact['aktif'] ?? 0);
        }

        $roles = ['admin', 'logistik', 'gudang', 'aset', 'unit', 'kepala_unit', 'kepala_sie', 'kepala_bidang'];
        $rolePermissions = [];
        foreach ($roles as $r) {
            $pData = $this->db('rsns_custom_logistik_non_medis_role_permissions')
                        ->where('role', $r)
                        ->oneArray();
            $rolePermissions[$r] = explode(',', $pData['permissions'] ?? '');
        }

        $availableMenus = [
        'manage' => 'Dashboard Logistik',
        'masterbarang' => 'Data Barang',
        'mastervendor' => 'Data Vendor',
        'masterunit' => 'Data Unit',
        'masterlokasi' => 'Lokasi Gudang',
        'mastersatuan' => 'Satuan Barang',
        'masterkategori' => 'Kategori & Klasifikasi',
        'masterrekanan' => 'Data Rekanan Jasa',
        'mastercoa' => 'Kode Akun (COA)',
        'pengadaanperencanaan' => 'Perencanaan Pengadaan',
        'pengadaanpr' => 'Permintaan (PR)',
        'pengadaanvendor' => 'Manajemen Vendor',
        'pengadaanpo' => 'Purchase Order (PO)',
        'pengadaanekatalog' => 'E-Katalog',
        'pengadaanpenerimaan' => 'Penerimaan Pengadaan',
        'pengadaankontrak' => 'Manajemen Kontrak',
        'gudangmanage' => 'Gudang Manage',
        'gudangpenerimaan' => 'Barang Masuk Gudang',
        'gudanglokasi' => 'Manajemen Lokasi',
        'gudangstok' => 'Pengelolaan Stok',
        'gudangopname' => 'Stock Opname',
        'gudangopnamev2' => 'Stok Opname V2',
        'gudangmetode' => 'Metode FIFO/FEFO',
        'gudangrusak' => 'Barang Rusak',
        'gudangmutasi' => 'Mutasi Antar Gudang',
        'distribusisppb' => 'Permintaan Barang (SPPB)',
        'distribusinonrutin' => 'Permintaan Non Rutin',
        'distribusimendesak' => 'Permintaan Langsung',
        'distribusiverifikasi' => 'Verifikasi & Approval',
        'distribusipacking' => 'Picking & Packing',
        'distribusiserahterima' => 'Serah Terima Barang',
        'distribusitracking' => 'Tracking Pengiriman',
        'distribusiretur' => 'Retur Barang dari Unit',
        'distribusikuota' => 'Kuota & Alokasi Unit',
        'asetregistrasi' => 'Registrasi Aset',
        'asetkib' => 'Kartu Inventaris (KIB)',
        'asetpenyusutan' => 'Penyusutan Aset',
        'asetpemeliharaan' => 'Pemeliharaan Aset',
        'asetmutasi' => 'Mutasi Aset',
        'asetpenghapusan' => 'Penghapusan Aset',
        'asetsensus' => 'Sensus & Verifikasi Aset',
        'laporanstokmutasi' => 'Laporan Stok & Mutasi',
