    public function postSaveHakakses()
    {
        $username = $_POST['username'] ?? '';
        $role = $_POST['role'] ?? 'unit';
        $kode_unit = $_POST['kode_unit'] ?? null;
        if (is_array($kode_unit)) {
            $kode_unit = implode(',', $kode_unit);
        }
        if (empty($kode_unit)) {
            $kode_unit = null;
        }

        if (empty($username)) {
            echo json_encode(['status' => 'error', 'message' => 'Username tidak valid!']);
            exit();
        }

        $exists = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        if ($exists) {
            $res = $this->db('rsns_custom_logistik_non_medis_user_roles')
                      ->where('username', $username)
                      ->save([
                          'role' => $role,
                          'kode_unit' => $kode_unit
                      ]);
        } else {
            $res = $this->db('rsns_custom_logistik_non_medis_user_roles')
                      ->save([
                          'username' => $username,
                          'role' => $role,
                          'kode_unit' => $kode_unit
                      ]);
        }

        if ($res) {
            $nomorWa = preg_replace('/[^0-9+]/', '', (string)($_POST['nomor_wa'] ?? ''));
            $waAktif = !empty($_POST['wa_aktif']) ? 1 : 0;
            $waSql = "INSERT INTO rsns_custom_logistik_non_medis_wa_contact (username, nomor_wa, aktif, tgl_diperbarui)
                    VALUES (?,?,?,NOW())
                    ON DUPLICATE KEY UPDATE nomor_wa=VALUES(nomor_wa), aktif=VALUES(aktif), tgl_diperbarui=NOW()";
            $this->db()->pdo()->prepare($waSql)->execute([$username, $nomorWa !== '' ? $nomorWa : null, $waAktif]);
            // Otomatis tambahkan akses menu logistik_non_medis ke user yang di-assign role
            $this->_syncLogistikAccess($username, true);
            echo json_encode(['status' => 'success', 'message' => 'Hak akses user berhasil disimpan.']);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan hak akses user!']);
        }
        exit();
    }

    public function postSaveRolePermissions()
    {
        $this->_initUserRoles();
        $permissions = $_POST['permissions'] ?? [];

        $roles = ['admin', 'logistik', 'gudang', 'aset', 'unit', 'kepala_unit', 'kepala_sie', 'kepala_bidang'];
        foreach ($roles as $r) {
            $rolePerms = isset($permissions[$r]) ? implode(',', $permissions[$r]) : 'manage';

            if (strpos($rolePerms, 'manage') === false) {
                $rolePerms = 'manage,' . $rolePerms;
            }

            $exists = $this->db('rsns_custom_logistik_non_medis_role_permissions')->where('role', $r)->oneArray();
            if ($exists) {
                $this->db('rsns_custom_logistik_non_medis_role_permissions')
                   ->where('role', $r)
                   ->save(['permissions' => $rolePerms]);
            } else {
                $this->db('rsns_custom_logistik_non_medis_role_permissions')
                   ->save(['role' => $r, 'permissions' => $rolePerms]);
            }
        }

        $this->core->setNotify('success', 'Pengaturan izin role berhasil diperbarui.');
        redirect(url([ADMIN, 'logistik_non_medis', 'hakakses']));
    }

    public function getManage()
    {
        $this->_addHeaderFiles();
        $this->_initSppb();
        $this->_initPacking();
        $this->_initKuota();

        $username = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';

        $permsData = $this->db('rsns_custom_logistik_non_medis_role_permissions')->where('role', $role)->oneArray();
        $permissions = explode(',', $permsData['permissions'] ?? 'manage');
        if (!$this->_canAccessRekapNonRutin()) {
            $permissions = array_values(array_diff($permissions, ['rekapnonrutin']));
        }
        // Pengeluaran mendesak adalah fungsi operasional langsung untuk pengelola logistik.
        if (in_array(strtolower($role), ['admin', 'logistik', 'gudang'], true) && !in_array('distribusimendesak', $permissions, true)) {
            $permissions[] = 'distribusimendesak';
        }
        $hakakses_access = in_array('hakakses', $permissions);

        $has_master = count(array_intersect(['masterbarang', 'mastervendor', 'masterunit', 'masterlokasi', 'mastersatuan', 'masterkategori', 'masterrekanan', 'mastercoa', 'masterinventaris', 'konfigurasifonnte', 'konfigurasiwaha'], $permissions)) > 0;
        $has_pengadaan = count(array_intersect(['pengadaanperencanaan', 'pengadaanpr', 'pengadaanvendor', 'pengadaanpo', 'pengadaanekatalog', 'pengadaanpenerimaan', 'pengadaankontrak', 'rencanabelanja', 'realisasibelanja'], $permissions)) > 0;
        $has_gudang = count(array_intersect(['gudangpenerimaan', 'gudanglokasi', 'gudangstok', 'gudangopname', 'gudangopnamev2', 'gudangmetode', 'gudangrusak', 'gudangmutasi'], $permissions)) > 0;
        $has_distribusi = count(array_intersect(['distribusisppb', 'distribusinonrutin', 'distribusimendesak', 'distribusiverifikasi', 'distribusipacking', 'distribusiserahterima', 'distribusitracking', 'distribusiretur', 'distribusikuota'], $permissions)) > 0;
        $has_aset = count(array_intersect(['asetregistrasi', 'asetkib', 'asetpenyusutan', 'asetpemeliharaan', 'asetmutasi', 'asetpenghapusan', 'asetsensus'], $permissions)) > 0;
        $has_laporan = count(array_intersect(['laporanstokmutasi', 'laporanpengadaan', 'rekapnonrutin', 'laporandistribusi', 'laporanaset', 'laporandashboardkpi', 'laporaneksporcetak', 'laporaninventaris', 'laporaninventaris'], $permissions)) > 0;

      // Tentukan tab pertama yang aktif berdasarkan permission user
        $first_active_tab = 'distribusi';
        if ($has_master) {
            $first_active_tab = 'master-data';
        } elseif ($has_pengadaan) {
            $first_active_tab = 'pengadaan';
        } elseif ($has_gudang) {
            $first_active_tab = 'manajemen-gudang';
        } elseif ($has_distribusi) {
            $first_active_tab = 'distribusi';
        } elseif ($has_aset) {
            $first_active_tab = 'aset';
        } elseif ($has_laporan) {
            $first_active_tab = 'laporan-audit';
        }

      // Individual permission flags untuk setiap menu item
        $perm_flags = [];
        $all_perm_keys = [
        'masterbarang', 'mastervendor', 'masterunit', 'masterlokasi', 'mastersatuan',
        'masterkategori', 'masterrekanan', 'mastercoa', 'masterinventaris', 'konfigurasifonnte', 'konfigurasiwaha',
        'pengadaanperencanaan', 'pengadaanpr', 'pengadaanvendor', 'pengadaanpo', 'pengadaankontrak',
        'rencanabelanja', 'realisasibelanja',
        'gudangpenerimaan', 'gudanglokasi', 'gudangstok', 'gudangopname', 'gudangopnamev2',
        'gudangmetode', 'gudangrusak', 'gudangmutasi',
        'distribusisppb', 'distribusinonrutin', 'distribusimendesak', 'distribusiverifikasi', 'distribusipacking',
        'distribusiserahterima', 'distribusitracking', 'distribusiretur', 'distribusikuota',
        'asetregistrasi', 'asetkib', 'asetpenyusutan', 'asetpemeliharaan',
        'asetmutasi', 'asetpenghapusan', 'asetsensus',
        'laporanstokmutasi', 'laporanpengadaan', 'rekapnonrutin', 'laporandistribusi',
        'laporanaset', 'laporandashboardkpi', 'laporaneksporcetak', 'laporaninventaris'
        ];
        foreach ($all_perm_keys as $pk) {
            $perm_flags['perm_' . $pk] = in_array($pk, $permissions);
        }
        $perm_flags['perm_laporancostunit'] = in_array('laporandistribusi', $permissions);
        $perm_flags['perm_konfigurasifonnte'] = in_array('konfigurasifonnte', $permissions);
        $perm_flags['perm_konfigurasiwaha'] = in_array('konfigurasiwaha', $permissions);

        $start_date = date('Y-m-d', strtotime('last Friday'));
        $end_date = date('Y-m-d', strtotime('+6 days', strtotime($start_date)));

        try {
            $count_verif = (int) $this->db()->pdo()->query("SELECT COUNT(DISTINCT no_sppb) FROM rsns_custom_logistik_non_medis_sppb WHERE status IN ('Disetujui Kabid', 'Disetujui Unit') OR (status = 'Diajukan' AND jenis_permintaan = 'Rutin')")->fetchColumn();
        } catch (\Exception $e) {
            $count_verif = 0;
        }
        try {
            $count_packing = count($this->db('rsns_custom_logistik_non_medis_sppb')->where('status', 'Proses Logistik')->orWhere('status', 'Proses Pengadaan')->orWhere('status', 'Picking')->orWhere('status', 'Packing')->group('no_sppb')->toArray());
        } catch (\Exception $e) {
            $count_packing = 0;
        }


        $dash_permintaan_minggu = 0;
        $dash_rutin_proses = 0;
        $dash_rutin_selesai = 0;

        $dash_total_nonrutin = 0;
        $dash_nonrutin_proses = 0;
        $dash_nonrutin_selesai = 0;

        $dash_cost_bulan = 0;
        $dash_total_aset = 0;
        $dash_total_po = 0;

        $pdo = $this->db()->pdo();
        $dashboard_scope_sql = '';
        $dashboard_scope_params = [];
        if (!in_array($role, ['admin', 'logistik'], true)) {
            $dashboard_scope_units = !empty($userRoleData['kode_unit'])
            ? $this->_getAllChildUnitKodes(array_map('trim', explode(',', $userRoleData['kode_unit'])))
            : [];
            if (!empty($dashboard_scope_units)) {
                $dashboard_scope_placeholders = implode(',', array_fill(0, count($dashboard_scope_units), '?'));
                $dashboard_scope_sql = " AND kode_unit IN ($dashboard_scope_placeholders) ";
                $dashboard_scope_params = array_values($dashboard_scope_units);
            } else {
                $dashboard_scope_sql = ' AND 1 = 0 ';
            }
        }

        try {
            // Hitung range hari Jumat ke Kamis
            $timestamp = time();
            $dayOfWeek = date('w', $timestamp);
            if ($dayOfWeek == 5) { // Jika hari ini Jumat
                $start_date = date('Y-m-d', $timestamp);
            } else {
                $start_date = date('Y-m-d', strtotime('last Friday', $timestamp));
            }
            $end_date = date('Y-m-d', strtotime('+6 days', strtotime($start_date)));

            $dash_rutin_periode = date('d/m', strtotime($start_date)) . ' - ' . date('d/m', strtotime($end_date));

            $q_rutin = $pdo->prepare("
            SELECT no_sppb, status
            FROM rsns_custom_logistik_non_medis_sppb
            WHERE tgl_sppb BETWEEN ? AND ?
              AND jenis_permintaan = 'Rutin'
              $dashboard_scope_sql
            GROUP BY no_sppb
        ");
            $q_rutin->execute(array_merge([$start_date, $end_date], $dashboard_scope_params));
            $q_rutin = $q_rutin->fetchAll(\PDO::FETCH_ASSOC);

            $dash_permintaan_minggu = count($q_rutin);
            foreach ($q_rutin as $r) {
                if (in_array($r['status'], ['Selesai', 'Ditolak', 'Batal', 'Dibatalkan'])) {
                    $dash_rutin_selesai++;
                } else {
                    $dash_rutin_proses++;
                }
            }
        } catch (\Exception $e) {
            $dash_permintaan_minggu = 0;
        }

        try {
            $q_nonrutin_stmt = $pdo->prepare("
            SELECT no_sppb, status
            FROM rsns_custom_logistik_non_medis_sppb
            WHERE jenis_permintaan = 'Non Rutin'
              AND YEAR(tgl_sppb) = YEAR(CURDATE())
              $dashboard_scope_sql
            GROUP BY no_sppb
        ");
            $q_nonrutin_stmt->execute($dashboard_scope_params);
            $q_nonrutin = $q_nonrutin_stmt->fetchAll(\PDO::FETCH_ASSOC);

            $dash_total_nonrutin = count($q_nonrutin);
            foreach ($q_nonrutin as $r) {
                if (in_array($r['status'], ['Selesai', 'Ditolak', 'Batal', 'Dibatalkan'])) {
                    $dash_nonrutin_selesai++;
                } else {
                    $dash_nonrutin_proses++;
                }
            }
        } catch (\Exception $e) {
            $dash_total_nonrutin = 0;
        }

        try {
            $pdo->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_aset` (
          `id` int(11) NOT NULL AUTO_INCREMENT,
          `kode_aset` varchar(50) NOT NULL,
          `nama_aset` varchar(255) DEFAULT NULL,
          `kode_item` varchar(50) DEFAULT NULL,
          `kode_unit` varchar(50) DEFAULT NULL,
          `status` varchar(50) NOT NULL DEFAULT 'Aktif',
          PRIMARY KEY (`id`)
        ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");
            $dash_total_aset = (int) $pdo->query("
            SELECT COUNT(*)
            FROM rsns_custom_logistik_non_medis_aset
            WHERE status = 'Aktif'
        ")->fetchColumn();
        } catch (\Exception $e) {
            $dash_total_aset = 0;
        }
        try {
            $pdo->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_po` (
          `id` int(11) NOT NULL AUTO_INCREMENT,
          `no_po` varchar(50) NOT NULL,
          `tgl_po` date NOT NULL,
          `kode_vendor` varchar(50) NOT NULL,
          PRIMARY KEY (`id`),
          UNIQUE KEY `no_po` (`no_po`)
        ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");
            $dash_total_po = (int) $pdo->query("
            SELECT COUNT(DISTINCT no_po)
            FROM rsns_custom_logistik_non_medis_po
            WHERE MONTH(tgl_po) = MONTH(CURDATE())
              AND YEAR(tgl_po) = YEAR(CURDATE())
        ")->fetchColumn();
        } catch (\Exception $e) {
            $dash_total_po = 0;
        }
        try {
            $dash_cost_bulan = (float) $pdo->query("
            SELECT COALESCE(SUM(s.jumlah_disetujui * b.harga_referensi), 0)
            FROM rsns_custom_logistik_non_medis_sppb s
            LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item
            WHERE s.status IN ('Siap Ambil', 'Selesai', 'Diterima')
              AND MONTH(s.tgl_sppb) = MONTH(CURDATE())
              AND YEAR(s.tgl_sppb) = YEAR(CURDATE())
        ")->fetchColumn();
        } catch (\Exception $e) {
            $dash_cost_bulan = 0;
        }

      // Dynamic Dashboard Variables
        $dash_status_usulan = '';
        $dash_butuh_persetujuan = 0;

      // Get user's unit codes and names
        $user_unit_kodes = [];
        $dash_nama_unit_string = '';
        if (!empty($userRoleData['kode_unit'])) {
            $user_unit_kodes = array_map('trim', explode(',', $userRoleData['kode_unit']));
            $in_clause = implode("','", $user_unit_kodes);
            try {
                $nama_units_arr = $this->db()->pdo()->query("SELECT nama_unit FROM rsns_custom_logistik_non_medis_unit WHERE kode_unit IN ('$in_clause')")->fetchAll(\PDO::FETCH_COLUMN);
                if (!empty($nama_units_arr)) {
                    $dash_nama_unit_string = implode(', ', $nama_units_arr);
                }
            } catch (\Exception $e) {
                $dash_nama_unit_string = '';
            }
        }

        if ($role === 'unit' && !empty($user_unit_kodes)) {
            // Status usulan terbaru untuk unit
            $in_clause = implode("','", $user_unit_kodes);
            try {
                $latest_stmt = $this->db()->pdo()->prepare("SELECT status, no_sppb
                FROM rsns_custom_logistik_non_medis_sppb
                WHERE kode_unit IN ('$in_clause')
                  AND jenis_permintaan = 'Rutin'
                  AND tgl_sppb BETWEEN ? AND ?
                ORDER BY tgl_sppb DESC, no_sppb DESC LIMIT 1");
                $latest_stmt->execute([$start_date, $end_date]);
                $latest = $latest_stmt->fetch(\PDO::FETCH_ASSOC);
                if ($latest) {
                    $dash_status_usulan = $latest['status'];
                }
            } catch (\Exception $e) {
                $dash_status_usulan = '';
            }
        } elseif (in_array($role, ['kepala_unit', 'kepala_sie', 'kepala_bidang']) && !empty($user_unit_kodes)) {
            // Total butuh persetujuan
            try {
                $all_child_kodes = $this->_getAllChildUnitKodes($user_unit_kodes);
                if (!empty($all_child_kodes)) {
                    $in_clause = implode("','", $all_child_kodes);
                    $target_status = '';
                    if ($role === 'kepala_unit') {
                        $target_status = 'Diajukan';
                    } elseif ($role === 'kepala_sie') {
                        $target_status = 'Disetujui Ka. Unit';
                    } elseif ($role === 'kepala_bidang') {
                        $target_status = 'Disetujui Ka. Sie';
                    }

                    if ($target_status) {
                        $count_q = $this->db()->pdo()->query("SELECT COUNT(DISTINCT no_sppb) as total FROM rsns_custom_logistik_non_medis_sppb WHERE status = '$target_status' AND jenis_permintaan = 'Non Rutin' AND kode_unit IN ('$in_clause')")->fetch(\PDO::FETCH_ASSOC);
                        $dash_butuh_persetujuan = $count_q['total'] ?? 0;
                    }
                }
            } catch (\Exception $e) {
                $dash_butuh_persetujuan = 0;
            }
        }


        return $this->draw('manage.html', array_merge([
        'count_verif' => $count_verif,
        'count_packing' => $count_packing,
        'dash_permintaan_minggu' => $dash_permintaan_minggu,
        'dash_rutin_proses' => $dash_rutin_proses,
        'dash_rutin_selesai' => $dash_rutin_selesai,
        'dash_rutin_periode' => $dash_rutin_periode ?? '',
        'dash_cost_bulan' => $dash_cost_bulan,
        'dash_total_aset' => $dash_total_aset,
        'dash_total_nonrutin' => $dash_total_nonrutin,
        'dash_nonrutin_proses' => $dash_nonrutin_proses,
        'dash_nonrutin_selesai' => $dash_nonrutin_selesai,
        'dash_total_po' => $dash_total_po,
        'dash_status_usulan' => $dash_status_usulan,
        'dash_butuh_persetujuan' => $dash_butuh_persetujuan,
        'dash_nama_unit_string' => $dash_nama_unit_string,
        'permissions' => $permissions,
        'hakakses_access' => $hakakses_access,
        'has_master' => $has_master,
        'has_pengadaan' => $has_pengadaan,
        'has_gudang' => $has_gudang,
        'has_distribusi' => $has_distribusi,
        'has_aset' => $has_aset,
        'has_laporan' => $has_laporan,
        'first_active_tab' => $first_active_tab,
        'role' => $role,
        'is_not_unit' => ($role !== 'unit')
        ], $perm_flags));
    }

    private function _getAllChildUnitKodes(array $kodes)
    {
        if (empty($kodes)) {
            return [];
        }
        $result_kodes = $kodes;
        $current_kodes = $kodes;

        while (true) {
            $in = implode("','", $current_kodes);
            $children = $this->db()->pdo()->query("
              SELECT kode_unit FROM rsns_custom_logistik_non_medis_unit 
              WHERE parent_id IN (
                  SELECT id FROM rsns_custom_logistik_non_medis_unit WHERE kode_unit IN ('$in')
              )
          ")->fetchAll(\PDO::FETCH_COLUMN);

            if (empty($children)) {
                break;
            }

            // Add new children to result, prepare for next level
            $new_children = array_diff($children, $result_kodes);
            if (empty($new_children)) {
                break; // Prevent infinite loops
            }

            $result_kodes = array_merge($result_kodes, $new_children);
            $current_kodes = $new_children;
        }

        return $result_kodes;
    }

