    private function _initDataBarang()
    {
        static $_databarang_initialized = false;
        if ($_databarang_initialized) {
            return;
        }
        $_databarang_initialized = true;
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_master_barang` (
        `kode_item` varchar(50) NOT NULL,
        `barcode` varchar(100) DEFAULT NULL,
        `nama_barang` varchar(200) NOT NULL,
        `deskripsi` text DEFAULT NULL,
        `spesifikasi` text DEFAULT NULL,
        `kategori` varchar(100) DEFAULT NULL,
        `kode_kategori` varchar(50) DEFAULT NULL,
        `sub_kategori` varchar(100) DEFAULT NULL,
        `satuan_dasar` varchar(50) NOT NULL,
        `satuan_konversi` varchar(50) DEFAULT NULL,
        `harga_referensi` double NOT NULL DEFAULT 0,
        `stok_min` double NOT NULL DEFAULT 0,
        `stok_max` double NOT NULL DEFAULT 0,
        `safety_stock` double NOT NULL DEFAULT 0,
        `foto` varchar(255) DEFAULT NULL,
        `dokumen` varchar(255) DEFAULT NULL,
        `default_kode_lokasi` varchar(50) DEFAULT NULL,
        `status` enum('Aktif','Tidak Aktif') NOT NULL DEFAULT 'Aktif',
        PRIMARY KEY (`kode_item`)
      ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");

        // Migration for existing tables
        $check_kategori = $this->db()->pdo()->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_master_barang` LIKE 'kategori'")->fetch();
        if (!$check_kategori) {
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `kategori` varchar(100) DEFAULT NULL AFTER `spesifikasi` ");
        }

        $check_kode_kategori = $this->db()->pdo()->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_master_barang` LIKE 'kode_kategori'")->fetch();
        if (!$check_kode_kategori) {
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `kode_kategori` varchar(50) DEFAULT NULL AFTER `kategori` ");
        }

        // Older installations were created without barcode, although the
        // master-barang save query has always included this field.
        $check_barcode = $this->db()->pdo()->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_master_barang` LIKE 'barcode'")->fetch();
        if (!$check_barcode) {
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `barcode` varchar(100) DEFAULT NULL AFTER `kode_item` ");
        }

        $check_sub_kategori = $this->db()->pdo()->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_master_barang` LIKE 'sub_kategori'")->fetch();
        if (!$check_sub_kategori) {
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `sub_kategori` varchar(100) DEFAULT NULL AFTER `kode_kategori` ");
        }

        $check = $this->db()->pdo()->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_master_barang` LIKE 'stok_min'")->fetch();
        if (!$check) {
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `stok_min` double NOT NULL DEFAULT 0 AFTER `harga_referensi` ");
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `stok_max` double NOT NULL DEFAULT 0 AFTER `stok_min` ");
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `safety_stock` double NOT NULL DEFAULT 0 AFTER `stok_max` ");
        }

        $check_loc = $this->db()->pdo()->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_master_barang` LIKE 'default_kode_lokasi'")->fetch();
        if (!$check_loc) {
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `default_kode_lokasi` varchar(50) DEFAULT NULL AFTER `dokumen` ");
        }

        $check_tipe = $this->db()->pdo()->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_master_barang` LIKE 'tipe_barang'")->fetch();
        if (!$check_tipe) {
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `tipe_barang` enum('Habis Pakai','Aset') NOT NULL DEFAULT 'Habis Pakai' AFTER `kategori` ");
        }

        $check_jenis = $this->db()->pdo()->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_master_barang` LIKE 'jenis_item'")->fetch();
        if (!$check_jenis) {
            $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_master_barang` ADD `jenis_item` enum('Rutin','Non Rutin') NOT NULL DEFAULT 'Rutin' AFTER `kategori` ");
        }

        $upload_dir = UPLOADS . '/logistik_non_medis';
        if (!is_dir($upload_dir)) {
            mkdir($upload_dir, 0777, true);
        }
        if (!is_dir($upload_dir . '/foto')) {
            mkdir($upload_dir . '/foto', 0777, true);
        }
        if (!is_dir($upload_dir . '/dokumen')) {
            mkdir($upload_dir . '/dokumen', 0777, true);
        }
    }

    private function _generateKodeBarang()
    {
        $prefix = 'BRG' . date('mY');
        $last = $this->db('rsns_custom_logistik_non_medis_master_barang')
                   ->where('kode_item', 'LIKE', $prefix . '%')
                   ->desc('kode_item')
                   ->limit(1)
                   ->oneArray();

        if ($last) {
            $last_num = (int) substr($last['kode_item'], -4);
            $next_num = str_pad($last_num + 1, 4, '0', STR_PAD_LEFT);
        } else {
            $next_num = '0001';
        }

        return $prefix . $next_num;
    }

    public function getMasterBarang()
    {
        $this->_initDataBarang();
        $this->_initKategori();
        $this->_addHeaderFiles();
        $kategori = $this->db('rsns_custom_logistik_non_medis_kategori')->toArray();
        usort($kategori, function ($a, $b) {
            return strcasecmp((string)($a['nama_kategori'] ?? ''), (string)($b['nama_kategori'] ?? ''));
        });
        return $this->draw('master.barang.html', ['kategori' => $kategori]);
    }

    public function anyDisplayMasterBarang()
    {
        $this->_initDataBarang();
        $perpage = 20;
        $halaman = isset($_POST['halaman']) ? (int)$_POST['halaman'] : 1;
        $cari = isset($_POST['cari']) ? $_POST['cari'] : '';
        $kategori = isset($_POST['kategori']) ? trim((string)$_POST['kategori']) : '';

        $_offset = ($halaman - 1) * $perpage;

        $query = $this->db('rsns_custom_logistik_non_medis_master_barang');
        if (!empty($cari)) {
            $query->where('kode_item', 'LIKE', '%' . $cari . '%')
                ->orLike('nama_barang', '%' . $cari . '%');
        }
        if ($kategori !== '') {
            $query->where('kode_kategori', $kategori);
        }

        $all_data = $query->toArray();
        $jumlah_data = count($all_data);
        $jml_halaman = ceil($jumlah_data / $perpage);

        $rows = $this->db('rsns_custom_logistik_non_medis_master_barang')
                    ->join('rsns_custom_logistik_non_medis_kategori', 'rsns_custom_logistik_non_medis_kategori.kode_kategori = rsns_custom_logistik_non_medis_master_barang.kode_kategori', 'LEFT')
                    ->select('rsns_custom_logistik_non_medis_master_barang.*')
                    ->select('rsns_custom_logistik_non_medis_kategori.nama_kategori');
        if (!empty($cari)) {
            $rows->where('rsns_custom_logistik_non_medis_master_barang.kode_item', 'LIKE', '%' . $cari . '%')
                ->orLike('rsns_custom_logistik_non_medis_master_barang.nama_barang', '%' . $cari . '%');
        }
        if ($kategori !== '') {
            $rows->where('rsns_custom_logistik_non_medis_master_barang.kode_kategori', $kategori);
        }
        $rows = $rows->desc('rsns_custom_logistik_non_medis_master_barang.kode_item')
                    ->offset($_offset)
                    ->limit($perpage)
                    ->toArray();

        echo $this->draw('master.barang.display.html', [
          'barang' => $rows,
          'halaman' => $halaman,
          'jumlah_data' => $jumlah_data,
          'jml_halaman' => $jml_halaman,
          'admin_mode' => $this->settings->get('settings.admin_mode')
        ]);
        exit();
    }

