    public function postSaveMasterBarang()
    {
        $this->_initDataBarang();
        $this->_initKategori();
        $kode_item = trim((string)($_POST['kode_item'] ?? ''));
        // Pada form tambah, kode ditampilkan sebagai placeholder. Jangan pernah
        // menyimpan placeholder tersebut sebagai kode barang literal.
        if ($kode_item === '' || strcasecmp($kode_item, '(Otomatis)') === 0) {
            $kode_item = $this->_generateKodeBarang();
        }

        $kode_kategori = $_POST['kode_kategori'] ?? '';
        $kategori_nama = '';
        if (!empty($kode_kategori)) {
            $kategori_row = $this->db('rsns_custom_logistik_non_medis_kategori')->where('kode_kategori', $kode_kategori)->oneArray();
            $kategori_nama = $kategori_row['nama_kategori'] ?? '';
        }

        $data = [
          'kode_item' => $kode_item,
          'barcode' => $_POST['barcode'] ?? '',
          'nama_barang' => $_POST['nama_barang'] ?? '',
          'deskripsi' => $_POST['deskripsi'] ?? '',
          'spesifikasi' => $_POST['spesifikasi'] ?? '',
          'kategori' => $_POST['kategori'] ?? $kategori_nama,
          'kode_kategori' => $kode_kategori,
          'tipe_barang' => $_POST['tipe_barang'] ?? 'Habis Pakai',
          'sub_kategori' => $_POST['sub_kategori'] ?? '',
          'satuan_dasar' => $_POST['satuan_dasar'] ?? '',
          'satuan_konversi' => $_POST['satuan_konversi'] ?? '',
          'harga_referensi' => preg_replace('/[^0-9]/', '', $_POST['harga_referensi'] ?? '0'),
          // Keep the enum value populated during edit. Older versions omitted
          // this field from the form payload, which resulted in NULL being
          // written to a NOT NULL column and made the save request hang/fail.
          'jenis_item' => $_POST['jenis_item'] ?? 'Rutin',
          'stok_min' => $_POST['stok_min'] ?? 0,
          'stok_max' => $_POST['stok_max'] ?? 0,
          'safety_stock' => $_POST['safety_stock'] ?? 0,
          'default_kode_lokasi' => !empty($_POST['default_kode_lokasi']) ? $_POST['default_kode_lokasi'] : null,
          'status' => $_POST['status'] ?? 'Aktif'
        ];

        // Logging Feature (wrapped in try-catch so it won't crash saving)
        try {
            $user = $this->core->getUserInfo('username', null, true);
            $tanggal_log = date('Y-m-d H:i:s');
            $ip = $_SERVER['REMOTE_ADDR'];
            $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
            $hostname = $cek_hostname['hostname'] ?? 'Unknown';
            $log_lokasi = '' . $hostname . ' | ' . $ip . '';
            $logdata = '' . $data['kode_item'] . ' | ' . $data['barcode'] . ' | ' . $data['nama_barang'] . ' | ' . $data['deskripsi'] . ' | ' . $data['spesifikasi'] . ' | ' . $data['kategori'] . ' | ' . $data['sub_kategori'] . ' | ' . $data['satuan_dasar'] . ' | ' . $data['satuan_konversi'] . ' | ' . $data['harga_referensi'] . ' | ' . $data['status'] . ' | ' . $user . '';

            $this->db('mlite_tracksql')->save([
              'log_id' => null,
              'log_modul' => 'logistik_non_medis_master_barang',
              'log_waktu' => $tanggal_log,
              'log_location' => $log_lokasi,
              'log_data' => $logdata,
              'log_status' => (isset($_POST['kode_item']) && $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $_POST['kode_item'])->oneArray()) ? 'U' : 'I',
              'log_username' => $user
            ]);
        } catch (\Throwable $e) {
        }

        $upload_dir = UPLOADS . '/logistik_non_medis';
        if (!is_dir($upload_dir)) {
            mkdir($upload_dir, 0777, true);
        }
        if (!is_dir($upload_dir . '/foto')) {
            mkdir($upload_dir . '/foto', 0777, true);
        }
        if (!is_dir($upload_dir . '/dokumen')) {
            mkdir($upload_dir . '/dokumen', 0777, true);
        }

        // Handle File Uploads
        if (isset($_FILES['foto']) && $_FILES['foto']['error'] == 0) {
            $allowed_images = ['jpg', 'jpeg', 'png', 'gif'];
            $ext = strtolower(pathinfo($_FILES['foto']['name'], PATHINFO_EXTENSION));
            if (in_array($ext, $allowed_images)) {
                $filename = 'foto_' . preg_replace('/[^a-zA-Z0-9_-]/', '_', $kode_item) . '_' . time() . '.' . $ext;
                if (move_uploaded_file($_FILES['foto']['tmp_name'], $upload_dir . '/foto/' . $filename)) {
                    $data['foto'] = $filename;
                } else {
                    echo json_encode(['status' => 'error', 'message' => 'Gagal mengupload foto ke server.']);
                    exit();
                }
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Format Foto tidak didukung! Gunakan jpg, jpeg, png, atau gif.']);
                exit();
            }
        }

        if (isset($_FILES['dokumen']) && $_FILES['dokumen']['error'] == 0) {
            $allowed_docs = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'txt', 'zip', 'rar'];
            $ext = strtolower(pathinfo($_FILES['dokumen']['name'], PATHINFO_EXTENSION));
            if (in_array($ext, $allowed_docs)) {
                $filename = 'dok_' . preg_replace('/[^a-zA-Z0-9_-]/', '_', $kode_item) . '_' . time() . '.' . $ext;
                if (move_uploaded_file($_FILES['dokumen']['tmp_name'], $upload_dir . '/dokumen/' . $filename)) {
                    $data['dokumen'] = $filename;
                } else {
                    echo json_encode(['status' => 'error', 'message' => 'Gagal mengupload dokumen ke server.']);
                    exit();
                }
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Format Dokumen tidak didukung! Gunakan pdf, doc, docx, xls, dll.']);
                exit();
            }
        }

        $cek = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $kode_item)->oneArray();

        // VPS lama mungkin belum memiliki kolom yang ditambahkan pada versi baru.
        // Gunakan hanya kolom yang benar-benar tersedia agar insert/update tetap kompatibel.
        $columnRows = $this->db()->pdo()
          ->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_master_barang`")
          ->fetchAll(\PDO::FETCH_ASSOC);
        $existingColumns = array_column($columnRows, 'Field');
        $saveData = array_intersect_key($data, array_flip($existingColumns));
        $saveData['kode_item'] = $kode_item;

        if (!$cek) {
            $columns = array_keys($saveData);
            $quotedColumns = implode(', ', array_map(function ($column) {
                return '`' . str_replace('`', '``', $column) . '`';
            }, $columns));
            $placeholders = implode(', ', array_fill(0, count($columns), '?'));
            $stmt = $this->db()->pdo()->prepare(
                "INSERT INTO `rsns_custom_logistik_non_medis_master_barang` ($quotedColumns) VALUES ($placeholders)"
            );
            $query = $stmt->execute(array_values($saveData));
        } else {
            if (isset($data['foto']) && !empty($cek['foto']) && file_exists($upload_dir . '/foto/' . $cek['foto'])) {
                @unlink($upload_dir . '/foto/' . $cek['foto']);
            }
            if (isset($data['dokumen']) && !empty($cek['dokumen']) && file_exists($upload_dir . '/dokumen/' . $cek['dokumen'])) {
                @unlink($upload_dir . '/dokumen/' . $cek['dokumen']);
            }

            unset($saveData['kode_item']);
            $setSql = "UPDATE `rsns_custom_logistik_non_medis_master_barang` SET " . implode(', ', array_map(function ($column) {
                return '`' . str_replace('`', '``', $column) . '`=?';
            }, array_keys($saveData))) . " WHERE `kode_item`=?";
            $params = array_values($saveData);
            $params[] = $kode_item;

            $stmt = $this->db()->pdo()->prepare($setSql);
            $query = $stmt->execute($params);
        }

        if ($query !== false) {
            echo json_encode(['status' => 'success']);
        } else {
            $error = $stmt->errorInfo();
            error_log('Logistik master barang save failed: ' . ($error[2] ?? 'unknown database error'));
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan data ke database. Periksa log server untuk detailnya.']);
        }
        exit();
    }

    public function postHapusMasterBarang()
    {
        $kode_item = $_POST['kode_item'] ?? '';
        if (empty($kode_item)) {
            echo json_encode(['status' => 'error', 'message' => 'Kode barang tidak boleh kosong.']);
            exit();
        }

        $cek = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $kode_item)->oneArray();
        if ($cek) {
            $upload_dir = UPLOADS . '/logistik_non_medis';
            if (!empty($cek['foto']) && file_exists($upload_dir . '/foto/' . $cek['foto'])) {
                @unlink($upload_dir . '/foto/' . $cek['foto']);
            }
            if (!empty($cek['dokumen']) && file_exists($upload_dir . '/dokumen/' . $cek['dokumen'])) {
                @unlink($upload_dir . '/dokumen/' . $cek['dokumen']);
            }

            // Delete from master_barang using direct PDO prepare/execute
            $stmt = $this->db()->pdo()->prepare("DELETE FROM `rsns_custom_logistik_non_medis_master_barang` WHERE `kode_item` = ?");
            $exec = $stmt->execute([$kode_item]);

            // Also delete from stok_batch if table exists
            try {
                $stmt_stok = $this->db()->pdo()->prepare("DELETE FROM `rsns_custom_logistik_non_medis_stok_batch` WHERE `kode_item` = ?");
                $stmt_stok->execute([$kode_item]);
            } catch (\Throwable $e) {
            }

            if ($exec) {
                echo json_encode(['status' => 'success']);
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Gagal menghapus data dari database.']);
            }
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Data barang tidak ditemukan.']);
        }
        exit();
    }

    public function postBulkDeleteMasterBarang()
    {
        $kode_items = $_POST['kode_items'] ?? [];
        if (empty($kode_items) || !is_array($kode_items)) {
            echo json_encode(['status' => 'error', 'message' => 'Tidak ada barang yang dipilih.']);
            exit();
        }

        $upload_dir = UPLOADS . '/logistik_non_medis';
        $pdo = $this->db()->pdo();
        
        $successCount = 0;
        foreach ($kode_items as $kode_item) {
            $cek = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $kode_item)->oneArray();
            if ($cek) {
                if (!empty($cek['foto']) && file_exists($upload_dir . '/foto/' . $cek['foto'])) {
                    @unlink($upload_dir . '/foto/' . $cek['foto']);
                }
                if (!empty($cek['dokumen']) && file_exists($upload_dir . '/dokumen/' . $cek['dokumen'])) {
                    @unlink($upload_dir . '/dokumen/' . $cek['dokumen']);
                }
                
                $stmt = $pdo->prepare("DELETE FROM `rsns_custom_logistik_non_medis_master_barang` WHERE `kode_item` = ?");
                $exec = $stmt->execute([$kode_item]);
                
                try {
                    $stmt_stok = $pdo->prepare("DELETE FROM `rsns_custom_logistik_non_medis_stok_batch` WHERE `kode_item` = ?");
                    $stmt_stok->execute([$kode_item]);
                } catch (\Throwable $e) {
                }
                
                if ($exec) $successCount++;
            }
        }
        
        echo json_encode(['status' => 'success', 'message' => "$successCount data berhasil dihapus."]);
        exit();
    }

    public function postBulkUpdateCategoryMasterBarang()
    {
        $this->_initDataBarang();
        $this->_initKategori();

        $kode_items = $_POST['kode_items'] ?? [];
        $kode_kategori = trim((string)($_POST['kode_kategori'] ?? ''));
        if (!is_array($kode_items)) {
            $kode_items = [];
        }
        $kode_items = array_values(array_unique(array_filter(array_map(function ($kode_item) {
            return trim((string)$kode_item);
        }, $kode_items), function ($kode_item) {
            return $kode_item !== '';
        })));

        if (empty($kode_items)) {
            echo json_encode(['status' => 'error', 'message' => 'Tidak ada barang yang dipilih.']);
            exit();
        }
        if ($kode_kategori === '') {
            echo json_encode(['status' => 'error', 'message' => 'Kategori tujuan wajib dipilih.']);
            exit();
        }

        $kategori = $this->db('rsns_custom_logistik_non_medis_kategori')
                         ->where('kode_kategori', $kode_kategori)
                         ->oneArray();
        if (!$kategori) {
            echo json_encode(['status' => 'error', 'message' => 'Kategori tujuan tidak ditemukan.']);
            exit();
        }

        $pdo = $this->db()->pdo();
        $placeholders = implode(',', array_fill(0, count($kode_items), '?'));
        $params = array_merge([$kode_kategori, $kategori['nama_kategori']], $kode_items);

        try {
            $pdo->beginTransaction();
            $stmt = $pdo->prepare("UPDATE rsns_custom_logistik_non_medis_master_barang
                                   SET kode_kategori = ?, kategori = ?
                                   WHERE kode_item IN ($placeholders)");
            $stmt->execute($params);
            $changed = $stmt->rowCount();
            $pdo->commit();

            echo json_encode([
              'status' => 'success',
              'message' => count($kode_items) . ' barang diproses; ' . $changed . ' kategori diperbarui.'
            ]);
        } catch (\Throwable $e) {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
            echo json_encode(['status' => 'error', 'message' => 'Gagal memperbarui kategori barang.']);
        }
        exit();
    }


    private function _initVendor()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_vendor` (
        `kode_vendor` varchar(50) NOT NULL,
        `nama_vendor` varchar(200) NOT NULL,
        `alamat` text DEFAULT NULL,
        `no_telp` varchar(50) DEFAULT NULL,
        `email` varchar(100) DEFAULT NULL,
        `website` varchar(100) DEFAULT NULL,
        `npwp` varchar(50) DEFAULT NULL,
        `siup` varchar(50) DEFAULT NULL,
        `status_pkp` enum('PKP','Non PKP') NOT NULL DEFAULT 'Non PKP',
        `nama_bank` varchar(100) DEFAULT NULL,
        `no_rekening` varchar(50) DEFAULT NULL,
        `nama_rekening` varchar(100) DEFAULT NULL,
        `pic_nama` varchar(100) DEFAULT NULL,
        `pic_kontak` varchar(50) DEFAULT NULL,
        `kategori_vendor` varchar(255) DEFAULT NULL,
        `rating` int(1) NOT NULL DEFAULT 0,
        `evaluasi` text DEFAULT NULL,
        `status` enum('Whitelist','Blacklist') NOT NULL DEFAULT 'Whitelist',
        `file_npwp` varchar(255) DEFAULT NULL,
        `file_siup` varchar(255) DEFAULT NULL,
        PRIMARY KEY (`kode_vendor`)
      ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");

        $upload_dir = UPLOADS . '/logistik_non_medis/vendor';
        if (!is_dir($upload_dir)) {
            mkdir($upload_dir, 0777, true);
        }
    }

    private function _generateKodeVendor()
    {
        $prefix = 'VND' . date('Y');
        $last = $this->db('rsns_custom_logistik_non_medis_vendor')
                   ->where('kode_vendor', 'LIKE', $prefix . '%')
                   ->desc('kode_vendor')
                   ->limit(1)
                   ->oneArray();

        if ($last) {
            $last_num = (int) substr($last['kode_vendor'], -4);
            $next_num = str_pad($last_num + 1, 4, '0', STR_PAD_LEFT);
        } else {
            $next_num = '0001';
        }

        return $prefix . $next_num;
    }

