        $data = [
          'kode_vendor' => $kode_vendor,
          'nama_vendor' => $_POST['nama_vendor'] ?? '',
          'alamat' => $_POST['alamat'] ?? '',
          'no_telp' => $_POST['no_telp'] ?? '',
          'email' => $_POST['email'] ?? '',
          'website' => $_POST['website'] ?? '',
          'npwp' => $_POST['npwp'] ?? '',
          'siup' => $_POST['siup'] ?? '',
          'status_pkp' => $_POST['status_pkp'] ?? 'Non PKP',
