    public function getPengadaanPerencanaan()
    {
        $this->_initPerencanaan();
        $this->_initDataBarang();
        $this->_initKategori();
        $this->_addHeaderFiles();

      // Load data langsung tanpa AJAX
        $sql = "
        SELECT p.*,
               COALESCE(NULLIF(p.kelompok_barang, ''), u.nama_unit, p.kode_unit) AS nama_unit,
               b.nama_barang,
               b.satuan_dasar,
               COALESCE(NULLIF(p.kelompok_barang, ''), k.nama_kategori, b.kategori, 'Umum') AS kategori
        FROM rsns_custom_logistik_non_medis_perencanaan p
        LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = p.kode_unit
        LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = p.kode_item
        LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
        ORDER BY p.id DESC
    ";
        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute([]);
        $rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);

      // Pre-kalkulasi agar tidak perlu ekspresi di template
        $perencanaan = [];
        foreach ($rows as $i => $row) {
            $row['no'] = $i + 1;
            $row['estimasi'] = number_format($row['total_qty'] * $row['harga_referensi'], 0, ',', '.');
            $row['bulan'] = isset($row['bulan']) ? $row['bulan'] : date('m');
            $row['kategori'] = isset($row['kategori']) ? $row['kategori'] : 'Umum';
            $row['pemakaian_lalu'] = isset($row['pemakaian_lalu']) ? $row['pemakaian_lalu'] : 0;
            $row['is_disetujui'] = $row['status'] === 'Disetujui';
            $perencanaan[] = $row;
        }

      // Data Konsolidasi (disetujui, dikelompokkan per barang)
        $sql_konsolidasi = "
        SELECT p.kode_item, b.nama_barang, b.satuan_dasar,
               SUM(p.total_qty) as total_qty,
               AVG(p.harga_referensi) as harga_avg
        FROM rsns_custom_logistik_non_medis_perencanaan p
        LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = p.kode_item
        WHERE p.status = 'Disetujui'
        GROUP BY p.kode_item, b.nama_barang, b.satuan_dasar
        ORDER BY total_qty DESC
    ";
        $stmt2 = $this->db()->pdo()->prepare($sql_konsolidasi);
        $stmt2->execute([]);
        $konsolidasi_raw = $stmt2->fetchAll(\PDO::FETCH_ASSOC);
        $konsolidasi = [];
        foreach ($konsolidasi_raw as $i => $row) {
            $row['no'] = $i + 1;
            $row['estimasi'] = number_format($row['total_qty'] * $row['harga_avg'], 0, ',', '.');
            $row['harga_avg_fmt'] = number_format($row['harga_avg'], 0, ',', '.');
            $konsolidasi[] = $row;
        }

      // Data Anggaran (dikelompokkan per kategori)
        $tahun_aktif = date('Y');
        $sql_anggaran = "
        SELECT b.kode_kategori as kategori,
               SUM(p.total_qty * p.harga_referensi) as subtotal
        FROM rsns_custom_logistik_non_medis_perencanaan p
        LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = p.kode_item
        WHERE p.tahun = ?
        GROUP BY b.kode_kategori
        ORDER BY subtotal DESC
    ";
        $stmt3 = $this->db()->pdo()->prepare($sql_anggaran);
        $stmt3->execute([$tahun_aktif]);
        $anggaran_raw = $stmt3->fetchAll(\PDO::FETCH_ASSOC);
        $grand_total = 0;
        $anggaran = [];
        foreach ($anggaran_raw as $i => $row) {
            $grand_total += $row['subtotal'];
            $row['no'] = $i + 1;
            $row['subtotal_fmt'] = number_format($row['subtotal'], 0, ',', '.');
            $anggaran[] = $row;
        }
        $grand_total_fmt = number_format($grand_total, 0, ',', '.');

        return $this->draw('pengadaan.perencanaan.html', [
        'token'          => $_GET['t'] ?? '',
        'perencanaan'    => $perencanaan,
        'konsolidasi'    => $konsolidasi,
        'anggaran'       => $anggaran,
        'grand_total'    => $grand_total_fmt,
        'tahun'          => $tahun_aktif,
        'chart_labels'   => json_encode(array_column($anggaran, 'kategori')),
        'chart_data'     => json_encode(array_column($anggaran, 'subtotal')),
        'js' => '
<script src="https://cdn.jsdelivr.net/npm/chart.js@2.9.4"></script>
<script>
$(document).ready(function() {
    var baseURL = mlite.url + "/" + mlite.admin + "/logistik_non_medis";

    // Chart Struktur Anggaran
    var chartLabels = ' . json_encode(array_column($anggaran, 'kategori')) . ';
    var chartData   = ' . json_encode(array_column($anggaran, 'subtotal')) . ';
    
    if(chartLabels.length > 0 && document.getElementById("chartAnggaran")) {
        var ctx = document.getElementById("chartAnggaran").getContext("2d");
        new Chart(ctx, {
            type: "pie",
            data: {
                labels: chartLabels,
                datasets: [{
                    data: chartData,
                    backgroundColor: [
                        "#3498db","#e74c3c","#2ecc71","#f39c12","#9b59b6",
                        "#1abc9c","#e67e22","#34495e","#e91e63","#00bcd4"
                    ],
                    borderWidth: 2,
                    borderColor: "#fff"
                }]
            },
            options: {
                responsive: true,
                legend: { position: "bottom" },
                tooltips: {
                    callbacks: {
                        label: function(item, data) {
                            var val = data.datasets[0].data[item.index];
                            return data.labels[item.index] + ": Rp. " + val.toLocaleString("id-ID");
                        }
                    }
                }
            }
        });
    }

    // Global listener untuk form perencanaan
    $(document).on("submit", "#formPerencanaan", function(e) {
        e.preventDefault();
        var btn = $("#btnSimpanRKBU");
        var form = $(this);
        btn.prop("disabled", true).html(\'<i class="fa fa-spinner fa-spin"></i> Menyimpan...\');
        
        $.ajax({
            url: form.attr("action"),
            type: "POST",
            data: new FormData(this),
            cache: false,
            contentType: false,
            processData: false,
            success: function(res) {
                try {
                    var data = JSON.parse(res);
                    if(data.status == "success") {
                        $("#modalForm").modal("hide");
                        alert(data.message + " Silakan refresh halaman untuk melihat data terbaru.");
                    } else {
                        alert(data.message);
                        btn.prop("disabled", false).html("Simpan Seluruh Usulan");
                    }
                } catch(err) {
                    alert("Tersimpan. Silakan refresh halaman.");
                    $("#modalForm").modal("hide");
                }
            },
            error: function() {
                alert("Gagal menyimpan. Periksa koneksi Anda.");
                btn.prop("disabled", false).html("Simpan Seluruh Usulan");
            }
        });
    });

    window.tambahRKBU = function() {
        $.post(baseURL + "/formperencanaan?t=" + mlite.token, function(data) {
            $("#form_content").html(data);
            $("#modalForm").modal("show");
        }).fail(function() {
            alert("Gagal memuat form. Periksa koneksi atau sesi login Anda.");
        });
    };

    window.viewRKBU = function(id) {
        $.post(baseURL + "/detailperencanaan?t=" + mlite.token, {id: id}, function(data) {
            $("#form_content").html(data);
            $("#modalForm").modal("show");
        }).fail(function() {
            alert("Gagal memuat detail.");
        });
    };

    window.editRKBU = function(id) {
        $.post(baseURL + "/formperencanaan?t=" + mlite.token, {id: id}, function(data) {
            $("#form_content").html(data);
            $("#modalForm").modal("show");
        });
    };

    window.hapusRKBU = function(id) {
        if(confirm("Apakah Anda yakin ingin menghapus data ini?")) {
            $.post(baseURL + "/hapusperencanaan?t=" + mlite.token, {id: id}, function() {
                window.location.reload();
            });
        }
    };
});
</script>'
        ]);
    }

    public function anyDetailPerencanaan()
    {
        $this->_initPerencanaan();
        $this->_initDataBarang();
        $this->_initKategori();
        $id = $_POST['id'] ?? '';
        $sql = "
          SELECT p.*,
                 COALESCE(NULLIF(p.kelompok_barang, ''), u.nama_unit, p.kode_unit) AS nama_unit,
                 b.nama_barang,
                 b.satuan_dasar,
                 COALESCE(NULLIF(p.kelompok_barang, ''), k.nama_kategori, b.kategori, 'Umum') AS kategori
          FROM rsns_custom_logistik_non_medis_perencanaan p
          LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = p.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = p.kode_item
          LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
          WHERE p.kode_perencanaan = ?
      ";
        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute([$id]);
        $row = $stmt->fetch(\PDO::FETCH_ASSOC);

        if ($row) {
            $row['estimasi'] = number_format($row['total_qty'] * $row['harga_referensi'], 0, ',', '.');
            $row['harga_referensi_fmt'] = number_format($row['harga_referensi'], 0, ',', '.');
        }

        echo $this->draw('perencanaan.detail.html', ['data' => $row]);
        exit();
    }

    public function getExportPerencanaanXlsx()
    {
        $this->_initPerencanaan();
        $this->_initDataBarang();
        $this->_initKategori();

        if (!class_exists('ZipArchive')) {
            http_response_code(500);
            echo 'Ekstensi ZIP PHP diperlukan untuk membuat file XLSX.';
            exit();
        }

        $sql = "SELECT p.*, b.nama_barang, b.satuan_dasar,
                       COALESCE(NULLIF(p.kelompok_barang, ''), k.nama_kategori, b.kategori, 'Umum') AS kategori
                FROM rsns_custom_logistik_non_medis_perencanaan p
                LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = p.kode_item
                LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
                ORDER BY p.tahun DESC, p.bulan DESC, p.kelompok_barang ASC, b.nama_barang ASC";
        $rows = $this->db()->pdo()->query($sql)->fetchAll(\PDO::FETCH_ASSOC);

        $priority_labels = [
          'D' => 'D (Desirable = Diinginkan/Penunjang)',
          'Desirable' => 'D (Desirable = Diinginkan/Penunjang)',
          'E' => 'E (Essential = Penting/Kebutuhan Utama)',
          'Essential' => 'E (Essential = Penting/Kebutuhan Utama)',
          'V' => 'V (Vital = Sangat Penting/Kritis)',
          'Vital' => 'V (Vital = Sangat Penting/Kritis)'
        ];
        $headers = [
          'No', 'Periode', 'Kelompok Barang', 'Kategori', 'Kode Barang', 'Nama Barang',
          'Pemakaian Bulan Lalu', 'Rencana Qty', 'Satuan', 'Harga Referensi',
          'Total Estimasi', 'Prioritas', 'Status'
        ];
        $sheet_rows = [];
        $merges = ['A1:M1', 'A2:M2', 'A3:M3'];
        $sheet_rows[] = '<row r="1" ht="28"><c r="A1" s="1" t="inlineStr"><is><t>LAPORAN USULAN PERENCANAAN KEBUTUHAN (RKBU)</t></is></c></row>';
        $sheet_rows[] = '<row r="2" ht="22"><c r="A2" s="1" t="inlineStr"><is><t>RUMAH SAKIT UMUM NURUSSYIFA</t></is></c></row>';
        $sheet_rows[] = '<row r="3" ht="20"><c r="A3" s="2" t="inlineStr"><is><t>' . $this->_xlsxEscape('Diekspor pada ' . date('d-m-Y H:i') . ' | Total ' . count($rows) . ' item') . '</t></is></c></row>';
        $sheet_rows[] = '<row r="4"/>';

        $header_cells = '';
        foreach ($headers as $index => $header) {
            $cell = $this->_xlsxColumnName($index + 1) . '5';
            $header_cells .= '<c r="' . $cell . '" s="3" t="inlineStr"><is><t>' . $this->_xlsxEscape($header) . '</t></is></c>';
        }
        $sheet_rows[] = '<row r="5" ht="34">' . $header_cells . '</row>';

        $grand_total = 0;
        foreach ($rows as $index => $row) {
            $row_number = $index + 6;
            $harga = (float)($row['harga_referensi'] ?? 0);
            $qty = (float)($row['total_qty'] ?? 0);
            $estimasi = $harga * $qty;
            $grand_total += $estimasi;
            $values = [
              $index + 1,
              str_pad((string)($row['bulan'] ?? ''), 2, '0', STR_PAD_LEFT) . '/' . ($row['tahun'] ?? ''),
              $row['kelompok_barang'] ?? '',
              $row['kategori'] ?? '',
              $row['kode_item'] ?? '',
              $row['nama_barang'] ?? '',
              (float)($row['pemakaian_lalu'] ?? 0),
              $qty,
              $row['satuan_dasar'] ?? '',
              $harga,
              $estimasi,
              $priority_labels[$row['prioritas'] ?? ''] ?? ($row['prioritas'] ?? ''),
              $row['status'] ?? ''
            ];

            $cells = '';
            foreach ($values as $column_index => $value) {
                $column_number = $column_index + 1;
                $reference = $this->_xlsxColumnName($column_number) . $row_number;
                $style = 4;
                if (in_array($column_number, [1,7,8], true)) {
                    $style = 5;
                } elseif (in_array($column_number, [10,11], true)) {
                    $style = 6;
                }
                if (is_numeric($value) && in_array($column_number, [1,7,8,10,11], true)) {
                    $cells .= '<c r="' . $reference . '" s="' . $style . '"><v>' . (0 + $value) . '</v></c>';
                } else {
                    $cells .= '<c r="' . $reference . '" s="' . $style . '" t="inlineStr"><is><t xml:space="preserve">' . $this->_xlsxEscape($value) . '</t></is></c>';
                }
            }
            $sheet_rows[] = '<row r="' . $row_number . '">' . $cells . '</row>';
        }

        $total_row = count($rows) + 6;
        $merges[] = 'A' . $total_row . ':J' . $total_row;
        $merges[] = 'K' . $total_row . ':M' . $total_row;
        $sheet_rows[] = '<row r="' . $total_row . '" ht="24">'
          . '<c r="A' . $total_row . '" s="7" t="inlineStr"><is><t>GRAND TOTAL ESTIMASI ANGGARAN</t></is></c>'
          . '<c r="K' . $total_row . '" s="7"><v>' . $grand_total . '</v></c></row>';

        $legend_start = $total_row + 2;
        $legends = [
          'D = Diinginkan/Penunjang: kebutuhan pendukung yang masih dapat ditunda.',
          'E = Penting/Kebutuhan Utama: dibutuhkan agar pelayanan tidak terganggu.',
          'V = Sangat Penting/Kritis: wajib diprioritaskan karena berpengaruh langsung pada pelayanan.'
        ];
        foreach ($legends as $offset => $legend) {
            $row_number = $legend_start + $offset;
            $merges[] = 'A' . $row_number . ':M' . $row_number;
            $sheet_rows[] = '<row r="' . $row_number . '" ht="22"><c r="A' . $row_number . '" s="8" t="inlineStr"><is><t>' . $this->_xlsxEscape($legend) . '</t></is></c></row>';
        }

        $signature_row = $legend_start + 5;
        foreach ([$signature_row, $signature_row + 1, $signature_row + 2] as $row_number) {
            $merges[] = 'A' . $row_number . ':D' . $row_number;
            $merges[] = 'E' . $row_number . ':I' . $row_number;
            $merges[] = 'J' . $row_number . ':M' . $row_number;
        }
        $sheet_rows[] = '<row r="' . $signature_row . '" ht="34">'
          . '<c r="A' . $signature_row . '" s="9" t="inlineStr"><is><t>Disusun oleh,&#10;Petugas Logistik</t></is></c>'
          . '<c r="E' . $signature_row . '" s="9" t="inlineStr"><is><t>Diperiksa oleh,&#10;Bagian Keuangan</t></is></c>'
          . '<c r="J' . $signature_row . '" s="9" t="inlineStr"><is><t>Mengetahui,&#10;Kabid Umum</t></is></c></row>';
        $sheet_rows[] = '<row r="' . ($signature_row + 1) . '" ht="65">'
          . '<c r="A' . ($signature_row + 1) . '" s="9"/><c r="E' . ($signature_row + 1) . '" s="9"/><c r="J' . ($signature_row + 1) . '" s="9"/></row>';
        $sheet_rows[] = '<row r="' . ($signature_row + 2) . '" ht="24">'
          . '<c r="A' . ($signature_row + 2) . '" s="9" t="inlineStr"><is><t>(........................................)</t></is></c>'
          . '<c r="E' . ($signature_row + 2) . '" s="9" t="inlineStr"><is><t>(........................................)</t></is></c>'
          . '<c r="J' . ($signature_row + 2) . '" s="9" t="inlineStr"><is><t>(........................................)</t></is></c></row>';

        $merge_xml = '';
        foreach ($merges as $merge) {
            $merge_xml .= '<mergeCell ref="' . $merge . '"/>';
        }
        $sheet_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          . '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
          . '<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>'
          . '<sheetViews><sheetView workbookViewId="0"><pane ySplit="5" topLeftCell="A6" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>'
          . '<cols><col min="1" max="1" width="6" customWidth="1"/><col min="2" max="2" width="12" customWidth="1"/>'
          . '<col min="3" max="4" width="22" customWidth="1"/><col min="5" max="5" width="18" customWidth="1"/>'
          . '<col min="6" max="6" width="32" customWidth="1"/><col min="7" max="8" width="15" customWidth="1"/>'
          . '<col min="9" max="9" width="12" customWidth="1"/><col min="10" max="11" width="19" customWidth="1"/>'
          . '<col min="12" max="12" width="28" customWidth="1"/><col min="13" max="13" width="14" customWidth="1"/></cols>'
          . '<sheetData>' . implode('', $sheet_rows) . '</sheetData>'
          . '<autoFilter ref="A5:M' . max(5, count($rows) + 5) . '"/>'
          . '<mergeCells count="' . count($merges) . '">' . $merge_xml . '</mergeCells>'
          . '<pageMargins left="0.25" right="0.25" top="0.5" bottom="0.5" header="0.2" footer="0.2"/>'
          . '<pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>';

        $styles_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          . '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
          . '<numFmts count="1"><numFmt numFmtId="164" formatCode="&quot;Rp&quot; #,##0"/></numFmts>'
          . '<fonts count="5"><font><sz val="10"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="10"/><name val="Calibri"/></font><font><b/><sz val="14"/><name val="Calibri"/></font><font><i/><color rgb="FF555555"/><sz val="10"/><name val="Calibri"/></font><font><b/><sz val="10"/><name val="Calibri"/></font></fonts>'
          . '<fills count="5"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF337AB7"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFD9EDF7"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFDFF0D8"/></patternFill></fill></fills>'
          . '<borders count="2"><border/><border><left style="thin"><color rgb="FFBFBFBF"/></left><right style="thin"><color rgb="FFBFBFBF"/></right><top style="thin"><color rgb="FFBFBFBF"/></top><bottom style="thin"><color rgb="FFBFBFBF"/></bottom></border></borders>'
          . '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
          . '<cellXfs count="10">'
          . '<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>'
          . '<xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf>'
          . '<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf>'
          . '<xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf>'
          . '<xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf>'
          . '<xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf>'
          . '<xf numFmtId="164" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyAlignment="1"><alignment horizontal="right" vertical="center"/></xf>'
          . '<xf numFmtId="164" fontId="4" fillId="4" borderId="1" xfId="0" applyNumberFormat="1" applyAlignment="1"><alignment horizontal="right" vertical="center"/></xf>'
          . '<xf numFmtId="0" fontId="3" fillId="3" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf>'
          . '<xf numFmtId="0" fontId="4" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf>'
          . '</cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>';

        $temporary_file = tempnam(sys_get_temp_dir(), 'rkbu_xlsx_');
        $zip = new \ZipArchive();
        if (!$temporary_file || $zip->open($temporary_file, \ZipArchive::CREATE | \ZipArchive::OVERWRITE) !== true) {
            http_response_code(500);
            echo 'File XLSX tidak dapat dibuat.';
            exit();
        }
        $zip->addFromString('[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/></Types>');
        $zip->addFromString('_rels/.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>');
        $zip->addFromString('xl/workbook.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Laporan RKBU" sheetId="1" r:id="rId1"/></sheets></workbook>');
        $zip->addFromString('xl/_rels/workbook.xml.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
        $zip->addFromString('xl/worksheets/sheet1.xml', $sheet_xml);
        $zip->addFromString('xl/styles.xml', $styles_xml);
        $zip->addFromString('docProps/core.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>Laporan RKBU RSU Nurussyifa</dc:title><dc:creator>mLITE RSU Nurussyifa</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">' . gmdate('Y-m-d\TH:i:s\Z') . '</dcterms:created></cp:coreProperties>');
        $zip->close();

        while (ob_get_level() > 0) {
            ob_end_clean();
        }
        $filename = 'Laporan_RKBU_RSU_Nurussyifa_' . date('Ymd_His') . '.xlsx';
        header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        header('Content-Disposition: attachment; filename="' . $filename . '"');
        header('Content-Length: ' . filesize($temporary_file));
        header('Cache-Control: max-age=0, must-revalidate');
        readfile($temporary_file);
        unlink($temporary_file);
        exit();
    }

    public function postSetujuiPerencanaan()
    {
        $this->_initPerencanaan();
        $id = trim((string)($_POST['id'] ?? ''));
        if ($id === '') {
            echo json_encode(['status' => 'error', 'message' => 'Data perencanaan tidak ditemukan.']);
            exit();
        }

        $row = $this->db('rsns_custom_logistik_non_medis_perencanaan')->where('id', $id)->oneArray();
        if (!$row) {
            echo json_encode(['status' => 'error', 'message' => 'Data perencanaan tidak ditemukan.']);
            exit();
        }
        $ok = $this->db('rsns_custom_logistik_non_medis_perencanaan')
                 ->where('id', $id)
                 ->update(['status' => 'Disetujui']);
        echo json_encode($ok
          ? ['status' => 'success', 'message' => 'Perencanaan berhasil disetujui.']
          : ['status' => 'error', 'message' => 'Gagal menyetujui perencanaan.']);
        exit();
    }

    public function postBulkpopperencanaan()
    {
        $this->_initPerencanaan();
        $this->_initPo();
        $ids = $_POST['ids'] ?? [];
        if (!is_array($ids)) {
            $ids = [$ids];
        }
        $ids = array_values(array_filter(array_map('intval', $ids)));
        if (empty($ids)) {
            echo json_encode(['status' => 'error', 'message' => 'Pilih minimal satu perencanaan.']);
            exit();
        }

        $placeholders = implode(',', array_fill(0, count($ids), '?'));
        $stmt = $this->db()->pdo()->prepare("SELECT p.*, b.nama_barang, b.satuan_dasar
          FROM rsns_custom_logistik_non_medis_perencanaan p
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = p.kode_item
          WHERE p.id IN ($placeholders) AND p.status = 'Disetujui'
          ORDER BY p.id ASC");
        $stmt->execute($ids);
        $rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        if (empty($rows)) {
            $statusStmt = $this->db()->pdo()->prepare("SELECT id, status FROM rsns_custom_logistik_non_medis_perencanaan WHERE id IN ($placeholders)");
            $statusStmt->execute($ids);
            $statusRows = $statusStmt->fetchAll(\PDO::FETCH_ASSOC);
            $statusInfo = [];
            foreach ($statusRows as $statusRow) {
                $statusInfo[] = '#' . $statusRow['id'] . ': ' . ($statusRow['status'] ?: 'tanpa status');
            }
            $detailStatus = $statusInfo ? ' Status item: ' . implode(', ', $statusInfo) . '.' : ' ID perencanaan tidak ditemukan.';
            echo json_encode(['status' => 'error', 'message' => 'Hanya perencanaan berstatus Disetujui yang dapat dibuat menjadi PO draft.' . $detailStatus]);
            exit();
        }

        $marker = 'Auto generated from RKBU: ' . implode(',', $ids);
        $existing = $this->db()->pdo()->prepare("SELECT no_po FROM rsns_custom_logistik_non_medis_po WHERE catatan LIKE ? LIMIT 1");
        $existing->execute(['%' . $marker . '%']);
        $old = (string)($existing->fetchColumn() ?: '');
        if ($old !== '') {
            echo json_encode(['status' => 'success', 'no_po' => $old, 'message' => 'PO draft untuk pilihan tersebut sudah tersedia.']);
            exit();
        }

        $detail = [];
        $total = 0;
        foreach ($rows as $row) {
            $qty = (float)$row['total_qty'];
            $harga = (float)$row['harga_referensi'];
            if ($qty <= 0) {
                continue;
            }
            $subtotal = $qty * $harga;
            $total += $subtotal;
            $detail[] = [
              'kode_item' => $row['kode_item'],
              'nama_barang' => $row['nama_barang'] ?: $row['kode_item'],
              'qty_pesan' => $qty,
              'jumlah' => $qty,
              'satuan' => $row['satuan_dasar'] ?: '-',
              'harga_satuan' => $harga,
              'harga' => $harga,
              'subtotal' => $subtotal,
              'sumber_perencanaan' => $row['kode_perencanaan']
            ];
        }
        if (empty($detail)) {
            echo json_encode(['status' => 'error', 'message' => 'Tidak ada jumlah barang yang dapat dibuat menjadi PO.']);
            exit();
        }

        try {
            $no_po = $this->_generateNoPO('BELUM-DITENTUKAN');
        } catch (\Throwable $e) {
            error_log('Generate nomor PO RKBU gagal: ' . $e->getMessage());
            echo json_encode(['status' => 'error', 'message' => 'Gagal membuat nomor PO: ' . $e->getMessage()]);
            exit();
        }
        try {
            $detailJson = json_encode($detail);
            if ($detailJson === false) {
                throw new \RuntimeException('Detail item PO tidak dapat dikonversi ke format JSON.');
            }
            $insert = $this->db()->pdo()->prepare("INSERT INTO rsns_custom_logistik_non_medis_po
              (no_po, tgl_po, kode_vendor, total_nilai, diskon, ppn, grand_total, detail_items, catatan, status, user_input)
              VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
            $saved = $insert->execute([
              $no_po,
              date('Y-m-d'),
              'BELUM-DITENTUKAN',
              $total,
              0,
              0,
              $total,
              $detailJson,
              $marker,
              'Draft',
              $this->core->getUserInfo('username', null, true)
            ]);
            if (!$saved) {
                $error = $insert->errorInfo();
                throw new \RuntimeException($error[2] ?? 'Database menolak penyimpanan PO.');
            }
        } catch (\Throwable $e) {
            error_log('Bulk PO RKBU gagal: ' . $e->getMessage());
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan PO draft: ' . $e->getMessage()]);
            exit();
        }
        echo json_encode($saved
          ? ['status' => 'success', 'no_po' => $no_po, 'message' => 'PO draft berhasil dibuat. Pilih vendor pada menu PO.']
          : ['status' => 'error', 'message' => 'Gagal membuat PO draft: database tidak menerima penyimpanan data.']);
        exit();
    }

    public function anyDisplayPerencanaan()
    {
        $this->_initPerencanaan();
        $this->_initDataBarang();
        $this->_initKategori();
        $perpage = 10;
        $halaman = isset($_POST['halaman']) ? (int)$_POST['halaman'] : 1;
        $cari = isset($_POST['cari']) ? $_POST['cari'] : '';
        $tahun = isset($_POST['tahun']) ? $_POST['tahun'] : '';

        $_offset = ($halaman - 1) * $perpage;

        $sql = "
          SELECT p.*,
                 COALESCE(NULLIF(p.kelompok_barang, ''), u.nama_unit, p.kode_unit) AS nama_unit,
                 b.nama_barang,
                 b.satuan_dasar,
                 COALESCE(NULLIF(p.kelompok_barang, ''), k.nama_kategori, b.kategori, 'Umum') AS kategori
          FROM rsns_custom_logistik_non_medis_perencanaan p
          LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = p.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = p.kode_item
          LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
          WHERE 1=1
      ";

        $params = [];

        if (!empty($tahun)) {
            $sql .= " AND p.tahun = ? ";
            $params[] = $tahun;
        }

        if (!empty($cari)) {
            $sql .= " AND (p.kode_perencanaan LIKE ? OR u.nama_unit LIKE ? OR p.kelompok_barang LIKE ? OR b.nama_barang LIKE ?) ";
            $params[] = '%' . $cari . '%';
            $params[] = '%' . $cari . '%';
            $params[] = '%' . $cari . '%';
            $params[] = '%' . $cari . '%';
        }

        $sql .= " ORDER BY p.id DESC ";

        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute($params);
        $all_data = $stmt->fetchAll(\PDO::FETCH_ASSOC);

        $jumlah_data = count($all_data);
        $jml_halaman = $jumlah_data > 0 ? ceil($jumlah_data / $perpage) : 1;
        $rows = array_slice($all_data, $_offset, $perpage);


        echo $this->draw('perencanaan.display.html', [
          'perencanaan' => $rows,
          'halaman' => $halaman,
          'jumlah_data' => $jumlah_data,
          'jml_halaman' => $jml_halaman,
          'admin_mode' => $this->settings->get('settings.admin_mode')
        ]);
        exit();
    }

    public function anyFormPerencanaan()
    {
        $this->_initPerencanaan();
        $this->_initUnit();
        $this->_initDataBarang();
        $this->_initKategori();

        // Jika ada data POST, maka ini adalah proses SIMPAN
        if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['items'])) {
            $kelompok_barang = trim($_POST['kelompok_barang'] ?? '');
            $kode_unit = '';
            $bulan = $_POST['bulan'] ?? date('m');
            $tahun = $_POST['tahun'] ?? date('Y');
            $status = $_POST['status'] ?? 'Draft';
            $items = $_POST['items'] ?? [];
            $kode_perencanaan_original = $_POST['kode_perencanaan_original'] ?? '';

            if (empty($kelompok_barang) || empty($items)) {
                echo json_encode(['status' => 'error', 'message' => 'Kelompok barang dan barang minimal harus diisi satu!']);
                exit();
            }

            $kode_unit = 'RUTIN-' . $this->_normalizeKodeKelompokPerencanaan($kelompok_barang);

            $kode_perencanaan = $this->_generateKodePerencanaan($kode_unit, $tahun, $bulan);
            $user = $this->core->getUserInfo('username', null, true);
            $tanggal = date('Y-m-d H:i:s');

            if (!empty($kode_perencanaan_original)) {
                $this->db('rsns_custom_logistik_non_medis_perencanaan')
                   ->where('kode_perencanaan', $kode_perencanaan_original)
                   ->delete();
            } else {
                $this->db('rsns_custom_logistik_non_medis_perencanaan')
                   ->where('kelompok_barang', $kelompok_barang)
                   ->where('bulan', $bulan)
                   ->where('tahun', $tahun)
                   ->delete();
            }

            $success_count = 0;
            foreach ($items as $item) {
                if (empty($item['kode_item'])) {
                    continue;
                }

                $data = [
                  'kode_perencanaan' => $kode_perencanaan,
                  'kode_unit' => $kode_unit,
                  'kelompok_barang' => $kelompok_barang,
                  'bulan' => $bulan,
                  'tahun' => $tahun,
                  'kode_item' => $item['kode_item'],
                  'pemakaian_lalu' => $item['pemakaian_lalu'] ?? 0,
                  'total_qty' => $item['total_qty'] ?? 0,
                  'harga_referensi' => str_replace(['Rp. ', 'Rp.', '.', ' '], '', $item['harga_referensi'] ?? 0),
                  'prioritas' => $item['prioritas'] ?? 'Desirable',
                  'status' => $status,
                  'tgl_input' => $tanggal,
                  'user_input' => $user
                ];

                if ($this->db('rsns_custom_logistik_non_medis_perencanaan')->save($data)) {
                    $success_count++;
                }
            }

            if ($success_count > 0) {
                // Logging
                $ip = $_SERVER['REMOTE_ADDR'];
                $hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray()['hostname'] ?? 'Unknown';
                $this->db('mlite_tracksql')->save([
                  'log_id' => null,
                  'log_modul' => 'logistik_non_medis_perencanaan',
                  'log_waktu' => date('Y-m-d H:i:s'),
                  'log_location' => $hostname . ' | ' . $ip,
                  'log_data' => 'Save Perencanaan: ' . $kode_perencanaan . ' | Kelompok: ' . $kelompok_barang . ' | Periode: ' . $bulan . '/' . $tahun . ' | Status: ' . $status . ' | ' . $user,
                  'log_status' => 'I',
                  'log_username' => $user
                ]);
                echo json_encode(['status' => 'success', 'message' => $success_count . ' item berhasil disimpan.']);
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan data barang.']);
            }
            exit();
        }

        $items = $this->db()->pdo()->query("
          SELECT b.*,
                 COALESCE(NULLIF(k.nama_kategori, ''), NULLIF(b.kategori, ''), b.kode_kategori) AS kelompok_barang
          FROM rsns_custom_logistik_non_medis_master_barang b
          LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
          ORDER BY COALESCE(k.nama_kategori, b.kategori, b.kode_kategori), b.nama_barang
      ")->fetchAll(\PDO::FETCH_ASSOC);
        $kelompok_barang = $this->db()->pdo()->query("
          SELECT DISTINCT kategori
          FROM (
              SELECT COALESCE(NULLIF(k.nama_kategori, ''), NULLIF(b.kategori, ''), b.kode_kategori) AS kategori
              FROM rsns_custom_logistik_non_medis_master_barang b
              LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
              WHERE COALESCE(NULLIF(k.nama_kategori, ''), NULLIF(b.kategori, ''), b.kode_kategori) IS NOT NULL
                AND COALESCE(NULLIF(k.nama_kategori, ''), NULLIF(b.kategori, ''), b.kode_kategori) <> ''
              UNION
              SELECT nama_kategori AS kategori
              FROM rsns_custom_logistik_non_medis_kategori
              WHERE nama_kategori IS NOT NULL AND nama_kategori <> ''
          ) kelompok
          ORDER BY kategori ASC
      ")->fetchAll(\PDO::FETCH_COLUMN);

        if (isset($_POST['id'])) {
            $ref = $this->db('rsns_custom_logistik_non_medis_perencanaan')->where('kode_perencanaan', $_POST['id'])->oneArray();
            $perencanaan_list = [];
            if ($ref) {
                $perencanaan_list = $this->db('rsns_custom_logistik_non_medis_perencanaan')
                                       ->where('kode_perencanaan', $_POST['id'])
                                       ->toArray();
                if (empty($ref['kelompok_barang']) && !empty($ref['kode_item'])) {
                    $stmt_barang_ref = $this->db()->pdo()->prepare("
                      SELECT COALESCE(NULLIF(k.nama_kategori, ''), NULLIF(b.kategori, ''), b.kode_kategori) AS kelompok_barang
                      FROM rsns_custom_logistik_non_medis_master_barang b
                      LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
                      WHERE b.kode_item = ?
                  ");
                    $stmt_barang_ref->execute([$ref['kode_item']]);
                    $ref['kelompok_barang'] = $stmt_barang_ref->fetchColumn() ?: '';
                }
                foreach ($perencanaan_list as &$row_perencanaan) {
                    if (empty($row_perencanaan['kelompok_barang'])) {
                        $row_perencanaan['kelompok_barang'] = $ref['kelompok_barang'] ?? '';
                    }
                }
                unset($row_perencanaan);
            }
            echo $this->draw('perencanaan.form.html', [
              'perencanaan' => $ref,
              'perencanaan_list' => $perencanaan_list,
              'mode' => 'edit',
              'kelompok_barang' => $kelompok_barang,
              'items' => $items,
              'token' => $_GET['t'] ?? ''
            ]);
        } else {
            $perencanaan = [
              'id' => '', 'kode_perencanaan' => '', 'kode_unit' => '', 'kelompok_barang' => '', 'tahun' => date('Y'), 'kode_item' => '',
              'jan' => 0, 'feb' => 0, 'mar' => 0, 'apr' => 0, 'mei' => 0, 'jun' => 0,
              'jul' => 0, 'agu' => 0, 'sep' => 0, 'okt' => 0, 'nov' => 0, 'des' => 0,
              'total_qty' => 0, 'harga_referensi' => 0, 'prioritas' => 'Desirable', 'status' => 'Draft'
            ];
            echo $this->draw('perencanaan.form.html', [
              'perencanaan' => $perencanaan,
              'mode' => 'add',
              'kelompok_barang' => $kelompok_barang,
              'items' => $items,
              'token' => $_GET['t'] ?? ''
            ]);
        }
        exit();
    }


    public function postHapusPerencanaan()
    {
        $id = $_POST['id'] ?? '';
        if ($id) {
            $cek = $this->db('rsns_custom_logistik_non_medis_perencanaan')->where('kode_perencanaan', $id)->oneArray();
            if ($cek) {
                $this->db('rsns_custom_logistik_non_medis_perencanaan')->where('kode_perencanaan', $id)->delete();

                // Logging
                try {
                    $user = $this->core->getUserInfo('username', null, true);
                    $ip = $_SERVER['REMOTE_ADDR'];
                    $hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray()['hostname'] ?? 'Unknown';
                    $this->db('mlite_tracksql')->save([
                    'log_id' => null,
                    'log_modul' => 'logistik_non_medis_perencanaan',
                    'log_waktu' => date('Y-m-d H:i:s'),
                    'log_location' => $hostname . ' | ' . $ip,
                    'log_data' => 'Delete Perencanaan: ' . $id,
                    'log_status' => 'D',
                    'log_username' => $user
                    ]);
                } catch (\Throwable $e) {
                }

                echo json_encode(['status' => 'success']);
            }
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Data perencanaan tidak ditemukan.']);
        }
        exit();
    }

    public function anyKonsolidasiData()
    {
        $tahun = $_POST['tahun'] ?? date('Y');
        $rows = $this->db('rsns_custom_logistik_non_medis_perencanaan')
                   ->join('rsns_custom_logistik_non_medis_master_barang', 'rsns_custom_logistik_non_medis_master_barang.kode_item = rsns_custom_logistik_non_medis_perencanaan.kode_item')
                   ->select('rsns_custom_logistik_non_medis_perencanaan.kode_item')
                   ->select('rsns_custom_logistik_non_medis_master_barang.nama_barang')
                   ->select('rsns_custom_logistik_non_medis_master_barang.satuan_dasar')
                   ->select('SUM(rsns_custom_logistik_non_medis_perencanaan.total_qty) AS total_qty')
                   ->select('AVG(rsns_custom_logistik_non_medis_perencanaan.harga_referensi) AS harga_avg')
                   ->where('rsns_custom_logistik_non_medis_perencanaan.tahun', $tahun)
                   ->where('rsns_custom_logistik_non_medis_perencanaan.status', 'Disetujui')
                   ->group('rsns_custom_logistik_non_medis_perencanaan.kode_item')
                   ->toArray();

        echo $this->draw('perencanaan.konsolidasi.html', ['data' => $rows, 'tahun' => $tahun]);
        exit();
    }

    public function anyAnggaranData()
    {
        $tahun = $_POST['tahun'] ?? date('Y');
        $rows = $this->db('rsns_custom_logistik_non_medis_perencanaan')
                   ->join('rsns_custom_logistik_non_medis_master_barang', 'rsns_custom_logistik_non_medis_master_barang.kode_item = rsns_custom_logistik_non_medis_perencanaan.kode_item')
                   ->select('rsns_custom_logistik_non_medis_master_barang.kategori')
                   ->select('SUM(rsns_custom_logistik_non_medis_perencanaan.total_qty * rsns_custom_logistik_non_medis_perencanaan.harga_referensi) AS subtotal')
                   ->where('rsns_custom_logistik_non_medis_perencanaan.tahun', $tahun)
                   ->where('rsns_custom_logistik_non_medis_perencanaan.status', 'Disetujui')
                   ->group('rsns_custom_logistik_non_medis_master_barang.kategori')
                   ->toArray();

        $grand_total = 0;
        foreach ($rows as $row) {
            $grand_total += (double)$row['subtotal'];
        }

        echo $this->draw('perencanaan.anggaran.html', ['data' => $rows, 'tahun' => $tahun, 'grand_total' => $grand_total]);
        exit();
    }

