    public function getPengadaanPr()
    {
        $this->_initPR();
        $this->_addHeaderFiles();

        $js_auto = '';
        if (isset($_GET['action']) && $_GET['action'] == 'add_from_katalog') {
            $katalog_id = $_GET['katalog_id'] ?? '';
