                $tanggal_log = date('Y-m-d H:i:s');
                $ip = $_SERVER['REMOTE_ADDR'];
                $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
                $hostname = $cek_hostname['hostname'] ?? 'Unknown';
                $log_lokasi = '' . $hostname . ' | ' . $ip . '';
                $logdata = '' . $data['kode_vendor'] . ' | ' . $data['jenis_record'] . ' | ' . $data['tgl_record'] . ' | ' . $data['nomor_dokumen'] . ' | ' . $data['nilai_nominal'] . ' | ' . $data['total_skor'] . ' | ' . $user . '';

                $this->db('mlite_tracksql')->save([
                  'log_id' => null,
                  'log_modul' => 'logistik_non_medis_vendor_evaluasi',
                  'log_waktu' => $tanggal_log,
                  'log_location' => $log_lokasi,
                  'log_data' => $logdata,
                  'log_status' => 'D',
                  'log_username' => $user
                ]);
            } catch (\Throwable $e) {
            }

            $stmt = $this->db()->pdo()->prepare("DELETE FROM `rsns_custom_logistik_non_medis_vendor_evaluasi` WHERE `id` = ?");
            $exec = $stmt->execute([$id]);

            if ($exec !== false) {
                echo json_encode(['status' => 'success']);
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Gagal menghapus data evaluasi vendor.']);
            }
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Data tidak ditemukan']);
        }
        exit();
    }

    private function _initHostnameTable()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_hostsname_pc` (
        `ip` varchar(50) NOT NULL,
        `hostname` varchar(100) NOT NULL,
        PRIMARY KEY (`ip`)
      ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");
    }

    private function _initPo()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_po` (
        `id` int(11) NOT NULL AUTO_INCREMENT,
        `no_po` varchar(50) NOT NULL,
        `tgl_po` date NOT NULL,
        `kode_vendor` varchar(50) NOT NULL,
        PRIMARY KEY (`id`),
        UNIQUE KEY `no_po` (`no_po`)
      ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");

        $columns = [
          'total_nilai' => "DOUBLE NOT NULL DEFAULT 0 AFTER kode_vendor",
          'diskon' => "DOUBLE NOT NULL DEFAULT 0 AFTER total_nilai",
          'ppn' => "DOUBLE NOT NULL DEFAULT 0 AFTER diskon",
          'grand_total' => "DOUBLE NOT NULL DEFAULT 0 AFTER ppn",
          'detail_items' => "LONGTEXT NOT NULL AFTER grand_total",
          'catatan' => "TEXT NULL AFTER detail_items",
          'status' => "ENUM('Draft','Terkirim','Sebagian Diterima','Selesai','Diamandemen','Dibatalkan') NOT NULL DEFAULT 'Draft' AFTER catatan",
          'tgl_kirim' => "DATETIME NULL AFTER status",
          'file_po' => "VARCHAR(255) NULL AFTER tgl_kirim",
          'user_input' => "VARCHAR(100) NULL AFTER file_po"
        ];

        foreach ($columns as $col => $def) {
            try {
                $checkColumn = $this->db()->pdo()->prepare("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_po` LIKE ?");
                $checkColumn->execute([$col]);
                if (!$checkColumn->fetch()) {
                    $this->db()->pdo()->exec("ALTER TABLE `rsns_custom_logistik_non_medis_po` ADD `$col` $def");
                }
            } catch (\Exception $e) {
                // Jangan hentikan halaman bila migrasi opsional gagal.
            }
        }

        $upload_dir = UPLOADS . '/logistik_non_medis/po';
        if (!is_dir($upload_dir)) {
            mkdir($upload_dir, 0777, true);
        }
    }

    private function _generateNoPO(string $kode_vendor)
    {
        $prefix = 'PO/' . date('Ym') . '/' . $kode_vendor . '/';
        $last = $this->db('rsns_custom_logistik_non_medis_po')
                   ->where('no_po', 'LIKE', $prefix . '%')
                   ->desc('no_po')
                   ->limit(1)
                   ->oneArray();

        if ($last) {
            $parts = explode('/', $last['no_po']);
            $last_num = (int) end($parts);
            $next_num = str_pad($last_num + 1, 4, '0', STR_PAD_LEFT);
        } else {
            $next_num = '0001';
        }

        return $prefix . $next_num;
    }

    public function getPengadaanpo()
    {
        $this->_initPo();
        $this->_addHeaderFiles();

      // Render form awal dari server agar tab "Buat PO Baru" tidak bergantung
      // pada request AJAX yang dapat terlewat ketika halaman dibuka via hash.
        $vendors = $this->db('rsns_custom_logistik_non_medis_vendor')->toArray();
        $barang = [];
        foreach ($this->db('rsns_custom_logistik_non_medis_master_barang')->toArray() as $row) {
            $barang[$row['kode_item']] = $row['nama_barang'];
        }
        $formData = [
        'id' => '',
        'no_po' => 'AUTO',
        'tgl_po' => date('Y-m-d'),
        'kode_vendor' => '',
        'total_nilai' => 0,
        'diskon' => 0,
        'ppn' => 0,
        'grand_total' => 0,
        'status' => 'Draft',
        'tgl_kirim' => '',
        'catatan' => '',
        'items' => [],
        'sumber_tipe' => '',
        'no_rencana' => ''
        ];
        $formMode = 'add';
        $requestedNoPo = trim((string)($_GET['no_po'] ?? ''));
        if ($requestedNoPo !== '') {
            $requestedPo = $this->db('rsns_custom_logistik_non_medis_po')->where('no_po', $requestedNoPo)->oneArray();
            if ($requestedPo) {
                $formData = $requestedPo;
                $formData['items'] = json_decode($requestedPo['detail_items'] ?? '[]', true) ?: [];
                foreach ($formData['items'] as &$item) {
                    $item['qty_pesan'] = $item['qty_pesan'] ?? ($item['jumlah'] ?? 0);
                    $item['harga_satuan'] = $item['harga_satuan'] ?? ($item['harga'] ?? 0);
                    $item['qty_diterima'] = $item['qty_diterima'] ?? 0;
                    $item['no_pr'] = $item['no_pr'] ?? ($item['sumber_sppb'] ?? '-');
                }
                unset($item);
                $formData['sumber_tipe'] = $formData['sumber_tipe'] ?? '';
                $formData['no_rencana'] = $formData['no_rencana'] ?? '';
                $formMode = 'edit';
            }
        }
        $formPo = $this->draw('pengadaan.po.form.html', [
        'data' => $formData,
        'mode' => $formMode,
        'vendors' => $vendors,
        'barang_map' => $barang
        ]);

        return $this->draw('pengadaan.po.html', [
        'form_po' => $formPo,
        'sumber_tipe' => '',
        'no_rencana' => ''
        ]);
    }

    public function anyDisplaypengadaanpo()
    {
        $this->_initPo();
        $perpage = 10;
        $halaman = isset($_POST['halaman']) ? (int)$_POST['halaman'] : 1;
        $cari = isset($_POST['cari']) ? $_POST['cari'] : '';

        $_offset = ($halaman - 1) * $perpage;

        $query = $this->db('rsns_custom_logistik_non_medis_po');
        if ($this->_demoModeEnabled()) {
            $query->where('no_po', 'LIKE', $this->_demoPrefix());
        }
        if (!empty($cari)) {
            $query->where('no_po', 'LIKE', '%' . $cari . '%')
                ->orLike('kode_vendor', '%' . $cari . '%');
        }

        $all_data = $query->toArray();
        $jumlah_data = count($all_data);
        $jml_halaman = ceil($jumlah_data / $perpage);

        $rows = $this->db('rsns_custom_logistik_non_medis_po');
        if ($this->_demoModeEnabled()) {
            $rows->where('no_po', 'LIKE', $this->_demoPrefix());
        }
        if (!empty($cari)) {
            $rows->where('no_po', 'LIKE', '%' . $cari . '%')
                ->orLike('kode_vendor', '%' . $cari . '%');
        }
        $rows = $rows->desc('id')
                    ->offset($_offset)
                    ->limit($perpage)
                    ->toArray();

        $vendors = [];
        $v_query = $this->db('rsns_custom_logistik_non_medis_vendor')->toArray();
        foreach ($v_query as $v) {
            $vendors[$v['kode_vendor']] = $v['nama_vendor'];
        }

        foreach ($rows as &$row) {
            $row['nama_vendor'] = $vendors[$row['kode_vendor']] ?? $row['kode_vendor'];
            $row['vendor_belum_dipilih'] = strpos((string)$row['no_po'], 'BELUM-DITENTUKAN') !== false;
            $row['no_po_display'] = $row['vendor_belum_dipilih']
              ? 'Draft - Vendor belum dipilih'
              : $row['no_po'];
            $row['grand_total_formatted'] = 'Rp. ' . number_format((float)$row['grand_total'], 0, ',', '.');
        }

        echo $this->draw('pengadaan.po.display.html', [
          'po' => $rows,
          'halaman' => $halaman,
          'jumlah_data' => $jumlah_data,
          'jml_halaman' => $jml_halaman,
          'admin_mode' => $this->settings->get('settings.admin_mode')
        ]);
        exit();
    }

    public function anyLoadprforpo()
    {
        $this->_initPR();
        $this->_initSppb();
        $kode_vendor = $_POST['kode_vendor'] ?? '';

        $sql = "
          SELECT p.*,
                 YEAR(p.tgl_pr) AS tahun,
                 COALESCE(NULLIF(s.nama_barang_manual, ''), b.nama_barang, p.kode_item) AS nama_barang,
                 CASE
                     WHEN s.subtotal_cost > 0 AND p.jumlah > 0 THEN s.subtotal_cost / p.jumlah
                     WHEN s.harga_satuan_cost > 0 THEN s.harga_satuan_cost
                     ELSE COALESCE(b.harga_referensi, 0)
                 END AS harga_referensi
          FROM rsns_custom_logistik_non_medis_pr p
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = p.kode_item
          LEFT JOIN rsns_custom_logistik_non_medis_sppb s
                 ON s.kode_item = p.kode_item
                AND p.justifikasi LIKE CONCAT('%SPPB Non Rutin: ', s.no_sppb, '.%')
          WHERE p.status = 'Disetujui'
          ORDER BY p.tgl_pr DESC, p.no_pr DESC, p.id DESC
      ";
        $prs = $this->db()->pdo()->query($sql)->fetchAll(\PDO::FETCH_ASSOC);

        header('Content-Type: application/json');
        echo json_encode($prs);
        exit();
    }

    public function anyLoadperencanaanforpo()
    {
        return $this->anyLoadprforpo();
    }

