            $data['items'] = json_decode($data['detail_items'], true) ?: [];
            foreach ($data['items'] as &$item) {
                // Draft PO dari SPPB memakai nama kolom sumber. Samakan dengan
                // struktur yang dibaca form PO agar qty dan harga langsung tampil.
                if (!isset($item['qty_pesan'])) {
                    $item['qty_pesan'] = $item['jumlah'] ?? 0;
                }
                if (!isset($item['harga_satuan'])) {
                    $item['harga_satuan'] = $item['harga'] ?? 0;
                }
                $item['qty_diterima'] = $item['qty_diterima'] ?? 0;
                $item['no_pr'] = $item['no_pr'] ?? ($item['sumber_sppb'] ?? '-');
            }
            unset($item);

            echo $this->draw('pengadaan.po.form.html', [
              'data' => $data,
              'mode' => 'edit',
              'vendors' => $vendors,
              'barang_map' => $barang
