    private function _initPemenuhanNonRutin()
    {
        $this->_initSppb();
        $pdo = $this->db()->pdo();
        $columns = [
          'sumber_pemenuhan' => "varchar(30) DEFAULT NULL AFTER `jenis_permintaan`",
          'referensi_pemenuhan' => "text DEFAULT NULL AFTER `sumber_pemenuhan`",
          'catatan_pemenuhan' => "text DEFAULT NULL AFTER `referensi_pemenuhan`",
          'user_tindak_lanjut' => "varchar(100) DEFAULT NULL AFTER `catatan_pemenuhan`",
          'tgl_tindak_lanjut' => "datetime DEFAULT NULL AFTER `user_tindak_lanjut`"
        ];
        foreach ($columns as $name => $definition) {
            $check = $pdo->query("SHOW COLUMNS FROM `rsns_custom_logistik_non_medis_sppb` LIKE " . $pdo->quote($name))->fetch();
            if (!$check) {
                $pdo->exec("ALTER TABLE `rsns_custom_logistik_non_medis_sppb` ADD `{$name}` {$definition}");
            }
        }
    }

    public function anyDisplayPermintaanNonRutin()
    {
        $this->_initPemenuhanNonRutin();
        $this->_initPR();
        $cari = trim((string)($_POST['cari'] ?? ''));
        $status = trim((string)($_POST['status'] ?? 'Proses Pengadaan'));
        $allowed_status = ['Logistik Umum & Rekap', 'Proses Pengadaan', 'Siap Diserahkan', 'Selesai'];
        if (!in_array($status, $allowed_status, true)) {
            $status = 'Proses Pengadaan';
        }

        $sql = "SELECT s.no_sppb, s.tgl_sppb, s.kode_unit, u.nama_unit, s.status,
                     s.keterangan, s.jenis_permintaan,
                     COUNT(s.kode_item) AS jml_item,
                     COALESCE(SUM(s.jumlah_disetujui), 0) AS total_qty,
                     COALESCE(SUM(s.jumlah_disetujui * COALESCE(s.estimasi_harga, 0)), 0) AS total_nilai,
                     GROUP_CONCAT(COALESCE(NULLIF(s.nama_barang_manual, ''), b.nama_barang, s.kode_item) SEPARATOR ', ') AS daftar_barang,
                     MAX(p.no_pr) AS no_pr,
                     MAX(po.no_po) AS no_po,
                     MAX(s.sumber_pemenuhan) AS sumber_pemenuhan,
                     MAX(s.referensi_pemenuhan) AS referensi_pemenuhan
              FROM rsns_custom_logistik_non_medis_sppb s
              LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = s.kode_unit
              LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item
              LEFT JOIN rsns_custom_logistik_non_medis_pr p
                ON p.justifikasi LIKE CONCAT('Auto generated from SPPB Non Rutin: ', s.no_sppb, '.%')
              LEFT JOIN rsns_custom_logistik_non_medis_po po
                ON po.catatan LIKE CONCAT('%Auto generated from SPPB Non Rutin: ', s.no_sppb, '%')
              WHERE s.jenis_permintaan = 'Non Rutin' AND s.status = ?";
        if ($this->_demoModeEnabled()) {
            $sql .= " AND s.no_sppb LIKE 'DEMO-OPERASIONAL-%'";
        }
        $params = [$status];
        if ($cari !== '') {
            $sql .= " AND (s.no_sppb LIKE ? OR u.nama_unit LIKE ? OR s.keterangan LIKE ? OR b.nama_barang LIKE ?)";
            $like = '%' . $cari . '%';
            $params = array_merge($params, [$like, $like, $like, $like]);
        }
        $sql .= " GROUP BY s.no_sppb, s.tgl_sppb, s.kode_unit, u.nama_unit, s.status, s.keterangan, s.jenis_permintaan
                ORDER BY s.tgl_sppb DESC, s.no_sppb DESC";

        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        foreach ($rows as &$row) {
            $row['tgl_sppb'] = date('d/m/Y', strtotime($row['tgl_sppb']));
            $row['total_qty'] = (float)$row['total_qty'];
            $row['total_nilai'] = (float)$row['total_nilai'];
        }
        unset($row);

        echo $this->draw('pengadaan.permintaan_nonrutin.display.html', [
          'rows' => $rows,
          'status' => $status,
          'role' => $this->core->getUserInfo('role', null, true)
        ]);
        exit();
    }

    public function anyKandidatPemenuhanNonRutin()
    {
        $this->_initPemenuhanNonRutin();
        $this->_initAset();
        $this->_initStok();
        $no_sppb = trim((string)($_POST['no_sppb'] ?? ''));
        $items = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->toArray();
        if (empty($items) || ($items[0]['jenis_permintaan'] ?? '') !== 'Non Rutin') {
            echo json_encode(['status' => 'error', 'message' => 'Permintaan Non-Rutin tidak ditemukan.']);
            exit();
        }

        $result = [];
        foreach ($items as $item) {
            $kode_item = (string)($item['kode_item'] ?? '');
            $barang = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $kode_item)->oneArray();
            $qty = (float)(($item['jumlah_disetujui'] ?? 0) > 0 ? $item['jumlah_disetujui'] : ($item['jumlah'] ?? 0));
            $stok_stmt = $this->db()->pdo()->prepare("SELECT COALESCE(SUM(stok), 0) FROM rsns_custom_logistik_non_medis_stok_batch WHERE kode_item = ? AND stok > 0 AND (tgl_expired IS NULL OR tgl_expired >= CURDATE())");
            $stok_stmt->execute([$kode_item]);
            $asset_stmt = $this->db()->pdo()->prepare("SELECT a.kode_aset, a.nama_aset, a.kode_unit, a.status_kondisi, a.pic, COALESCE(u.nama_unit, '-') AS nama_unit
              FROM rsns_custom_logistik_non_medis_aset a
              LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = a.kode_unit
              WHERE a.kode_item = ? AND a.status = 'Aktif'
                AND NOT EXISTS (SELECT 1 FROM rsns_custom_logistik_non_medis_aset_mutasi m WHERE m.kode_aset = a.kode_aset AND m.status IN ('Draft','Diajukan','Disetujui Asal'))
              ORDER BY FIELD(a.status_kondisi, 'Baik','Rusak Ringan','Rusak Berat'), u.nama_unit, a.nama_aset");
            $asset_stmt->execute([$kode_item]);
            $result[] = [
              'kode_item' => $kode_item,
              'nama_barang' => $item['nama_barang_manual'] ?: ($barang['nama_barang'] ?? $kode_item),
              'jumlah' => $qty,
              'satuan' => $item['satuan'] ?? ($barang['satuan'] ?? '-'),
              'stok' => (float)$stok_stmt->fetchColumn(),
              'aset' => $asset_stmt->fetchAll(\PDO::FETCH_ASSOC)
            ];
        }
        echo json_encode([
          'status' => 'success',
          'no_sppb' => $no_sppb,
          'kode_unit' => $items[0]['kode_unit'] ?? '',
          'status_sppb' => $items[0]['status'] ?? '',
          'sumber_pemenuhan' => $items[0]['sumber_pemenuhan'] ?? '',
          'items' => $result
        ]);
        exit();
    }

    public function postTindakLanjutPemenuhanNonRutin()
    {
        $this->_initPemenuhanNonRutin();
        $no_sppb = trim((string)($_POST['no_sppb'] ?? ''));
        $jalur = trim((string)($_POST['jalur'] ?? ''));
        $catatan = trim((string)($_POST['catatan'] ?? ''));
        $selected_assets = array_values(array_unique(array_filter((array)($_POST['kode_aset'] ?? []))));
        $user = $this->core->getUserInfo('username', null, true);
        $roleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $roleData['role'] ?? 'unit';
        if (!in_array($role, ['admin', 'logistik'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Hanya Admin/Logistik yang dapat menentukan sumber pemenuhan.']);
            exit();
        }

        $items = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->toArray();
        if (empty($items) || ($items[0]['jenis_permintaan'] ?? '') !== 'Non Rutin') {
            echo json_encode(['status' => 'error', 'message' => 'Permintaan Non-Rutin tidak ditemukan.']);
            exit();
        }
        $current_status = $items[0]['status'] ?? '';
        if (!in_array($current_status, ['Proses Pengadaan', 'Logistik Umum & Rekap'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Tindak lanjut hanya dapat ditentukan saat status Proses Pengadaan atau Logistik & Rekap.']);
            exit();
        }
        if (!in_array($jalur, ['stok', 'mutasi', 'perbaikan', 'po'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Pilih sumber pemenuhan terlebih dahulu.']);
            exit();
        }
        if ($jalur === 'po' && $current_status !== 'Proses Pengadaan') {
            echo json_encode(['status' => 'error', 'message' => 'Pengadaan PO hanya dapat dibuat setelah Konsul Kabid Umum selesai.']);
            exit();
        }
        $marker = 'Pemenuhan SPPB Non Rutin: ' . $no_sppb;
        $current_source = (string)($items[0]['sumber_pemenuhan'] ?? '');
        if ($current_source === 'Mutasi Aset') {
            $check = $this->db()->pdo()->prepare("SELECT COUNT(*) FROM rsns_custom_logistik_non_medis_aset_mutasi WHERE keterangan LIKE ? AND status IN ('Draft','Diajukan','Disetujui Asal')");
            $check->execute(['%' . $marker . '%']);
            if ((int)$check->fetchColumn() > 0) {
                echo json_encode(['status' => 'error', 'message' => 'Mutasi aset untuk permintaan ini masih berjalan. Selesaikan atau batalkan mutasi tersebut terlebih dahulu.']);
                exit();
            }
        } elseif ($current_source === 'Perbaikan Aset') {
            $check = $this->db()->pdo()->prepare("SELECT COUNT(*) FROM rsns_custom_logistik_non_medis_aset_pemeliharaan WHERE deskripsi LIKE ? AND status IN ('Jadwal','Menunggu','Diproses')");
            $check->execute(['%' . $marker . '%']);
            if ((int)$check->fetchColumn() > 0) {
                echo json_encode(['status' => 'error', 'message' => 'Perbaikan aset untuk permintaan ini masih berjalan. Selesaikan pekerjaan perbaikan terlebih dahulu.']);
                exit();
            }
        } elseif ($current_source === 'Pengadaan PO') {
            $active_po = $this->_findActivePoFromSppb($no_sppb);
            if ($active_po && $jalur !== 'po') {
                echo json_encode(['status' => 'error', 'message' => 'Permintaan sudah terhubung dengan PO ' . $active_po['no_po'] . '. Batalkan PO jika sumber pemenuhan akan diubah.']);
                exit();
            }
        }

        if ($jalur === 'stok') {
            $this->_initStok();
        } elseif ($jalur === 'po') {
            $this->_initPo();
        } elseif ($jalur === 'mutasi') {
            $this->_initAset();
        } elseif ($jalur === 'perbaikan') {
            $this->_initAset();
            $this->_initAsetPemeliharaan();
        }

        $pdo = $this->db()->pdo();
        try {
            $pdo->beginTransaction();
            $reference = '';
            $label = '';
            $redirect_url = '';
            $new_status = 'Proses Pengadaan';

            if ($jalur === 'stok') {
                foreach ($items as $item) {
                    $qty = (float)(($item['jumlah_disetujui'] ?? 0) > 0 ? $item['jumlah_disetujui'] : ($item['jumlah'] ?? 0));
                    $stmt = $pdo->prepare("SELECT COALESCE(SUM(stok), 0) FROM rsns_custom_logistik_non_medis_stok_batch WHERE kode_item = ? AND stok > 0 AND (tgl_expired IS NULL OR tgl_expired >= CURDATE())");
                    $stmt->execute([$item['kode_item']]);
                    $available = (float)$stmt->fetchColumn();
                    if ($available < $qty) {
                        throw new \RuntimeException('Stok ' . ($item['nama_barang_manual'] ?: $item['kode_item']) . ' tidak cukup. Tersedia ' . $available . ', dibutuhkan ' . $qty . '.');
                    }
                }
                $label = 'Stok Gudang';
                $new_status = 'Siap Diserahkan';
            } elseif ($jalur === 'po') {
                $label = 'Pengadaan PO';
                $no_po = $this->_generatePoFromSppb($no_sppb, $user, false);
                if ($no_po === '') {
                    throw new \RuntimeException('Tidak ada item yang dapat dibuat menjadi PO.');
                }
                $reference = $no_po;
                $redirect_url = url([ADMIN, 'logistik_non_medis', 'pengadaanpo']) . '&no_po=' . rawurlencode($no_po) . '#po-form';
            } else {
                if (empty($selected_assets)) {
                    throw new \RuntimeException('Pilih minimal satu aset yang akan diproses.');
                }
                $placeholders = implode(',', array_fill(0, count($selected_assets), '?'));
                $asset_stmt = $pdo->prepare("SELECT * FROM rsns_custom_logistik_non_medis_aset a WHERE a.kode_aset IN ({$placeholders}) AND a.status = 'Aktif'
                  AND NOT EXISTS (SELECT 1 FROM rsns_custom_logistik_non_medis_aset_mutasi m WHERE m.kode_aset = a.kode_aset AND m.status IN ('Draft','Diajukan','Disetujui Asal')) FOR UPDATE");
                $asset_stmt->execute($selected_assets);
                $assets = $asset_stmt->fetchAll(\PDO::FETCH_ASSOC);
                if (count($assets) !== count($selected_assets)) {
                    throw new \RuntimeException('Sebagian aset tidak ditemukan, tidak aktif, atau sedang dalam proses mutasi lain.');
                }
                $requested_codes = array_column($items, 'kode_item');
                foreach ($assets as $asset) {
                    if (!in_array($asset['kode_item'], $requested_codes, true)) {
                        throw new \RuntimeException('Aset ' . $asset['kode_aset'] . ' tidak sesuai dengan barang yang diminta.');
                    }
                    if ($jalur === 'perbaikan' && ($asset['status_kondisi'] ?? '') === 'Baik') {
                        throw new \RuntimeException('Aset ' . $asset['kode_aset'] . ' masih berkondisi Baik dan tidak perlu dibuatkan perbaikan.');
                    }
                }

                if ($jalur === 'mutasi') {
                    $required = [];
                    foreach ($items as $item) {
                        $required[$item['kode_item']] = (int)ceil((float)(($item['jumlah_disetujui'] ?? 0) > 0 ? $item['jumlah_disetujui'] : ($item['jumlah'] ?? 0)));
                    }
                    $selected_count = [];
                    foreach ($assets as $asset) {
                        if (($asset['status_kondisi'] ?? '') !== 'Baik') {
                            throw new \RuntimeException('Aset ' . $asset['kode_aset'] . ' belum berkondisi Baik. Gunakan jalur Perbaikan Aset.');
                        }
                        $selected_count[$asset['kode_item']] = ($selected_count[$asset['kode_item']] ?? 0) + 1;
                    }
                    foreach ($required as $kode_item => $qty) {
                        if (($selected_count[$kode_item] ?? 0) < $qty) {
                            throw new \RuntimeException('Jumlah aset terpilih untuk ' . $kode_item . ' kurang. Dibutuhkan ' . $qty . ' unit.');
                        }
                    }
                    $prefix = 'MUT-AST/' . date('Ym') . '/';
                    $max_stmt = $pdo->prepare("SELECT MAX(no_mutasi) FROM rsns_custom_logistik_non_medis_aset_mutasi WHERE no_mutasi LIKE ? FOR UPDATE");
                    $max_stmt->execute([$prefix . '%']);
                    $sequence = (int)substr((string)$max_stmt->fetchColumn(), -4);
                    $references = [];
                    foreach ($assets as $asset) {
                        $sequence++;
                        $no_mutasi = $prefix . sprintf('%04d', $sequence);
                        $this->db('rsns_custom_logistik_non_medis_aset_mutasi')->save([
                          'no_mutasi' => $no_mutasi,
                          'kode_aset' => $asset['kode_aset'],
                          'kode_unit_asal' => $asset['kode_unit'],
                          'kode_unit_tujuan' => $items[0]['kode_unit'],
                          'kode_lokasi_asal' => $asset['kode_lokasi'] ?? null,
                          'kode_lokasi_tujuan' => null,
                          'pic_asal' => $asset['pic'] ?? null,
                          'pic_tujuan' => null,
                          'keterangan' => 'Pemenuhan SPPB Non Rutin: ' . $no_sppb . ($catatan !== '' ? '. ' . $catatan : ''),
                          'tanggal_mutasi' => date('Y-m-d'),
                          'status' => 'Diajukan',
                          'user_mutasi' => $user,
                          'tgl_input' => date('Y-m-d H:i:s')
                        ]);
                        $references[] = $no_mutasi;
                    }
                    $label = 'Mutasi Aset';
                    $reference = implode(', ', $references);
                    $redirect_url = url([ADMIN, 'logistik_non_medis', 'asetmutasi']);
                } else {
                    $references = [];
                    foreach ($assets as $asset) {
                        $kode_wo = $this->_generateKodeWO();
                        $this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')->save([
                          'kode_pemeliharaan' => $kode_wo,
                          'kode_aset' => $asset['kode_aset'],
                          'jenis_pemeliharaan' => 'Corrective',
                          'tanggal_direncanakan' => date('Y-m-d'),
                          'nama_kegiatan' => 'Perbaikan untuk ' . $no_sppb,
                          'deskripsi' => 'Pemenuhan SPPB Non Rutin: ' . $no_sppb . ($catatan !== '' ? '. ' . $catatan : ''),
                          'prioritas' => 'Tinggi',
                          'status' => 'Menunggu',
                          'user_input' => $user,
                          'tgl_input' => date('Y-m-d H:i:s')
                        ]);
                        $references[] = $kode_wo;
                    }
                    $label = 'Perbaikan Aset';
                    $reference = implode(', ', $references);
                    $redirect_url = url([ADMIN, 'logistik_non_medis', 'asetpemeliharaan']);
                }
            }

            $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->update([
              'sumber_pemenuhan' => $label,
              'referensi_pemenuhan' => $reference,
              'catatan_pemenuhan' => $catatan,
              'user_tindak_lanjut' => $user,
              'tgl_tindak_lanjut' => date('Y-m-d H:i:s'),
              'status' => $new_status
            ]);
            $pdo->commit();
            if ($new_status === 'Siap Diserahkan') {
                $this->_buatNotifSiapAmbilSppb($no_sppb, $items[0]['kode_unit']);
            }
            $this->_logAction('logistik_non_medis_sppb', 'Tindak lanjut ' . $no_sppb . ': ' . $label . ($reference ? ' | ' . $reference : ''), 'U');
            echo json_encode([
              'status' => 'success',
              'message' => $label . ' berhasil dipilih sebagai sumber pemenuhan.' . ($new_status === 'Siap Diserahkan' ? ' Barang dapat disiapkan untuk serah terima.' : ''),
              'redirect_url' => $redirect_url
            ]);
        } catch (\Throwable $e) {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
        exit();
    }

    private function _findActivePoFromSppb(string $no_sppb): array
    {
        $marker = 'Auto generated from SPPB Non Rutin: ' . $no_sppb;
        $escaped_no_sppb = str_replace('/', '\\/', $no_sppb);
        $stmt = $this->db()->pdo()->prepare("SELECT *
          FROM rsns_custom_logistik_non_medis_po
          WHERE status <> 'Dibatalkan'
            AND (catatan LIKE ? OR detail_items LIKE ? OR detail_items LIKE ?)
          ORDER BY id DESC
          LIMIT 1");
        $stmt->execute([
          '%' . $marker . '%',
          '%' . $no_sppb . '%',
          '%' . $escaped_no_sppb . '%'
        ]);
        $po = $stmt->fetch(\PDO::FETCH_ASSOC);
        return is_array($po) ? $po : [];
    }

    private function _generatePoFromSppb(string $no_sppb, string $user, bool $initialize = true): string
    {
        if ($initialize) {
            $this->_initPo();
        }
        $items = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->toArray();
        if (empty($items)) {
            return '';
        }
        $marker = 'Auto generated from SPPB Non Rutin: ' . $no_sppb;
        $existing = $this->_findActivePoFromSppb($no_sppb);
        if (!empty($existing['no_po'])) {
            return (string)$existing['no_po'];
        }
        $kode_vendor = 'BELUM-DITENTUKAN';
        $no_po = $this->_generateNoPO($kode_vendor);
        $detail = [];
        $total = 0;
        foreach ($items as $item) {
            $qty = (float)($item['jumlah_disetujui'] > 0 ? $item['jumlah_disetujui'] : $item['jumlah']);
            if ($qty <= 0) {
                continue;
            }
            $harga = (float)($item['estimasi_harga'] ?? 0);
            $subtotal = $qty * $harga;
            $total += $subtotal;
            $detail[] = [
              'kode_item' => $item['kode_item'],
              'nama_barang' => $item['nama_barang_manual'] ?: $item['kode_item'],
              'jumlah' => $qty,
              'qty_pesan' => $qty,
              'qty_diterima' => 0,
              'satuan' => $item['satuan'],
              'harga' => $harga,
              'harga_satuan' => $harga,
              'subtotal' => $subtotal,
              'no_pr' => $no_sppb,
              'sumber_sppb' => $no_sppb
            ];
        }
        if (empty($detail)) {
            return '';
        }
        $this->db('rsns_custom_logistik_non_medis_po')->save(['no_po' => $no_po,'tgl_po' => date('Y-m-d'),'kode_vendor' => $kode_vendor,'total_nilai' => $total,'diskon' => 0,'ppn' => 0,'grand_total' => $total,'detail_items' => json_encode($detail),'catatan' => $marker,'status' => 'Draft','user_input' => $user]);
        return $no_po;
    }

    public function postGenerateOrderNonRutin()
    {
        $this->_initSppb();
        $no_sppb = trim((string)($_POST['no_sppb'] ?? ''));
        $username = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';

        if (!in_array($role, ['admin', 'logistik'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Hanya Admin/Logistik yang dapat membuat PO.']);
            exit();
        }
        $sppb = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if (!$sppb || $sppb['jenis_permintaan'] !== 'Non Rutin') {
            echo json_encode(['status' => 'error', 'message' => 'Permintaan Non Rutin tidak ditemukan.']);
            exit();
        }
        if ($this->_demoModeEnabled() && strpos($no_sppb, 'DEMO-OPERASIONAL-') !== 0) {
            echo json_encode(['status' => 'error', 'message' => 'Mode demo aktif: hanya data demo yang dapat diproses.']);
            exit();
        }
        if ($sppb['status'] !== 'Proses Pengadaan') {
            echo json_encode(['status' => 'error', 'message' => 'Order hanya dapat dibuat saat status Proses Pengadaan.']);
            exit();
        }

        $no_po = $this->_generatePoFromSppb($no_sppb, $username);
        if ($no_po === '') {
            echo json_encode(['status' => 'error', 'message' => 'Tidak ada item dengan jumlah disetujui untuk dibuat menjadi PO.']);
            exit();
        }
        $this->_logAction('logistik_non_medis_sppb', 'Generate PO dari SPPB Non Rutin: ' . $no_sppb . ' | PO: ' . $no_po, 'U');
        $po_url = url([ADMIN, 'logistik_non_medis', 'pengadaanpo']) . '&no_po=' . rawurlencode($no_po) . '#po-form';
        echo json_encode([
          'status' => 'success',
          'no_po' => $no_po,
          'po_url' => $po_url,
          'message' => 'PO Draft berhasil dibuat: ' . $no_po . '. Lengkapi vendor lalu terbitkan PO.'
        ]);
        exit();
    }

