    public function postImportMutasiCsv()
    {
        if (empty($_FILES['file_csv']['tmp_name'])) {
            echo json_encode(['status' => 'error', 'message' => 'File tidak ditemukan']);
            exit;
        }

        $file = $_FILES['file_csv']['tmp_name'];
        $content = file_get_contents($file);
        if (empty($content)) {
            echo json_encode(['status' => 'error', 'message' => 'File CSV kosong']);
            exit;
        }

        // Auto-detect delimiter: semicolon or comma
        $first_line = strtok($content, "\n");
        $delimiter = (substr_count($first_line, ';') > substr_count($first_line, ',')) ? ';' : ',';

        $handle = fopen($file, 'r');
        $header_raw = fgetcsv($handle, 0, $delimiter);
        if (!$header_raw) {
            fclose($handle);
            echo json_encode(['status' => 'error', 'message' => 'Gagal membaca header CSV']);
            exit;
        }

        // Normalize header & map flexible column names
        $header = array_map(function ($h) {
            return strtolower(trim($h));
        }, $header_raw);

        // Column name aliases
        $aliases_kode   = ['kode_item', 'kode barang', 'kode_barang', 'item_code', 'kode'];
        $aliases_jenis  = ['jenis_mutasi', 'jenis mutasi (masuk/keluar/penyesuaian)', 'jenis mutasi', 'jenis', 'tipe'];
        $aliases_jumlah = ['jumlah', 'qty', 'quantity', 'jml'];
        $aliases_ket    = ['keterangan', 'catatan item', 'catatan_item', 'catatan', 'note', 'notes', 'ket'];
        $aliases_tgl    = ['tanggal', 'tanggal (yyyy-mm-dd)', 'tgl', 'tgl_mutasi', 'date'];
        $aliases_catatan = ['catatan umum', 'catatan_umum', 'deskripsi', 'description'];

        $find_col = function ($aliases) use ($header) {
            foreach ($aliases as $alias) {
                $idx = array_search($alias, $header);
                if ($idx !== false) {
                    return $idx;
                }
            }
            return false;
        };

        $col_kode   = $find_col($aliases_kode);
        $col_jenis  = $find_col($aliases_jenis);
        $col_jumlah = $find_col($aliases_jumlah);
        $col_ket    = $find_col($aliases_ket);
        $col_tgl    = $find_col($aliases_tgl);
        $col_catatan = $find_col($aliases_catatan);

        if ($col_kode === false || $col_jenis === false || $col_jumlah === false) {
            fclose($handle);
            $detected = implode($delimiter, $header);
            echo json_encode(['status' => 'error', 'message' => "Kolom CSV tidak sesuai. Wajib: Kode Barang, Jenis Mutasi, Jumlah. Kolom terdeteksi: $detected"]);
            exit;
        }

        $user = $this->core->getUserInfo('username', null, true);
        $no_mutasi = $this->_generateNoMutasi();

        // Ambil tanggal dari baris pertama data (jika ada kolom tanggal)
        $tgl_mutasi = date('Y-m-d');
        $catatan_umum = 'Import CSV oleh ' . $user;

        // Peek first data row for tanggal & catatan
        $pos = ftell($handle);
        $first_row = fgetcsv($handle, 0, $delimiter);
        if ($first_row) {
            if ($col_tgl !== false && !empty(trim($first_row[$col_tgl] ?? ''))) {
                $parsed_tgl = date('Y-m-d', strtotime(trim($first_row[$col_tgl])));
                if ($parsed_tgl && $parsed_tgl !== '1970-01-01') {
                    $tgl_mutasi = $parsed_tgl;
                }
            }
            if ($col_catatan !== false && !empty(trim($first_row[$col_catatan] ?? ''))) {
                $catatan_umum = trim($first_row[$col_catatan]);
            }
        }
        fseek($handle, $pos); // Rewind to re-process first data row

        // Create mutasi header
        $this->db('rsns_custom_logistik_non_medis_mutasi')->save([
          'no_mutasi' => $no_mutasi,
          'tgl_mutasi' => $tgl_mutasi,
          'keterangan' => $catatan_umum,
          'status' => 'Draft',
          'user_input' => $user,
          'tgl_input' => date('Y-m-d H:i:s')
        ]);

        $row_num = 1;
        $imported = 0;
        $errors = [];

        while (($row = fgetcsv($handle, 0, $delimiter)) !== false) {
            $row_num++;
            $kode_item = trim($row[$col_kode] ?? '');
            $jenis = trim($row[$col_jenis] ?? '');
            $jumlah = floatval($row[$col_jumlah] ?? 0);
            $ket = ($col_ket !== false) ? trim($row[$col_ket] ?? '') : '';

            if (empty($kode_item) || $jumlah <= 0) {
                $errors[] = "Baris $row_num: kode_item kosong atau jumlah tidak valid";
                continue;
            }

            // Validasi jenis_mutasi
            $valid_jenis = ['Masuk', 'Keluar', 'Penyesuaian'];
            if (!in_array($jenis, $valid_jenis)) {
                $errors[] = "Baris $row_num: jenis_mutasi '$jenis' tidak valid (gunakan: Masuk/Keluar/Penyesuaian)";
                continue;
            }

            // Cek kode_item ada di master
            $barang = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $kode_item)->oneArray();
            if (!$barang) {
                $errors[] = "Baris $row_num: kode_item '$kode_item' tidak ditemukan di Master Barang";
                continue;
            }

            $this->db('rsns_custom_logistik_non_medis_mutasi_detail')->save([
              'no_mutasi' => $no_mutasi,
              'kode_item' => $kode_item,
              'jenis_mutasi' => $jenis,
              'batch_no' => '-',
              'qty' => $jumlah,
              'satuan' => $barang['satuan_dasar'] ?? '',
              'keterangan' => $ket
            ]);
            $imported++;
        }
        fclose($handle);

        if ($imported == 0) {
            $this->db('rsns_custom_logistik_non_medis_mutasi')->where('no_mutasi', $no_mutasi)->delete();
            echo json_encode(['status' => 'error', 'message' => 'Tidak ada data yang berhasil diimport. ' . implode('; ', $errors)]);
        } else {
            $msg = "Berhasil import $imported item ke mutasi $no_mutasi (tgl: $tgl_mutasi, status: Draft).";
            if (!empty($errors)) {
                $msg .= ' Beberapa baris dilewati: ' . implode('; ', $errors);
            }
            $this->_logAction('logistik_non_medis_mutasi', 'Import CSV Mutasi: ' . $no_mutasi);
            echo json_encode(['status' => 'success', 'message' => $msg]);
        }
        exit;
    }

    public function getExportMutasiCsv()
    {
        $kategori = $_GET['kategori'] ?? '';
        $bulan = $_GET['bulan'] ?? date('m');
        $tahun = $_GET['tahun'] ?? date('Y');

        $tgl_awal = "$tahun-$bulan-01";
        $tgl_akhir = date('Y-m-t', strtotime($tgl_awal));

        $sql = "SELECT m.no_mutasi, m.tgl_mutasi, m.kode_lokasi_asal, m.kode_lokasi_tujuan, m.status,
                     d.kode_item, b.nama_barang, d.jenis_mutasi, d.batch_no, d.qty, d.satuan, d.keterangan
              FROM rsns_custom_logistik_non_medis_mutasi m
              JOIN rsns_custom_logistik_non_medis_mutasi_detail d ON d.no_mutasi = m.no_mutasi
              LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = d.kode_item
              WHERE m.tgl_mutasi BETWEEN ? AND ?";

        $params = [$tgl_awal, $tgl_akhir];

        if (!empty($kategori)) {
            $sql .= " AND b.kode_kategori = ?";
            $params[] = $kategori;
        }

        $sql .= " ORDER BY m.tgl_mutasi ASC, m.no_mutasi ASC";

        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);

        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=export_mutasi_' . $tahun . $bulan . '.csv');

        $output = fopen('php://output', 'w');
        fputcsv($output, ['No Mutasi', 'Tgl Mutasi', 'Lokasi Asal', 'Lokasi Tujuan', 'Status', 'Kode Item', 'Nama Barang', 'Jenis Mutasi', 'Batch', 'Qty', 'Satuan', 'Keterangan']);
        foreach ($rows as $row) {
            fputcsv($output, [
              $row['no_mutasi'], $row['tgl_mutasi'], $row['kode_lokasi_asal'], $row['kode_lokasi_tujuan'],
              $row['status'], $row['kode_item'], $row['nama_barang'], $row['jenis_mutasi'],
              $row['batch_no'], $row['qty'], $row['satuan'], $row['keterangan']
            ]);
        }
        fclose($output);
        exit();
    }

    public function anyDisplayKartuStok()
    {
        $kode_item = $_POST['kode_item'] ?? '';
        $kode_lokasi = $_POST['kode_lokasi'] ?? '';
        $tgl_awal = empty($_POST['tgl_awal']) ? '2000-01-01' : $_POST['tgl_awal'];
        $tgl_akhir = empty($_POST['tgl_akhir']) ? '2099-12-31' : $_POST['tgl_akhir'];

        $query = $this->db('rsns_custom_logistik_non_medis_kartu_stok')
                    ->select('rsns_custom_logistik_non_medis_kartu_stok.*, rsns_custom_logistik_non_medis_master_barang.nama_barang')
                    ->leftJoin('rsns_custom_logistik_non_medis_master_barang', 'rsns_custom_logistik_non_medis_kartu_stok.kode_item = rsns_custom_logistik_non_medis_master_barang.kode_item')
                    ->where('rsns_custom_logistik_non_medis_kartu_stok.tgl_transaksi', '>=', $tgl_awal . ' 00:00:00')
                    ->where('rsns_custom_logistik_non_medis_kartu_stok.tgl_transaksi', '<=', $tgl_akhir . ' 23:59:59');

        if (!empty($kode_item)) {
            $query->where('rsns_custom_logistik_non_medis_kartu_stok.kode_item', $kode_item);
        }
        if (!empty($kode_lokasi)) {
            $query->where('rsns_custom_logistik_non_medis_kartu_stok.kode_lokasi', $kode_lokasi);
        }

        $rows = $query->asc('tgl_transaksi')->asc('id')->toArray();

        echo $this->draw('gudang.mutasi.display.html', [
          'mutasi_history' => $rows, // Changed to mutasi_history to avoid conflict with transaction list
          'kode_item' => $kode_item,
          'kode_lokasi' => $kode_lokasi,
          'is_history' => true,
          'jml_halaman' => 1,
          'pages' => [1],
          'halaman' => 1
        ]);
        exit();
    }

    private function _logAction(string $modul, string $action, string $status = 'I')
    {
        $user = $this->core->getUserInfo('username', null, true);
        $ip = $_SERVER['REMOTE_ADDR'] ?? 'Localhost';
        $host_row = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
        $hostname = $host_row['hostname'] ?? 'Unknown';

        $this->db('mlite_tracksql')->save([
          'log_id' => null,
          'log_modul' => $modul,
          'log_waktu' => date('Y-m-d H:i:s'),
          'log_location' => $hostname . ' | ' . $ip,
          'log_data' => $action . ' | User: ' . $user,
          'log_status' => $status,
          'log_username' => $user
        ]);
    }
    private function _initOpname()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_opname` (
        `id` int(11) NOT NULL AUTO_INCREMENT,
        `no_opname` varchar(50) NOT NULL,
        `tgl_opname` date DEFAULT NULL,
        `tgl_jadwal` date DEFAULT NULL,
        `kode_lokasi` varchar(50) NOT NULL,
        `kode_item` varchar(50) DEFAULT NULL,
        `stok_sistem` double NOT NULL DEFAULT 0,
        `stok_fisik` double NOT NULL DEFAULT 0,
        `selisih` double NOT NULL DEFAULT 0,
        `keterangan` text DEFAULT NULL,
        `status` enum('Jadwal','Draft','Selesai') NOT NULL DEFAULT 'Jadwal',
        `user_input` varchar(100) DEFAULT NULL,
        PRIMARY KEY (`id`),
        KEY `no_opname` (`no_opname`),
        KEY `kode_lokasi` (`kode_lokasi`),
        KEY `kode_item` (`kode_item`)
      ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");
    }

    private function _generateNoOpname()
    {
        $prefix = 'SO/' . date('Ym') . '/';
        $last = $this->db('rsns_custom_logistik_non_medis_opname')
                   ->where('no_opname', 'LIKE', $prefix . '%')
                   ->desc('no_opname')
                   ->limit(1)
                   ->oneArray();

        if ($last) {
            $parts = explode('/', $last['no_opname']);
            $last_num = (int) end($parts);
            $next_num = str_pad($last_num + 1, 4, '0', STR_PAD_LEFT);
        } else {
            $next_num = '0001';
        }

        return $prefix . $next_num;
    }

    public function getGudangOpname()
    {
        $this->_initOpname();
        $this->_addHeaderFiles();
        return $this->draw('gudang.opname.html');
    }

    public function anyDisplayOpname()
    {
        $this->_initOpname();
        $perpage = 10;
        $halaman = isset($_POST['halaman']) ? (int)$_POST['halaman'] : 1;
        $cari = isset($_POST['cari']) ? $_POST['cari'] : '';

        $_offset = ($halaman - 1) * $perpage;

        $where = "";
        if (!empty($cari)) {
            $where = " WHERE no_opname LIKE '%$cari%' ";
        }

        $sql_all = "SELECT no_opname FROM rsns_custom_logistik_non_medis_opname $where GROUP BY no_opname";
        $all_data = $this->db()->pdo()->query($sql_all)->fetchAll();
        $jumlah_data = count($all_data);
        $jml_halaman = ceil($jumlah_data / $perpage);

        $sql = "SELECT * FROM rsns_custom_logistik_non_medis_opname 
              WHERE id IN (SELECT MAX(id) FROM rsns_custom_logistik_non_medis_opname $where GROUP BY no_opname)
              ORDER BY id DESC LIMIT $_offset, $perpage";
        $rows = $this->db()->pdo()->query($sql)->fetchAll(\PDO::FETCH_ASSOC);

        $pages = [];
        if ($jml_halaman > 1) {
            for ($i = 1; $i <= $jml_halaman; $i++) {
                $pages[] = $i;
            }
        }

        echo $this->draw('gudang.opname.display.html', [
          'opname' => $rows,
          'halaman' => $halaman,
          'jumlah_data' => $jumlah_data,
          'jml_halaman' => $jml_halaman,
          'pages' => $pages
        ]);
        exit();
    }

    public function anyFormOpname()
    {
        $this->_initOpname();
        $this->_initKategori();
        $kategori = $this->db('rsns_custom_logistik_non_medis_kategori')
            ->where('kode_kategori', '!=', 'KAT-006')
            ->asc('nama_kategori')
            ->toArray();
        $mode = $_POST['mode'] ?? 'add';

        if ($mode == 'edit' && isset($_POST['no_opname'])) {
            $no_opname = $_POST['no_opname'];
            $opname_rows = $this->db('rsns_custom_logistik_non_medis_opname')->where('no_opname', $no_opname)->toArray();
            $opname = $opname_rows[0];

            // Get item names
            $barang_rows = $this->db('rsns_custom_logistik_non_medis_master_barang')->toArray();
            $barang_map = [];
            foreach ($barang_rows as $b) {
                $barang_map[$b['kode_item']] = $b['nama_barang'];
            }

            $opname['detail_items'] = [];
            foreach ($opname_rows as $row) {
                if (empty($row['kode_item'])) {
                    continue;
                }
                $row['nama_barang'] = $barang_map[$row['kode_item']] ?? $row['kode_item'];
                foreach ($barang_rows as $b) {
                    if ($b['kode_item'] === $row['kode_item']) {
                        $row['satuan_dasar'] = $b['satuan_dasar'] ?? '';
                        break;
                    }
                }
                $opname['detail_items'][] = $row;
            }
            $opname['kode_lokasi'] = 'GLOBAL';
            echo $this->draw('gudang.opname.form.html', ['opname' => $opname, 'mode' => 'edit', 'kategori' => $kategori]);
        } else {
            $opname = [
              'no_opname' => $this->_generateNoOpname(),
              'tgl_opname' => date('Y-m-d'),
              'tgl_jadwal' => date('Y-m-d'),
              'kode_lokasi' => 'GLOBAL',
              'detail_items' => [],
              'status' => 'Draft'
            ];
            echo $this->draw('gudang.opname.form.html', ['opname' => $opname, 'mode' => 'add', 'kategori' => $kategori]);
        }
        exit();
    }

    public function anyLoadItemsForOpname()
    {
        // Opname hanya mencatat jumlah fisik terkini dari seluruh master barang aktif.
        // Tidak memakai stok sistem/lokasi agar tidak melakukan perbandingan.
        $sql = "SELECT b.kode_item, b.nama_barang, b.satuan_dasar, b.kode_kategori, k.nama_kategori
                FROM rsns_custom_logistik_non_medis_master_barang b
                LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
                WHERE b.status = 'Aktif' AND b.kode_kategori <> 'KAT-006'
                ORDER BY b.nama_barang ASC, b.kode_item ASC";
        $barang_rows = $this->db()->pdo()->query($sql)->fetchAll(\PDO::FETCH_ASSOC);

        $items = [];
        foreach ($barang_rows as $b) {
            $items[] = [
              'kode_item' => $b['kode_item'],
              'nama_barang' => $b['nama_barang'],
              'satuan_dasar' => $b['satuan_dasar'] ?? '',
              'kode_kategori' => $b['kode_kategori'],
              'nama_kategori' => $b['nama_kategori'] ?? 'Tanpa Kategori',
              'stok_sistem' => 0,
              'stok_fisik' => 0,
              'selisih' => 0,
              'keterangan' => ''
            ];
        }

        echo json_encode(['status' => 'success', 'items' => $items]);
        exit();
    }

    public function postSaveOpname()
    {
        $no_opname = $_POST['no_opname'] ?? '';
        $status = $_POST['status'] ?? 'Draft';
        $user = $this->core->getUserInfo('username', null, true);

        $items = [];
        if (isset($_POST['kode_item']) && is_array($_POST['kode_item'])) {
            foreach ($_POST['kode_item'] as $key => $kode_item) {
                $items[] = [
                  'no_opname' => $no_opname,
                  'tgl_opname' => $_POST['tgl_opname'] ?? date('Y-m-d'),
                  'tgl_jadwal' => $_POST['tgl_jadwal'] ?? date('Y-m-d'),
                  'kode_lokasi' => 'GLOBAL',
                  'kode_item' => $kode_item,
                  'stok_sistem' => 0,
                  'stok_fisik' => $_POST['stok_fisik'][$key] ?? 0,
                  'selisih' => 0,
                  'keterangan' => $_POST['keterangan_item'][$key] ?? '',
                  'status' => $status,
                  'user_input' => $user
                ];
            }
        }

        // If no items but it's a schedule, save at least the header info
        if (empty($items) && $status == 'Jadwal') {
            $items[] = [
              'no_opname' => $no_opname,
              'tgl_opname' => null,
              'tgl_jadwal' => $_POST['tgl_jadwal'] ?? date('Y-m-d'),
              'kode_lokasi' => 'GLOBAL',
              'kode_item' => null,
              'stok_sistem' => 0,
              'stok_fisik' => 0,
              'selisih' => 0,
              'keterangan' => $_POST['keterangan'] ?? 'Jadwal Opname',
              'status' => 'Jadwal',
              'user_input' => $user
            ];
        }

        // Start transaction or just delete old ones and insert new
        $this->db('rsns_custom_logistik_non_medis_opname')->where('no_opname', $no_opname)->delete();

        $success = true;
        foreach ($items as $item) {
            if (!$this->db('rsns_custom_logistik_non_medis_opname')->save($item)) {
                $success = false;
            }
        }

        if ($success) {
            // Logging to mlite_tracksql
            $ip = $_SERVER['REMOTE_ADDR'];
            $hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray()['hostname'] ?? 'Unknown';
            $this->db('mlite_tracksql')->save([
              'log_id' => null,
              'log_modul' => 'logistik_non_medis_opname',
              'log_waktu' => date('Y-m-d H:i:s'),
              'log_location' => $hostname . ' | ' . $ip,
              'log_data' => 'Save Opname ' . $no_opname . ' Status: ' . $status,
              'log_status' => ($status == 'Selesai' ? 'U' : 'I'),
              'log_username' => $user
            ]);

            echo json_encode(['status' => 'success']);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan data opname']);
        }
        exit();
    }

