        if (!is_dir($upload_dir . '/bast')) {
            mkdir($upload_dir . '/bast', 0777, true);
        }
    }

    private function _encodeSerahTerimaSignature(string $payload): array
    {
        if (strlen($payload) > 250000) {
            throw new \RuntimeException('Data tanda tangan terlalu besar. Silakan hapus dan ulangi tanda tangan.');
        }
        $decoded = json_decode($payload, true);
        if (!is_array($decoded) || (int)($decoded['version'] ?? 0) !== 1 || empty($decoded['strokes']) || !is_array($decoded['strokes'])) {
            throw new \RuntimeException('Format tanda tangan tidak valid.');
        }
        $width = max(1, min(2000, (int)($decoded['width'] ?? 350)));
        $height = max(1, min(1000, (int)($decoded['height'] ?? 180)));
        $cleanStrokes = [];
        $totalPoints = 0;
        foreach (array_slice($decoded['strokes'], 0, 200) as $stroke) {
            if (!is_array($stroke)) {
                continue;
            }
            $cleanPoints = [];
            foreach ($stroke as $point) {
                if (!is_array($point) || count($point) < 2 || !is_numeric($point[0]) || !is_numeric($point[1])) {
                    continue;
                }
                $x = round(max(0, min($width, (float)$point[0])), 1);
                $y = round(max(0, min($height, (float)$point[1])), 1);
                $cleanPoints[] = [$x, $y];
                $totalPoints++;
                if ($totalPoints > 12000) {
                    throw new \RuntimeException('Tanda tangan terlalu kompleks. Silakan ulangi dengan goresan yang lebih sederhana.');
                }
            }
            if (count($cleanPoints) >= 2) {
                $cleanStrokes[] = $cleanPoints;
            }
        }
        if (!$cleanStrokes || $totalPoints < 3) {
            throw new \RuntimeException('Tanda tangan belum terbaca.');
        }
        $canonical = json_encode(['version' => 1, 'width' => $width, 'height' => $height, 'strokes' => $cleanStrokes], JSON_UNESCAPED_SLASHES);
        if ($canonical === false) {
            throw new \RuntimeException('Tanda tangan gagal diproses.');
        }
        $compressed = gzdeflate($canonical, 9);
        if ($compressed === false) {
            throw new \RuntimeException('Tanda tangan gagal dikompresi.');
        }
        return [
          'data' => 'SIGV1:' . base64_encode($compressed),
          'hash' => hash('sha256', $canonical),
          'points' => $totalPoints,
          'bytes' => strlen($compressed)
        ];
    }

    private function _serahTerimaSignatureDataUri(string $stored): string
    {
        if (strpos($stored, 'data:image/') === 0) {
            return $stored;
        }
        if (strpos($stored, 'SIGV1:') !== 0) {
            return '';
        }
        $compressed = base64_decode(substr($stored, 6), true);
        $json = $compressed !== false ? @gzinflate($compressed) : false;
        $signature = $json !== false ? json_decode($json, true) : null;
        if (!is_array($signature) || empty($signature['strokes'])) {
            return '';
        }
        $width = max(1, (int)($signature['width'] ?? 350));
        $height = max(1, (int)($signature['height'] ?? 180));
        $paths = '';
        foreach ($signature['strokes'] as $stroke) {
            if (!is_array($stroke) || count($stroke) < 2) {
                continue;
            }
            $points = [];
            foreach ($stroke as $point) {
                if (is_array($point) && count($point) >= 2) {
                    $points[] = ((float)$point[0]) . ',' . ((float)$point[1]);
                }
            }
            if (count($points) >= 2) {
                $paths .= '<polyline points="' . implode(' ', $points) . '"/>';
            }
        }
        if ($paths === '') {
            return '';
        }
        $svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' . $width . ' ' . $height . '" width="' . $width . '" height="' . $height . '"><g fill="none" stroke="#000080" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">' . $paths . '</g></svg>';
        return 'data:image/svg+xml;base64,' . base64_encode($svg);
    }

    private function _isSerahTerimaSignatureHashValid(string $stored, string $expectedHash): bool
    {
        if ($expectedHash === '' || strpos($stored, 'SIGV1:') !== 0) {
            return false;
        }
        $compressed = base64_decode(substr($stored, 6), true);
        $canonical = $compressed !== false ? @gzinflate($compressed) : false;
        return $canonical !== false && hash_equals($expectedHash, hash('sha256', $canonical));
    }

    private function _generateNoSerahTerima()
    {
        $prefix = 'BAST/' . date('Ymd') . '/';
        $last = $this->db('rsns_custom_logistik_non_medis_serah_terima')
                   ->where('no_serah_terima', 'LIKE', $prefix . '%')
                   ->desc('no_serah_terima')
                   ->limit(1)
                   ->oneArray();

        if ($last) {
            $last_num = (int) substr($last['no_serah_terima'], -4);
            $next_num = str_pad($last_num + 1, 4, '0', STR_PAD_LEFT);
        } else {
            $next_num = '0001';
        }

        return $prefix . $next_num;
    }

    private function _generateNoPacking()
    {
        $prefix = 'PKG/' . date('Ymd') . '/';
        $last = $this->db('rsns_custom_logistik_non_medis_packing')
                   ->where('no_packing', 'LIKE', $prefix . '%')
                   ->desc('no_packing')
