    private function _renderSppbPage(string $jenis)
    {
        $this->_initSppb();
        $this->_initSerahTerima();
        $this->_addHeaderFiles();

        $username = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';

        $nama_unit = '';
        if (!empty($userRoleData['kode_unit'])) {
            $unit = $this->db('rsns_custom_logistik_non_medis_unit')->where('kode_unit', $userRoleData['kode_unit'])->oneArray();
            $nama_unit = $unit['nama_unit'] ?? '';
        }

        $current_week_sppb = null;
        if ($jenis === 'Rutin' && $role === 'unit' && !empty($userRoleData['kode_unit'])) {
            $timestamp = time();
            $dayOfWeek = date('w', $timestamp);
            $offset = $dayOfWeek == 0 ? 6 : $dayOfWeek - 1;
            $monday = date('Y-m-d', strtotime("-$offset days", $timestamp));
            $sunday = date('Y-m-d', strtotime("+6 days", strtotime($monday)));

            $sql_cek = "SELECT no_sppb, tgl_sppb, status FROM rsns_custom_logistik_non_medis_sppb 
                      WHERE kode_unit = ? AND jenis_permintaan = 'Rutin' 
                      AND status NOT IN ('Ditolak', 'Dibatalkan') 
                      AND tgl_sppb BETWEEN ? AND ? ORDER BY id DESC LIMIT 1";
            $stmt_cek = $this->db()->pdo()->prepare($sql_cek);
            $stmt_cek->execute([$userRoleData['kode_unit'], $monday, $sunday]);
            $current_week_sppb = $stmt_cek->fetch(\PDO::FETCH_ASSOC);
            if ($current_week_sppb) {
                $current_week_sppb['tgl_sppb_display'] = date('d/m/Y', strtotime($current_week_sppb['tgl_sppb']));
            }
        }
        $units_raw = $this->db('rsns_custom_logistik_non_medis_unit')->toArray();
        $units = [];
        foreach ($units_raw as $u) {
            $n = strtolower($u['nama_unit'] ?? '');
            if (strpos($n, 'kasie') !== false || strpos($n, 'kanit') !== false || strpos($n, 'kabid') !== false) {
                continue;
            }
            $units[] = $u;
        }

        return $this->draw('distribusi.sppb.html', [
          'role' => $role,
          'nama_unit' => $nama_unit,
          'jenis_page' => $jenis,
          'current_week_sppb' => $current_week_sppb,
          'units' => $units,
          'can_create_sppb' => in_array($role, ['admin', 'unit', 'logistik'], true),
          'can_manage_distribusi_controls' => in_array($role, ['admin', 'logistik'], true),
          'can_access_rekap_nonrutin' => $jenis === 'Non Rutin' && $this->_canAccessRekapNonRutin(),
          'rekap_tanggal_awal' => date('Y-m-01'),
          'rekap_tanggal_akhir' => date('Y-m-t')
        ]);
    }

    public function anyAjaxMasterBarang()
    {
        $cari = trim((string)($_GET['q'] ?? ''));
        $jenis_permintaan = trim((string)($_GET['jenis_permintaan'] ?? 'Rutin'));

        if ($jenis_permintaan !== 'Non Rutin' && !empty($_GET['daftar_kategori'])) {
            $stmt = $this->db()->pdo()->query("SELECT DISTINCT b.kode_kategori AS kode, COALESCE(k.nama_kategori, NULLIF(b.sub_kategori, ''), NULLIF(b.kategori, ''), 'Tanpa Kelompok') AS nama FROM rsns_custom_logistik_non_medis_master_barang b LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori WHERE b.status = 'Aktif' ORDER BY nama ASC");
            header('Content-Type: application/json');
            echo json_encode($stmt->fetchAll(\PDO::FETCH_ASSOC));
            exit();
        }

        if ($jenis_permintaan === 'Non Rutin') {
            $sql = "SELECT kode AS kode_item, nama AS nama_barang, '' AS satuan_dasar,
                           nama_kelompok, nama_jenis
                    FROM rsns_custom_logistik_non_medis_inventaris_master
                    WHERE jenis_master = 'BARANG' AND kode_kategori = '2' AND status = 'Aktif'";
            $params = [];
            if ($cari !== '') {
                $sql .= " AND (nama LIKE ? OR kode LIKE ? OR nama_kelompok LIKE ? OR nama_jenis LIKE ?)";
                $like = '%' . $cari . '%';
                $params = [$like, $like, $like, $like];
            }
            $sql .= " ORDER BY nama ASC LIMIT 20";
            $stmt = $this->db()->pdo()->prepare($sql);
            $stmt->execute($params);
            $items = $stmt->fetchAll(\PDO::FETCH_ASSOC);

            header('Content-Type: application/json');
            echo json_encode($items ?: []);
            exit();
        }

        $kelompok = trim((string)($_GET['kelompok_barang'] ?? ''));
        $sql = "SELECT kode_item, nama_barang, satuan_dasar, kode_kategori, harga_referensi FROM rsns_custom_logistik_non_medis_master_barang WHERE status = 'Aktif'";
        $params = [];
        if (!empty($_GET['non_aset'])) $sql .= " AND tipe_barang = 'Habis Pakai'";
        if ($kelompok !== '') { $sql .= ' AND kode_kategori = ?'; $params[] = $kelompok; }
        if ($cari !== '') { $sql .= ' AND (nama_barang LIKE ? OR kode_item LIKE ?)'; $like = '%' . $cari . '%'; $params[] = $like; $params[] = $like; }
        $sql .= ' ORDER BY nama_barang ASC LIMIT 20';
        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute($params);
        $items = $stmt->fetchAll(\PDO::FETCH_ASSOC) ?: [];

        header('Content-Type: application/json');
        echo json_encode($items);
        exit();
    }

    public function anyAjaxPerbandinganPpi()
    {
        $t1_start = $_POST['t1_start'] ?? '';
        $t1_end = $_POST['t1_end'] ?? '';
        $t2_start = $_POST['t2_start'] ?? '';
        $t2_end = $_POST['t2_end'] ?? '';

        $ppi_condition = " AND (b.nama_barang LIKE '%plastik 40%' OR b.nama_barang LIKE '%plastik 80%' OR b.nama_barang LIKE '%kuning%' OR b.nama_barang LIKE '%hitam%' OR b.nama_barang LIKE '%tisu besar%' OR b.nama_barang LIKE '%tisu kecil%') ";

        // Get items for Period 1
        $sql1 = "SELECT b.nama_barang as nama, COALESCE(SUM(s.jumlah_disetujui), 0) as qty1 
               FROM rsns_custom_logistik_non_medis_sppb s 
               LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item 
               WHERE s.status IN ('Selesai', 'Diterima') AND s.tgl_sppb BETWEEN ? AND ? " . $ppi_condition . " 
               GROUP BY s.kode_item";
        $stmt1 = $this->db()->pdo()->prepare($sql1);
        $stmt1->execute([$t1_start, $t1_end]);
        $data1 = $stmt1->fetchAll(\PDO::FETCH_ASSOC);

        // Get items for Period 2
        $sql2 = "SELECT b.nama_barang as nama, COALESCE(SUM(s.jumlah_disetujui), 0) as qty2 
               FROM rsns_custom_logistik_non_medis_sppb s 
               LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item 
               WHERE s.status IN ('Selesai', 'Diterima') AND s.tgl_sppb BETWEEN ? AND ? " . $ppi_condition . " 
               GROUP BY s.kode_item";
        $stmt2 = $this->db()->pdo()->prepare($sql2);
        $stmt2->execute([$t2_start, $t2_end]);
        $data2 = $stmt2->fetchAll(\PDO::FETCH_ASSOC);

        $combined = [];
        foreach ($data1 as $row) {
            $combined[$row['nama']] = ['nama' => $row['nama'], 'qty1' => $row['qty1'], 'qty2' => 0];
        }
        foreach ($data2 as $row) {
            if (!isset($combined[$row['nama']])) {
                $combined[$row['nama']] = ['nama' => $row['nama'], 'qty1' => 0, 'qty2' => 0];
            }
            $combined[$row['nama']]['qty2'] = $row['qty2'];
        }

        $result = array_values($combined);

        // Sort by absolute diff descending
        usort($result, function ($a, $b) {
            return abs($b['qty1'] - $b['qty2']) - abs($a['qty1'] - $a['qty2']);
        });

        header('Content-Type: application/json');
        echo json_encode(['status' => 'ok', 'data' => $result]);
        exit();
    }

    public function anyDisplaySppbPpi()
    {
        $perpage = 20;
        $halaman = isset($_POST['halaman']) ? (int)$_POST['halaman'] : 1;
        $cari = isset($_POST['cari']) ? $_POST['cari'] : '';
        $status = isset($_POST['status']) ? $_POST['status'] : '';
        $tgl_awal = isset($_POST['tgl_awal']) ? $_POST['tgl_awal'] : '';
        $tgl_akhir = isset($_POST['tgl_akhir']) ? $_POST['tgl_akhir'] : '';
        $unit_filter = isset($_POST['unit']) ? $_POST['unit'] : '';

        $_offset = ($halaman - 1) * $perpage;

        $username = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = strtolower($userRoleData['role'] ?? $this->core->getUserInfo('role', null, true) ?: 'unit');
        $user_kode_unit = $userRoleData['kode_unit'] ?? null;
        $can_manage_distribusi_controls = in_array($role, ['admin', 'logistik'], true);

        if (!$can_manage_distribusi_controls) {
            $cari = '';
            $status = '';
            $unit_filter = '';
        }

        // Filter item langsung supaya daftar barang dan jumlah item di riwayat
        // hanya berisi barang PPI, bukan seluruh item dalam SPPB yang kebetulan
        // memiliki satu barang PPI.
        $ppi_condition = " AND (b.nama_barang LIKE '%plastik 40%' OR b.nama_barang LIKE '%plastik 80%' OR b.nama_barang LIKE '%kuning%' OR b.nama_barang LIKE '%hitam%' OR b.nama_barang LIKE '%tisu besar%' OR b.nama_barang LIKE '%tisu kecil%') ";

        $sql = "
          SELECT s.no_sppb, s.tgl_sppb, s.kode_unit, u.nama_unit, s.status, s.keterangan, s.jenis_permintaan, s.tgl_input,
                 s.ditolak_pada_status, s.diambil_oleh, s.tgl_diambil,
                 EXISTS(SELECT 1 FROM rsns_custom_logistik_non_medis_serah_terima st WHERE st.no_sppb = s.no_sppb AND st.tanda_terima IS NOT NULL AND st.tanda_terima != '') AS has_bast,
                 COUNT(s.kode_item) as jml_item,
                 GROUP_CONCAT(CONCAT(COALESCE(NULLIF(s.nama_barang_manual, ''), b.nama_barang, s.kode_item), IF(s.jenis_keluar = 'Tambahan', ' <span class=\"label label-success\">Tambahan</span>', '')) SEPARATOR ', ') as daftar_barang
          FROM rsns_custom_logistik_non_medis_sppb s
          LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = s.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item
          WHERE 1=1 " . $ppi_condition;

        $params = [];
        if (!empty($cari)) {
            $sql .= " AND (s.no_sppb LIKE ? OR u.nama_unit LIKE ? OR b.nama_barang LIKE ? OR s.nama_barang_manual LIKE ?) ";
            $params[] = '%' . $cari . '%';
            $params[] = '%' . $cari . '%';
            $params[] = '%' . $cari . '%';
            $params[] = '%' . $cari . '%';
        }

        if (!empty($status)) {
            $sql .= " AND s.status = ? ";
            $params[] = $status;
        }

        if (!empty($tgl_awal) && !empty($tgl_akhir)) {
            $sql .= " AND s.tgl_sppb BETWEEN ? AND ? ";
            $params[] = $tgl_awal;
            $params[] = $tgl_akhir;
        } elseif (!empty($tgl_awal)) {
            $sql .= " AND s.tgl_sppb >= ? ";
            $params[] = $tgl_awal;
        } elseif (!empty($tgl_akhir)) {
            $sql .= " AND s.tgl_sppb <= ? ";
            $params[] = $tgl_akhir;
        }

        if (!empty($unit_filter)) {
            $sql .= " AND s.kode_unit = ? ";
            $params[] = $unit_filter;
        }

        if (in_array($role, ['unit', 'kepala_unit', 'kepala_sie', 'kepala_bidang']) && !empty($user_kode_unit)) {
            $units_arr = $this->getChildUnitCodes(explode(',', $user_kode_unit));
            $placeholders = implode(',', array_fill(0, count($units_arr), '?'));
            $sql .= " AND s.kode_unit IN ($placeholders) ";
            foreach ($units_arr as $uu) {
                $params[] = trim($uu);
            }
        }

        $sql .= " GROUP BY s.no_sppb ORDER BY s.tgl_sppb DESC ";

        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute($params);
        $all_data = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        $total_data = count($all_data);

        $data = array_slice($all_data, $_offset, $perpage);
        $jml_halaman = ceil($total_data / $perpage);

        foreach ($data as $i => &$row) {
            $row['no'] = $i + 1 + $_offset;
            $row['tgl_sppb'] = date('d/m/Y', strtotime($row['tgl_sppb']));
            $row['can_edit'] = false;
            $row['can_delete'] = false;
            $row['can_approve_ka_unit'] = false;
            $row['can_approve_ka_sie'] = false;
            $row['can_approve_ka_bidang'] = false;
            $row['can_proses_logistik'] = false;
            $row['can_review_logistik'] = false;
            $row['can_keputusan_dana'] = false;
            $row['can_siap_ambil'] = false;
            $row['can_selesaikan'] = false;
            $row['can_buat_surat_order'] = false;
        }

        $pages = [];
        for ($i = 1; $i <= $jml_halaman; $i++) {
            $pages[] = $i;
        }

        $count_belum_diproses = 0;
        $count_siap_diambil = 0;
        $count_selesai = 0;

        foreach ($all_data as $s_row) {
            $s_status = $s_row['status'] ?? '';
            if (in_array($s_status, ['Selesai', 'Ditolak', 'Batal', 'Dibatalkan'])) {
                $count_selesai++;
            } else {
                if (in_array($s_status, ['Draft', 'Diajukan'])) {
                    $count_belum_diproses++;
                }
                if (in_array($s_status, ['Siap Ambil', 'Siap Diserahkan'])) {
                    $count_siap_diambil++;
                }
            }
        }

        echo $this->draw('distribusi.ppi.display.html', [
          'sppb' => $data,
          'halaman' => $halaman,
          'jml_halaman' => $jml_halaman,
          'total_data' => $total_data,
          'role' => $role,
          'can_manage_distribusi_controls' => $can_manage_distribusi_controls,
          'count_belum_diproses' => $count_belum_diproses,
          'count_siap_diambil' => $count_siap_diambil,
          'count_selesai' => $count_selesai,
          'pages' => $pages
        ]);
        exit();
    }

    public function anyDisplaySppb()
    {
        try {
            $this->_initPemenuhanNonRutin();
            $this->_initPo();
            $this->_initPenerimaan();
            $perpage = 10;
            $halaman = isset($_POST['halaman']) ? (int)$_POST['halaman'] : 1;
            $cari = isset($_POST['cari']) ? $_POST['cari'] : '';
            $status = isset($_POST['status']) ? $_POST['status'] : '';
            $jenis_permintaan = isset($_POST['jenis_permintaan']) ? $_POST['jenis_permintaan'] : '';
            $approval_tab = isset($_POST['approval_tab']) ? $_POST['approval_tab'] : '';
            $list_tab = isset($_POST['list_tab']) ? $_POST['list_tab'] : '';

            $_offset = ($halaman - 1) * $perpage;

            $username = $this->core->getUserInfo('username', null, true);
            $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
            $role = $userRoleData['role'] ?? 'unit';
            $user_kode_unit = $userRoleData['kode_unit'] ?? null;
            $can_manage_distribusi_controls = in_array($role, ['admin', 'logistik'], true);

            $tgl_awal = isset($_POST['tgl_awal']) ? $_POST['tgl_awal'] : '';
            $tgl_akhir = isset($_POST['tgl_akhir']) ? $_POST['tgl_akhir'] : '';
            $unit_filter = isset($_POST['unit']) ? $_POST['unit'] : '';

            if (!$can_manage_distribusi_controls) {
                  $cari = '';
                  $status = '';
                  $unit_filter = '';
            }

            $sql = "
          SELECT s.no_sppb, s.tgl_sppb, s.kode_unit, u.nama_unit, s.status, s.keterangan, s.jenis_permintaan, s.tgl_input,
                 s.ditolak_pada_status, s.diambil_oleh, s.tgl_diambil,
                 MAX(s.sumber_pemenuhan) AS sumber_pemenuhan,
                 MAX(s.referensi_pemenuhan) AS referensi_pemenuhan,
                 EXISTS(SELECT 1 FROM rsns_custom_logistik_non_medis_serah_terima st WHERE st.no_sppb = s.no_sppb AND st.tanda_terima IS NOT NULL AND st.tanda_terima != '') AS has_bast,
                 COUNT(s.kode_item) as jml_item,
                 GROUP_CONCAT(CONCAT(
                   CASE WHEN s.jenis_permintaan = 'Non Rutin'
                     THEN COALESCE(NULLIF(s.nama_barang_manual, ''), im.nama, b.nama_barang, s.kode_item)
                     ELSE COALESCE(NULLIF(s.nama_barang_manual, ''), b.nama_barang, s.kode_item)
                   END,
                   IF(s.jenis_keluar = 'Tambahan', ' <span class=\"label label-success\">Tambahan</span>', '')
                 ) SEPARATOR ', ') as daftar_barang
          FROM rsns_custom_logistik_non_medis_sppb s
          LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = s.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im
            ON im.jenis_master = 'BARANG' AND im.kode_kategori = '2' AND im.kode = s.kode_item
          WHERE 1=1
      ";

            if ($this->_demoModeEnabled()) {
                $sql .= " AND s.no_sppb LIKE 'DEMO-OPERASIONAL-%' ";
            }

            $params = [];
            if (!empty($cari)) {
                $sql .= " AND (s.no_sppb LIKE ? OR u.nama_unit LIKE ? OR b.nama_barang LIKE ? OR s.nama_barang_manual LIKE ? OR (s.jenis_permintaan = 'Non Rutin' AND im.nama LIKE ?)) ";
                $params[] = '%' . $cari . '%';
                $params[] = '%' . $cari . '%';
                $params[] = '%' . $cari . '%';
                $params[] = '%' . $cari . '%';
                $params[] = '%' . $cari . '%';
            }

            if (!empty($status)) {
                $sql .= " AND s.status = ? ";
                $params[] = $status;
            }

            if (!empty($jenis_permintaan)) {
                $sql .= " AND s.jenis_permintaan = ? ";
                $params[] = $jenis_permintaan;
            }

            if (!empty($tgl_awal) && !empty($tgl_akhir)) {
                $sql .= " AND s.tgl_sppb BETWEEN ? AND ? ";
                $params[] = $tgl_awal;
                $params[] = $tgl_akhir;
            } elseif (!empty($tgl_awal)) {
                $sql .= " AND s.tgl_sppb >= ? ";
                $params[] = $tgl_awal;
            } elseif (!empty($tgl_akhir)) {
                $sql .= " AND s.tgl_sppb <= ? ";
                $params[] = $tgl_akhir;
            }

            if (!empty($unit_filter)) {
                $sql .= " AND s.kode_unit = ? ";
                $params[] = $unit_filter;
            }

            if (in_array($role, ['unit', 'kepala_unit', 'kepala_sie', 'kepala_bidang']) && !empty($user_kode_unit)) {
                $units_arr = $this->getChildUnitCodes(explode(',', $user_kode_unit));
                $placeholders = implode(',', array_fill(0, count($units_arr), '?'));
                $sql .= " AND s.kode_unit IN ($placeholders) ";
                foreach ($units_arr as $uu) {
                    $params[] = trim($uu);
                }
            }

        // Tab filtering untuk role approver
            if (in_array($role, ['kepala_unit', 'kepala_sie', 'kepala_bidang']) && !empty($approval_tab)) {
                if ($approval_tab === 'pending') {
                    if ($role === 'kepala_unit') {
                        // Ka. Unit hanya approve Non Rutin; Rutin langsung ke logistik
                        $sql .= " AND s.jenis_permintaan = 'Non Rutin' AND s.status = 'Diajukan' ";
                    } elseif ($role === 'kepala_sie') {
                        // Ka. Sie hanya approve Non Rutin yang sudah disetujui Ka. Unit; Rutin dihandle logistik
                        $sql .= " AND s.jenis_permintaan = 'Non Rutin' AND s.status = 'Disetujui Ka. Unit' ";
                    } elseif ($role === 'kepala_bidang') {
                        $sql .= " AND s.jenis_permintaan = 'Non Rutin' AND s.status = 'Disetujui Ka. Sie' ";
                    }
                } elseif ($approval_tab === 'history') {
                    if ($role === 'kepala_unit') {
                        $sql .= " AND s.user_approve_ka_unit = ? ";
                        $params[] = $username;
                    } elseif ($role === 'kepala_sie') {
                        $sql .= " AND s.user_approve_ka_sie = ? ";
                        $params[] = $username;
                    } elseif ($role === 'kepala_bidang') {
                        $sql .= " AND s.user_approve_ka_bidang = ? ";
                        $params[] = $username;
                    }
                }
            } else {
                // Tab filtering untuk list utama (Aktif vs Riwayat) jika bukan di tab approval
                if (!empty($list_tab)) {
                    if ($list_tab === 'active') {
                        $sql .= " AND s.status NOT IN ('Selesai', 'Batal', 'Dibatalkan', 'Ditolak') ";
                    } elseif ($list_tab === 'history') {
                        $sql .= " AND s.status IN ('Selesai', 'Batal', 'Dibatalkan', 'Ditolak') ";
                    }
                }
            }

            $sql .= " GROUP BY s.no_sppb, s.tgl_sppb, s.kode_unit, u.nama_unit, s.status, s.keterangan, s.jenis_permintaan, s.tgl_input, s.ditolak_pada_status, s.diambil_oleh, s.tgl_diambil
                ORDER BY s.tgl_input DESC, s.no_sppb DESC ";

            $stmt = $this->db()->pdo()->prepare($sql);
            $stmt->execute($params);
            $all_data = $stmt->fetchAll(\PDO::FETCH_ASSOC);
            if (!is_array($all_data)) {
                $all_data = [];
            }

            $jumlah_data = count($all_data);
            $jml_halaman = $jumlah_data > 0 ? ceil($jumlah_data / $perpage) : 1;
            $rows = array_slice($all_data, $_offset, $perpage);

        // Calculate summary independent of pagination but dependent on filters
        // Note: we use all_data to calculate the summary
            $count_belum_diproses = 0;
            $count_siap_diambil = 0;
            $count_selesai = 0;

            foreach ($all_data as $s_row) {
                $s_status = $s_row['status'] ?? '';
                $s_jenis = $s_row['jenis_permintaan'] ?? 'Rutin';

                if (in_array($s_status, ['Selesai', 'Ditolak', 'Batal', 'Dibatalkan'])) {
                    $count_selesai++;
                } else {
                    if ($s_jenis === 'Rutin') {
                        if (in_array($s_status, ['Draft', 'Diajukan'])) {
                            $count_belum_diproses++;
                        }
                        if (in_array($s_status, ['Siap Ambil', 'Siap Diserahkan'])) {
                            $count_siap_diambil++;
                        }
                    } else {
                        // Non Rutin
                        if (in_array($s_status, ['Draft', 'Diajukan', 'Disetujui Ka. Unit', 'Disetujui Ka. Sie', 'Disetujui Kabid', 'Diserahkan ke Kasie Umum', 'Verifikasi Kasie Umum'])) {
                            $count_belum_diproses++;
                        }
                        if (in_array($s_status, ['Siap Ambil', 'Siap Diserahkan'])) {
                            $count_siap_diambil++;
                        }
                    }
                }
            }

            $current_no_sppbs = array_unique(array_column($rows, 'no_sppb'));
            $non_editable_sppbs = [];
            if (!empty($current_no_sppbs)) {
                $placeholders = implode(',', array_fill(0, count($current_no_sppbs), '?'));
                $sql_non_editable = "SELECT DISTINCT no_sppb FROM rsns_custom_logistik_non_medis_sppb 
                               WHERE no_sppb IN ($placeholders) 
                               AND status NOT IN ('Draft', 'Diajukan', 'Ditolak')";
                $stmt_non_editable = $this->db()->pdo()->prepare($sql_non_editable);
                $stmt_non_editable->execute(array_values($current_no_sppbs));
                $non_editable_sppbs = $stmt_non_editable->fetchAll(\PDO::FETCH_COLUMN);
            }

            $can_decide_konsul_kabid = $this->_canAccessRekapNonRutin();
            foreach ($rows as $i => &$row) {
                $row['no'] = $i + 1 + $_offset;
                $row['tgl_sppb'] = date('d/m/Y', strtotime($row['tgl_sppb']));
                $row['can_edit'] = false;
                $row['can_delete'] = false;
                $row['can_approve_ka_unit'] = false;
                $row['can_approve_ka_sie'] = false;
                $row['can_approve_ka_bidang'] = false;
                $row['can_proses_logistik'] = false;
                $row['can_review_logistik'] = false;
                $row['can_keputusan_dana'] = false;
                $row['can_siap_ambil'] = false;
                $row['can_selesaikan'] = false;
                $row['can_generate_po'] = false;
                $row['can_open_po'] = false;
                $row['can_receive_po'] = false;
                $row['can_tindak_lanjut'] = false;
                $row['no_po'] = '';
                $row['po_status'] = '';
                $row['po_url'] = '';
                $row['penerimaan_url'] = '';
                $row['pemenuhan_url'] = '';

                $row_status = $row['status'] ?? '';
                $row_jenis = $row['jenis_permintaan'] ?? 'Rutin';
                if ($row_jenis === 'Non Rutin' && in_array($row_status, ['Logistik Umum & Rekap', 'Proses Pengadaan'], true)) {
                    $row['can_tindak_lanjut'] = in_array($role, ['admin', 'logistik'], true);
                    $row['pemenuhan_url'] = url([ADMIN, 'logistik_non_medis', 'permintaannonrutin'])
                      . '&no_sppb=' . rawurlencode((string)$row['no_sppb']);
                }
                if ($row_jenis === 'Non Rutin' && $row_status === 'Proses Pengadaan') {
                    $active_po = $this->_findActivePoFromSppb((string)$row['no_sppb']);
                    if ($active_po) {
                        $row['no_po'] = (string)($active_po['no_po'] ?? '');
                        $row['po_status'] = (string)($active_po['status'] ?? '');
                        $row['po_url'] = url([ADMIN, 'logistik_non_medis', 'pengadaanpo'])
                          . '&no_po=' . rawurlencode($row['no_po']) . '#po-form';
                        $row['penerimaan_url'] = url([ADMIN, 'logistik_non_medis', 'pengadaanpenerimaan'])
                          . '&no_po=' . rawurlencode($row['no_po']) . '#penerimaan-form';
                        $row['can_open_po'] = in_array($role, ['admin', 'logistik'], true);
                        $row['can_receive_po'] = in_array($role, ['admin', 'logistik'], true)
                          && in_array($row['po_status'], ['Terkirim', 'Sebagian Diterima'], true);
                    }
                }
                $row['ditolak_pada_label'] = $this->_getSppbRejectStageLabel(
                    $row['ditolak_pada_status'] ?? '',
                    $row_jenis
                );
                $in_unit_scope = true;
                if (in_array($role, ['unit', 'kepala_unit', 'kepala_sie', 'kepala_bidang'], true) && !empty($user_kode_unit)) {
                    $scope_units = $this->getChildUnitCodes(explode(',', $user_kode_unit));
                    $in_unit_scope = in_array($row['kode_unit'], $scope_units, true);
                }

                $is_fully_editable = !in_array($row['no_sppb'], $non_editable_sppbs, true);

                // Unit/perwakilan unit hanya boleh mengubah pengajuan yang belum melewati tahap Diajukan.
                if ($role === 'admin') {
                    $row['can_edit'] = $is_fully_editable && in_array($row_status, ['Draft', 'Diajukan', 'Ditolak'], true);
                    $row['can_delete'] = $is_fully_editable && in_array($row_status, ['Draft', 'Diajukan'], true);
                } elseif ($role === 'logistik') {
                    $row['can_edit'] = $is_fully_editable && in_array($row_status, ['Draft', 'Diajukan', 'Ditolak'], true);
                } elseif (in_array($role, ['unit', 'kepala_unit', 'kepala_sie', 'kepala_bidang'], true) && $in_unit_scope) {
                    $row['can_edit'] = $is_fully_editable && in_array($row_status, ['Draft', 'Diajukan', 'Ditolak'], true);
                    $row['can_delete'] = $is_fully_editable && in_array($row_status, ['Draft', 'Diajukan'], true);
                }

                // Persetujuan mengikuti step.
                // Rutin: langsung ke logistik (tidak ada approval Ka. Unit).
                // Non Rutin: Ka. Unit → Ka. Sie → Ka. Bid → logistik.
                if ($row_jenis !== 'Rutin') {
                    $row['can_approve_ka_unit'] = $row_status === 'Diajukan' && (($role === 'kepala_unit' && $in_unit_scope) || $role === 'admin');
                    $row['can_approve_ka_sie'] = $row_status === 'Disetujui Ka. Unit' && (($role === 'kepala_sie' && $in_unit_scope) || $role === 'admin');
                    $row['can_approve_ka_bidang'] = $row_status === 'Disetujui Ka. Sie' && (($role === 'kepala_bidang' && $in_unit_scope) || $role === 'admin');
                }

                $row['can_proses_logistik'] = ($role === 'admin' || $role === 'logistik') && (
                  // Rutin: langsung bisa diproses dari status Diajukan
                  ($row_jenis === 'Rutin' && in_array($row_status, ['Diajukan', 'Disetujui Unit'], true))
                  // Non Rutin: baru bisa diproses setelah Disetujui Kabid
                  || ($row_jenis !== 'Rutin' && in_array($row_status, ['Disetujui Kabid', 'Disetujui Unit'], true))
                );
                $row['can_review_logistik'] = ($role === 'admin' || $role === 'logistik') && (
                  $row_status === 'Proses Logistik'
                  || ($row_jenis === 'Non Rutin' && in_array($row_status, ['Diserahkan ke Kasie Umum','Verifikasi Kasie Umum','Diteruskan ke Logistik Umum','Rekap Logistik','Logistik Umum & Rekap'], true))
                );
                $row['can_keputusan_dana'] = $can_decide_konsul_kabid && $row_jenis === 'Non Rutin' && in_array($row_status, ['Konsultasi Dana','Konsul Pengajuan ke Kabid Umum'], true);
                $row['can_siap_ambil'] = ($role === 'admin' || $role === 'logistik')
                  && $row_jenis === 'Non Rutin'
                  && in_array($row_status, ['Diserahkan ke Keuangan','Pengajuan Dana ke Bendahara'], true);
                if ($row_jenis === 'Non Rutin' && $row_status === 'Proses Pengadaan') {
                    $row['can_siap_ambil'] = ($row['sumber_pemenuhan'] ?? '') === 'Pengadaan PO'
                      && $row['po_status'] === 'Selesai';
                }
                $row['can_selesaikan'] = in_array($role, ['admin', 'logistik'], true) && in_array($row_status, ['Siap Ambil','Siap Diserahkan'], true);
                $row['can_buat_surat_order'] = false;
            }

            $pages = [];
            for ($p = 1; $p <= $jml_halaman; $p++) {
                $pages[] = $p;
            }

            echo $this->draw('distribusi.sppb.display.html', [
            'sppb' => $rows,
            'halaman' => $halaman,
            'jumlah_data' => $jumlah_data,
            'jml_halaman' => $jml_halaman,
            'pages' => $pages,
            'admin_mode' => $this->settings->get('settings.admin_mode'),
            'role' => $role,
            'count_belum_diproses' => $count_belum_diproses,
            'count_siap_diambil' => $count_siap_diambil,
            'count_selesai' => $count_selesai
            ]);
            exit();
        } catch (\Throwable $e) {
            file_put_contents(sys_get_temp_dir() . '/mlite_sppb_error.txt', $e->getMessage() . "\n" . $e->getTraceAsString());
            echo "ERROR: " . $e->getMessage() . "<br>FILE: " . $e->getFile() . " LINE: " . $e->getLine();
            exit();
        }
    }

    public function anyFormSppb()
    {
        $this->_initSppb();
        $this->_initLokasi();
        $this->_initSatuan();

        $username = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';
        $user_kode_unit = $userRoleData['kode_unit'] ?? null;

        $units_raw = $this->db('rsns_custom_logistik_non_medis_unit')->toArray();
        $units = [];
        foreach ($units_raw as $u) {
            $n = strtolower($u['nama_unit'] ?? '');
            if (strpos($n, 'kasie') !== false || strpos($n, 'kanit') !== false || strpos($n, 'kabid') !== false) {
                continue;
            }
            $units[] = $u;
        }
        foreach ($units as &$unit_row) {
            $unit_row['ka_unit_parent'] = $this->_getKaUnitFromParent($unit_row['kode_unit'] ?? '');
        }
        unset($unit_row);
        $items = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('status', 'Aktif')->toArray();
        $satuans = $this->db('rsns_custom_logistik_non_medis_satuan')->asc('nama_satuan')->toArray();
        $satuan_options = '<option value="">-- Pilih --</option>';
        foreach ($satuans as $sat) {
            $nama_satuan = htmlspecialchars($sat['nama_satuan'] ?? '', ENT_QUOTES, 'UTF-8');
            if ($nama_satuan !== '') {
                $satuan_options .= '<option value="' . $nama_satuan . '">' . $nama_satuan . '</option>';
            }
        }

        if (isset($_POST['no_sppb'])) {
            $no_sppb = $_POST['no_sppb'];
            $rows = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->toArray();
            if (empty($rows)) {
                exit('Data permintaan tidak ditemukan.');
            }
            $sppb_ref = $rows[0];
            if (!in_array($sppb_ref['status'], ['Draft', 'Diajukan', 'Ditolak'], true)) {
                exit('<div class=\"alert alert-warning\"><i class=\"fa fa-exclamation-triangle\"></i> <strong>Data sudah diproses dan tidak dapat diubah secara keseluruhan.</strong><br><br>Beberapa barang dalam SPPB ini sudah diproses atau selesai. Jika Anda ingin mengatur <strong>Barang Tambahan</strong>, silakan tutup form ini, lalu klik tombol <strong>Detail (ikon mata biru)</strong> pada tabel, kemudian klik <strong>Atur Barang Tambahan</strong>.</div>');
            }
            if (in_array($role, ['unit', 'kepala_unit', 'kepala_sie', 'kepala_bidang'], true) && !empty($user_kode_unit)) {
                $units_arr = $this->getChildUnitCodes(explode(',', $user_kode_unit));
                if (!in_array($sppb_ref['kode_unit'], $units_arr, true)) {
                    exit('Anda tidak memiliki hak untuk mengubah permintaan unit lain.');
                }
            }
            foreach ($rows as &$r) {
                if ($sppb_ref['jenis_permintaan'] === 'Non Rutin') {
                    $barang = $this->db('rsns_custom_logistik_non_medis_inventaris_master')
                      ->where('jenis_master', 'BARANG')
                      ->where('kode_kategori', '2')
                      ->where('kode', $r['kode_item'])
                      ->oneArray();
                    $r['nama_barang'] = $r['nama_barang_manual'] ?: ($barang['nama'] ?? $r['kode_item']);
                } else {
                    $barang = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $r['kode_item'])->oneArray();
                    $r['nama_barang'] = $barang ? $barang['nama_barang'] : ($r['nama_barang_manual'] ?: $r['kode_item']);
                }
            }
            $sppb = $rows[0];
            if ($sppb['jenis_permintaan'] === 'Non Rutin' && empty($sppb['ka_unit'])) {
                $sppb['ka_unit'] = $this->_getKaUnitFromParent($sppb['kode_unit']);
            }
            $sppb['items'] = $rows;

            $status = $sppb['status'];
            $jenis_perm = $sppb['jenis_permintaan'];
            $stepper_step = 1;
            $stepper_rejected = false;

            if (in_array($status, ['Ditolak', 'Dibatalkan'])) {
                $stepper_rejected = true;
            } elseif ($jenis_perm === 'Non Rutin') {
                if ($status === 'Disetujui Ka. Unit') {
                    $stepper_step = 2;
                } elseif ($status === 'Disetujui Ka. Sie') {
                    $stepper_step = 3;
                } elseif ($status === 'Disetujui Kabid' || $status === 'Disetujui Unit') {
                    $stepper_step = 4;
                } elseif ($status === 'Diserahkan ke Kasie Umum') {
                    $stepper_step = 5;
                } elseif ($status === 'Verifikasi Kasie Umum') {
                    $stepper_step = 6;
                } elseif (in_array($status, ['Diteruskan ke Logistik Umum','Rekap Logistik','Logistik Umum & Rekap'], true)) {
                    $stepper_step = 7;
                } elseif (in_array($status, ['Konsultasi Dana','Konsul Pengajuan ke Kabid Umum'], true)) {
                    $stepper_step = 8;
                } elseif (in_array($status, ['Diserahkan ke Keuangan','Pengajuan Dana ke Bendahara'], true)) {
                    $stepper_step = 9;
                } elseif ($status === 'Proses Pengadaan') {
                    $stepper_step = 10;
                } elseif (in_array($status, ['Siap Ambil','Siap Diserahkan'], true)) {
                    $stepper_step = 11;
                } elseif ($status === 'Tidak ACC') {
                    $stepper_step = 8;
                    $stepper_rejected = true;
                } elseif (in_array($status, ['Selesai', 'Ready', 'Diterima'])) {
                    $stepper_step = 12;
                }
            } else {
                if (in_array($status, ['Disetujui Ka. Unit', 'Disetujui Ka. Sie', 'Disetujui Kabid', 'Disetujui Unit'])) {
                    $stepper_step = 2;
                } elseif (in_array($status, ['Proses Logistik', 'Proses', 'Terverifikasi'])) {
                    $stepper_step = 3;
                } elseif (in_array($status, ['Proses Pengadaan', 'Picking', 'Packing', 'Siap Ambil', 'Ready', 'Dikirim'])) {
                    $stepper_step = 4;
                } elseif (in_array($status, ['Diterima', 'Selesai'])) {
                    $stepper_step = 5;
                }
            }

            echo $this->draw('distribusi.sppb.form.html', ['sppb' => $sppb, 'mode' => 'edit', 'units' => $units, 'items' => $items, 'satuans' => $satuans, 'satuan_options' => $satuan_options, 'role' => $role, 'user_kode_unit' => $user_kode_unit, 'stepper_step' => $stepper_step, 'stepper_rejected' => $stepper_rejected]);
        } else {
            $sppb = [
              'no_sppb' => '',
              'tgl_sppb' => date('Y-m-d'),
              'kode_unit' => ($role === 'unit' && !empty($user_kode_unit)) ? $user_kode_unit : '',
              'jenis_permintaan' => isset($_POST['jenis']) ? $_POST['jenis'] : 'Rutin',
              'status' => 'Draft',
              'latar_belakang_tujuan' => '',
              'sasaran_kegunaan' => '',
              'rencana_digunakan' => '',
              'sifat_permintaan' => 'Biasa',
              'diajukan_oleh' => $username,
              'penanggung_jawab_1' => '',
              'penanggung_jawab_2' => '',
              'ka_unit' => '',
              'items' => []
            ];
            if (!empty($sppb['kode_unit'])) {
                $sppb['ka_unit'] = $this->_getKaUnitFromParent($sppb['kode_unit']);
            }
            echo $this->draw('distribusi.sppb.form.html', ['sppb' => $sppb, 'mode' => 'add', 'units' => $units, 'items' => $items, 'satuans' => $satuans, 'satuan_options' => $satuan_options, 'role' => $role, 'user_kode_unit' => $user_kode_unit, 'stepper_step' => 1, 'stepper_rejected' => false]);
        }
        exit();
    }

    public function anyDetailSppb()
    {
        $this->_initPemenuhanNonRutin();
        $this->_initSerahTerima();
        if (isset($_POST['no_sppb'])) {
            $no_sppb = $_POST['no_sppb'];
            $sql = "
              SELECT s.*, u.nama_unit,
                     CASE WHEN s.jenis_permintaan = 'Non Rutin'
                       THEN COALESCE(NULLIF(s.nama_barang_manual, ''), im.nama, b.nama_barang, s.kode_item)
                       ELSE COALESCE(NULLIF(s.nama_barang_manual, ''), b.nama_barang, s.kode_item)
                     END AS nama_barang
              FROM rsns_custom_logistik_non_medis_sppb s
              LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = s.kode_unit
              LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item
              LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im
                ON im.jenis_master = 'BARANG' AND im.kode_kategori = '2' AND im.kode = s.kode_item
              WHERE s.no_sppb = ?
          ";
            $stmt = $this->db()->pdo()->prepare($sql);
            $stmt->execute([$no_sppb]);
            $rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);

            if ($rows) {
                $jenis_perm = $rows[0]['jenis_permintaan'];
                $status = $rows[0]['status'];
                $username = $this->core->getUserInfo('username', null, true);
                $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
                $role = $userRoleData['role'] ?? 'unit';

                $can_add_tambahan = ($jenis_perm === 'Rutin' && in_array($role, ['unit', 'admin', 'logistik']) && !in_array($status, ['Ditolak', 'Dibatalkan']));

                foreach ($rows as $idx => &$row) {
                    $row['index'] = $idx;
                    $row['can_edit_tambahan'] = ($can_add_tambahan && isset($row['jenis_keluar']) && $row['jenis_keluar'] === 'Tambahan');
                    $row['foto_barang_html'] = '-';
                    $photo_list = json_decode($row['foto_barang'] ?? '[]', true);
                    if (is_array($photo_list) && !empty($photo_list)) {
                        $photo_html = '<div style="display:flex;flex-wrap:wrap;gap:5px;min-width:130px">';
                        foreach ($photo_list as $photo_name) {
                            $photo_name = basename((string)$photo_name);
                            if ($photo_name === '') {
                                continue;
                            }
                            $photo_url = url('uploads/logistik_non_medis/sppb_items/' . $photo_name);
                            $safe_url = htmlspecialchars($photo_url, ENT_QUOTES, 'UTF-8');
                            $photo_html .= '<a href="' . $safe_url . '" target="_blank" title="Lihat foto barang"><img src="' . $safe_url . '" alt="Foto barang" style="width:55px;height:55px;object-fit:cover;border:1px solid #ddd;border-radius:4px"></a>';
                        }
                        $row['foto_barang_html'] = $photo_html . '</div>';
                    }
                }
                $sppb = $rows[0];
                $sppb['ditolak_pada_label'] = $this->_getSppbRejectStageLabel($sppb['ditolak_pada_status'] ?? '', $sppb['jenis_permintaan'] ?? '');
                $sppb['pemenuhan_url'] = url([ADMIN, 'logistik_non_medis', 'permintaannonrutin']) . '&no_sppb=' . rawurlencode($no_sppb);
                $sppb['items'] = $rows;

                $serah_terima = $this->db('rsns_custom_logistik_non_medis_serah_terima')
                                    ->where('no_sppb', $no_sppb)
                                    ->desc('id')
                                    ->oneArray();
                if ($serah_terima && !empty($serah_terima['tanda_terima'])) {
                    $serah_terima['tanda_tangan_url'] = $this->_serahTerimaSignatureDataUri((string)$serah_terima['tanda_terima']);
                    $serah_terima['hash_pendek'] = substr((string)($serah_terima['tanda_terima_hash'] ?? ''), 0, 12);
                    $serah_terima['hash_valid'] = $this->_isSerahTerimaSignatureHashValid((string)$serah_terima['tanda_terima'], (string)($serah_terima['tanda_terima_hash'] ?? ''));
                    $serah_terima['ukuran_ttd'] = strlen((string)$serah_terima['tanda_terima']);
                } else {
                    $serah_terima = [];
                }

                $user_kode_unit = $userRoleData['kode_unit'] ?? null;
                $units_arr = !empty($user_kode_unit) ? $this->getChildUnitCodes(explode(',', $user_kode_unit)) : [];

                $status = $sppb['status'];
                $jenis_perm = $sppb['jenis_permintaan'];
                $stepper_step = 1;
                $stepper_rejected = false;
                $can_approve_sppb = false;
                $sumber_pemenuhan = trim((string)($sppb['sumber_pemenuhan'] ?? ''));
                $flow_internal = in_array($sumber_pemenuhan, ['Stok Gudang', 'Mutasi Aset', 'Perbaikan Aset'], true);
                $flow_source_label = $sumber_pemenuhan !== '' ? $sumber_pemenuhan : 'Belum dipilih';
                $flow_next = 'Menunggu penentuan sumber pemenuhan oleh Logistik & Rekap.';

                if (in_array($status, ['Ditolak', 'Dibatalkan'])) {
                    $stepper_rejected = true;
                } elseif ($jenis_perm === 'Non Rutin') {
                    if ($status === 'Disetujui Ka. Unit') {
                        $stepper_step = 2;
                    } elseif ($status === 'Disetujui Ka. Sie') {
                        $stepper_step = 3;
                    } elseif ($status === 'Disetujui Kabid' || $status === 'Disetujui Unit') {
                        $stepper_step = 4;
                    } elseif ($status === 'Diserahkan ke Kasie Umum') {
                        $stepper_step = 5;
                    } elseif ($status === 'Verifikasi Kasie Umum') {
                        $stepper_step = 6;
                    } elseif (in_array($status, ['Diteruskan ke Logistik Umum','Rekap Logistik','Logistik Umum & Rekap'], true)) {
                        $stepper_step = 7;
                    } elseif (in_array($status, ['Konsultasi Dana','Konsul Pengajuan ke Kabid Umum'], true)) {
                        $stepper_step = 8;
                    } elseif (in_array($status, ['Diserahkan ke Keuangan','Pengajuan Dana ke Bendahara'], true)) {
                        $stepper_step = 9;
                    } elseif ($status === 'Proses Pengadaan') {
                        $stepper_step = 10;
                    } elseif (in_array($status, ['Siap Ambil','Siap Diserahkan'], true)) {
                        $stepper_step = 11;
                    } elseif ($status === 'Tidak ACC') {
                        $stepper_step = 8;
                        $stepper_rejected = true;
                    } elseif (in_array($status, ['Selesai', 'Ready', 'Diterima'])) {
                        $stepper_step = 12;
                    }

                    if ($status === 'Proses Pengadaan' && $sumber_pemenuhan === '') {
                        $stepper_step = 7;
                    } elseif ($status === 'Proses Pengadaan' && $flow_internal) {
                        $stepper_step = 8;
                    }
                } else {
                    if (in_array($status, ['Disetujui Ka. Unit', 'Disetujui Ka. Sie', 'Disetujui Kabid', 'Disetujui Unit'])) {
                        $stepper_step = 2;
                    } elseif (in_array($status, ['Proses Logistik', 'Proses', 'Terverifikasi'])) {
                        $stepper_step = 3;
                    } elseif (in_array($status, ['Proses Pengadaan', 'Picking', 'Packing', 'Siap Ambil', 'Ready', 'Dikirim'])) {
                        $stepper_step = 4;
                    } elseif (in_array($status, ['Diterima', 'Selesai'])) {
                        $stepper_step = 5;
                    }
                }

                if ($jenis_perm === 'Non Rutin') {
                    if ($sumber_pemenuhan === 'Stok Gudang') {
                        $flow_next = in_array($status, ['Siap Ambil', 'Siap Diserahkan'], true)
                          ? 'Barang sudah siap. Lanjutkan serah terima dan tanda tangan digital.'
                          : 'Stok gudang sedang diverifikasi.';
                    } elseif ($sumber_pemenuhan === 'Mutasi Aset') {
                        $flow_next = in_array($status, ['Siap Ambil', 'Siap Diserahkan'], true)
                          ? 'Mutasi aset telah selesai. Lanjutkan serah terima dan tanda tangan digital.'
                          : 'Menunggu persetujuan dan penyelesaian mutasi aset antarunit.';
                    } elseif ($sumber_pemenuhan === 'Perbaikan Aset') {
                        $flow_next = 'Menunggu pekerjaan perbaikan aset selesai; setelah itu pilih pemenuhan/serah terima.';
                    } elseif ($sumber_pemenuhan === 'Pengadaan PO') {
                        $flow_next = in_array($status, ['Siap Ambil', 'Siap Diserahkan'], true)
                          ? 'Barang PO telah diterima. Lanjutkan serah terima dan tanda tangan digital.'
                          : 'Menunggu proses PO dan penerimaan barang.';
                    }
                }

                if ($jenis_perm !== 'Rutin') {
                    if ($status === 'Diajukan' && in_array($role, ['kepala_unit', 'admin'], true)) {
                        $can_approve_sppb = $role !== 'kepala_unit' || empty($units_arr) || in_array($sppb['kode_unit'], $units_arr, true);
                    } elseif ($status === 'Disetujui Ka. Unit' && in_array($role, ['kepala_sie', 'admin'], true)) {
                        $can_approve_sppb = $role !== 'kepala_sie' || empty($units_arr) || in_array($sppb['kode_unit'], $units_arr, true);
                    } elseif ($status === 'Disetujui Ka. Sie' && in_array($role, ['kepala_bidang', 'admin'], true)) {
                        $can_approve_sppb = $role !== 'kepala_bidang' || empty($units_arr) || in_array($sppb['kode_unit'], $units_arr, true);
                    }
                }

                $inline_mode = isset($_POST['inline']) ? (int)$_POST['inline'] : 0;
                echo $this->draw('distribusi.sppb.detail.html', ['sppb' => $sppb, 'serah_terima' => $serah_terima, 'role' => $role, 'can_approve_sppb' => $can_approve_sppb, 'can_decide_konsul_kabid' => $this->_canAccessRekapNonRutin(), 'stepper_step' => $stepper_step, 'stepper_rejected' => $stepper_rejected, 'flow_internal' => $flow_internal, 'flow_source_label' => $flow_source_label, 'flow_next' => $flow_next, 'can_add_tambahan' => $can_add_tambahan, 'inline_mode' => $inline_mode]);
            }
        }
        exit();
    }

    public function postImportsppbmingguan()
    {
        $username = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';
        if (!in_array($role, ['admin', 'logistik'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Import hanya boleh dilakukan oleh role admin atau logistik.']);
            exit;
        }

        if (empty($_FILES['file']['tmp_name'])) {
            echo json_encode(['status' => 'error', 'message' => 'File tidak ditemukan']);
            exit;
        }

        $periode = $_POST['periode'] ?? date('Y-m');
        $minggu_ke = $_POST['minggu_ke'] ?? 1;

        $file = $_FILES['file']['tmp_name'];
        $handle = fopen($file, 'r');
        if (!$handle) {
            echo json_encode(['status' => 'error', 'message' => 'Gagal membaca file']);
            exit;
        }

        $header = fgetcsv($handle);
        if (!$header) {
            echo json_encode(['status' => 'error', 'message' => 'File kosong atau format salah']);
            exit;
        }

        $db = $this->db()->pdo();
        $sppb_data = [];
        $row_num = 1;
        $errors = [];

        // Load all units and items into memory for fast lookup
        $units = $this->db('rsns_custom_logistik_non_medis_unit')->toArray();
        $unit_map = [];
        foreach ($units as $u) {
            $unit_map[strtolower(trim($u['nama_unit']))] = $u['kode_unit'];
        }

        $items = $this->db('rsns_custom_logistik_non_medis_master_barang')->toArray();
        $item_map = [];
        foreach ($items as $i) {
            $item_map[strtolower(trim($i['nama_barang']))] = $i['kode_item'];
        }

        while (($data = fgetcsv($handle)) !== false) {
            $row_num++;
            if (count($data) < 4) {
                continue;
            }

            $nama_unit = trim($data[1]);
            $nama_barang = trim($data[2]);
            $jumlah = floatval(trim($data[3]));

            if (empty($nama_unit) || empty($nama_barang) || $jumlah <= 0) {
                continue;
            }

            $unit_key = strtolower($nama_unit);
            $item_key = strtolower($nama_barang);

            if (!isset($unit_map[$unit_key])) {
                $errors[] = "Baris $row_num: Unit '$nama_unit' tidak ditemukan.";
                continue;
            }

            if (!isset($item_map[$item_key])) {
                $errors[] = "Baris $row_num: Barang '$nama_barang' tidak ditemukan.";
                continue;
            }

            $kode_unit = $unit_map[$unit_key];
            $kode_item = $item_map[$item_key];

            if (!isset($sppb_data[$kode_unit])) {
                $sppb_data[$kode_unit] = [];
            }

            $sppb_data[$kode_unit][] = [
              'kode_item' => $kode_item,
              'jumlah' => $jumlah
            ];
        }
        fclose($handle);

        if (empty($sppb_data)) {
            $msg = "Tidak ada data valid yang bisa diimport. " . implode("<br>", $errors);
            echo json_encode(['status' => 'error', 'message' => $msg]);
            exit;
        }

        $success_count = 0;
        $tgl_sppb = $periode . '-01'; // Default date within the period
        $user_input = $this->core->getUserInfo('username', null, true);

        foreach ($sppb_data as $kode_unit => $items) {
            $no_sppb = $this->_generateNoSPPB($kode_unit);

            foreach ($items as $item) {
                $data_insert = [
                  'no_sppb' => $no_sppb,
                  'tgl_sppb' => $tgl_sppb,
                  'minggu_ke' => $minggu_ke,
                  'kode_unit' => $kode_unit,
                  'jenis_permintaan' => 'Rutin',
                  'kode_item' => $item['kode_item'],
                  'jumlah' => $item['jumlah'],
                  'status' => 'Diajukan',
                  'sifat_permintaan' => 'Rutin',
                  'user_input' => $user_input,
                  'tgl_input' => date('Y-m-d H:i:s')
                ];
                $this->db('rsns_custom_logistik_non_medis_sppb')->save($data_insert);
                $success_count++;
            }

            $this->_logAction('logistik_non_medis_sppb', 'Import SPPB Mingguan: ' . $no_sppb . ' (Minggu ke-' . $minggu_ke . ')', 'I');
        }

        $msg = "Berhasil mengimport $success_count item ke dalam " . count($sppb_data) . " nomor SPPB.";
        if (!empty($errors)) {
            $msg .= "<br><br><strong>Peringatan:</strong><br>" . implode("<br>", array_slice($errors, 0, 10));
            if (count($errors) > 10) {
                $msg .= "<br>...dan " . (count($errors) - 10) . " error lainnya.";
            }
        }

        echo json_encode(['status' => 'success', 'message' => $msg]);
        exit;
    }

    public function postSaveSppb()
    {
        ob_start(); // Prevent PHP Notice/Warning from polluting JSON response
        $no_sppb = $_POST['no_sppb'] ?? '';
        $kode_unit = $_POST['kode_unit'] ?? '';
        $status = $_POST['status'] ?? 'Diajukan';
        $user = $this->core->getUserInfo('username', null, true);

        // Determine jenis_permintaan automatically from item type (Habis Pakai vs Aset)
        // Use single IN() query instead of per-item queries for performance
        $jenis_permintaan = 'Rutin';
        if (isset($_POST['kode_item']) && is_array($_POST['kode_item'])) {
            $kode_items = array_filter($_POST['kode_item']);
            if (!empty($kode_items)) {
                $placeholders = implode(',', array_fill(0, count($kode_items), '?'));
                $stmt_tipe = $this->db()->pdo()->prepare("SELECT COUNT(*) FROM rsns_custom_logistik_non_medis_master_barang WHERE kode_item IN ($placeholders) AND tipe_barang = 'Aset'");
                $stmt_tipe->execute(array_values($kode_items));
                if ((int)$stmt_tipe->fetchColumn() > 0) {
                    $jenis_permintaan = 'Non Rutin';
                }
            }
        }


        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';
        $user_kode_unit = $userRoleData['kode_unit'] ?? null;

        if ($role === 'unit' && !empty($user_kode_unit)) {
            $kode_unit = $user_kode_unit; // enforce user's unit
        }

        if (empty($no_sppb)) {
            $no_sppb = $this->_generateNoSPPB($kode_unit);
        }

        // Check if already processed
        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if ($cek && !in_array($cek['status'], ['Draft', 'Diajukan', 'Ditolak'])) {
            while (ob_get_level()) {
                ob_end_clean();
            }
            echo json_encode(['status' => 'error', 'message' => 'Data sudah diproses dan tidak dapat diubah!']);
            exit();
        }

        $return_status_after_rejection = '';
        if ($cek && in_array($cek['status'], ['Ditolak', 'Draft'], true)) {
            // Restore the status it had before it was rejected (Bypass Opsi A)
            $return_status_after_rejection = $this->_normalizeSppbReturnStatus($cek['ditolak_pada_status'] ?? '');
            // The form probably sends 'Diajukan' if they hit "Simpan & Ajukan", override it:
            if (in_array($status, ['Diajukan', 'Ditolak'], true) && $return_status_after_rejection !== '') {
                $status = $return_status_after_rejection;
            }
        }

        // Enforce that a unit user can only edit their own SPPB
        if (in_array($role, ['unit', 'kepala_unit', 'kepala_sie', 'kepala_bidang'], true) && !empty($user_kode_unit) && $cek) {
            $units_arr = $this->getChildUnitCodes(explode(',', $user_kode_unit));
            if (!in_array($cek['kode_unit'], $units_arr, true)) {
                while (ob_get_level()) {
                    ob_end_clean();
                }
                echo json_encode(['status' => 'error', 'message' => 'Anda tidak memiliki hak untuk mengubah permintaan unit lain!']);
                exit();
            }
        }

        $jenis_permintaan = $_POST['jenis_permintaan'] ?? 'Rutin';
        $tgl_sppb = $_POST['tgl_sppb'] ?? date('Y-m-d');
        $nonrutin_meta = [
          'latar_belakang_tujuan' => trim((string)($_POST['latar_belakang_tujuan'] ?? '')),
          'sasaran_kegunaan' => trim((string)($_POST['sasaran_kegunaan'] ?? '')),
          'rencana_digunakan' => trim((string)($_POST['rencana_digunakan'] ?? '')),
          'sifat_permintaan' => (function () {
            $v = $_POST['sifat_permintaan'] ?? 'Biasa';
            return in_array($v, ['Urgent', 'Biasa'], true) ? $v : 'Biasa';
          })(),
          'diajukan_oleh' => trim((string)($_POST['diajukan_oleh'] ?? '')),
          'penanggung_jawab_1' => trim((string)($_POST['penanggung_jawab_1'] ?? '')),
          'penanggung_jawab_2' => trim((string)($_POST['penanggung_jawab_2'] ?? '')),
          'ka_unit' => $this->_getKaUnitFromParent($kode_unit)
        ];

        if ($jenis_permintaan === 'Non Rutin' && $status === 'Diajukan') {
            if ($nonrutin_meta['latar_belakang_tujuan'] === '' || $nonrutin_meta['sasaran_kegunaan'] === '' || $nonrutin_meta['rencana_digunakan'] === '' || $nonrutin_meta['diajukan_oleh'] === '' || $nonrutin_meta['penanggung_jawab_1'] === '') {
                while (ob_get_level()) {
                    ob_end_clean();
                }
                echo json_encode(['status' => 'error', 'message' => 'Data non rutin wajib diisi: latar belakang/tujuan, sasaran kegunaan, rencana digunakan, diajukan oleh, dan minimal 1 penanggung jawab.']);
                exit();
            }
        }

        if ($kode_unit === '' || $tgl_sppb === '') {
            while (ob_get_level()) {
                ob_end_clean();
            }
            echo json_encode(['status' => 'error', 'message' => 'Tanggal SPPB dan unit pengaju wajib diisi.']);
            exit();
        }

        $jumlah_items = isset($_POST['jumlah']) && is_array($_POST['jumlah']) ? count($_POST['jumlah']) : 0;
        if ($jumlah_items < 1) {
            while (ob_get_level()) {
                ob_end_clean();
            }
            echo json_encode(['status' => 'error', 'message' => 'Minimal satu barang wajib diisi.']);
            exit();
        }

        // Validate every item before existing rows are replaced.
        $validated_items = [];
        $allowed_old_photos = [];
        if ($cek) {
            $existing_rows = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->toArray();
            foreach ($existing_rows as $existing_row) {
                $old_list = json_decode($existing_row['foto_barang'] ?? '[]', true);
                if (is_array($old_list)) {
                    foreach ($old_list as $old_name) {
                        $old_name = basename((string)$old_name);
                        if ($old_name !== '') {
                            $allowed_old_photos[$old_name] = true;
                        }
                    }
                }
            }
        }

        $allowed_photo_mimes = [
          'image/jpeg' => 'jpg',
          'image/png' => 'png',
          'image/webp' => 'webp'
        ];
        $photo_upload_dir = UPLOADS . '/logistik_non_medis/sppb_items';

        for ($key = 0; $key < $jumlah_items; $key++) {
            $item_sumber = $_POST['item_sumber'][$key] ?? 'master';
            $kode_item = trim((string)($_POST['kode_item'][$key] ?? ''));
            $nama_barang_manual = trim((string)($_POST['nama_barang_manual'][$key] ?? ''));
            $spesifikasi_manual = trim((string)($_POST['spesifikasi_manual'][$key] ?? ''));
            $jumlah = (float)($_POST['jumlah'][$key] ?? 0);
            $satuan = trim((string)($_POST['satuan'][$key] ?? ''));
            $estimasi_harga = (float)($_POST['estimasi_harga'][$key] ?? 0);
            $keterangan_item = trim((string)($_POST['keterangan_item'][$key] ?? ''));

            if ($jumlah <= 0 || $satuan === '' || ($jenis_permintaan === 'Non Rutin' && $keterangan_item === '')) {
                while (ob_get_level()) {
                    ob_end_clean();
                }
                $required_message = $jenis_permintaan === 'Non Rutin'
                  ? 'jumlah, satuan, dan keterangan item wajib diisi.'
                  : 'jumlah dan satuan wajib diisi.';
                echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': ' . $required_message]);
                exit();
            }

            if ($jenis_permintaan === 'Non Rutin') {
                if (!in_array($item_sumber, ['master', 'manual'], true)) {
                    $item_sumber = 'manual';
                }
                if (($item_sumber === 'manual' && $nama_barang_manual === '') || ($item_sumber === 'master' && $kode_item === '')) {
                    while (ob_get_level()) {
                        ob_end_clean();
                    }
                    echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': barang atau nama usulan baru wajib diisi.']);
                    exit();
                }
                if ($item_sumber === 'master') {
                    $master_inventaris = $this->db('rsns_custom_logistik_non_medis_inventaris_master')
                      ->where('jenis_master', 'BARANG')
                      ->where('kode_kategori', '2')
                      ->where('status', 'Aktif')
                      ->where('kode', $kode_item)
                      ->oneArray();
                    if (!$master_inventaris) {
                        while (ob_get_level()) {
                            ob_end_clean();
                        }
                        echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': barang tidak ditemukan pada Master Inventaris.']);
                        exit();
                    }
                    // Simpan nama sebagai snapshot agar tetap terbaca di seluruh alur persetujuan dan laporan.
                    $nama_barang_manual = $master_inventaris['nama'];
                }
                if ($spesifikasi_manual === '' || $estimasi_harga <= 0) {
                    while (ob_get_level()) {
                        ob_end_clean();
                    }
                    echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': spesifikasi dan estimasi harga wajib diisi dengan nilai lebih dari nol.']);
                    exit();
                }
            } elseif ($kode_item === '') {
                while (ob_get_level()) {
                    ob_end_clean();
                }
                echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': barang wajib dipilih.']);
                exit();
            }

            $existing_photos = [];
            $old_json = $_POST['foto_barang_lama'][$key] ?? '[]';
            $old_photos = json_decode((string)$old_json, true);
            if (is_array($old_photos)) {
                foreach ($old_photos as $old_name) {
                    $old_name = basename((string)$old_name);
                    if (isset($allowed_old_photos[$old_name]) && is_file($photo_upload_dir . '/' . $old_name)) {
                        $existing_photos[] = $old_name;
                    }
                }
            }

            $new_photos = [];
            $file_names = $_FILES['foto_barang']['name'][$key] ?? [];
            $file_tmp_names = $_FILES['foto_barang']['tmp_name'][$key] ?? [];
            $file_errors = $_FILES['foto_barang']['error'][$key] ?? [];
            $file_sizes = $_FILES['foto_barang']['size'][$key] ?? [];
            if (!is_array($file_names)) {
                $file_names = [$file_names];
            }
            if (!is_array($file_tmp_names)) {
                $file_tmp_names = [$file_tmp_names];
            }
            if (!is_array($file_errors)) {
                $file_errors = [$file_errors];
            }
            if (!is_array($file_sizes)) {
                $file_sizes = [$file_sizes];
            }

            foreach ($file_names as $file_index => $original_name) {
                $upload_error = (int)($file_errors[$file_index] ?? UPLOAD_ERR_NO_FILE);
                if ($upload_error === UPLOAD_ERR_NO_FILE) {
                    continue;
                }
                if ($upload_error !== UPLOAD_ERR_OK) {
                    while (ob_get_level()) {
                        ob_end_clean();
                    }
                    echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': salah satu foto gagal diunggah.']);
                    exit();
                }
                if ((int)($file_sizes[$file_index] ?? 0) > 5 * 1024 * 1024) {
                    while (ob_get_level()) {
                        ob_end_clean();
                    }
                    echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': ukuran setiap foto maksimal 5 MB.']);
                    exit();
                }
                $tmp_name = $file_tmp_names[$file_index] ?? '';
                $finfo = finfo_open(FILEINFO_MIME_TYPE);
                $mime = $finfo && $tmp_name !== '' ? finfo_file($finfo, $tmp_name) : '';
                if ($finfo) {
                    finfo_close($finfo);
                }
                if (!isset($allowed_photo_mimes[$mime])) {
                    while (ob_get_level()) {
                        ob_end_clean();
                    }
                    echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': foto harus berformat JPG, PNG, atau WebP.']);
                    exit();
                }
                $new_photos[] = ['tmp_name' => $tmp_name, 'extension' => $allowed_photo_mimes[$mime]];
            }

            if ($jenis_permintaan === 'Non Rutin' && count($existing_photos) + count($new_photos) < 1) {
                while (ob_get_level()) {
                    ob_end_clean();
                }
                echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': minimal satu foto barang wajib diunggah.']);
                exit();
            }
            if (count($existing_photos) + count($new_photos) > 10) {
                while (ob_get_level()) {
                    ob_end_clean();
                }
                echo json_encode(['status' => 'error', 'message' => 'Baris ' . ($key + 1) . ': maksimal 10 foto untuk satu barang.']);
                exit();
            }

            $validated_items[$key] = [
              'item_sumber' => $item_sumber,
              'kode_item' => $kode_item,
              'nama_barang_manual' => $nama_barang_manual,
              'spesifikasi_manual' => $spesifikasi_manual,
              'jumlah' => $jumlah,
              'satuan' => $satuan,
              'estimasi_harga' => $estimasi_harga,
              'keterangan_item' => $keterangan_item,
              'existing_photos' => $existing_photos,
              'new_photos' => $new_photos
            ];
        }

        // Validasi 1 minggu 1 kali untuk Permintaan Rutin
        if ($jenis_permintaan === 'Rutin') {
            $timestamp = strtotime($tgl_sppb);
            $dayOfWeek = date('w', $timestamp);
            $offset = $dayOfWeek == 0 ? 6 : $dayOfWeek - 1;
            $monday = date('Y-m-d', strtotime("-$offset days", $timestamp));
            $sunday = date('Y-m-d', strtotime("+6 days", strtotime($monday)));

            $sql_cek_rutin = "SELECT no_sppb FROM rsns_custom_logistik_non_medis_sppb 
                            WHERE kode_unit = ? 
                            AND jenis_permintaan = 'Rutin'
                            AND status NOT IN ('Ditolak', 'Dibatalkan')
                            AND tgl_sppb BETWEEN ? AND ?
                            AND no_sppb != ?";
            $stmt_cek = $this->db()->pdo()->prepare($sql_cek_rutin);
            $stmt_cek->execute([$kode_unit, $monday, $sunday, $no_sppb]);
            $existing_rutin = $stmt_cek->fetch();

            if ($existing_rutin) {
                while (ob_get_level()) {
                    ob_end_clean();
                }
                echo json_encode(['status' => 'error', 'message' => 'Permintaan Rutin hanya dapat dilakukan 1 kali dalam seminggu (Senin - Minggu). Anda sudah mengajukan SPPB Rutin minggu ini (No: ' . $existing_rutin['no_sppb'] . '). Silakan ajukan Permintaan Non Rutin.']);
                exit();
            }
        }

        // Check Quota
        if ($status == 'Diajukan' || $status == 'Disetujui Unit') {
            $tgl_sppb = $_POST['tgl_sppb'] ?? date('Y-m-d');
            $tahun = date('Y', strtotime($tgl_sppb));
            $bulan = (int)date('m', strtotime($tgl_sppb));
            $triwulan = ceil($bulan / 3);

            if (isset($_POST['kode_item']) && is_array($_POST['kode_item'])) {
                foreach ($_POST['kode_item'] as $key => $kode_item) {
                    $item_sumber = $_POST['item_sumber'][$key] ?? 'master';
                    if ($jenis_permintaan === 'Non Rutin' && $item_sumber === 'manual') {
                        continue;
                    }
                    $qty_request = $_POST['jumlah'][$key] ?? 0;

                    // Get total quota
                    $sql_q = "SELECT SUM(jumlah) as total FROM rsns_custom_logistik_non_medis_kuota 
                            WHERE kode_unit = ? AND kode_item = ? AND status = 'Disetujui' AND tahun = ?
                            AND ( (periode_tipe = 'Bulanan' AND bulan = ?) OR (periode_tipe = 'Triwulan' AND triwulan = ?) )";
                    $stmt_q = $this->db()->pdo()->prepare($sql_q);
                    $stmt_q->execute([$kode_unit, $kode_item, $tahun, $bulan, $triwulan]);
                    $total_quota = $stmt_q->fetch()['total'] ?? 0;

                    if ($total_quota > 0) {
                        // Get usage (including those already in other SPPBs)
                        $sql_u = "SELECT SUM(jumlah) as total_used FROM rsns_custom_logistik_non_medis_sppb 
                                WHERE kode_unit = ? AND kode_item = ? AND no_sppb != ?
                                AND status NOT IN ('Draft', 'Ditolak')
                                AND YEAR(tgl_sppb) = ? AND MONTH(tgl_sppb) = ?";
                        $stmt_u = $this->db()->pdo()->prepare($sql_u);
                        $stmt_u->execute([$kode_unit, $kode_item, $no_sppb, $tahun, $bulan]);
                        $used = $stmt_u->fetch()['total_used'] ?? 0;

                        if (($used + $qty_request) > $total_quota) {
                            $item_name = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $kode_item)->oneArray()['nama_barang'] ?? $kode_item;
                            while (ob_get_level()) {
                                ob_end_clean();
                            }
                            echo json_encode(['status' => 'error', 'message' => "Kuota tidak mencukupi untuk item: $item_name. Sisa kuota saat ini: " . ($total_quota - $used)]);
                            exit();
                        }
                    }
                }
            }
        }

        $pdo = $this->db()->pdo();
        $uploaded_photo_paths = [];
        $success = 0;

        try {
            if (!is_dir($photo_upload_dir) && !mkdir($photo_upload_dir, 0755, true) && !is_dir($photo_upload_dir)) {
                throw new \RuntimeException('Folder penyimpanan foto tidak dapat dibuat.');
            }

            $pdo->beginTransaction();
            $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->delete();

            foreach ($validated_items as $key => $item) {
                $kode_item = $item['kode_item'];
                $item_sumber = $item['item_sumber'];
                $nama_barang_manual = $item['nama_barang_manual'];
                $spesifikasi_manual = $item['spesifikasi_manual'];

                if ($jenis_permintaan === 'Non Rutin' && $item_sumber === 'manual') {
                    $kode_item = 'USUL-' . date('YmdHis') . '-' . ($key + 1) . '-' . substr(md5(uniqid('', true)), 0, 6);
                } else {
                    $item_sumber = 'master';
                    if ($jenis_permintaan !== 'Non Rutin') {
                        $nama_barang_manual = null;
                    }
                }

                $photo_names = $item['existing_photos'];
                foreach ($item['new_photos'] as $new_photo) {
                    $safe_no_sppb = preg_replace('/[^A-Za-z0-9_-]/', '-', $no_sppb);
                    $photo_name = $safe_no_sppb . '-' . ($key + 1) . '-' . date('YmdHis') . '-' . substr(md5(uniqid('', true)), 0, 10) . '.' . $new_photo['extension'];
                    $destination = $photo_upload_dir . '/' . $photo_name;
                    if (!move_uploaded_file($new_photo['tmp_name'], $destination)) {
                        throw new \RuntimeException('Foto barang pada baris ' . ($key + 1) . ' gagal disimpan.');
                    }
                    $uploaded_photo_paths[] = $destination;
                    $photo_names[] = $photo_name;
                }

                $keterangan_umum = trim((string)($_POST['keterangan_umum'] ?? ''));
                $keterangan = $keterangan_umum;
                if ($item['keterangan_item'] !== '') {
                    $keterangan = $keterangan === '' ? $item['keterangan_item'] : $keterangan . "\nItem: " . $item['keterangan_item'];
                }

                $data = [
                  'no_sppb' => $no_sppb,
                  'tgl_sppb' => $tgl_sppb,
                  'kode_unit' => $kode_unit,
                  'jenis_permintaan' => $jenis_permintaan,
                  'kode_item' => $kode_item,
                  'item_sumber' => $item_sumber,
                  'nama_barang_manual' => $nama_barang_manual,
                  'spesifikasi_manual' => $spesifikasi_manual,
                  'estimasi_harga' => $item['estimasi_harga'],
                  'foto_barang' => json_encode(array_values(array_unique($photo_names))),
                  'latar_belakang_tujuan' => $jenis_permintaan === 'Non Rutin' ? $nonrutin_meta['latar_belakang_tujuan'] : null,
                  'sasaran_kegunaan' => $jenis_permintaan === 'Non Rutin' ? $nonrutin_meta['sasaran_kegunaan'] : null,
                  'rencana_digunakan' => $jenis_permintaan === 'Non Rutin' ? $nonrutin_meta['rencana_digunakan'] : null,
                  'sifat_permintaan' => $jenis_permintaan === 'Non Rutin' ? $nonrutin_meta['sifat_permintaan'] : 'Biasa',
                  'diajukan_oleh' => $jenis_permintaan === 'Non Rutin' ? $nonrutin_meta['diajukan_oleh'] : null,
                  'penanggung_jawab_1' => $jenis_permintaan === 'Non Rutin' ? $nonrutin_meta['penanggung_jawab_1'] : null,
                  'penanggung_jawab_2' => $jenis_permintaan === 'Non Rutin' ? $nonrutin_meta['penanggung_jawab_2'] : null,
                  'ka_unit' => $jenis_permintaan === 'Non Rutin' ? $nonrutin_meta['ka_unit'] : null,
                  'jumlah' => $item['jumlah'],
                  'satuan' => $item['satuan'],
                  'status' => $status,
                  'keterangan' => $keterangan,
                  'keterangan_item' => $item['keterangan_item'],
                  'alasan_penolakan' => null,
                  'ditolak_pada_status' => $status === 'Draft' ? ($return_status_after_rejection ?: null) : null,
                  'user_input' => $user,
                  'tgl_input' => date('Y-m-d H:i:s')
                ];
                if (!$this->db('rsns_custom_logistik_non_medis_sppb')->save($data)) {
                    throw new \RuntimeException('Data barang pada baris ' . ($key + 1) . ' gagal disimpan.');
                }
                $success++;
            }

            $pdo->commit();
        } catch (\Throwable $e) {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
            foreach ($uploaded_photo_paths as $uploaded_path) {
                if (is_file($uploaded_path)) {
                    @unlink($uploaded_path);
                }
            }
            while (ob_get_level()) {
                ob_end_clean();
            }
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
            exit();
        }

        if ($success > 0) {
            $this->_logAction('logistik_non_medis_sppb', 'Simpan SPPB: ' . $no_sppb . ' | Status: ' . $status);
            $notification_result = null;

            $jenis_perm = $_POST['jenis_permintaan'] ?? 'Rutin';
            if ($jenis_perm === 'Rutin' && $status === 'Diajukan') {
                $unit_row = $this->db('rsns_custom_logistik_non_medis_unit')->where('kode_unit', $kode_unit)->oneArray();
                $nama_unit_notif = trim((string)($unit_row['nama_unit'] ?? $kode_unit));
                $tgl_perm_notif = date('d/m/Y', strtotime($tgl_sppb));
                $notification = [
                  'user_target' => 'ADMIN',
                  'pesan' => 'Permintaan Rutin baru masuk. Unit: ' . $nama_unit_notif . ' | Total item: ' . $success . ' | Tgl permintaan: ' . $tgl_perm_notif,
                  'tipe' => 'rutin_baru',
                  'url' => '#distribusisppb',
                  'is_read' => 0,
                  'tgl_dibuat' => date('Y-m-d H:i:s')
                ];
                $this->db('rsns_custom_logistik_non_medis_notifikasi')->save($notification);
                $this->_broadcastNotification($notification);
            } elseif ($jenis_perm === 'Non Rutin' && $status === 'Diajukan') {
                $notification_result = $this->_notifyApprovalRecipients(
                    'kepala_unit',
                    $kode_unit,
                    $no_sppb,
                    'Permintaan Non Rutin ' . $no_sppb . ' membutuhkan persetujuan Ka. Unit.',
                    'approval_ka_unit'
                );
            }

            while (ob_get_level()) {
                ob_end_clean();
            }
            echo json_encode([
              'status' => 'success',
              'no_sppb' => $no_sppb,
              'new_status' => $status,
              'message' => 'Permintaan berhasil disimpan dengan status ' . $status . '.',
              'notification' => $notification_result
            ]);
        } else {
            while (ob_get_level()) {
                ob_end_clean();
            }
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan data.']);
        }
        exit();
    }

    public function postTambahitemsppbtambahan()
    {
        $no_sppb = $_POST['no_sppb'] ?? '';
        $kode_item = $_POST['kode_item'] ?? '';
        $jumlah = $_POST['jumlah'] ?? 0;
