          'satuan' => $satuan,
          'status' => 'Diajukan',
          'keterangan' => $existing['keterangan'] ?? '',
          'keterangan_item' => $keterangan_item,
          'user_input' => $user,
          'tgl_input' => date('Y-m-d H:i:s')
