    public function postApproveSppb()
    {
        $no_sppb = $_POST['no_sppb'] ?? '';
        $user = $this->core->getUserInfo('username', null, true);

        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';
        $user_kode_unit = $userRoleData['kode_unit'] ?? null;
        $units_arr = !empty($user_kode_unit) ? $this->getChildUnitCodes(explode(',', $user_kode_unit)) : [];

        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if (!$cek) {
            echo json_encode(['status' => 'error', 'message' => 'Data permintaan tidak ditemukan.']);
            exit();
        }

        $current_status = $cek['status'];
        $now = date('Y-m-d H:i:s');
        $update_data = [];
        $log_msg = '';

        if ($current_status === 'Diajukan') {
            // Rutin langsung ke logistik, tidak perlu persetujuan Ka. Unit
            if ($cek['jenis_permintaan'] === 'Rutin') {
                echo json_encode(['status' => 'error', 'message' => 'Permintaan Rutin tidak membutuhkan persetujuan Ka. Unit, langsung diproses oleh Logistik.']);
                exit();
            }
            if (!in_array($role, ['kepala_unit', 'admin'])) {
                echo json_encode(['status' => 'error', 'message' => 'Hanya Kepala Unit yang dapat menyetujui tahap ini.']);
                exit();
            }
            if ($role === 'kepala_unit' && !empty($units_arr) && !in_array($cek['kode_unit'], $units_arr)) {
                echo json_encode(['status' => 'error', 'message' => 'Anda tidak memiliki hak untuk menyetujui permintaan unit lain!']);
                exit();
            }
            $update_data = [
              'status' => 'Disetujui Ka. Unit',
              'user_approve_ka_unit' => $user,
              'tgl_approve_ka_unit' => $now
            ];
            $log_msg = 'Approve SPPB Non Rutin Ka. Unit: ' . $no_sppb;
        } elseif ($current_status === 'Disetujui Ka. Unit') {
            if ($cek['jenis_permintaan'] === 'Rutin') {
                echo json_encode(['status' => 'error', 'message' => 'Permintaan Rutin tidak membutuhkan ACC KASI.']);
                exit();
            }
            if (!in_array($role, ['kepala_sie', 'admin'])) {
                echo json_encode(['status' => 'error', 'message' => 'Hanya Kepala Sie yang dapat menyetujui tahap ini.']);
                exit();
            }
            if ($role === 'kepala_sie' && !empty($units_arr) && !in_array($cek['kode_unit'], $units_arr)) {
                echo json_encode(['status' => 'error', 'message' => 'Anda tidak memiliki hak untuk menyetujui permintaan unit lain!']);
                exit();
            }
            $update_data = [
              'status' => 'Disetujui Ka. Sie',
              'user_approve_ka_sie' => $user,
              'tgl_approve_ka_sie' => $now
            ];
            $log_msg = 'Approve SPPB Ka. Sie: ' . $no_sppb;
        } elseif ($current_status === 'Disetujui Ka. Sie') {
            if (!in_array($role, ['kepala_bidang', 'admin'])) {
                echo json_encode(['status' => 'error', 'message' => 'Hanya Kepala Bidang yang dapat menyetujui tahap ini.']);
                exit();
            }
            if ($role === 'kepala_bidang' && !empty($units_arr) && !in_array($cek['kode_unit'], $units_arr)) {
                echo json_encode(['status' => 'error', 'message' => 'Anda tidak memiliki hak untuk menyetujui permintaan unit lain!']);
                exit();
            }
            $update_data = [
              'status' => 'Disetujui Kabid',
              'user_approve_ka_bidang' => $user,
              'tgl_approve_ka_bidang' => $now,
              'user_approve_unit' => $user,
              'tgl_approve_unit' => $now
            ];
            $log_msg = 'Approve SPPB Ka. Bidang (Disetujui Kabid): ' . $no_sppb;
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Status permintaan tidak dapat disetujui pada tahap ini.']);
            exit();
        }

        // Jika ada keterangan tambahan, gabungkan dengan keterangan lama
        $keterangan_baru = trim((string)($_POST['keterangan'] ?? ''));
        if ($keterangan_baru !== '') {
            $ket_lama = trim((string)($cek['keterangan'] ?? ''));
            $prefix = '[' . date('d/m/Y H:i') . ' - ' . $user . ']: ';
            $update_data['keterangan'] = ($ket_lama === '') ? $prefix . $keterangan_baru : $ket_lama . "\n" . $prefix . $keterangan_baru;
        }

        $update = $this->db('rsns_custom_logistik_non_medis_sppb')
                     ->where('no_sppb', $no_sppb)
                     ->update($update_data);

        if ($update) {
            // Non Rutin: jika jumlah ACC belum ditentukan, otomatis gunakan jumlah yang diminta.
            // Nilai yang sudah diubah manual oleh Ka. Unit tetap dipertahankan.
            if ($cek['jenis_permintaan'] === 'Non Rutin' && in_array($current_status, ['Diajukan', 'Disetujui Ka. Unit', 'Disetujui Ka. Sie'], true)) {
                $stmt_qty = $this->db()->pdo()->prepare("UPDATE rsns_custom_logistik_non_medis_sppb
                  SET jumlah_disetujui = jumlah
                  WHERE no_sppb = ? AND status != 'Ditolak' AND jumlah_disetujui <= 0");
                $stmt_qty->execute([$no_sppb]);
            }
            $this->_logAction('logistik_non_medis_sppb', $log_msg, 'U');
            $notification_result = null;
            if (($update_data['status'] ?? '') === 'Disetujui Ka. Unit') {
                $notification_result = $this->_notifyApprovalRecipients('kepala_sie', $cek['kode_unit'], $no_sppb, 'Permintaan ' . $no_sppb . ' sudah disetujui Ka. Unit dan membutuhkan persetujuan KASI.', 'approval_kasie');
            } elseif (($update_data['status'] ?? '') === 'Disetujui Ka. Sie') {
                $notification_result = $this->_notifyApprovalRecipients('kepala_bidang', $cek['kode_unit'], $no_sppb, 'Permintaan ' . $no_sppb . ' sudah disetujui KASI dan membutuhkan persetujuan KABID.', 'approval_kabid');
            } elseif (($update_data['status'] ?? '') === 'Disetujui Kabid') {
                $notification_result = $this->_notificationSummary([
                  $this->_notifyUser((string)($cek['user_input'] ?? ''), 'Permintaan ' . $no_sppb . ' telah disetujui sampai tahap KABID.', 'approval_selesai', $no_sppb)
                ]);
            }
            $new_status = (string)($update_data['status'] ?? '');
            echo json_encode([
              'status' => 'success',
              'new_status' => $new_status,
              'message' => 'Status permintaan berhasil diubah menjadi ' . $new_status . '.',
              'notification' => $notification_result
            ]);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyetujui permintaan.']);
        }
        exit();
    }

  /**
   * Mengembalikan SPPB Non Rutin dari tahap ACC KASI ke Ka. Unit.
   * Jumlah ACC dikosongkan agar Ka. Unit dapat menilai ulang setiap item.
   */
    public function postMundurSppb()
    {
        $no_sppb = trim((string)($_POST['no_sppb'] ?? ''));
        $user = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';
        $user_kode_unit = $userRoleData['kode_unit'] ?? null;
        $units_arr = !empty($user_kode_unit) ? $this->getChildUnitCodes(explode(',', $user_kode_unit)) : [];

        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if (!$cek) {
            echo json_encode(['status' => 'error', 'message' => 'Data permintaan tidak ditemukan.']);
            exit();
        }
        if ($cek['jenis_permintaan'] !== 'Non Rutin' || $cek['status'] !== 'Disetujui Ka. Unit') {
            echo json_encode(['status' => 'error', 'message' => 'Hanya permintaan Non Rutin pada tahap ACC Ka. Unit yang dapat dimundurkan.']);
            exit();
        }
        if (!in_array($role, ['kepala_sie', 'admin'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Hanya KASI atau Admin yang dapat mengembalikan ke Ka. Unit.']);
            exit();
        }
        if ($role === 'kepala_sie' && !empty($units_arr) && !in_array($cek['kode_unit'], $units_arr, true)) {
            echo json_encode(['status' => 'error', 'message' => 'Anda tidak memiliki hak untuk mengubah permintaan unit lain.']);
            exit();
        }

        $pdo = $this->db()->pdo();
        $pdo->beginTransaction();
        try {
            $stmt = $pdo->prepare("UPDATE rsns_custom_logistik_non_medis_sppb
              SET status = 'Diajukan', jumlah_disetujui = 0,
                  user_approve_ka_unit = NULL, tgl_approve_ka_unit = NULL,
                  user_approve_ka_sie = NULL, tgl_approve_ka_sie = NULL,
                  user_approve_ka_bidang = NULL, tgl_approve_ka_bidang = NULL,
                  user_approve_unit = NULL, tgl_approve_unit = NULL,
                  ditolak_pada_status = NULL
              WHERE no_sppb = ?");
            $stmt->execute([$no_sppb]);
            $pdo->commit();

            $this->_logAction('logistik_non_medis_sppb', 'Kembalikan SPPB ke Ka. Unit: ' . $no_sppb, 'U');
            echo json_encode(['status' => 'success', 'new_status' => 'Diajukan', 'message' => 'Status permintaan dikembalikan menjadi Diajukan untuk penilaian ulang Ka. Unit.']);
        } catch (\Throwable $e) {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
            echo json_encode(['status' => 'error', 'message' => 'Gagal mengembalikan permintaan ke Ka. Unit.']);
        }
        exit();
    }

    private function _generatePrFromSppb(string $no_sppb, string $user): string
    {
        $this->_initPR();
        $sppb_items = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->toArray();
        if (empty($sppb_items)) {
            return '';
        }

        $marker = "Auto generated from SPPB Non Rutin: {$no_sppb}.";
        $stmt_existing = $this->db()->pdo()->prepare("
          SELECT no_pr
          FROM rsns_custom_logistik_non_medis_pr
          WHERE justifikasi LIKE ?
          ORDER BY id ASC
          LIMIT 1
      ");
        $stmt_existing->execute([$marker . '%']);
        $existing_no_pr = (string)($stmt_existing->fetchColumn() ?: '');
        if ($existing_no_pr !== '') {
            $this->db('rsns_custom_logistik_non_medis_pr')
               ->where('no_pr', $existing_no_pr)
               ->update([
                   'status' => 'Disetujui',
                   'petugas_logistik' => $user,
                   'tgl_acc' => date('Y-m-d H:i:s')
               ]);
            return $existing_no_pr;
        }

        $kode_unit = $sppb_items[0]['kode_unit'];
        $no_pr = $this->_generateNoPR($kode_unit);

        foreach ($sppb_items as $item) {
            $jumlah = $item['jumlah_disetujui'] > 0 ? $item['jumlah_disetujui'] : $item['jumlah'];
            if ($jumlah <= 0) {
                continue;
            }

            $pr_data = [
              'no_pr' => $no_pr,
              'tgl_pr' => date('Y-m-d'),
              'kode_unit' => $kode_unit,
              'kode_item' => $item['kode_item'],
              'jumlah' => $jumlah,
              'satuan' => $item['satuan'],
              'justifikasi' => $marker . "\nBarang: " . ($item['nama_barang_manual'] ?: $item['kode_item']) . "\nAlasan/Keterangan: {$item['keterangan']}",
              'status' => 'Disetujui',
              'petugas_logistik' => $user,
              'tgl_acc' => date('Y-m-d H:i:s'),
              'user_input' => $user
            ];
            $this->db('rsns_custom_logistik_non_medis_pr')->save($pr_data);
        }

        return $no_pr;
    }

    public function postRejectSppb()
    {
        $no_sppb = $_POST['no_sppb'] ?? '';
        $alasan = $_POST['alasan_penolakan'] ?? '';
        $user = $this->core->getUserInfo('username', null, true);

        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';
        $user_kode_unit = $userRoleData['kode_unit'] ?? null;

        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if (!$cek) {
            echo json_encode(['status' => 'error', 'message' => 'Data tidak ditemukan!']);
            exit();
        }

        $current_status_reject = $cek['status'];
        $ditolak_pada = $current_status_reject;

        if (!in_array($role, ['kepala_unit', 'kepala_sie', 'kepala_bidang', 'admin', 'logistik'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Anda tidak memiliki hak untuk menolak permintaan.']);
            exit();
        }

        // Validasi: role harus sesuai tahap status
        if ($cek['jenis_permintaan'] === 'Non Rutin') {
            if ($role === 'kepala_unit' && $current_status_reject !== 'Diajukan') {
                echo json_encode(['status' => 'error', 'message' => 'Ka. Unit hanya dapat menolak pada tahap "Diajukan".']);
                exit();
            }
            if ($role === 'kepala_sie' && $current_status_reject !== 'Disetujui Ka. Unit') {
                echo json_encode(['status' => 'error', 'message' => 'KASI hanya dapat menolak pada tahap "Disetujui Ka. Unit".']);
                exit();
            }
            if ($role === 'kepala_bidang' && $current_status_reject !== 'Disetujui Ka. Sie') {
                echo json_encode(['status' => 'error', 'message' => 'KABID hanya dapat menolak pada tahap "Disetujui Ka. Sie".']);
                exit();
            }
        } else {
            if ($role === 'kepala_unit' && $current_status_reject !== 'Diajukan') {
                echo json_encode(['status' => 'error', 'message' => 'Ka. Unit hanya dapat menolak pada tahap "Diajukan".']);
                exit();
            }
            if ($role === 'kepala_sie' && $current_status_reject !== 'Disetujui Ka. Unit') {
                echo json_encode(['status' => 'error', 'message' => 'Ka. Sie hanya dapat menolak pada tahap "Disetujui Ka. Unit".']);
                exit();
            }
        }
        if ($cek['jenis_permintaan'] !== 'Non Rutin' && $role === 'kepala_bidang' && !in_array($current_status_reject, ['Disetujui Ka. Sie', 'Disetujui Kabid', 'Disetujui Unit'])) {
            echo json_encode(['status' => 'error', 'message' => 'Ka. Bidang hanya dapat menolak pada tahap "Disetujui Ka. Sie".']);
            exit();
        }

        // Cek hierarki unit: gunakan getChildUnitCodes agar Kabid/Kasie bisa reject unit di bawahnya
        if (in_array($role, ['kepala_unit', 'kepala_sie', 'kepala_bidang'], true) && !empty($user_kode_unit)) {
            $units_arr = $this->getChildUnitCodes(explode(',', $user_kode_unit));
            if (!in_array($cek['kode_unit'], $units_arr)) {
                echo json_encode(['status' => 'error', 'message' => 'Anda tidak memiliki hak untuk menolak permintaan unit lain!']);
                exit();
            }
        }

        // Simpan status mesin; label tampilannya dibuat saat detail ditampilkan.
        $ditolak_pada_label = $this->_getSppbRejectStageLabel($ditolak_pada, $cek['jenis_permintaan']);
        $reject_data = [
          'status' => 'Ditolak',
          'alasan_penolakan' => $alasan,
          'ditolak_pada_status' => $ditolak_pada,
          'user_approve_unit' => null,
          'tgl_approve_unit' => null
        ];
        if ($cek['jenis_permintaan'] === 'Non Rutin') {
            if ($current_status_reject === 'Diajukan') {
                $reject_data['user_approve_ka_unit'] = null;
                $reject_data['tgl_approve_ka_unit'] = null;
                $reject_data['user_approve_ka_sie'] = null;
                $reject_data['tgl_approve_ka_sie'] = null;
                $reject_data['user_approve_ka_bidang'] = null;
                $reject_data['tgl_approve_ka_bidang'] = null;
            } elseif ($current_status_reject === 'Disetujui Ka. Unit') {
                $reject_data['user_approve_ka_sie'] = null;
                $reject_data['tgl_approve_ka_sie'] = null;
                $reject_data['user_approve_ka_bidang'] = null;
                $reject_data['tgl_approve_ka_bidang'] = null;
            } elseif ($current_status_reject === 'Disetujui Ka. Sie') {
                $reject_data['user_approve_ka_bidang'] = null;
                $reject_data['tgl_approve_ka_bidang'] = null;
            }
        }

        $update = $this->db('rsns_custom_logistik_non_medis_sppb')
                     ->where('no_sppb', $no_sppb)
                     ->update($reject_data);

        if ($update) {
            $this->_logAction('logistik_non_medis_sppb', 'Tolak SPPB (' . $ditolak_pada_label . '): ' . $no_sppb . ' | Alasan: ' . $alasan, 'U');
            $notification_result = $this->_notificationSummary([
              $this->_notifyUser((string)($cek['user_input'] ?? ''), 'Permintaan ' . $no_sppb . ' ditolak pada ' . $ditolak_pada_label . '. Alasan: ' . $alasan, 'approval_ditolak', $no_sppb)
            ]);
            echo json_encode([
              'status' => 'success',
              'new_status' => 'Ditolak',
              'message' => 'Status permintaan berhasil diubah menjadi Ditolak.',
              'notification' => $notification_result
            ]);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menolak permintaan.']);
        }
        exit();
    }

    public function postVerifikasiSppb()
    {
        $no_sppb = $_POST['no_sppb'] ?? '';
        $user = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';

        if (!in_array($role, ['admin', 'logistik'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Hanya admin/logistik yang dapat memproses tahap logistik.']);
            exit();
        }

        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if (!$cek) {
            echo json_encode(['status' => 'error', 'message' => 'Data tidak ditemukan.']);
            exit();
        }
        $valid_status = in_array($cek['status'], ['Disetujui Kabid', 'Disetujui Unit'], true)
          || ($cek['status'] === 'Diajukan' && $cek['jenis_permintaan'] === 'Rutin');
        if (!$valid_status) {
            echo json_encode(['status' => 'error', 'message' => 'Status belum masuk tahap proses berikutnya.']);
            exit();
        }
        $next_status = ($cek['jenis_permintaan'] === 'Non Rutin') ? 'Diserahkan ke Kasie Umum' : 'Proses Logistik';

        $update = $this->db('rsns_custom_logistik_non_medis_sppb')
                     ->where('no_sppb', $no_sppb)
                     ->update([
                         'status' => $next_status,
                         'user_verifikasi' => $user,
                         'tgl_verifikasi' => date('Y-m-d H:i:s')
                     ]);

        if ($update) {
            $this->_logAction('logistik_non_medis_sppb', $next_status . ' SPPB: ' . $no_sppb, 'U');
            echo json_encode([
              'status' => 'success',
              'new_status' => $next_status,
              'message' => 'Status permintaan berhasil diubah menjadi ' . $next_status . '.'
            ]);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal memproses permintaan.']);
        }
        exit();
    }

    public function postProsesLogistikSppb()
    {
        // Rutin selesai di logistik langsung siap ambil; non rutin lanjut ke pengadaan.
        $no_sppb = $_POST['no_sppb'] ?? '';
        $user = $this->core->getUserInfo('username', null, true);
        $items = $_POST['items'] ?? []; // array [kode_item => ['qty_acc' => x, 'acc' => 'y/n']]
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';

        if (!in_array($role, ['admin', 'logistik'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Hanya admin/logistik yang dapat review proses logistik.']);
            exit();
        }

        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if (!$cek) {
            echo json_encode(['status' => 'error', 'message' => 'Data tidak ditemukan.']);
            exit();
        }
        if ($cek['jenis_permintaan'] === 'Non Rutin') {
            $alur_nonrutin = [
              'Diserahkan ke Kasie Umum' => 'Verifikasi Kasie Umum',
              'Verifikasi Kasie Umum' => 'Logistik Umum & Rekap',
              'Diteruskan ke Logistik Umum' => 'Logistik Umum & Rekap',
              'Rekap Logistik' => 'Konsul Pengajuan ke Kabid Umum',
              'Logistik Umum & Rekap' => 'Konsul Pengajuan ke Kabid Umum',
              'Proses Logistik' => 'Logistik Umum & Rekap'
            ];
            $next_status = $alur_nonrutin[$cek['status']] ?? '';
            if ($next_status === '') {
                echo json_encode(['status' => 'error', 'message' => 'Status tidak valid untuk alur non rutin berikutnya.']);
                exit();
            }
        } else {
            if ($cek['status'] !== 'Proses Logistik') {
                echo json_encode(['status' => 'error', 'message' => 'Status tidak valid untuk proses logistik.']);
                exit();
            }
            $next_status = 'Siap Ambil';
        }

        $pdo = $this->db()->pdo();
        $pdo->beginTransaction();
        try {
            $catatan_validasi = $_POST['catatan_validasi'] ?? '';
            if ($cek['jenis_permintaan'] !== 'Non Rutin') {
                if (empty($items)) {
                    echo json_encode(['status' => 'error', 'message' => 'Tidak ada item yang diproses.']);
                    exit();
                }
                $semua_ditolak = true;
                foreach ($items as $kode_item => $item_data) {
                    $qty_acc = max(0, (float)($item_data['qty_acc'] ?? 0));
                    $acc = ($item_data['acc'] ?? 'y') === 'y' ? 'Disetujui Unit' : 'Ditolak';
                    if ($acc === 'Ditolak' || $qty_acc <= 0) {
                        $qty_acc = 0;
                        $acc = 'Ditolak';
                    } else {
                        $semua_ditolak = false;
                    }
                    $stmt = $pdo->prepare("UPDATE `rsns_custom_logistik_non_medis_sppb` SET jumlah_disetujui = ?, status = ? WHERE no_sppb = ? AND kode_item = ?");
                    $stmt->execute([$qty_acc, $acc, $no_sppb, $kode_item]);
                }
                if ($semua_ditolak && !empty($items)) {
                    $next_status = 'Ditolak';
                }
            }

            if ($next_status === 'Ditolak') {
                $stmt2 = $pdo->prepare("UPDATE `rsns_custom_logistik_non_medis_sppb` SET status = ?, user_verifikasi = ?, tgl_verifikasi = ? WHERE no_sppb = ?");
            } else {
                $stmt2 = $pdo->prepare("UPDATE `rsns_custom_logistik_non_medis_sppb` SET status = ?, user_verifikasi = ?, tgl_verifikasi = ? WHERE no_sppb = ? AND status != 'Ditolak'");
            }
            $stmt2->execute([$next_status, $user, date('Y-m-d H:i:s'), $no_sppb]);

            if ($catatan_validasi !== '') {
                $stmtCatatan = $pdo->prepare("UPDATE `rsns_custom_logistik_non_medis_sppb` SET keterangan = CONCAT(IFNULL(keterangan,''), '\nCatatan Validasi Gudang: ', ?) WHERE no_sppb = ?");
                $stmtCatatan->execute([$catatan_validasi, $no_sppb]);
            }

            $pdo->commit();
            $this->_logAction('logistik_non_medis_sppb', $next_status . ' SPPB: ' . $no_sppb, 'U');
            $notification_result = null;
            if ($next_status === 'Siap Ambil') {
                $this->_buatNotifSiapAmbilSppb($no_sppb, $cek['kode_unit']);
            } elseif ($next_status === 'Konsul Pengajuan ke Kabid Umum') {
                $this->_recordNotifierEvent($no_sppb, (string)($cek['kode_unit'] ?? ''));
                $notification_result = $this->_notifyKabidUmum(
                    $no_sppb,
                    'Permintaan non rutin ' . $no_sppb . ' dari unit ' . ($cek['kode_unit'] ?? '-') . ' menunggu keputusan Kabid Umum.'
                );
            }
            echo json_encode([
              'status' => 'success',
              'new_status' => $next_status,
              'message' => 'Status permintaan berhasil diubah menjadi ' . $next_status . '.',
              'notification' => $notification_result
            ]);
        } catch (\Throwable $e) {
            $pdo->rollBack();
            echo json_encode(['status' => 'error', 'message' => 'Gagal: ' . $e->getMessage()]);
        }
        exit();
    }

    public function postKeputusanDanaSppb()
    {
        $no_sppb = $_POST['no_sppb'] ?? '';
        $keputusan = $_POST['keputusan'] ?? '';
        $alasan = trim((string)($_POST['alasan'] ?? ''));
        $user = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';

        if (!$this->_canAccessRekapNonRutin()) {
            echo json_encode(['status' => 'error', 'message' => 'Hanya Kabid Umum, Logistik, atau Admin yang dapat menyimpan keputusan konsul.']);
            exit();
        }

        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if (!$cek || $cek['jenis_permintaan'] !== 'Non Rutin' || !in_array($cek['status'], ['Konsultasi Dana','Konsul Pengajuan ke Kabid Umum'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Status harus Konsul Pengajuan ke Kabid Umum untuk menyimpan keputusan.']);
            exit();
        }

        $data = [
          'status' => $keputusan === 'acc' ? 'Pengajuan Dana ke Bendahara' : 'Tidak ACC',
          'user_verifikasi' => $user,
          'tgl_verifikasi' => date('Y-m-d H:i:s')
        ];
        if ($keputusan !== 'acc') {
            $data['alasan_penolakan'] = $alasan !== '' ? $alasan : 'Tidak ACC pada konsul pengajuan ke Kabid Umum.';
            $data['ditolak_pada_status'] = 'Tahap Konsul Pengajuan ke Kabid Umum';
        }

        $update = $this->db('rsns_custom_logistik_non_medis_sppb')
                     ->where('no_sppb', $no_sppb)
                     ->update($data);
        if ($update) {
            $this->_logAction('logistik_non_medis_sppb', ($keputusan === 'acc' ? 'ACC Konsul Kabid Umum' : 'Tidak ACC Konsul Kabid Umum') . ' SPPB: ' . $no_sppb, 'U');
            echo json_encode([
              'status' => 'success',
              'new_status' => $data['status'],
              'message' => 'Status permintaan berhasil diubah menjadi ' . $data['status'] . '.'
            ]);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan keputusan dana.']);
        }
        exit();
    }

    public function anyGetItemsSppb()
    {
        $no_sppb = $_POST['no_sppb'] ?? '';
        if (empty($no_sppb)) {
            echo json_encode(['status' => 'error', 'message' => 'No SPPB kosong']);
            exit();
        }
        $rows = $this->db('rsns_custom_logistik_non_medis_sppb')
                   ->leftJoin('rsns_custom_logistik_non_medis_master_barang', 'rsns_custom_logistik_non_medis_sppb.kode_item = rsns_custom_logistik_non_medis_master_barang.kode_item')
                   ->select('rsns_custom_logistik_non_medis_sppb.*')
                   ->select('COALESCE(NULLIF(rsns_custom_logistik_non_medis_sppb.nama_barang_manual, \'\'), rsns_custom_logistik_non_medis_master_barang.nama_barang, rsns_custom_logistik_non_medis_sppb.kode_item) AS nama_barang')
                   ->where('no_sppb', $no_sppb)
                   ->toArray();
        if (!is_array($rows)) {
            $rows = [];
        }

        $this->_initStok();
        foreach ($rows as &$item) {
            $stok_stmt = $this->db()->pdo()->prepare("
              SELECT COALESCE(SUM(stok), 0) AS stok_sistem
              FROM rsns_custom_logistik_non_medis_stok_batch
              WHERE kode_item = ? AND stok > 0
                AND (tgl_expired IS NULL OR tgl_expired >= CURDATE())
          ");
            $stok_stmt->execute([$item['kode_item']]);
            $item['stok_sistem'] = (float)$stok_stmt->fetchColumn();
        }

        echo json_encode(['status' => 'success', 'items' => $rows]);
        exit();
    }

    public function postSiapAmbilSppb()
    {
        $this->_initPemenuhanNonRutin();
        $no_sppb = $_POST['no_sppb'] ?? '';
        $user = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';

        if (!in_array($role, ['admin', 'logistik'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Hanya admin/logistik yang dapat menandai siap ambil.']);
            exit();
        }

        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if (!$cek) {
            echo json_encode(['status' => 'error', 'message' => 'Data tidak ditemukan.']);
            exit();
        }
        if ($cek['jenis_permintaan'] === 'Non Rutin' && in_array($cek['status'], ['Diserahkan ke Keuangan','Pengajuan Dana ke Bendahara'], true)) {
            $update = $this->db('rsns_custom_logistik_non_medis_sppb')
                         ->where('no_sppb', $no_sppb)
                         ->update([
                             'status' => 'Proses Pengadaan',
                             'user_verifikasi' => $user,
                             'tgl_verifikasi' => date('Y-m-d H:i:s')
                         ]);
            if ($update) {
                $this->_logAction('logistik_non_medis_sppb', 'Masuk Proses Pengadaan Non Rutin: ' . $no_sppb, 'U');
                $triage_url = url([ADMIN, 'logistik_non_medis', 'permintaannonrutin']);
                echo json_encode([
                  'status' => 'success',
                  'message' => 'Permintaan masuk Proses Pengadaan. Tentukan sumber pemenuhan: stok gudang, mutasi aset, perbaikan, atau PO.',
                  'redirect_url' => $triage_url
                ]);
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Gagal mengubah status.']);
            }
            exit();
        }
        if ($cek['status'] !== 'Proses Pengadaan') {
            echo json_encode(['status' => 'error', 'message' => 'Status belum masuk tahap proses pengadaan.']);
            exit();
        }
        if ($cek['jenis_permintaan'] === 'Non Rutin') {
            $source = (string)($cek['sumber_pemenuhan'] ?? '');
            if ($source === '') {
                echo json_encode([
                  'status' => 'error',
                  'message' => 'Sumber pemenuhan belum dipilih. Gunakan menu Permintaan Non-Rutin lalu klik Tindak Lanjuti.',
                  'redirect_url' => url([ADMIN, 'logistik_non_medis', 'permintaannonrutin'])
                ]);
                exit();
            }
            if ($source === 'Mutasi Aset' || $source === 'Perbaikan Aset') {
                echo json_encode([
                  'status' => 'error',
                  'message' => $source . ' masih menjadi sumber pemenuhan. Selesaikan proses tersebut terlebih dahulu.',
                  'redirect_url' => $source === 'Mutasi Aset'
                    ? url([ADMIN, 'logistik_non_medis', 'asetmutasi'])
                    : url([ADMIN, 'logistik_non_medis', 'asetpemeliharaan'])
                ]);
                exit();
            }
            if ($source === 'Stok Gudang') {
                $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->update(['status' => 'Siap Diserahkan']);
                $this->_buatNotifSiapAmbilSppb($no_sppb, $cek['kode_unit']);
                echo json_encode(['status' => 'success', 'message' => 'Barang dari stok gudang siap diserahkan.']);
                exit();
            }
            $po = $this->_findActivePoFromSppb($no_sppb);
            if (!$po) {
                echo json_encode([
                  'status' => 'error',
                  'code' => 'po_belum_ada',
                  'message' => 'Belum ada PO aktif. Generate PO pengganti terlebih dahulu.'
                ]);
                exit();
            }

            $po_status = (string)($po['status'] ?? 'Draft');
            $po_url = url([ADMIN, 'logistik_non_medis', 'pengadaanpo'])
              . '&no_po=' . rawurlencode((string)$po['no_po']) . '#po-form';
            $penerimaan_url = url([ADMIN, 'logistik_non_medis', 'pengadaanpenerimaan'])
              . '&no_po=' . rawurlencode((string)$po['no_po']) . '#penerimaan-form';

            if (in_array($po_status, ['Draft', 'Diamandemen'], true)) {
                echo json_encode([
                  'status' => 'error',
                  'code' => 'po_belum_dikirim',
                  'message' => 'PO ' . $po['no_po'] . ' masih ' . $po_status . '. Pilih vendor, simpan, lalu tandai sudah diorder.',
                  'redirect_url' => $po_url
                ]);
                exit();
            }
            if (in_array($po_status, ['Terkirim', 'Sebagian Diterima'], true)) {
                echo json_encode([
                  'status' => 'error',
                  'code' => 'penerimaan_belum_selesai',
                  'message' => 'Barang untuk PO ' . $po['no_po'] . ' belum selesai diterima.',
                  'redirect_url' => $penerimaan_url
                ]);
                exit();
            }
            if ($po_status !== 'Selesai') {
                echo json_encode([
                  'status' => 'error',
                  'message' => 'PO ' . $po['no_po'] . ' belum dapat dilanjutkan. Status saat ini: ' . $po_status . '.',
                  'redirect_url' => $po_url
                ]);
                exit();
            }
            $update = $this->db('rsns_custom_logistik_non_medis_sppb')
                         ->where('no_sppb', $no_sppb)
                         ->update([
                             'status' => 'Siap Diserahkan',
                             'user_verifikasi' => $user,
                             'tgl_verifikasi' => date('Y-m-d H:i:s')
                         ]);
            if ($update) {
                $this->_logAction('logistik_non_medis_sppb', 'SPPB Non Rutin Siap Diserahkan: ' . $no_sppb, 'U');
                echo json_encode(['status' => 'success', 'message' => 'PO telah selesai diterima. Permintaan sekarang Siap Diserahkan.']);
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Gagal mengubah status.']);
            }
            exit();
        }
        $update = $this->db('rsns_custom_logistik_non_medis_sppb')
                     ->where('no_sppb', $no_sppb)
                     ->update([
                         'status' => 'Siap Ambil',
                         'user_verifikasi' => $user,
                         'tgl_verifikasi' => date('Y-m-d H:i:s')
                     ]);
        if ($update) {
            $this->_logAction('logistik_non_medis_sppb', 'SPPB Siap Ambil: ' . $no_sppb, 'U');

            $this->_buatNotifSiapAmbilSppb($no_sppb, $cek['kode_unit']);

            echo json_encode(['status' => 'success']);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal mengubah status.']);
        }
        exit();
    }

    private function _buatNotifSiapAmbilSppb(string $no_sppb, string $kode_unit)
    {
        if (empty($no_sppb) || empty($kode_unit)) {
            return;
        }

        $exists = $this->db('rsns_custom_logistik_non_medis_notifikasi')
                     ->where('user_target', $kode_unit)
                     ->where('tipe', 'siap_diambil')
                     ->where('url', ADMIN . '/logistik_non_medis/distribusibhp')
                     ->like('pesan', '%' . $no_sppb . '%')
                     ->oneArray();
        if ($exists) {
            return;
        }

        $notification = [
          'user_target' => $kode_unit,
          'pesan' => 'Barang untuk permintaan ' . $no_sppb . ' sudah siap diambil.',
          'tipe' => 'siap_diambil',
          'url' => ADMIN . '/logistik_non_medis/distribusibhp',
          'is_read' => 0,
          'tgl_dibuat' => date('Y-m-d H:i:s')
        ];
        $this->db('rsns_custom_logistik_non_medis_notifikasi')->save($notification);
        $this->_broadcastNotification($notification);
    }

    public function postSelesaikanSppb()
    {
        $this->_initSppb();
        $this->_initSerahTerima();
        $no_sppb = $_POST['no_sppb'] ?? '';
        $diambil_oleh = trim((string)($_POST['diambil_oleh'] ?? ''));
        $tanda_tangan_payload = trim((string)($_POST['tanda_tangan_pengambil'] ?? ''));
        $user = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';
        $user_kode_unit = $userRoleData['kode_unit'] ?? null;

        if ($diambil_oleh === '') {
            echo json_encode(['status' => 'error', 'message' => 'Nama pengambil barang wajib diisi.']);
            exit();
        }
        if ($tanda_tangan_payload === '') {
            echo json_encode(['status' => 'error', 'message' => 'Tanda tangan pengambil wajib diisi.']);
            exit();
        }
        try {
            $signature = $this->_encodeSerahTerimaSignature($tanda_tangan_payload);
        } catch (\Throwable $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
            exit();
        }

        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if (!$cek || !in_array($cek['status'], ['Siap Ambil','Siap Diserahkan'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Status harus "Siap Ambil" atau "Siap Diserahkan" untuk diselesaikan.']);
            exit();
        }
        if (!in_array($role, ['admin', 'logistik'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Konfirmasi siap ambil hanya dapat dilakukan oleh admin/logistik.']);
            exit();
        }

        if ($cek['jenis_permintaan'] === 'Non Rutin' && $cek['status'] === 'Siap Diserahkan') {
            if (($cek['sumber_pemenuhan'] ?? '') === 'Stok Gudang') {
                $this->_initStok();
                $stok_fisik = isset($_POST['stok_fisik']) && is_array($_POST['stok_fisik']) ? $_POST['stok_fisik'] : [];
                $stok_kurang = $this->_getSppbStokKurang($no_sppb);
                if (!empty($stok_kurang) && empty($stok_fisik)) {
                    echo json_encode([
                      'status' => 'need_adjustment',
                      'message' => 'Stok sistem kurang. Isi stok fisik yang tersedia untuk melanjutkan.',
                      'items' => $stok_kurang
                    ]);
                    exit();
                }
                $stok_fisik_map = [];
                if (!empty($stok_kurang)) {
                    foreach ($stok_kurang as $row) {
                        $kode_item = $row['kode_item'];
                        $nilai_fisik = isset($stok_fisik[$kode_item]) ? (float)$stok_fisik[$kode_item] : -1;
                        if ($nilai_fisik < (float)$row['qty']) {
                            echo json_encode([
                              'status' => 'error',
                              'message' => 'Stok fisik ' . $row['nama_barang'] . ' minimal ' . $this->_formatQty((float)$row['qty']) . ' untuk menyelesaikan pengambilan.'
                            ]);
                            exit();
                        }
                        $stok_fisik_map[$kode_item] = $nilai_fisik;
                    }
                }
                $stok_result = $this->_catatStokKeluarSppb($no_sppb, $stok_fisik_map);
                if ($stok_result['status'] !== 'success') {
                    echo json_encode($stok_result);
                    exit();
                }
            }
            try {
                $this->_simpanTandaTanganPengambilanSppb($no_sppb, $diambil_oleh, $user, $signature);
            } catch (\Throwable $e) {
                echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
                exit();
            }
            $update = $this->db('rsns_custom_logistik_non_medis_sppb')
                         ->where('no_sppb', $no_sppb)
                         ->update([
                             'status' => 'Selesai',
                             'diambil_oleh' => $diambil_oleh,
                             'tgl_diambil' => date('Y-m-d H:i:s')
                         ]);
            if ($update) {
                $this->_logAction('logistik_non_medis_sppb', 'SPPB Non Rutin Diterima/Selesai: ' . $no_sppb . ' | Diterima oleh: ' . $diambil_oleh, 'U');
                echo json_encode(['status' => 'success']);
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Gagal menyelesaikan permintaan.']);
            }
            exit();
        }

        $stok_fisik = isset($_POST['stok_fisik']) && is_array($_POST['stok_fisik']) ? $_POST['stok_fisik'] : [];
        $stok_kurang = $this->_getSppbStokKurang($no_sppb);
        if (!empty($stok_kurang) && empty($stok_fisik)) {
            echo json_encode([
              'status' => 'need_adjustment',
              'message' => 'Stok sistem kurang. Isi stok fisik yang tersedia untuk melanjutkan.',
              'items' => $stok_kurang
            ]);
            exit();
        }

        $stok_fisik_map = [];
        if (!empty($stok_kurang)) {
            foreach ($stok_kurang as $row) {
                $kode_item = $row['kode_item'];
                $nilai_fisik = isset($stok_fisik[$kode_item]) ? (float)$stok_fisik[$kode_item] : -1;
                if ($nilai_fisik < (float)$row['qty']) {
                    echo json_encode([
                      'status' => 'error',
                      'message' => 'Stok fisik ' . $row['nama_barang'] . ' minimal ' . $this->_formatQty((float)$row['qty']) . ' untuk menyelesaikan pengambilan.'
                    ]);
                    exit();
                }
                $stok_fisik_map[$kode_item] = $nilai_fisik;
            }
        }

        $stok_result = $this->_catatStokKeluarSppb($no_sppb, $stok_fisik_map);
        if ($stok_result['status'] !== 'success') {
            echo json_encode($stok_result);
            exit();
        }

        try {
            $this->_simpanTandaTanganPengambilanSppb($no_sppb, $diambil_oleh, $user, $signature);
        } catch (\Throwable $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
            exit();
        }
        $update = $this->db('rsns_custom_logistik_non_medis_sppb')
                     ->where('no_sppb', $no_sppb)
                     ->update([
                         'status' => 'Selesai',
                         'diambil_oleh' => $diambil_oleh,
                         'tgl_diambil' => date('Y-m-d H:i:s')
                     ]);
        if ($update) {
            $this->_logAction('logistik_non_medis_sppb', 'SPPB Selesai: ' . $no_sppb . ' | Diambil oleh: ' . $diambil_oleh, 'U');
            echo json_encode(['status' => 'success']);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyelesaikan permintaan.']);
        }
        exit();
    }

    private function _getSppbStokKurang(string $no_sppb): array
    {
        $this->_initStok();
        $sql = "
          SELECT s.kode_item, s.nama_barang_manual, s.jumlah, s.jumlah_disetujui, s.status, b.nama_barang
          FROM rsns_custom_logistik_non_medis_sppb s
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item
          WHERE s.no_sppb = ?
      ";
        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute([$no_sppb]);

        $kurang = [];
        foreach ($stmt->fetchAll(\PDO::FETCH_ASSOC) as $item) {
            $qty = (float)($item['jumlah_disetujui'] ?? 0);
            if ($qty <= 0) {
                $qty = (float)($item['jumlah'] ?? 0);
            }
            if ($qty <= 0 || ($item['status'] ?? '') === 'Ditolak') {
                continue;
            }

            $stok_stmt = $this->db()->pdo()->prepare("
              SELECT COALESCE(SUM(stok), 0) AS stok_sistem
              FROM rsns_custom_logistik_non_medis_stok_batch
              WHERE kode_item = ? AND stok > 0
                AND (tgl_expired IS NULL OR tgl_expired >= CURDATE())
          ");
            $stok_stmt->execute([$item['kode_item']]);
            $stok_sistem = (float)$stok_stmt->fetchColumn();

            if ($stok_sistem < $qty) {
                $kurang[] = [
                  'kode_item' => $item['kode_item'],
                  'nama_barang' => $item['nama_barang'] ?: ($item['nama_barang_manual'] ?: $item['kode_item']),
                  'qty' => $qty,
                  'stok_sistem' => $stok_sistem,
                  'kurang' => $qty - $stok_sistem
                ];
            }
        }

        return $kurang;
    }

    private function _formatQty(float $qty): string
    {
        return rtrim(rtrim(number_format($qty, 2, ',', '.'), '0'), ',');
    }

    private function _catatStokKeluarSppb(string $no_sppb, array $stok_fisik = [])
    {
        $this->_initStok();

        $existing = $this->db('rsns_custom_logistik_non_medis_kartu_stok')
                       ->where('no_referensi', $no_sppb)
                       ->where('tipe_transaksi', 'Keluar')
                       ->oneArray();
        if ($existing) {
            return ['status' => 'success', 'message' => 'Stok keluar SPPB sudah tercatat.'];
        }

        $items = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->toArray();
        if (empty($items)) {
            return ['status' => 'error', 'message' => 'Data item SPPB tidak ditemukan.'];
        }

        $plan = [];
        foreach ($items as $item) {
            $qty = (float)($item['jumlah_disetujui'] ?? 0);
            if ($qty <= 0) {
                $qty = (float)($item['jumlah'] ?? 0);
            }
            if ($qty <= 0 || ($item['status'] ?? '') === 'Ditolak') {
                continue;
            }

            $plan[] = [
              'kode_item' => $item['kode_item'],
              'qty' => $qty,
              'stok_fisik' => $stok_fisik[$item['kode_item']] ?? null
            ];
        }

        if (empty($plan)) {
            return ['status' => 'error', 'message' => 'Tidak ada item valid untuk dicatat ke kartu stok.'];
        }

        foreach ($plan as $row) {
            $this->_updateStokKeluarTanpaLokasi($row['kode_item'], $row['qty'], $no_sppb, $row['stok_fisik']);
        }

        return ['status' => 'success'];
    }

    private function _updateStokKeluarTanpaLokasi(string $kode_item, float $qty, string $no_ref, ?float $stok_fisik = null)
    {
        $metode = $this->_getMetodeStok();
        $query = $this->db('rsns_custom_logistik_non_medis_stok_batch')
                    ->where('kode_item', $kode_item)
                    ->where('stok', '>', 0);

        if ($metode == 'FEFO') {
            $query->asc('tgl_expired')->asc('tgl_terima');
        } else {
            $query->asc('tgl_terima');
        }

        $batches = $query->toArray();
        $remaining = (float)$qty;
        $last_stok_akhir = 0;
        $last_harga = 0;

        foreach ($batches as $batch) {
            if ($remaining <= 0) {
                break;
            }
            if (!empty($batch['tgl_expired']) && $batch['tgl_expired'] < date('Y-m-d')) {
                continue;
            }

            $take = min($remaining, (float)$batch['stok']);
            $stok_baru = (float)$batch['stok'] - $take;

            $this->db('rsns_custom_logistik_non_medis_stok_batch')
               ->where('kode_item', $kode_item)
               ->where('kode_lokasi', $batch['kode_lokasi'])
               ->where('batch_no', $batch['batch_no'])
               ->update(['stok' => $stok_baru]);

            $this->_recordKartuStok($kode_item, $batch['kode_lokasi'], $batch['batch_no'], 'Keluar', $no_ref, 0, $take, $stok_baru, $batch['harga_beli'] ?? 0);
            $last_stok_akhir = $stok_baru;
            $last_harga = (float)($batch['harga_beli'] ?? 0);
            $remaining -= $take;
        }

        if ($remaining > 0) {
            $stok_existing_keluar = (float)$qty - $remaining;
            $kode_lokasi = 'FISIK-MANUAL';
            $batch_no = 'FISIK-MANUAL';
            $manual_batch = $this->db('rsns_custom_logistik_non_medis_stok_batch')
                               ->where('kode_item', $kode_item)
                               ->where('kode_lokasi', $kode_lokasi)
                               ->where('batch_no', $batch_no)
                               ->oneArray();
            $stok_awal = $manual_batch ? (float)$manual_batch['stok'] : 0;
            if ($stok_fisik !== null) {
                $stok_fisik_manual = max(0, $stok_fisik - $stok_existing_keluar);
                if ($manual_batch) {
                    $this->db('rsns_custom_logistik_non_medis_stok_batch')
                       ->where('kode_item', $kode_item)
                       ->where('kode_lokasi', $kode_lokasi)
                       ->where('batch_no', $batch_no)
                       ->update(['stok' => $stok_fisik_manual]);
                } else {
                    $this->db('rsns_custom_logistik_non_medis_stok_batch')->save([
                      'kode_item' => $kode_item,
                      'kode_lokasi' => $kode_lokasi,
                      'batch_no' => $batch_no,
                      'tgl_expired' => null,
                      'tgl_terima' => date('Y-m-d'),
                      'harga_beli' => $last_harga,
                      'stok' => $stok_fisik_manual
                    ]);
                }

                $selisih = $stok_fisik_manual - $stok_awal;
                if (abs($selisih) > 0.00001) {
                    $this->_recordKartuStok(
                        $kode_item,
                        $kode_lokasi,
                        $batch_no,
                        'Opname',
                        $no_ref,
                        $selisih > 0 ? $selisih : 0,
                        $selisih < 0 ? abs($selisih) : 0,
                        $stok_fisik_manual,
                        $last_harga
                    );
                }

                $manual_batch = ['stok' => $stok_fisik_manual];
                $stok_awal = $stok_fisik_manual;
            }
            $stok_baru = $stok_awal - $remaining;

            if ($manual_batch) {
                $this->db('rsns_custom_logistik_non_medis_stok_batch')
                   ->where('kode_item', $kode_item)
                   ->where('kode_lokasi', $kode_lokasi)
                   ->where('batch_no', $batch_no)
                   ->update(['stok' => $stok_baru]);
            } else {
                $this->db('rsns_custom_logistik_non_medis_stok_batch')->save([
                  'kode_item' => $kode_item,
                  'kode_lokasi' => $kode_lokasi,
                  'batch_no' => $batch_no,
                  'tgl_expired' => null,
                  'tgl_terima' => date('Y-m-d'),
                  'harga_beli' => $last_harga,
                  'stok' => $stok_baru
                ]);
            }

            $this->_recordKartuStok($kode_item, $kode_lokasi, $batch_no, 'Keluar', $no_ref, 0, $remaining, $stok_baru, $last_harga);
        }
    }

    public function postHapusSppb()
    {
        $no_sppb = $_POST['no_sppb'] ?? '';
        $user = $this->core->getUserInfo('username', null, true);
        $userRoleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        $role = $userRoleData['role'] ?? 'unit';
        $user_kode_unit = $userRoleData['kode_unit'] ?? null;
        $cek = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
        if ($cek) {
            if ($role === 'logistik') {
                echo json_encode(['status' => 'error', 'message' => 'Role logistik tidak memiliki hak hapus permintaan.']);
                exit();
            }
            if ($role !== 'admin') {
                if (!in_array($cek['status'], ['Draft', 'Diajukan'], true)) {
                    echo json_encode(['status' => 'error', 'message' => 'Permintaan sudah masuk proses persetujuan dan tidak dapat dibatalkan.']);
                    exit();
                }
                if (in_array($role, ['unit', 'kepala_unit', 'kepala_sie', 'kepala_bidang'], true) && !empty($user_kode_unit)) {
                    $units_arr = $this->getChildUnitCodes(explode(',', $user_kode_unit));
                    if (!in_array($cek['kode_unit'], $units_arr, true)) {
                        echo json_encode(['status' => 'error', 'message' => 'Anda tidak memiliki hak untuk menghapus permintaan unit lain!']);
                        exit();
                    }
                }
            }
            if (!in_array($cek['status'], ['Draft', 'Diajukan'])) {
                echo json_encode(['status' => 'error', 'message' => 'Data sudah diproses dan tidak dapat diubah!']);
                exit();
            }

            $stmt = $this->db()->pdo()->prepare("DELETE FROM `rsns_custom_logistik_non_medis_sppb` WHERE `no_sppb` = ?");
            $exec = $stmt->execute([$no_sppb]);

            if ($exec !== false) {
                $this->_logAction('logistik_non_medis_sppb', 'Hapus SPPB: ' . $no_sppb, 'D');
                echo json_encode(['status' => 'success']);
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Gagal menghapus data SPPB.']);
            }
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Data SPPB tidak ditemukan.']);
        }
        exit();
    }

    public function anyCetakSppb($no_sppb = '')
    {
        $this->_initSppb();
        if (empty($no_sppb)) {
            $no_sppb = $_GET['no_sppb'] ?? '';
        }

        $sql = "
          SELECT s.*, u.nama_unit, COALESCE(NULLIF(s.nama_barang_manual, ''), b.nama_barang, s.kode_item) AS nama_barang
          FROM rsns_custom_logistik_non_medis_sppb s
          LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = s.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item
          WHERE s.no_sppb = ?
      ";
        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute([$no_sppb]);
        $rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);

        if (!$rows) {
            die('Data tidak ditemukan');
        }

        foreach ($rows as $idx => &$row) {
            $row['index'] = $idx;
        }
        $sppb = $rows[0];
        $sppb['items'] = $rows;

        echo $this->draw('distribusi.sppb.cetak.html', [
          'sppb' => $sppb,
          'preview_mode' => isset($_GET['preview']) && (string)$_GET['preview'] === '1',
          'logo' => url() . '/' . $this->settings->get('settings.logo'),
          'nama_rs' => 'RSU Nurusyifa',
          'alamat_rs' => $this->settings->get('settings.alamat'),
          'kota_rs' => $this->settings->get('settings.kota'),
          'kontak_rs' => $this->settings->get('settings.nomor_telepon')
        ]);
        exit();
    }


