    /** Pengeluaran langsung untuk kebutuhan mendesak/non-rutin tanpa alur persetujuan. */
    public function getDistribusiMendesak()
    {
        $this->_initSppb();
        $this->_initStok();
        $this->_addHeaderFiles();
        $username = $this->core->getUserInfo('username', null, true);
        $roleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = strtolower($roleData['role'] ?? 'unit');
        $unitScope = [];
        if (!in_array($role, ['admin', 'logistik', 'gudang'], true) && !empty($roleData['kode_unit'])) {
            $unitScope = $this->_getAllChildUnitKodes(array_map('trim', explode(',', $roleData['kode_unit'])));
        }
        $units = $this->db('rsns_custom_logistik_non_medis_unit')->where('status', 'Aktif')->toArray();
        if ($unitScope) {
            $units = array_values(array_filter($units, function ($u) use ($unitScope) { return in_array($u['kode_unit'], $unitScope, true); }));
        }
        $items = $this->db()->pdo()->query("SELECT b.kode_item, b.nama_barang, b.satuan_dasar, b.kode_kategori, k.nama_kategori
          FROM rsns_custom_logistik_non_medis_master_barang b
          LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
          WHERE b.status = 'Aktif' AND (b.tipe_barang IS NULL OR b.tipe_barang <> 'Aset')
          ORDER BY b.nama_barang")->fetchAll(\PDO::FETCH_ASSOC);
        $categories = [];
        foreach ($items as $item) {
            $name = trim((string)($item['nama_kategori'] ?? ''));
            $code = trim((string)($item['kode_kategori'] ?? ''));
            if ($name !== '' && $code !== '') $categories[$code] = ['kode' => $code, 'nama' => $name];
        }
        uasort($categories, function ($a, $b) { return strcasecmp($a['nama'], $b['nama']); });
        $defaultUnit = count($units) === 1 ? $units[0]['kode_unit'] : trim((string)($roleData['kode_unit'] ?? ''));
        $defaultUnitName = '';
        foreach ($units as $unit) {
            if (($unit['kode_unit'] ?? '') === $defaultUnit) { $defaultUnitName = $unit['nama_unit'] ?? ''; break; }
        }
        return $this->draw('distribusi.mendesak.html', [
          'units' => $units, 'items' => $items, 'categories' => array_values($categories), 'role' => $role,
          'default_unit' => $defaultUnit, 'default_unit_name' => $defaultUnitName
        ]);
    }

    public function anyDisplayDistribusiMendesak()
    {
        $this->_initSppb();
        $cari = trim((string)($_POST['cari'] ?? ''));
        $unit = trim((string)($_POST['unit'] ?? ''));
        $halaman = max(1, (int)($_POST['halaman'] ?? 1));
        $perHalaman = 20;
        $where = " WHERE s.jenis_permintaan='Non Rutin' AND s.sifat_permintaan IN ('Mendesak','Langsung')";
        $params = [];

        $username = $this->core->getUserInfo('username', null, true);
        $roleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = strtolower($roleData['role'] ?? 'unit');
        if (!in_array($role, ['admin', 'logistik', 'gudang'], true) && !empty($roleData['kode_unit'])) {
            $unitScope = $this->_getAllChildUnitKodes(array_map('trim', explode(',', $roleData['kode_unit'])));
            if ($unitScope) {
                $where .= ' AND s.kode_unit IN (' . implode(',', array_fill(0, count($unitScope), '?')) . ')';
                $params = array_merge($params, $unitScope);
            }
        }
        if ($unit !== '') {
            $where .= " AND (u.nama_unit LIKE ? OR s.kode_unit LIKE ?)";
            $params[] = '%' . $unit . '%';
            $params[] = '%' . $unit . '%';
        }
        if ($cari !== '') {
            $where .= " AND (s.no_sppb LIKE ? OR u.nama_unit LIKE ? OR s.diajukan_oleh LIKE ? OR s.keterangan LIKE ?)";
            $params = array_merge($params, array_fill(0, 4, '%' . $cari . '%'));
        }

        $fromSql = " FROM rsns_custom_logistik_non_medis_sppb s
                     LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit=s.kode_unit";
        $countStmt = $this->db()->pdo()->prepare('SELECT COUNT(DISTINCT s.no_sppb)' . $fromSql . $where);
        $countStmt->execute($params);
        $total = (int)$countStmt->fetchColumn();
        $totalHalaman = max(1, (int)ceil($total / $perHalaman));
        $halaman = min($halaman, $totalHalaman);
        $offset = ($halaman - 1) * $perHalaman;

        $sql = "SELECT s.no_sppb, s.tgl_sppb, s.status, s.diajukan_oleh, s.keterangan,
                       u.nama_unit, COUNT(*) jumlah_jenis, SUM(s.jumlah_disetujui) total_qty,
                       MAX(s.id) urutan" . $fromSql . $where .
               " GROUP BY s.no_sppb, s.tgl_sppb, s.status, s.diajukan_oleh, s.keterangan, u.nama_unit
                 ORDER BY urutan DESC LIMIT " . $perHalaman . " OFFSET " . $offset;
        $stmt = $this->db()->pdo()->prepare($sql); $stmt->execute($params);
        $pages = [];
        $awal = max(1, $halaman - 2);
        $akhir = min($totalHalaman, $halaman + 2);
        for ($i = $awal; $i <= $akhir; $i++) {
            $pages[] = ['number' => $i, 'active' => $i === $halaman];
        }
        echo $this->draw('distribusi.mendesak.display.html', [
          'rows' => $stmt->fetchAll(\PDO::FETCH_ASSOC),
          'total' => $total,
          'from' => $total > 0 ? $offset + 1 : 0,
          'to' => min($offset + $perHalaman, $total),
          'current_page' => $halaman,
          'total_pages' => $totalHalaman,
          'prev_page' => max(1, $halaman - 1),
          'next_page' => min($totalHalaman, $halaman + 1),
          'has_prev' => $halaman > 1,
          'has_next' => $halaman < $totalHalaman,
          'pages' => $pages
        ]);
        exit();
    }

    private function _generateNoMendesak(): string
    {
        $prefix = 'PL/' . date('Ym') . '/';
        $stmt = $this->db()->pdo()->prepare("SELECT no_sppb FROM rsns_custom_logistik_non_medis_sppb WHERE no_sppb LIKE ? ORDER BY no_sppb DESC LIMIT 1");
        $stmt->execute([$prefix . '%']);
        $last = $stmt->fetchColumn();
        $number = $last ? ((int)substr($last, -4) + 1) : 1;
        return $prefix . str_pad((string)$number, 4, '0', STR_PAD_LEFT);
    }

    public function postSimpanDistribusiMendesak()
    {
        $this->_initSppb(); $this->_initStok();
        $kode_unit = trim((string)($_POST['kode_unit'] ?? ''));
        $peminta = trim((string)($_POST['diajukan_oleh'] ?? ''));
        $alasan = trim((string)($_POST['keterangan'] ?? ''));
        $cara = ($_POST['cara_proses'] ?? 'siapkan') === 'langsung' ? 'langsung' : 'siapkan';
        $kodeItems = $_POST['kode_item'] ?? []; $jumlah = $_POST['jumlah'] ?? []; $jumlahSetuju = $_POST['jumlah_disetujui'] ?? [];
        if (!$kode_unit || !$peminta || !$alasan || !is_array($kodeItems) || !is_array($jumlah) || !is_array($jumlahSetuju)) { echo json_encode(['status'=>'error','message'=>'Unit, nama peminta, keperluan, dan barang wajib diisi.']); exit(); }
        $rows = [];
        foreach ($kodeItems as $i => $kode) {
            $kode = trim((string)$kode); $qty = (float)($jumlah[$i] ?? 0); $qtySetuju = (float)($jumlahSetuju[$i] ?? $qty);
            if (!$kode || $qty <= 0) continue;
            if ($qtySetuju <= 0 || $qtySetuju > $qty) { echo json_encode(['status'=>'error','message'=>'Jumlah disetujui harus lebih dari 0 dan tidak boleh melebihi jumlah diminta.']); exit(); }
            $barang = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $kode)->where('status', 'Aktif')->oneArray();
            if (!$barang || (($barang['tipe_barang'] ?? 'Habis Pakai') === 'Aset')) { echo json_encode(['status'=>'error','message'=>'Barang tidak valid atau termasuk aset.']); exit(); }
            $stokStmt = $this->db()->pdo()->prepare("SELECT COALESCE(SUM(stok),0) FROM rsns_custom_logistik_non_medis_stok_batch WHERE kode_item=? AND stok>0 AND (tgl_expired IS NULL OR tgl_expired>=CURDATE())");
            $stokStmt->execute([$kode]); $stok = (float)$stokStmt->fetchColumn();
            if ($stok + 0.00001 < $qtySetuju) { echo json_encode(['status'=>'error','message'=>'Stok '.$barang['nama_barang'].' tidak mencukupi. Tersedia: '.$stok.' '.$barang['satuan_dasar']]); exit(); }
            $rows[] = [$kode, $qty, $qtySetuju, $barang];
        }
        if (!$rows) { echo json_encode(['status'=>'error','message'=>'Minimal satu barang dengan jumlah lebih dari 0.']); exit(); }
        $no = $this->_generateNoMendesak(); $pdo = $this->db()->pdo();
        try {
            $pdo->beginTransaction();
            foreach ($rows as $row) {
                [$kode, $qty, $qtySetuju, $barang] = $row;
                $this->db('rsns_custom_logistik_non_medis_sppb')->save([
                  'no_sppb'=>$no, 'tgl_sppb'=>date('Y-m-d'), 'kode_unit'=>$kode_unit, 'jenis_permintaan'=>'Non Rutin',
                  'kode_item'=>$kode, 'item_sumber'=>'master', 'estimasi_harga'=>(float)($barang['harga_referensi'] ?? 0),
                  'sifat_permintaan'=>'Langsung', 'diajukan_oleh'=>$peminta, 'jumlah'=>$qty, 'jumlah_disetujui'=>$qtySetuju,
                  'satuan'=>$barang['satuan_dasar'] ?? '', 'status'=>$cara === 'langsung' ? 'Siap Diserahkan' : 'Proses Logistik', 'keterangan'=>$alasan,
                  'keterangan_item'=>'Permintaan langsung', 'user_input'=>$this->core->getUserInfo('username', null, true), 'tgl_input'=>date('Y-m-d H:i:s')
                ]);
            }
            $pdo->commit();
            echo json_encode(['status'=>'success','no_sppb'=>$no,'lanjut_serah'=>$cara === 'langsung']);
        } catch (\Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); echo json_encode(['status'=>'error','message'=>'Gagal menyimpan: '.$e->getMessage()]); }
        exit();
    }

    public function postDistribusiMendesakSiapkan()
    {
        $this->_initSppb();
        $no = trim((string)($_POST['no_sppb'] ?? ''));
        $row = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no)->oneArray();
        if (!$row || !in_array($row['sifat_permintaan'] ?? '', ['Mendesak', 'Langsung'], true) || ($row['status'] ?? '') !== 'Proses Logistik') {
            echo json_encode(['status'=>'error','message'=>'Permintaan tidak ditemukan atau statusnya bukan sedang disiapkan.']); exit();
        }
        $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no)->update(['status'=>'Siap Diserahkan']);
        echo json_encode(['status'=>'success']); exit();
    }

