    public function anyDistribusiMendesakFormSerah()
    {
        $this->_initSppb();
        $this->_initSerahTerima();
        $no_sppb = trim((string)($_POST['no_sppb'] ?? ''));
        $sppb = $this->db('rsns_custom_logistik_non_medis_sppb s')
                   ->select('s.*, u.nama_unit')
                   ->leftJoin('rsns_custom_logistik_non_medis_unit u', 'u.kode_unit = s.kode_unit')
                   ->where('s.no_sppb', $no_sppb)
                   ->oneArray();
        if (!$sppb) {
            echo '<div class="modal-body"><div class="alert alert-danger">Data pengeluaran mendesak tidak ditemukan.</div></div>';
            exit();
        }
        if (!in_array($sppb['sifat_permintaan'] ?? '', ['Mendesak', 'Langsung'], true)) {
            echo '<div class="modal-body"><div class="alert alert-danger">Data ini bukan permintaan langsung.</div></div>'; exit();
        }
        $items = $this->db('rsns_custom_logistik_non_medis_sppb s')
                    ->select('s.*, b.nama_barang')
                    ->leftJoin('rsns_custom_logistik_non_medis_master_barang b', 'b.kode_item = s.kode_item')
                    ->where('s.no_sppb', $no_sppb)
                    ->toArray();
        $total_qty = 0;
        foreach ($items as &$item) {
            $item['nama_barang'] = $item['nama_barang'] ?? $item['kode_item'];
            $item['jumlah_diminta'] = (float)($item['jumlah'] ?? 0);
            $item['jumlah_setuju'] = (float)(($item['jumlah_disetujui'] ?? 0) > 0 ? $item['jumlah_disetujui'] : $item['jumlah']);
            $total_qty += $item['jumlah_setuju'];
        }
        unset($item);
        echo $this->draw('distribusi.mendesak.serah.html', [
          'sppb' => $sppb,
          'items' => $items,
          'total_jenis' => count($items),
          'total_qty' => $total_qty,
          'no_bast' => $this->_generateNoSerahTerima()
        ]);
        exit();
    }

    public function getCetakDistribusiMendesak()
    {
        $this->_initSppb();
        $this->_initSerahTerima();
        $no_sppb = trim((string)($_GET['no_sppb'] ?? ''));
        $sppb = $this->db('rsns_custom_logistik_non_medis_sppb s')
                   ->select('s.*, u.nama_unit')
                   ->leftJoin('rsns_custom_logistik_non_medis_unit u', 'u.kode_unit = s.kode_unit')
                   ->where('s.no_sppb', $no_sppb)
                   ->oneArray();
        $st = $this->db('rsns_custom_logistik_non_medis_serah_terima')->where('no_sppb', $no_sppb)->oneArray();
        if (!$sppb || !$st || !in_array($sppb['sifat_permintaan'] ?? '', ['Mendesak', 'Langsung'], true)) {
            exit('Bukti pengambilan barang tidak ditemukan.');
        }
        $items = $this->db('rsns_custom_logistik_non_medis_sppb s')
                    ->select('s.*, b.nama_barang')
                    ->leftJoin('rsns_custom_logistik_non_medis_master_barang b', 'b.kode_item = s.kode_item')
                    ->where('s.no_sppb', $no_sppb)
                    ->toArray();
        foreach ($items as $i => &$item) {
            $item['no_urut'] = $i + 1;
            $item['nama_barang'] = $item['nama_barang'] ?? $item['kode_item'];
            $item['jumlah_setuju'] = (float)(($item['jumlah_disetujui'] ?? 0) > 0 ? $item['jumlah_disetujui'] : $item['jumlah']);
        }
        unset($item);
        $logo = $this->settings->get('settings.logo') ? url($this->settings->get('settings.logo')) : url('assets/img/logo.png');
        echo $this->draw('distribusi.mendesak.cetak.html', [
          'sppb' => $sppb,
          'st' => $st,
          'items' => $items,
          'total_jenis' => count($items),
          'ttd_url' => !empty($st['tanda_terima']) ? $this->_serahTerimaSignatureDataUri((string)$st['tanda_terima']) : '',
          'logo' => $logo,
          'nama_rs' => $this->settings->get('settings.nama_instansi'),
          'alamat_rs' => $this->settings->get('settings.alamat'),
          'kontak_rs' => $this->settings->get('settings.nomor_telepon')
        ]);
        exit();
    }

    public function postSaveSerahTerima()
    {
        $this->_initSerahTerima();
        $no_sppb = $_POST['no_sppb'] ?? '';
        $no_serah_terima = $_POST['no_serah_terima'] ?? '';
        $penerima_nama = $_POST['penerima_nama'] ?? '';
        $tanda_terima_payload = $_POST['tanda_terima'] ?? '';

        if (empty($no_sppb) || empty($penerima_nama) || empty($tanda_terima_payload)) {
            echo json_encode(['status' => 'error', 'message' => 'Data tidak lengkap!']);
            exit();
        }
        try {
            $signature = $this->_encodeSerahTerimaSignature($tanda_terima_payload);
        } catch (\Throwable $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
            exit();
        }

        $upload_dir = UPLOADS . '/logistik_non_medis/serah_terima';
        $foto_filename = '';

        if (isset($_FILES['foto_kondisi']) && $_FILES['foto_kondisi']['error'] == 0) {
            $ext = strtolower(pathinfo($_FILES['foto_kondisi']['name'], PATHINFO_EXTENSION));
            $foto_filename = 'foto_' . str_replace('/', '-', $no_serah_terima) . '_' . time() . '.' . $ext;
            move_uploaded_file($_FILES['foto_kondisi']['tmp_name'], $upload_dir . '/foto/' . $foto_filename);
        }

        $data = [
          'no_serah_terima' => $no_serah_terima,
          'no_sppb' => $no_sppb,
          'tanggal_serah' => date('Y-m-d H:i:s'),
          'petugas_pengirim' => $this->core->getUserInfo('username', null, true),
          'penerima_nama' => $penerima_nama,
          'penerima_nip' => $_POST['penerima_nip'] ?? '',
          'foto_kondisi' => $foto_filename,
          'tanda_terima' => $signature['data'],
          'tanda_terima_format' => 'STROKES_V1',
          'tanda_terima_hash' => $signature['hash'],
          'tanda_terima_ip' => substr((string)($_SERVER['REMOTE_ADDR'] ?? ''), 0, 45),
          'tanda_terima_user_agent' => substr((string)($_SERVER['HTTP_USER_AGENT'] ?? ''), 0, 255),
          'keterangan' => $_POST['keterangan'] ?? ''
        ];

        $save = $this->db('rsns_custom_logistik_non_medis_serah_terima')->save($data);

        if ($save) {
            $stok_result = $this->_catatStokKeluarSppb($no_sppb);
            if ($stok_result['status'] !== 'success') {
                echo json_encode($stok_result);
                exit();
            }

            $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->update(['status' => 'Selesai']);

            // Log Activity & Internal Notification
            $user = $this->core->getUserInfo('username', null, true);
            $ip = $_SERVER['REMOTE_ADDR'] ?? '';
            $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
            $hostname = $cek_hostname['hostname'] ?? 'Unknown';
            $this->db('mlite_tracksql')->save([
              'log_id' => null,
              'log_modul' => 'logistik_non_medis_serah_terima',
              'log_waktu' => date('Y-m-d H:i:s'),
              'log_location' => $hostname . ' | ' . $ip,
              'log_data' => 'Serah Terima Selesai: ' . $no_sppb . ' | BAST: ' . $no_serah_terima,
              'log_status' => 'I',
              'log_username' => $user
            ]);

            echo json_encode(['status' => 'success', 'no_sppb' => $no_sppb]);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan data serah terima.']);
        }
        exit();
    }

    public function anyCetakBASTSerahTerima($no_sppb = null)
    {
        $this->_initSerahTerima();
        if (!$no_sppb) {
            $no_sppb = $_GET['no_sppb'] ?? null;
        }
        if (!$no_sppb) {
