        foreach ($kategori_master as $row) $kategori_map[$row['kode_kategori']] = $row['nama_kategori'];
        $kelompok_map = [];
        foreach ($kelompok_master as $row) $kelompok_map[$row['kode_kategori'] . '|' . $row['kode_kelompok']] = $row['nama_kelompok'];
        $query = $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->asc('kode_kategori')->asc('kode_kelompok')->asc('kode_jenis');
        $all = $query->toArray();
        $filtered = [];
        foreach ($all as $row) {
            $key = $row['kode_kategori'] . '|' . $row['kode_kelompok'];
            $row['nama_kategori'] = $kategori_map[$row['kode_kategori']] ?? ('Kategori ' . $row['kode_kategori']);
            $row['nama_kelompok'] = $kelompok_map[$key] ?? ('Kelompok ' . $row['kode_kelompok']);
            $match = $kategori === '' || $row['kode_kategori'] === $kategori;
            $match = $match && ($kelompok === '' || $key === $kelompok);
            if ($cari !== '') {
                $haystack = strtolower($row['nama_jenis'] . ' ' . $row['nama_kategori'] . ' ' . $row['nama_kelompok'] . ' ' . $row['kode_jenis']);
                $match = $match && strpos($haystack, strtolower($cari)) !== false;
            }
            if ($match) $filtered[] = $row;
        }
        $jumlah_data = count($filtered);
        $jml_halaman = max(1, (int) ceil($jumlah_data / $perpage));
        $halaman = min($halaman, $jml_halaman);
        $pages = range(1, $jml_halaman);
        $jenis_master = array_slice($filtered, ($halaman - 1) * $perpage, $perpage);
        echo $this->draw('master.inventaris.jenis.display.html', compact('jenis_master', 'halaman', 'jml_halaman', 'jumlah_data', 'pages'));
        exit();
    }

    public function postSaveMasterInventaris()
    {
        $this->_initAset();
        $id = (int) ($_POST['id'] ?? 0);
        $jenis = $_POST['jenis_master'] ?? '';
        $nama = trim($_POST['nama'] ?? '');
        if (!in_array($jenis, ['UNIT', 'KATEGORI', 'KELOMPOK', 'JENIS', 'BARANG'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Jenis master dan nama wajib diisi.']);
            exit();
        }

        if ($jenis === 'UNIT') {
            $nama = trim($_POST['nama_unit'] ?? '');
            $existing = $id ? $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('id', $id)->oneArray() : null;
            $kode = $existing['kode'] ?? ('MANUAL-' . uniqid());
            $kodeUnitAngka = (int)preg_replace('/\D/', '', $_POST['kode_unit_inventaris'] ?? '');
            $kodeInventaris = $kodeUnitAngka <= 99
              ? str_pad((string)$kodeUnitAngka, 2, '0', STR_PAD_LEFT)
              : str_pad((string)$kodeUnitAngka, 3, '0', STR_PAD_LEFT);
            if (!preg_match('/^\d{2,3}$/', $kodeInventaris) || $kodeUnitAngka < 1 || $kodeUnitAngka > 999) {
                echo json_encode(['status' => 'error', 'message' => 'Kode unit harus 01-99 atau 100-999.']);
                exit();
            }
            if ($nama === '') {
                echo json_encode(['status' => 'error', 'message' => 'Nama unit wajib diisi.']);
                exit();
            }
            $cekUrut = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('jenis_master', 'UNIT')->where('kode_inventaris', $kodeInventaris);
            if ($id) {
                $cekUrut = $cekUrut->where('id', '!=', $id);
            }
            if ($cekUrut->oneArray()) {
                echo json_encode(['status' => 'error', 'message' => 'Urutan inventaris tersebut sudah dipakai unit lain.']);
                exit();
            }
            $data = ['jenis_master' => 'UNIT', 'kode' => $kode, 'kode_inventaris' => $kodeInventaris, 'kode_kategori' => '', 'nama' => $nama, 'kode_kelompok' => null, 'kode_jenis' => null, 'kode_barang' => null, 'kib_jenis' => null, 'status' => 'Aktif', 'tgl_input' => date('Y-m-d H:i:s')];
        } elseif ($jenis === 'KATEGORI') {
            $kodeKategori = preg_replace('/\D/', '', $_POST['kode_kategori_input'] ?? '');
            $namaKategori = trim($_POST['nama_kategori'] ?? '');
            $kodeLama = $_POST['kode_kategori_lama'] ?? '';
            if (!preg_match('/^[1-9]$/', $kodeKategori) || $namaKategori === '') {
                echo json_encode(['status' => 'error', 'message' => 'Kode dan nama kategori wajib diisi.']);
                exit();
            }
            $cek = $this->db('rsns_custom_logistik_non_medis_inventaris_kategori')->where('kode_kategori', $kodeKategori);
            if ($kodeLama !== '') {
                $cek = $cek->where('kode_kategori', '!=', $kodeLama);
            }
            if ($cek->oneArray()) {
                echo json_encode(['status' => 'error', 'message' => 'Kode kategori sudah dipakai.']);
                exit();
            }
            if ($kodeLama !== '' && $kodeLama !== $kodeKategori) {
                $used = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('kode_kategori', $kodeLama)->count()
                  + $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->where('kode_kategori', $kodeLama)->count()
                  + $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->where('kode_kategori', $kodeLama)->count();
                if ($used > 0) {
                    echo json_encode(['status' => 'error', 'message' => 'Kode kategori tidak dapat diubah karena sudah dipakai.']);
                    exit();
                }
            }
            if ($kodeLama !== '') {
                $this->db('rsns_custom_logistik_non_medis_inventaris_kategori')->where('kode_kategori', $kodeLama)->save(['kode_kategori' => $kodeKategori, 'nama_kategori' => $namaKategori]);
            } else {
                $this->db('rsns_custom_logistik_non_medis_inventaris_kategori')->save(['kode_kategori' => $kodeKategori, 'nama_kategori' => $namaKategori]);
            }
            echo json_encode(['status' => 'success', 'message' => 'Master kategori tersimpan.']);
            exit();
        } elseif ($jenis === 'KELOMPOK') {
            $kodeKategori = $_POST['kode_kategori_kelompok'] ?? '';
            $kodeKelompok = str_pad(preg_replace('/\D/', '', $_POST['kode_kelompok_input'] ?? ''), 2, '0', STR_PAD_LEFT);
            $namaKelompok = trim($_POST['nama_kelompok'] ?? '');
            $kodeKategoriLama = $_POST['kode_kategori_lama'] ?? '';
            $kodeKelompokLama = $_POST['kode_kelompok_lama'] ?? '';
            if (!preg_match('/^\d{2}$/', $kodeKelompok) || (int) $kodeKelompok < 1 || $namaKelompok === '' || !$this->db('rsns_custom_logistik_non_medis_inventaris_kategori')->where('kode_kategori', $kodeKategori)->oneArray()) {
                echo json_encode(['status' => 'error', 'message' => 'Kategori, kode kelompok, dan nama kelompok wajib valid.']);
                exit();
            }
            $cek = $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->oneArray();
            if ($cek && ($kodeKategoriLama !== $kodeKategori || $kodeKelompokLama !== $kodeKelompok)) {
                echo json_encode(['status' => 'error', 'message' => 'Kode kelompok sudah dipakai pada kategori ini.']);
                exit();
            }
            $dataKelompok = ['kode_kategori' => $kodeKategori, 'kode_kelompok' => $kodeKelompok, 'nama_kelompok' => $namaKelompok];
            if ($kodeKategoriLama !== '' && $kodeKelompokLama !== '') {
                if ($kodeKategoriLama !== $kodeKategori || $kodeKelompokLama !== $kodeKelompok) {
                    $used = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('kode_kategori', $kodeKategoriLama)->where('kode_kelompok', $kodeKelompokLama)->count()
                      + $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->where('kode_kategori', $kodeKategoriLama)->where('kode_kelompok', $kodeKelompokLama)->count();
                    if ($used > 0) {
                        echo json_encode(['status' => 'error', 'message' => 'Kode kelompok tidak dapat diubah karena sudah dipakai.']);
                        exit();
                    }
                }
                $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->where('kode_kategori', $kodeKategoriLama)->where('kode_kelompok', $kodeKelompokLama)->save($dataKelompok);
            } else {
                $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->save($dataKelompok);
            }
            $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->save(['nama_kelompok' => $namaKelompok]);
            echo json_encode(['status' => 'success', 'message' => 'Master kelompok tersimpan.']);
            exit();
        } elseif ($jenis === 'JENIS') {
            $kodeKategori = $_POST['kode_kategori_jenis'] ?? '';
            $kodeKelompok = $_POST['kode_kelompok_jenis'] ?? '';
            $kodeJenis = str_pad(preg_replace('/\D/', '', $_POST['kode_jenis_input'] ?? ''), 2, '0', STR_PAD_LEFT);
            $namaJenis = trim($_POST['nama_jenis'] ?? '');
            $kodeKategoriLama = $_POST['kode_kategori_lama'] ?? '';
            $kodeKelompokLama = $_POST['kode_kelompok_lama'] ?? '';
            $kodeJenisLama = $_POST['kode_jenis_lama'] ?? '';
            if (!preg_match('/^\d{2}$/', $kodeJenis) || (int) $kodeJenis < 1 || $namaJenis === '' || !$this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->oneArray()) {
                echo json_encode(['status' => 'error', 'message' => 'Kategori, kelompok, kode jenis, dan nama jenis wajib valid.']);
                exit();
            }
            $cek = $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->where('kode_jenis', $kodeJenis)->oneArray();
            if ($cek && ($kodeKategoriLama !== $kodeKategori || $kodeKelompokLama !== $kodeKelompok || $kodeJenisLama !== $kodeJenis)) {
                echo json_encode(['status' => 'error', 'message' => 'Kode jenis sudah dipakai pada kelompok ini.']);
                exit();
            }
            $dataJenis = ['kode_kategori' => $kodeKategori, 'kode_kelompok' => $kodeKelompok, 'kode_jenis' => $kodeJenis, 'nama_jenis' => $namaJenis];
            if ($kodeKategoriLama !== '' && $kodeKelompokLama !== '' && $kodeJenisLama !== '') {
                if ($kodeKategoriLama !== $kodeKategori || $kodeKelompokLama !== $kodeKelompok || $kodeJenisLama !== $kodeJenis) {
                    $used = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('kode_kategori', $kodeKategoriLama)->where('kode_kelompok', $kodeKelompokLama)->where('kode_jenis', $kodeJenisLama)->count();
                    if ($used > 0) {
                        echo json_encode(['status' => 'error', 'message' => 'Kode jenis tidak dapat diubah karena sudah dipakai barang.']);
                        exit();
                    }
                }
                $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->where('kode_kategori', $kodeKategoriLama)->where('kode_kelompok', $kodeKelompokLama)->where('kode_jenis', $kodeJenisLama)->save($dataJenis);
            } else {
                $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->save($dataJenis);
            }
            $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->where('kode_jenis', $kodeJenis)->save(['nama_jenis' => $namaJenis]);
            echo json_encode(['status' => 'success', 'message' => 'Master jenis barang tersimpan.']);
            exit();
        } else {
            if ($nama === '') {
                echo json_encode(['status' => 'error', 'message' => 'Nama barang wajib diisi.']);
                exit();
            }
            $kategori = $_POST['kode_kategori'] ?? '2';
            $kelompok = $_POST['kode_kelompok'] ?? '';
            $jenisKode = $_POST['kode_jenis'] ?? '';
            $kelompokRow = $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->where('kode_kategori', $kategori)->where('kode_kelompok', $kelompok)->oneArray();
            $jenisRow = $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->where('kode_kategori', $kategori)->where('kode_kelompok', $kelompok)->where('kode_jenis', $jenisKode)->oneArray();
            if (!$kelompokRow || !$jenisRow) {
                echo json_encode(['status' => 'error', 'message' => 'Pilih kategori, kelompok, dan jenis yang valid.']);
                exit();
            }
            $existing = $id ? $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('id', $id)->oneArray() : null;
            if ($existing) {
                $barangKode = $existing['kode_barang'];
            } else {
                $last = $this->db()->pdo()->prepare("SELECT MAX(CAST(kode_barang AS UNSIGNED)) FROM rsns_custom_logistik_non_medis_inventaris_master WHERE jenis_master='BARANG' AND kode_kategori=? AND kode_kelompok=? AND kode_jenis=?");
                $last->execute([$kategori, $kelompok, $jenisKode]);
                $barangKode = str_pad((string) ((int) $last->fetchColumn() + 1), 2, '0', STR_PAD_LEFT);
            }
            if ((int) $barangKode > 99) {
                echo json_encode(['status' => 'error', 'message' => 'Nomor barang pada jenis ini sudah mencapai 99.']);
                exit();
            }
            $hargaReferensi = (float) preg_replace('/[^0-9]/', '', $_POST['harga_referensi'] ?? '0');
            $data = ['jenis_master' => 'BARANG', 'kode' => $kelompok . $jenisKode . $barangKode, 'kode_inventaris' => null, 'kode_kategori' => $kategori, 'nama' => $nama, 'kode_kelompok' => $kelompok, 'kode_jenis' => $jenisKode, 'kode_barang' => $barangKode, 'nama_kelompok' => $kelompokRow['nama_kelompok'], 'nama_jenis' => $jenisRow['nama_jenis'], 'kib_jenis' => $_POST['kib_jenis'] ?: null, 'harga_referensi' => $hargaReferensi, 'status' => 'Aktif', 'tgl_input' => date('Y-m-d H:i:s')];
        }
        $cekKode = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('jenis_master', $data['jenis_master'])->where('kode_kategori', $data['kode_kategori'])->where('kode', $data['kode']);
        if ($id) {
            $cekKode = $cekKode->where('id', '!=', $id);
        }
        if ($cekKode->oneArray()) {
            echo json_encode(['status' => 'error', 'message' => 'Kode tersebut sudah ada pada Master Inventaris.']);
            exit();
        }
        if ($id) {
            $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('id', $id)->save($data);
        } else {
            $this->db('rsns_custom_logistik_non_medis_inventaris_master')->save($data);
        }
        echo json_encode(['status' => 'success', 'message' => 'Master Inventaris tersimpan.']);
        exit();
    }

    public function anyDetailMasterInventaris()
    {
        $this->_initAset();
        $jenis = $_POST['jenis_master'] ?? '';
        if ($jenis === 'KATEGORI') {
            $row = $this->db('rsns_custom_logistik_non_medis_inventaris_kategori')->where('kode_kategori', $_POST['kode_kategori'] ?? '')->oneArray();
        } elseif ($jenis === 'KELOMPOK') {
            $row = $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->where('kode_kategori', $_POST['kode_kategori'] ?? '')->where('kode_kelompok', $_POST['kode_kelompok'] ?? '')->oneArray();
        } elseif ($jenis === 'JENIS') {
            $row = $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->where('kode_kategori', $_POST['kode_kategori'] ?? '')->where('kode_kelompok', $_POST['kode_kelompok'] ?? '')->where('kode_jenis', $_POST['kode_jenis'] ?? '')->oneArray();
        } else {
            $row = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('id', (int) ($_POST['id'] ?? 0))->oneArray();
        }
        echo json_encode($row ?: ['status' => 'error', 'message' => 'Data tidak ditemukan.']);
        exit();
    }

    public function postHapusMasterInventaris()
    {
        $this->_initAset();
        $jenis = $_POST['jenis_master'] ?? '';
        if ($jenis === 'KATEGORI') {
            $kodeKategori = $_POST['kode_kategori'] ?? '';
            $used = $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->where('kode_kategori', $kodeKategori)->count()
              + $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->where('kode_kategori', $kodeKategori)->count()
              + $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('kode_kategori', $kodeKategori)->count();
            if ($used > 0) {
                echo json_encode(['status' => 'error', 'message' => 'Kategori tidak dapat dihapus karena sudah dipakai.']);
                exit();
            }
            $this->db('rsns_custom_logistik_non_medis_inventaris_kategori')->where('kode_kategori', $kodeKategori)->delete();
        } elseif ($jenis === 'KELOMPOK') {
            $kodeKategori = $_POST['kode_kategori'] ?? '';
            $kodeKelompok = $_POST['kode_kelompok'] ?? '';
            $used = $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->count()
              + $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->count();
            if ($used > 0) {
                echo json_encode(['status' => 'error', 'message' => 'Kelompok tidak dapat dihapus karena sudah dipakai.']);
                exit();
            }
            $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->delete();
        } elseif ($jenis === 'JENIS') {
            $kodeKategori = $_POST['kode_kategori'] ?? '';
            $kodeKelompok = $_POST['kode_kelompok'] ?? '';
            $kodeJenis = $_POST['kode_jenis'] ?? '';
            $used = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->where('kode_jenis', $kodeJenis)->count();
            if ($used > 0) {
                echo json_encode(['status' => 'error', 'message' => 'Jenis barang tidak dapat dihapus karena sudah dipakai barang inventaris.']);
                exit();
            }
            $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->where('kode_kategori', $kodeKategori)->where('kode_kelompok', $kodeKelompok)->where('kode_jenis', $kodeJenis)->delete();
        } else {
            $row = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('id', (int) ($_POST['id'] ?? 0))->oneArray();
            if (!$row) {
                echo json_encode(['status' => 'error', 'message' => 'Data tidak ditemukan.']);
                exit();
            }
            $used = $row['jenis_master'] === 'UNIT'
              ? $this->db('rsns_custom_logistik_non_medis_aset')->where('kode_unit', $row['kode'])->count()
              : $this->db('rsns_custom_logistik_non_medis_aset')->where('kode_item', $row['kode'])->count();
            if ($used > 0) {
                echo json_encode(['status' => 'error', 'message' => 'Tidak dapat dihapus karena sudah dipakai oleh ' . $used . ' aset.']);
                exit();
            }
            $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('id', $row['id'])->delete();
        }
        echo json_encode(['status' => 'success', 'message' => 'Data master dihapus.']);
        exit();
    }

    public function getExportMasterInventarisXlsx()
    {
        $this->_initAset();
        $tab = strtolower(trim($_GET['tab'] ?? ''));
        if (!in_array($tab, ['unit', 'kategori', 'kelompok', 'jenis', 'barang'], true)) {
            http_response_code(400);
            echo 'Parameter tab tidak valid.';
            exit();
        }
        if (!class_exists('ZipArchive')) {
            http_response_code(500);
            echo 'Ekstensi ZIP PHP diperlukan untuk membuat file XLSX.';
            exit();
        }
        $kategori_map = [];
        $kelompok_map = [];
        if (in_array($tab, ['kelompok', 'jenis', 'barang'], true)) {
            foreach ($this->db('rsns_custom_logistik_non_medis_inventaris_kategori')->toArray() as $r) {
                $kategori_map[$r['kode_kategori']] = $r['nama_kategori'];
            }
        }
        if (in_array($tab, ['jenis', 'barang'], true)) {
            foreach ($this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->asc('kode_kategori')->asc('kode_kelompok')->toArray() as $r) {
                $kelompok_map[$r['kode_kategori'] . '|' . $r['kode_kelompok']] = $r['nama_kelompok'];
            }
        }
        $headers = [];
        $data_rows = [];
        $sheet_name = 'Data';
        $title = '';
        switch ($tab) {
            case 'unit':
                $sheet_name = 'Master Unit';
                $title = 'MASTER UNIT INVENTARIS';
                $headers = ['No', 'Kode Unit', 'Nama Unit'];
                foreach ($this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('jenis_master', 'UNIT')->desc('kode')->toArray() as $i => $r) {
                    $data_rows[] = [$i + 1, $r['kode_inventaris'] ?? '', $r['nama'] ?? ''];
                }
                break;
            case 'kategori':
                $sheet_name = 'Master Kategori';
                $title = 'MASTER KATEGORI INVENTARIS';
                $headers = ['No', 'Kode Kategori', 'Nama Kategori'];
                foreach ($this->db('rsns_custom_logistik_non_medis_inventaris_kategori')->asc('kode_kategori')->toArray() as $i => $r) {
                    $data_rows[] = [$i + 1, $r['kode_kategori'], $r['nama_kategori']];
                }
                break;
            case 'kelompok':
                $sheet_name = 'Master Kelompok';
                $title = 'MASTER KELOMPOK INVENTARIS';
                $headers = ['No', 'Kategori', 'Kode Kelompok', 'Nama Kelompok'];
                foreach ($this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->asc('kode_kategori')->asc('kode_kelompok')->toArray() as $i => $r) {
                    $data_rows[] = [$i + 1, $kategori_map[$r['kode_kategori']] ?? ('Kategori ' . $r['kode_kategori']), $r['kode_kelompok'], $r['nama_kelompok']];
                }
                break;
            case 'jenis':
                $sheet_name = 'Master Jenis';
                $title = 'MASTER JENIS BARANG INVENTARIS';
                $headers = ['No', 'Kategori', 'Kelompok', 'Kode Jenis', 'Nama Jenis'];
                foreach ($this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->asc('kode_kategori')->asc('kode_kelompok')->asc('kode_jenis')->toArray() as $i => $r) {
                    $data_rows[] = [$i + 1, $kategori_map[$r['kode_kategori']] ?? ('Kategori ' . $r['kode_kategori']), $kelompok_map[$r['kode_kategori'] . '|' . $r['kode_kelompok']] ?? ('Kelompok ' . $r['kode_kelompok']), $r['kode_jenis'], $r['nama_jenis']];
                }
                break;
            case 'barang':
                $sheet_name = 'Master Barang';
                $title = 'MASTER DATA BARANG INVENTARIS';
                $headers = ['No', 'Kategori', 'Kelompok', 'Jenis', 'Kode Barang', 'Nama Barang', 'KIB', 'Harga Referensi Utama / Unit', 'Tahun Referensi', 'Sumber Referensi'];
                foreach ($this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('jenis_master', 'BARANG')->asc('kode_kategori')->asc('kode_kelompok')->asc('kode_jenis')->asc('kode_barang')->toArray() as $i => $r) {
                    $data_rows[] = [$i + 1, $kategori_map[$r['kode_kategori'] ?? ''] ?? ('Kategori ' . ($r['kode_kategori'] ?? '')), $r['nama_kelompok'] ?: ('Kelompok ' . $r['kode_kelompok']), $r['nama_jenis'] ?: ('Jenis ' . $r['kode_jenis']), $r['kode'] ?? '', $r['nama'] ?? '', $r['kib_jenis'] ?? '', (float) ($r['harga_referensi'] ?? 0), $r['tahun_harga_referensi'] ?? '', $r['sumber_harga_referensi'] ?? ''];
                }
                break;
        }
        $col_count = count($headers);
        $last_col_name = $this->_xlsxColumnName($col_count);
        $xml_rows = [];
        $xml_rows[] = '<row r="1" ht="24"><c r="A1" s="1" t="inlineStr"><is><t>' . $this->_xlsxEscape($title) . '</t></is></c></row>';
        $xml_rows[] = '<row r="2" ht="20"><c r="A2" s="2" t="inlineStr"><is><t>' . $this->_xlsxEscape('Total: ' . count($data_rows) . ' data | Diekspor: ' . date('d-m-Y H:i')) . '</t></is></c></row>';
        $xml_rows[] = '<row r="3"></row>';
        $hc = '';
        foreach ($headers as $hi => $hv) {
            $hc .= '<c r="' . $this->_xlsxColumnName($hi + 1) . '4" s="3" t="inlineStr"><is><t>' . $this->_xlsxEscape($hv) . '</t></is></c>';
        }
        $xml_rows[] = '<row r="4" ht="28">' . $hc . '</row>';
        foreach ($data_rows as $di => $dv) {
            $rn = $di + 5;
            $dc = '';
            foreach ($dv as $ci => $cv) {
                $cr = $this->_xlsxColumnName($ci + 1) . $rn;
                if ($ci === 0 && is_numeric($cv)) {
                    $dc .= '<c r="' . $cr . '" s="4"><v>' . (0 + $cv) . '</v></c>';
                } elseif ($cv === null || $cv === '') {
                    $dc .= '<c r="' . $cr . '" s="4"/>';
                } else {
                    $dc .= '<c r="' . $cr . '" s="4" t="inlineStr"><is><t xml:space="preserve">' . $this->_xlsxEscape($cv) . '</t></is></c>';
                }
            }
            $xml_rows[] = '<row r="' . $rn . '">' . $dc . '</row>';
        }
        $lr = count($data_rows) + 4;
        $cw = '';
        if ($tab === 'unit' || $tab === 'kategori') {
            $cw = '<col min="1" max="1" width="6" customWidth="1"/><col min="2" max="2" width="16" customWidth="1"/><col min="3" max="3" width="40" customWidth="1"/>';
        } elseif ($tab === 'kelompok') {
            $cw = '<col min="1" max="1" width="6" customWidth="1"/><col min="2" max="2" width="22" customWidth="1"/><col min="3" max="3" width="16" customWidth="1"/><col min="4" max="4" width="35" customWidth="1"/>';
        } elseif ($tab === 'jenis') {
            $cw = '<col min="1" max="1" width="6" customWidth="1"/><col min="2" max="2" width="22" customWidth="1"/><col min="3" max="3" width="28" customWidth="1"/><col min="4" max="4" width="14" customWidth="1"/><col min="5" max="5" width="32" customWidth="1"/>';
        } elseif ($tab === 'barang') {
            $cw = '<col min="1" max="1" width="6" customWidth="1"/><col min="2" max="2" width="18" customWidth="1"/><col min="3" max="3" width="28" customWidth="1"/><col min="4" max="4" width="28" customWidth="1"/><col min="5" max="5" width="16" customWidth="1"/><col min="6" max="6" width="35" customWidth="1"/><col min="7" max="7" width="10" customWidth="1"/><col min="8" max="8" width="22" customWidth="1"/><col min="9" max="9" width="16" customWidth="1"/><col min="10" max="10" width="55" customWidth="1"/>';
        }
        $ws_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="4" topLeftCell="A5" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>' . $cw . '</cols><sheetData>' . implode('', $xml_rows) . '</sheetData><autoFilter ref="A4:' . $last_col_name . max(4, $lr) . '"/><mergeCells count="2"><mergeCell ref="A1:' . $last_col_name . '1"/><mergeCell ref="A2:' . $last_col_name . '2"/></mergeCells></worksheet>';
        $st_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF337AB7"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="2"><border/><border><left style="thin"><color rgb="FFD9D9D9"/></left><right style="thin"><color rgb="FFD9D9D9"/></right><top style="thin"><color rgb="FFD9D9D9"/></top><bottom style="thin"><color rgb="FFD9D9D9"/></bottom></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="5"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>';
        $tf = tempnam(sys_get_temp_dir(), 'mi_xlsx_');
        $zip = new \ZipArchive();
        if (!$tf || $zip->open($tf, \ZipArchive::CREATE | \ZipArchive::OVERWRITE) !== true) {
            http_response_code(500);
            echo 'File XLSX tidak dapat dibuat.';
            exit();
        }
        $sn = $this->_xlsxEscape($sheet_name);
        $zip->addFromString('[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/></Types>');
        $zip->addFromString('_rels/.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>');
        $zip->addFromString('xl/workbook.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="' . $sn . '" sheetId="1" r:id="rId1"/></sheets></workbook>');
        $zip->addFromString('xl/_rels/workbook.xml.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
        $zip->addFromString('xl/worksheets/sheet1.xml', $ws_xml);
        $zip->addFromString('xl/styles.xml', $st_xml);
        $zip->addFromString('docProps/core.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>' . $sn . '</dc:title><dc:creator>mLITE RSU Nurusyifa</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">' . gmdate('Y-m-d\TH:i:s\Z') . '</dcterms:created></cp:coreProperties>');
        $zip->close();
        while (ob_get_level() > 0) {
            ob_end_clean();
        }
        $fn = str_replace(' ', '_', $sheet_name) . '_' . date('Ymd_His') . '.xlsx';
        header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        header('Content-Disposition: attachment; filename="' . $fn . '"');
        header('Content-Length: ' . filesize($tf));
        header('Cache-Control: max-age=0, must-revalidate');
        readfile($tf);
        unlink($tf);
        exit();
    }

    private function _generateNomorInventaris(string $kode_unit, string $kode_item, string $kode_kategori = '2')
    {
        $unit = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('jenis_master', 'UNIT')->where('kode', $kode_unit)->where('status', 'Aktif')->oneArray();
        $barang = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('jenis_master', 'BARANG')->where('kode_kategori', $kode_kategori)->where('kode', $kode_item)->where('status', 'Aktif')->oneArray();
        if (!$unit || !$barang) {
            throw new \RuntimeException('Unit atau barang belum disiapkan pada Master Inventaris.');
        }

        $unitCode = preg_replace('/\D/', '', (string)$unit['kode_inventaris']);
        if (!preg_match('/^\d{2,3}$/', $unitCode)) {
            throw new \RuntimeException('Kode inventaris unit harus terdiri dari 2 atau 3 digit.');
        }
        $kelompok = str_pad(preg_replace('/\D/', '', $barang['kode_kelompok']), 2, '0', STR_PAD_LEFT);
        $jenis = str_pad(preg_replace('/\D/', '', $barang['kode_jenis']), 2, '0', STR_PAD_LEFT);
        $item = str_pad(preg_replace('/\D/', '', $barang['kode_barang']), 2, '0', STR_PAD_LEFT);
        $prefix = $unitCode . ($barang['kode_kategori'] ?: '2') . $kelompok . $jenis . $item;

        $stmt = $this->db()->pdo()->prepare("SELECT MAX(CAST(RIGHT(nomor_inventaris, 3) AS UNSIGNED)) FROM rsns_custom_logistik_non_medis_aset WHERE nomor_inventaris LIKE ?");
        $stmt->execute([$prefix . '%']);
        $last = (int) $stmt->fetchColumn();
        if ($last >= 999) {
            throw new \RuntimeException('Nomor urut inventaris untuk kombinasi ini sudah mencapai batas 999.');
        }
        return $prefix . str_pad((string) ($last + 1), 3, '0', STR_PAD_LEFT);
    }

    public function getAsetRegistrasi()
    {
        $this->_initAset();
        $this->_addHeaderFiles();
        $units = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('jenis_master', 'UNIT')->where('status', 'Aktif')->toArray();
        $kelompok = $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->asc('kode_kategori')->asc('kode_kelompok')->toArray();
        $jenis = $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->asc('kode_kategori')->asc('kode_kelompok')->asc('kode_jenis')->toArray();

        $total = $this->db('rsns_custom_logistik_non_medis_aset')->where('status', 'Aktif')->count();
        $baik = $this->db('rsns_custom_logistik_non_medis_aset')->where('status', 'Aktif')->where('status_kondisi', 'Baik')->count();
        $perhatian = $this->db('rsns_custom_logistik_non_medis_aset')->where('status', 'Aktif')->where('status_kondisi', '!=', 'Baik')->count();
        $berlabel = $total;

        $ringkasan = [
          'total' => $total,
          'baik' => $baik,
          'perlu_perhatian' => $perhatian,
          'berlabel' => $berlabel
        ];

        return $this->draw('aset.registrasi.html', [
          'units' => $units,
          'kelompok' => $kelompok,
          'jenis' => $jenis,
          'ringkasan' => $ringkasan
        ]);
    }

    public function getExportAset()
    {
        $this->_initAset();
        $cari = trim((string)($_GET['cari'] ?? ''));
        $filter_unit = trim((string)($_GET['filter_unit'] ?? ''));
        $filter_sumber = trim((string)($_GET['filter_sumber'] ?? ''));
        $filter_kondisi = trim((string)($_GET['filter_kondisi'] ?? ''));
        $filter_kelompok = trim((string)($_GET['filter_kelompok'] ?? ''));
        $filter_jenis = trim((string)($_GET['filter_jenis'] ?? ''));
        $where = ["a.status = 'Aktif'"];
        $params = [];
        if ($cari !== '') {
            $where[] = '(a.kode_aset LIKE ? OR a.nomor_inventaris LIKE ? OR a.nama_aset LIKE ? OR a.serial_number LIKE ? OR im.nama LIKE ?)';
            $like = '%' . $cari . '%';
            $params = [$like, $like, $like, $like, $like];
        }
        if ($filter_unit !== '') {
            $where[] = 'a.kode_unit = ?';
            $params[] = $filter_unit;
        }
        if ($filter_sumber !== '') {
            $where[] = 'a.sumber_perolehan = ?';
            $params[] = $filter_sumber;
        }
        if ($filter_kondisi !== '') {
            $where[] = 'a.status_kondisi = ?';
            $params[] = $filter_kondisi;
        }
        if ($filter_kelompok !== '') {
            $kelompokParts = explode('|', $filter_kelompok);
            if (count($kelompokParts) === 2) {
                $where[] = 'im.kode_kategori = ? AND im.kode_kelompok = ?';
                $params[] = $kelompokParts[0];
                $params[] = $kelompokParts[1];
            } else {
                $where[] = 'im.kode_kelompok = ?';
                $params[] = $filter_kelompok;
            }
        }
        if ($filter_jenis !== '') {
            $jenisParts = explode('|', $filter_jenis);
            if (count($jenisParts) === 3) {
                $where[] = 'im.kode_kategori = ? AND im.kode_kelompok = ? AND im.kode_jenis = ?';
                $params[] = $jenisParts[0];
                $params[] = $jenisParts[1];
                $params[] = $jenisParts[2];
            } else {
                $where[] = 'im.kode_jenis = ?';
                $params[] = $filter_jenis;
            }
        }
        $sql = "SELECT COALESCE(a.asset_group_id,-a.id) group_key,
                     MIN(a.nomor_inventaris) nomor_awal, MAX(a.nomor_inventaris) nomor_akhir,
                     MAX(COALESCE(im.nama,a.nama_aset)) nama_barang, MAX(a.merk_type) merk_type,
                     MAX(a.satuan) satuan, COUNT(DISTINCT a.id) jumlah_aset,
                     SUM(a.status_kondisi='Baik') jumlah_baik,
                     SUM(a.status_kondisi='Rusak Ringan') jumlah_rusak_ringan,
                     SUM(a.status_kondisi='Rusak Berat') jumlah_rusak_berat,
                     MAX(COALESCE(NULLIF(a.tahun_beli,0),CASE WHEN a.tanggal_perolehan>='1900-01-01' THEN YEAR(a.tanggal_perolehan) END)) tahun_beli,
                     MAX(a.sumber_perolehan) sumber_perolehan,
                     MAX(COALESCE(iu.nama,a.kode_unit,'-')) nama_unit,
                     MAX(COALESCE(NULLIF(a.harga_beli,0),NULLIF(a.harga_referensi_import,0),NULLIF(im.harga_referensi,0),0)) harga_unit,
                     SUM(COALESCE(NULLIF(a.harga_beli,0),NULLIF(a.harga_referensi_import,0),NULLIF(im.harga_referensi,0),0)) total_harga
              FROM rsns_custom_logistik_non_medis_aset a
              LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master iu
                ON iu.jenis_master='UNIT' AND iu.kode_kategori='' AND iu.kode=a.kode_unit
              LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im
                ON im.jenis_master='BARANG' AND im.kode_kategori=COALESCE(NULLIF(a.kode_kategori_aset,''),'2') AND im.kode=a.kode_item
              WHERE " . implode(' AND ', $where) . "
              GROUP BY COALESCE(a.asset_group_id,-a.id)
              ORDER BY nama_unit ASC, nama_barang ASC, nomor_awal ASC";
        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        $labels = [];
        if ($cari !== '') $labels[] = 'Pencarian: ' . $cari;
        if ($filter_unit !== '') $labels[] = 'Unit: ' . $filter_unit;
        if ($filter_sumber !== '') $labels[] = 'Asal: ' . $filter_sumber;
        if ($filter_kondisi !== '') $labels[] = 'Kondisi: ' . $filter_kondisi;
        if ($filter_kelompok !== '') $labels[] = 'Kelompok: ' . $filter_kelompok;
        if ($filter_jenis !== '') $labels[] = 'Jenis: ' . $filter_jenis;
        $this->_outputAsetKibXlsx($rows, $labels ? implode(' | ', $labels) : 'Semua aset aktif');
    }

    public function anyDisplayAsetRegistrasi()
    {
        $this->_initAset();
        $perpage = 10;
        $halaman = isset($_POST['halaman']) ? (int)$_POST['halaman'] : 1;
        if ($halaman < 1) {
            $halaman = 1;
        }
        $cari = isset($_POST['cari']) ? trim($_POST['cari']) : '';
        $filter_unit = isset($_POST['filter_unit']) ? trim($_POST['filter_unit']) : '';
        $filter_sumber = isset($_POST['filter_sumber']) ? trim($_POST['filter_sumber']) : '';
        $filter_kondisi = isset($_POST['filter_kondisi']) ? trim($_POST['filter_kondisi']) : '';
        $filter_kelompok = isset($_POST['filter_kelompok']) ? trim($_POST['filter_kelompok']) : '';
        $filter_jenis = isset($_POST['filter_jenis']) ? trim($_POST['filter_jenis']) : '';

        $_offset = ($halaman - 1) * $perpage;

        $where = ["a.status = 'Aktif'"];
        $params = [];

        if (!empty($cari)) {
            $where[] = "(a.kode_aset LIKE ? OR a.nomor_inventaris LIKE ? OR a.nama_aset LIKE ? OR a.serial_number LIKE ? OR EXISTS (
              SELECT 1 FROM rsns_custom_logistik_non_medis_aset ax
              WHERE ax.asset_group_id=a.asset_group_id AND ax.status='Aktif'
                AND (ax.kode_aset LIKE ? OR ax.nomor_inventaris LIKE ?)
            ))";
            for ($i = 0; $i < 6; $i++) {
                $params[] = '%' . $cari . '%';
            }
        }
        if (!empty($filter_unit)) {
            $where[] = "a.kode_unit = ?";
            $params[] = $filter_unit;
        }
        if (!empty($filter_sumber)) {
            $where[] = "a.sumber_perolehan = ?";
            $params[] = $filter_sumber;
        }
        if (!empty($filter_kondisi)) {
            $where[] = "EXISTS (SELECT 1 FROM rsns_custom_logistik_non_medis_aset ak
              WHERE ak.status='Aktif' AND ak.status_kondisi=?
                AND COALESCE(ak.asset_group_id,-ak.id)=COALESCE(a.asset_group_id,-a.id))";
            $params[] = $filter_kondisi;
        }
        if ($filter_kelompok !== '') {
            $kelompokParts = explode('|', $filter_kelompok);
            if (count($kelompokParts) === 2) {
                $where[] = 'im.kode_kategori = ? AND im.kode_kelompok = ?';
                $params[] = $kelompokParts[0];
                $params[] = $kelompokParts[1];
            } else {
                $where[] = 'im.kode_kelompok = ?';
                $params[] = $filter_kelompok;
            }
        }
        if ($filter_jenis !== '') {
            $jenisParts = explode('|', $filter_jenis);
            if (count($jenisParts) === 3) {
                $where[] = 'im.kode_kategori = ? AND im.kode_kelompok = ? AND im.kode_jenis = ?';
                $params[] = $jenisParts[0];
                $params[] = $jenisParts[1];
                $params[] = $jenisParts[2];
            } else {
                $where[] = 'im.kode_jenis = ?';
                $params[] = $filter_jenis;
            }
        }

        $where_sql = implode(' AND ', $where);
        $from_sql = "
          FROM rsns_custom_logistik_non_medis_aset a
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master iu
            ON iu.jenis_master = 'UNIT' AND iu.kode_kategori = '' AND iu.kode = a.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im
            ON im.jenis_master = 'BARANG'
           AND im.kode_kategori = COALESCE(NULLIF(a.kode_kategori_aset, ''), '2')
           AND im.kode = a.kode_item
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_kelompok ik
            ON ik.kode_kategori = im.kode_kategori AND ik.kode_kelompok = im.kode_kelompok
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_jenis ij
            ON ij.kode_kategori = im.kode_kategori AND ij.kode_kelompok = im.kode_kelompok AND ij.kode_jenis = im.kode_jenis
          WHERE {$where_sql}
      ";

        $stmt_asset_count = $this->db()->pdo()->prepare("SELECT COUNT(DISTINCT a.id) {$from_sql}");
        $stmt_asset_count->execute($params);
        $jumlah_aset = (int) $stmt_asset_count->fetchColumn();

        $stmt_count = $this->db()->pdo()->prepare("SELECT COUNT(DISTINCT COALESCE(a.asset_group_id, -a.id)) {$from_sql}");
        $stmt_count->execute($params);
        $jumlah_data = (int) $stmt_count->fetchColumn();
        $jml_halaman = $jumlah_data > 0 ? ceil($jumlah_data / $perpage) : 1;

        $stmt_rows = $this->db()->pdo()->prepare("
          SELECT COALESCE(a.asset_group_id, -a.id) AS group_key,
                 MAX(a.asset_group_id) AS asset_group_id,
                 MIN(a.id) AS id,
                 MAX(a.kode_item) AS kode_item,
                 MAX(a.nama_aset) AS nama_aset,
                 MAX(a.merk_type) AS merk_type,
                 MAX(a.kode_unit) AS kode_unit,
                 MAX(COALESCE(iu.nama, a.kode_unit)) AS nama_unit,
                 MAX(a.lokasi_fisik) AS lokasi_fisik,
                 MAX(a.sumber_perolehan) AS sumber_perolehan,
                 MAX(a.tahun_beli) AS tahun_beli,
                 MAX(a.tahun_beli_referensi) AS tahun_beli_referensi,
                 MAX(a.tanggal_perolehan) AS tanggal_perolehan,
                 MAX(a.satuan) AS satuan,
                 COUNT(DISTINCT a.id) AS jumlah_aset,
                 MIN(a.nomor_inventaris) AS nomor_awal,
                 MAX(a.nomor_inventaris) AS nomor_akhir,
                 SUM(CASE WHEN a.status_kondisi='Baik' THEN 1 ELSE 0 END) AS jumlah_baik,
                 SUM(CASE WHEN a.status_kondisi='Rusak Ringan' THEN 1 ELSE 0 END) AS jumlah_rusak_ringan,
                 SUM(CASE WHEN a.status_kondisi='Rusak Berat' THEN 1 ELSE 0 END) AS jumlah_rusak_berat,
                 MAX(COALESCE(im.nama, a.nama_aset)) AS nama_item_master,
                 MAX(COALESCE(im.nama_kelompok, ik.nama_kelompok)) AS nama_kelompok,
                 MAX(COALESCE(im.nama_jenis, ij.nama_jenis)) AS nama_jenis,
                 MAX(COALESCE(NULLIF(a.harga_beli, 0), NULLIF(a.harga_referensi_import, 0), NULLIF(im.harga_referensi, 0), 0)) AS harga_tampil,
                 CASE
                   WHEN MAX(COALESCE(a.harga_beli, 0)) > 0 THEN 'Harga Perolehan'
                   WHEN MAX(COALESCE(a.harga_referensi_import, 0)) > 0 THEN 'Referensi Import'
                   WHEN MAX(COALESCE(im.harga_referensi, 0)) > 0 THEN 'Harga Referensi'
                   ELSE 'Belum Tersedia'
                 END AS sumber_harga_tampil
          {$from_sql}
          GROUP BY COALESCE(a.asset_group_id, -a.id)
          ORDER BY MAX(a.id) DESC
          LIMIT {$perpage} OFFSET {$_offset}
      ");
        $stmt_rows->execute($params);
        $rows = $stmt_rows->fetchAll(\PDO::FETCH_ASSOC);

        $nomor_tabel = $_offset;
        foreach ($rows as &$row) {
            $row['nomor_tabel'] = ++$nomor_tabel;
            $row['nama_kelompok'] = $row['nama_kelompok'] ?? '-';
            $row['nama_jenis'] = $row['nama_jenis'] ?? '-';
            $row['satuan_dasar'] = '';
            $row['total_harga_tampil'] = (double)$row['harga_tampil'] * (int)$row['jumlah_aset'];
            $row['range_inventaris'] = $row['nomor_awal'] === $row['nomor_akhir']
              ? $row['nomor_awal']
              : $row['nomor_awal'] . ' – ' . $row['nomor_akhir'];
        }

        $stmt_kelompok = $this->db()->pdo()->prepare("
          SELECT COALESCE(im.nama_kelompok, ik.nama_kelompok, 'Belum Terhubung Master') label, COUNT(DISTINCT a.id) total
          {$from_sql}
          GROUP BY COALESCE(im.nama_kelompok, ik.nama_kelompok, 'Belum Terhubung Master')
          ORDER BY total DESC
          LIMIT 8
      ");
        $stmt_kelompok->execute($params);
        $chart_kelompok = $stmt_kelompok->fetchAll(\PDO::FETCH_ASSOC);

        $stmt_tahun = $this->db()->pdo()->prepare("
          SELECT CASE
                   WHEN a.tahun_beli BETWEEN 1900 AND 2100 THEN CAST(a.tahun_beli AS CHAR)
                   WHEN a.tanggal_perolehan BETWEEN '1900-01-01' AND '2100-12-31' THEN CAST(YEAR(a.tanggal_perolehan) AS CHAR)
                   ELSE 'Belum Diisi'
                 END label,
                 COUNT(DISTINCT a.id) total
          {$from_sql}
          GROUP BY label
          ORDER BY (label = 'Belum Diisi'), CAST(label AS UNSIGNED) DESC
      ");
        $stmt_tahun->execute($params);
        $chart_tahun = $stmt_tahun->fetchAll(\PDO::FETCH_ASSOC);

        $stmt_unit = $this->db()->pdo()->prepare("
          SELECT COALESCE(iu.nama, a.kode_unit, 'Tanpa Unit') label, COUNT(DISTINCT a.id) total
          {$from_sql}
          GROUP BY COALESCE(iu.nama, a.kode_unit, 'Tanpa Unit')
          ORDER BY total DESC
          LIMIT 8
      ");
        $stmt_unit->execute($params);
        $chart_unit = $stmt_unit->fetchAll(\PDO::FETCH_ASSOC);

        $stmt_kondisi = $this->db()->pdo()->prepare("
          SELECT
            COUNT(DISTINCT CASE WHEN a.status_kondisi = 'Baik' THEN a.id END) AS baik,
            COUNT(DISTINCT CASE WHEN a.status_kondisi = 'Rusak Ringan' THEN a.id END) AS rusak_ringan,
            COUNT(DISTINCT CASE WHEN a.status_kondisi = 'Rusak Berat' THEN a.id END) AS rusak_berat
          {$from_sql}
      ");
        $stmt_kondisi->execute($params);
        $chart_kondisi = $stmt_kondisi->fetch(\PDO::FETCH_ASSOC) ?: [];
        $chart_kondisi_data = [
          (int)($chart_kondisi['baik'] ?? 0),
          (int)($chart_kondisi['rusak_ringan'] ?? 0),
          (int)($chart_kondisi['rusak_berat'] ?? 0)
        ];

        $stmt_total = $this->db()->pdo()->prepare("
          SELECT SUM(COALESCE(NULLIF(a.jumlah, 0), 1) * COALESCE(NULLIF(a.harga_beli, 0), NULLIF(a.harga_referensi_import, 0), NULLIF(im.harga_referensi, 0), 0)) AS total_nilai,
                 SUM(CASE WHEN COALESCE(a.harga_beli, 0) <= 0 AND COALESCE(a.harga_referensi_import, 0) <= 0 AND COALESCE(im.harga_referensi, 0) <= 0 THEN 1 ELSE 0 END) AS harga_kosong,
                 SUM(CASE WHEN COALESCE(a.harga_beli, 0) <= 0 AND (COALESCE(a.harga_referensi_import, 0) > 0 OR COALESCE(im.harga_referensi, 0) > 0) THEN 1 ELSE 0 END) AS harga_referensi_dipakai
          {$from_sql}
      ");
        $stmt_total->execute($params);
        $total_res = $stmt_total->fetch(\PDO::FETCH_ASSOC);
        $total_nilai = (double)($total_res['total_nilai'] ?? 0);
        $harga_kosong = (int)($total_res['harga_kosong'] ?? 0);
        $harga_referensi_dipakai = (int)($total_res['harga_referensi_dipakai'] ?? 0);

        $html_stats = $this->draw('aset.registrasi.stats.html', [
          'jumlah_data' => $jumlah_aset,
          'total_nilai' => $total_nilai,
          'harga_kosong' => $harga_kosong,
          'harga_referensi_dipakai' => $harga_referensi_dipakai,
          'chart_kondisi_data' => json_encode($chart_kondisi_data),
          'chart_kelompok_labels' => json_encode(array_column($chart_kelompok, 'label')),
          'chart_kelompok_data' => json_encode(array_map('intval', array_column($chart_kelompok, 'total'))),
          'chart_tahun_labels' => json_encode(array_column($chart_tahun, 'label')),
          'chart_tahun_data' => json_encode(array_map('intval', array_column($chart_tahun, 'total'))),
          'chart_unit_labels' => json_encode(array_column($chart_unit, 'label')),
          'chart_unit_data' => json_encode(array_map('intval', array_column($chart_unit, 'total')))
        ]);

        $html = $this->draw('aset.registrasi.display.html', [
          'aset' => $rows,
          'halaman' => $halaman,
          'jumlah_data' => $jumlah_data,
          'jml_halaman' => $jml_halaman
        ]);
        echo json_encode([
          'html' => $html,
          'html_stats' => $html_stats,
          'jumlah' => $jumlah_data,
          'halaman' => $halaman,
          'jml_halaman' => $jml_halaman
        ]);
        exit();
    }

    public function anyFormAsetRegistrasi()
    {
        $data = $this->_getAsetRegistrasiFormData($_POST['id'] ?? '');
        $data['standalone'] = false;
        $data['return_url'] = url([ADMIN, 'logistik_non_medis', 'asetregistrasi']);
        echo $this->draw('aset.registrasi.form.html', $data);
        exit();
    }

    private function _getAsetRegistrasiFormData($id = '')
    {
        $this->_initAset();
        $master_barang = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('jenis_master', 'BARANG')->where('status', 'Aktif')->toArray();
        $units = $this->db('rsns_custom_logistik_non_medis_inventaris_master')->where('jenis_master', 'UNIT')->where('status', 'Aktif')->toArray();
        $kategori_master = $this->db('rsns_custom_logistik_non_medis_inventaris_kategori')->asc('kode_kategori')->toArray();
        $kelompok_master = $this->db('rsns_custom_logistik_non_medis_inventaris_kelompok')->asc('kode_kategori')->asc('kode_kelompok')->toArray();
        $jenis_master = $this->db('rsns_custom_logistik_non_medis_inventaris_jenis')->asc('kode_kategori')->asc('kode_kelompok')->asc('kode_jenis')->toArray();

        if (!empty($id)) {
            $aset = $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->oneArray();
            $aset = array_merge([
              'nomor_inventaris' => '', 'nomor_dokumen' => '', 'merk_type' => '',
              'lokasi_fisik' => '', 'bahan' => '', 'tahun_beli' => '',
              'satuan' => 'Buah', 'jumlah' => 1, 'keterangan_inventaris' => ''
            ], $aset ?: []);
            $master_terpilih = $this->db('rsns_custom_logistik_non_medis_inventaris_master')
              ->where('jenis_master', 'BARANG')
              ->where('status', 'Aktif')
              ->where('kode_kategori', $aset['kode_kategori_aset'] ?: '2')
              ->where('kode', $aset['kode_item'])
              ->oneArray();
            $aset['master_kategori'] = $master_terpilih['kode_kategori'] ?? ($aset['kode_kategori_aset'] ?: '2');
            $aset['master_kelompok'] = $master_terpilih['kode_kelompok'] ?? '';
            $aset['master_jenis'] = $master_terpilih['kode_jenis'] ?? '';
            return [
              'aset' => $aset,
              'mode' => 'edit',
              'master_barang' => $master_barang,
              'units' => $units,
              'kategori_master' => $kategori_master,
              'kelompok_master' => $kelompok_master,
              'jenis_master' => $jenis_master,
              'kategori_aset' => []
            ];
        }

        $aset = [
              'id' => '',
              'kode_aset' => '',
              'nomor_inventaris' => '',
              'kode_kategori_aset' => '',
              'master_kategori' => '',
              'master_kelompok' => '',
              'master_jenis' => '',
              'serial_number' => '',
              'nomor_dokumen' => '',
              'kode_item' => '',
              'nama_aset' => '',
              'merk_type' => '',
              'spesifikasi' => '',
              'foto_depan' => '',
              'foto_detail' => '',
              'tanggal_perolehan' => '',
              'harga_beli' => 0,
              'sumber_perolehan' => 'Beli',
              'kode_unit' => '',
              'lokasi_fisik' => '',
              'bahan' => '',
              'tahun_beli' => date('Y'),
              'satuan' => 'Buah',
              'jumlah' => 1,
              'pic' => '',
              'status_kondisi' => 'Baik',
              'keterangan_inventaris' => ''
        ];
        return [
              'aset' => $aset,
              'mode' => 'add',
              'master_barang' => $master_barang,
              'units' => $units,
              'kategori_master' => $kategori_master,
              'kelompok_master' => $kelompok_master,
              'jenis_master' => $jenis_master,
              'kategori_aset' => []
        ];
    }

    public function getAsetFormPage()
    {
        $this->_addHeaderFiles();
        $id = (int)($_GET['id'] ?? 0);
        $from = (($_GET['from'] ?? '') === 'kib') ? 'kib' : 'registrasi';
        $groupId = max(0, (int)($_GET['group_id'] ?? 0));
        $data = $this->_getAsetRegistrasiFormData($id);
        $data['standalone'] = true;
        $data['from'] = $from;
        $data['group_id'] = $groupId;
        if ($from === 'kib') {
            $data['return_url'] = url([ADMIN, 'logistik_non_medis', 'asetkib']);
        } elseif ($groupId > 0) {
            $data['return_url'] = url([ADMIN, 'logistik_non_medis', 'asetgrouppage']) . '&group_id=' . $groupId;
        } else {
            $data['return_url'] = url([ADMIN, 'logistik_non_medis', 'asetregistrasi']);
        }
        return $this->draw('aset.registrasi.form.html', $data);
    }

    public function anyGenerateKodeAset()
    {
        $kode_unit = $_POST['kode_unit'] ?? '';
        if (empty($kode_unit)) {
            echo json_encode(['status' => 'error', 'message' => 'Unit wajib dipilih!']);
            exit();
        }
        $kode_aset = $this->_generateKodeAset($kode_unit);
        echo json_encode(['status' => 'success', 'kode_aset' => $kode_aset]);
        exit();
    }

    public function anyGenerateNomorInventaris()
    {
        $this->_initAset();
        try {
            $kode_unit = $_POST['kode_unit'] ?? '';
            $kode_item = $_POST['kode_item'] ?? '';
            $kode_kategori = $_POST['kode_kategori_aset'] ?? '2';
            if (!$kode_unit || !$kode_item) {
                echo json_encode(['status' => 'error', 'message' => 'Unit dan barang inventaris wajib dipilih.']);
                exit();
            }
            $nomor = $this->_generateNomorInventaris($kode_unit, $kode_item, $kode_kategori);
            echo json_encode(['status' => 'success', 'nomor_inventaris' => $nomor, 'kode_aset' => 'AST-' . $nomor]);
        } catch (\Throwable $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
        exit();
    }

    public function postSaveAsetRegistrasi()
    {
        $this->_initAset();
        $id = $_POST['id'] ?? '';
        $kode_unit = $_POST['kode_unit'] ?? '';

        if (empty($kode_unit)) {
            echo json_encode(['status' => 'error', 'message' => 'Unit wajib dipilih!']);
            exit();
        }

        $kode_aset = $_POST['kode_aset'] ?? '';

        $harga_beli = $_POST['harga_beli'] ?? 0;
        $harga_beli = str_replace(['Rp.', '.', ' '], '', $harga_beli);
        $harga_beli = (double) $harga_beli;

        $nilai_residu = $_POST['nilai_residu'] ?? 0;
        $nilai_residu = str_replace(['Rp.', '.', ' '], '', $nilai_residu);
        $nilai_residu = (double) $nilai_residu;

        $masa_manfaat_tahun = isset($_POST['masa_manfaat_tahun']) ? (int)$_POST['masa_manfaat_tahun'] : 0;
        $nomor_inventaris = preg_replace('/[^0-9]/', '', $_POST['nomor_inventaris'] ?? '');
        $jumlah_registrasi = empty($id) ? max(1, (int)($_POST['jumlah'] ?? 1)) : 1;
        $aset_saat_ini = !empty($id) ? $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->oneArray() : null;
        $kode_kategori_aset = trim((string)($_POST['kode_kategori_aset'] ?? '2'));
        $barang_inventaris = $this->db('rsns_custom_logistik_non_medis_inventaris_master')
                                  ->where('jenis_master', 'BARANG')
                                  ->where('kode_kategori', $kode_kategori_aset)
                                  ->where('kode', $_POST['kode_item'] ?? '')
                                  ->where('status', 'Aktif')
                                  ->oneArray();
        if (!$barang_inventaris) {
            echo json_encode(['status' => 'error', 'message' => 'Barang dan kategori tidak cocok dengan Master Inventaris.']);
            exit();
        }
        if (empty($id)) {
            try {
                $nomor_inventaris = $this->_generateNomorInventaris($kode_unit, $_POST['kode_item'] ?? '', $kode_kategori_aset);
                $kode_aset = 'AST-' . $nomor_inventaris;
            } catch (\Throwable $e) {
                echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
                exit();
            }
        }
        if ($nomor_inventaris !== '' && !in_array(strlen($nomor_inventaris), [12, 13], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Nomor inventaris harus terdiri dari 12 digit (atau 13 digit untuk kode unit tiga angka).']);
            exit();
        }
        if ($nomor_inventaris !== '') {
            $nomor_tidak_berubah = $aset_saat_ini && (string)$aset_saat_ini['nomor_inventaris'] === $nomor_inventaris;
            if (!$nomor_tidak_berubah) {
                $cekNomor = $this->db('rsns_custom_logistik_non_medis_aset')->where('nomor_inventaris', $nomor_inventaris);
                if (!empty($id)) {
                    $cekNomor = $cekNomor->where('id', '!=', $id);
                }
                if ($cekNomor->oneArray()) {
                    echo json_encode(['status' => 'error', 'message' => 'Nomor inventaris sudah digunakan oleh aset lain.']);
                    exit();
                }
            }
            if (empty($id) && ((int) substr($nomor_inventaris, -3) + $jumlah_registrasi - 1) > 999) {
                echo json_encode(['status' => 'error', 'message' => 'Jumlah melebihi sisa nomor inventaris untuk kombinasi unit dan barang ini. Maksimal nomor urut adalah 999.']);
                exit();
            }
        }

        $tanggal_perolehan = trim((string)($_POST['tanggal_perolehan'] ?? ''));
        if ($tanggal_perolehan !== '') {
            $tanggal_valid = \DateTime::createFromFormat('Y-m-d', $tanggal_perolehan);
            if (!$tanggal_valid || $tanggal_valid->format('Y-m-d') !== $tanggal_perolehan) {
                echo json_encode(['status' => 'error', 'message' => 'Format tanggal perolehan tidak valid.']);
                exit();
            }
        }

        $data = [
          'serial_number' => $_POST['serial_number'] ?? '',
          'nomor_inventaris' => $nomor_inventaris,
          'nomor_dokumen' => $_POST['nomor_dokumen'] ?? '',
          'kode_item' => $_POST['kode_item'] ?? '',
          'kode_kategori_aset' => $kode_kategori_aset,
          'nama_aset' => $_POST['nama_aset'] ?? '',
          'merk_type' => $_POST['merk_type'] ?? '',
          'spesifikasi' => $_POST['spesifikasi'] ?? '',
          'tanggal_perolehan' => $tanggal_perolehan !== '' ? $tanggal_perolehan : null,
          'tahun_beli' => !empty($_POST['tahun_beli']) ? (int) $_POST['tahun_beli'] : null,
          'harga_beli' => $harga_beli,
          'sumber_perolehan' => $_POST['sumber_perolehan'] ?? 'Beli',
          'kode_unit' => $kode_unit,
          'lokasi_fisik' => $_POST['lokasi_fisik'] ?? '',
          'bahan' => $_POST['bahan'] ?? '',
          'satuan' => $_POST['satuan'] ?? '',
          'jumlah' => 1,
          'pic' => $_POST['pic'] ?? '',
          'status_kondisi' => $_POST['status_kondisi'] ?? 'Baik',
          'keterangan_inventaris' => $_POST['keterangan_inventaris'] ?? '',
          'status' => 'Aktif',
          'nilai_residu' => $nilai_residu,
          'masa_manfaat_tahun' => $masa_manfaat_tahun
        ];

        // Capture and Sanitize KIB Fields
        $kib_jenis = $_POST['kib_jenis'] ?? null;
        if (empty($kib_jenis)) {
            $kib_jenis = null;
        }

        $data['kib_jenis'] = $kib_jenis;

        if ($kib_jenis !== null) {
            if ($kib_jenis == 'A') {
                $data['kib_luas'] = (double) ($_POST['kib_luas_A'] ?? 0);
                $data['kib_hak'] = $_POST['kib_hak'] ?? '';
                $data['kib_no_sertifikat'] = $_POST['kib_no_sertifikat_A'] ?? '';
                $data['kib_tgl_sertifikat'] = !empty($_POST['kib_tgl_sertifikat_A']) ? $_POST['kib_tgl_sertifikat_A'] : null;
                $data['kib_penggunaan'] = $_POST['kib_penggunaan'] ?? '';
                $data['kib_alamat'] = $_POST['kib_alamat_A'] ?? '';
            } elseif ($kib_jenis == 'B') {
                $data['kib_merk'] = $_POST['kib_merk'] ?? '';
                $data['kib_ukuran'] = $_POST['kib_ukuran_B'] ?? '';
                $data['kib_bahan'] = $_POST['kib_bahan_B'] ?? '';
                $data['kib_no_pabrik'] = $_POST['kib_no_pabrik'] ?? '';
                $data['kib_no_rangka'] = $_POST['kib_no_rangka'] ?? '';
                $data['kib_no_mesin'] = $_POST['kib_no_mesin'] ?? '';
                $data['kib_no_polisi'] = $_POST['kib_no_polisi'] ?? '';
                $data['kib_no_bpkb'] = $_POST['kib_no_bpkb'] ?? '';
            } elseif ($kib_jenis == 'C') {
                $data['kib_bertingkat'] = $_POST['kib_bertingkat'] ?? 'Tidak';
                $data['kib_beton'] = $_POST['kib_beton'] ?? 'Tidak';
                $data['kib_luas'] = (double) ($_POST['kib_luas_C'] ?? 0);
                $data['kib_status_tanah'] = $_POST['kib_status_tanah_C'] ?? '';
                $data['kib_no_sertifikat'] = $_POST['kib_no_sertifikat_C'] ?? '';
                $data['kib_tgl_sertifikat'] = !empty($_POST['kib_tgl_sertifikat_C']) ? $_POST['kib_tgl_sertifikat_C'] : null;
                $data['kib_alamat'] = $_POST['kib_alamat_C'] ?? '';
            } elseif ($kib_jenis == 'D') {
                $data['kib_konstruksi'] = $_POST['kib_konstruksi'] ?? '';
                $data['kib_panjang'] = (double) ($_POST['kib_panjang'] ?? 0);
                $data['kib_lebar'] = (double) ($_POST['kib_lebar'] ?? 0);
                $data['kib_luas'] = (double) ($_POST['kib_luas_D'] ?? 0);
                $data['kib_no_sertifikat'] = $_POST['kib_no_sertifikat_D'] ?? '';
                $data['kib_tgl_sertifikat'] = !empty($_POST['kib_tgl_sertifikat_D']) ? $_POST['kib_tgl_sertifikat_D'] : null;
                $data['kib_status_tanah'] = $_POST['kib_status_tanah_D'] ?? '';
                $data['kib_alamat'] = $_POST['kib_alamat_D'] ?? '';
            } elseif ($kib_jenis == 'E') {
                $data['kib_judul'] = $_POST['kib_judul'] ?? '';
                $data['kib_pencipta'] = $_POST['kib_pencipta'] ?? '';
                $data['kib_bahan'] = $_POST['kib_bahan_E'] ?? '';
                $data['kib_ukuran'] = $_POST['kib_ukuran_E'] ?? '';
            } elseif ($kib_jenis == 'F') {
                $data['kib_proyek_bangunan'] = $_POST['kib_proyek_bangunan'] ?? '';
                $data['kib_bertingkat'] = $_POST['kib_bertingkat_F'] ?? 'Tidak';
                $data['kib_beton'] = $_POST['kib_beton_F'] ?? 'Tidak';
                $data['kib_luas'] = (double) ($_POST['kib_luas_F'] ?? 0);
                $data['kib_tgl_mulai'] = !empty($_POST['kib_tgl_mulai']) ? $_POST['kib_tgl_mulai'] : null;
                $data['kib_tgl_rencana_selesai'] = !empty($_POST['kib_tgl_rencana_selesai']) ? $_POST['kib_tgl_rencana_selesai'] : null;
                $data['kib_progress_persen'] = (double) ($_POST['kib_progress_persen'] ?? 0);
                $data['kib_alamat'] = $_POST['kib_alamat_F'] ?? '';
            }
        } else {
            // Clear KIB columns
            $data['kib_luas'] = 0;
            $data['kib_alamat'] = null;
            $data['kib_hak'] = null;
            $data['kib_tgl_sertifikat'] = null;
            $data['kib_no_sertifikat'] = null;
            $data['kib_penggunaan'] = null;
            $data['kib_merk'] = null;
            $data['kib_ukuran'] = null;
            $data['kib_bahan'] = null;
            $data['kib_no_pabrik'] = null;
            $data['kib_no_rangka'] = null;
            $data['kib_no_mesin'] = null;
            $data['kib_no_polisi'] = null;
            $data['kib_no_bpkb'] = null;
            $data['kib_bertingkat'] = 'Tidak';
            $data['kib_beton'] = 'Tidak';
            $data['kib_status_tanah'] = null;
            $data['kib_konstruksi'] = null;
            $data['kib_panjang'] = 0;
            $data['kib_lebar'] = 0;
            $data['kib_judul'] = null;
            $data['kib_pencipta'] = null;
            $data['kib_proyek_bangunan'] = null;
            $data['kib_tgl_mulai'] = null;
            $data['kib_tgl_rencana_selesai'] = null;
            $data['kib_progress_persen'] = 0;
        }

        $upload_dir = UPLOADS . '/logistik_non_medis/aset';
        if (!is_dir($upload_dir)) {
            mkdir($upload_dir, 0777, true);
        }

        $allowed_images = ['jpg', 'jpeg', 'png'];

        if (isset($_FILES['foto_depan']) && $_FILES['foto_depan']['error'] == 0) {
            $ext = strtolower(pathinfo($_FILES['foto_depan']['name'], PATHINFO_EXTENSION));
            if (in_array($ext, $allowed_images)) {
                $filename = 'depan_' . time() . '_' . rand(100, 999) . '.' . $ext;
                if (move_uploaded_file($_FILES['foto_depan']['tmp_name'], $upload_dir . '/' . $filename)) {
                    $data['foto_depan'] = $filename;
                }
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Format Foto Depan tidak didukung! Gunakan jpg, jpeg, atau png.']);
                exit();
            }
        }

        if (isset($_FILES['foto_detail']) && $_FILES['foto_detail']['error'] == 0) {
            $ext = strtolower(pathinfo($_FILES['foto_detail']['name'], PATHINFO_EXTENSION));
            if (in_array($ext, $allowed_images)) {
                $filename = 'detail_' . time() . '_' . rand(100, 999) . '.' . $ext;
                if (move_uploaded_file($_FILES['foto_detail']['tmp_name'], $upload_dir . '/' . $filename)) {
                    $data['foto_detail'] = $filename;
                }
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Format Foto Detail tidak didukung! Gunakan jpg, jpeg, atau png.']);
                exit();
            }
        }

        $user = $this->core->getUserInfo('username', null, true);

        if (empty($id)) {
            $data['nilai_buku'] = $harga_beli;
            $data['akumulasi_penyusutan'] = 0;
            $data['tgl_input'] = date('Y-m-d H:i:s');
            $data['user_input'] = $user;

            $created_count = 0;
            $created_codes = [];
            $created_numbers = [];
            $pdo_aset = $this->db()->pdo();
            try {
                $pdo_aset->beginTransaction();
                $kode_group = 'GRP-' . date('YmdHis') . '-' . strtoupper(substr(uniqid(), -5));
                $stmt_group = $pdo_aset->prepare("INSERT INTO rsns_custom_logistik_non_medis_asset_groups
                  (kode_group,kode_item,kode_kategori,nama_group,kode_unit,lokasi_fisik,tanggal_perolehan,tahun_beli,sumber_perolehan,satuan,harga_satuan,jumlah,status,tgl_input,user_input)
                  VALUES (?,?,?,?,?,?,?,?,?,?,?,?, 'Aktif',?,?)");
                $stmt_group->execute([
                  $kode_group,
                  $data['kode_item'],
                  $kode_kategori_aset,
                  $data['nama_aset'],
                  $kode_unit,
                  $data['lokasi_fisik'],
                  $data['tanggal_perolehan'],
                  $data['tahun_beli'],
                  $data['sumber_perolehan'],
                  $data['satuan'],
                  $data['harga_beli'],
                  $jumlah_registrasi,
                  $data['tgl_input'],
                  $user
                ]);
                $asset_group_id = (int)$pdo_aset->lastInsertId();
                for ($i = 0; $i < $jumlah_registrasi; $i++) {
                    if ($i > 0) {
                        $nomor_inventaris = $this->_generateNomorInventaris($kode_unit, $_POST['kode_item'] ?? '', $kode_kategori_aset);
                        $kode_aset = 'AST-' . $nomor_inventaris;
                    }

                    $row_data = $data;
                    $row_data['asset_group_id'] = $asset_group_id;
                    $row_data['nomor_inventaris'] = $nomor_inventaris;
                    $row_data['kode_aset'] = $kode_aset;

                    $saved = $this->db('rsns_custom_logistik_non_medis_aset')->save($row_data);
                    if (!$saved) {
                        throw new \RuntimeException('Gagal menyimpan aset ke-' . ($i + 1) . '.');
                    }

                    $created_count++;
                    $created_codes[] = $kode_aset;
                    $created_numbers[] = $nomor_inventaris;
                    $this->db('rsns_custom_logistik_non_medis_aset_mutasi')->save([
                      'kode_aset' => $kode_aset,
                      'kode_unit_asal' => null,
                      'kode_unit_tujuan' => $kode_unit,
                      'pic_asal' => null,
                      'pic_tujuan' => $data['pic'],
                      'keterangan' => 'Registrasi aset awal',
                      'tanggal_mutasi' => date('Y-m-d H:i:s'),
                      'user_mutasi' => $user
                  ]);
                }
                $stmt_group_range = $pdo_aset->prepare("UPDATE rsns_custom_logistik_non_medis_asset_groups SET nomor_awal=?,nomor_akhir=?,jumlah=? WHERE id=?");
                $stmt_group_range->execute([
                  $created_numbers[0] ?? null,
                  $created_numbers[count($created_numbers) - 1] ?? null,
                  $created_count,
                  $asset_group_id
                ]);
                $pdo_aset->commit();
                $query = $created_count === $jumlah_registrasi;
            } catch (\Throwable $e) {
                if ($pdo_aset->inTransaction()) {
                    $pdo_aset->rollBack();
                }
                echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
                exit();
            }
        } else {
            $existing = $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->oneArray();
            if (!$existing) {
                echo json_encode(['status' => 'error', 'message' => 'Aset tidak ditemukan!']);
                exit();
            }

            $data['nilai_buku'] = $harga_beli - $existing['akumulasi_penyusutan'];

            if (isset($data['foto_depan']) && !empty($existing['foto_depan']) && file_exists($upload_dir . '/' . $existing['foto_depan'])) {
                unlink($upload_dir . '/' . $existing['foto_depan']);
            }
            if (isset($data['foto_detail']) && !empty($existing['foto_detail']) && file_exists($upload_dir . '/' . $existing['foto_detail'])) {
                unlink($upload_dir . '/' . $existing['foto_detail']);
            }

            $query = $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->update($data);

            if ($existing['kode_unit'] != $kode_unit || $existing['pic'] != $data['pic']) {
                $this->db('rsns_custom_logistik_non_medis_aset_mutasi')->save([
                  'kode_aset' => $existing['kode_aset'],
                  'kode_unit_asal' => $existing['kode_unit'],
                  'kode_unit_tujuan' => $kode_unit,
                  'pic_asal' => $existing['pic'],
                  'pic_tujuan' => $data['pic'],
                  'keterangan' => 'Mutasi penugasan aset',
                  'tanggal_mutasi' => date('Y-m-d H:i:s'),
                  'user_mutasi' => $user
                ]);
            }
        }

        if ($query) {
            // Log to mlite_tracksql on success
            $tanggal_log = date('Y-m-d H:i:s');
            $ip = $_SERVER['REMOTE_ADDR'] ?? 'Localhost';
            $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
            $hostname = $cek_hostname['hostname'] ?? 'Unknown';
            $log_lokasi = '' . $hostname . ' | ' . $ip . '';
            $log_kode_aset = empty($id) && !empty($created_codes) ? implode(',', $created_codes) : $kode_aset;
            $logdata = '' . $log_kode_aset . ' | ' . $data['serial_number'] . ' | ' . $data['kode_item'] . ' | ' . $data['nama_aset'] . ' | ' . $data['spesifikasi'] . ' | ' . $data['tanggal_perolehan'] . ' | ' . $data['harga_beli'] . ' | ' . $data['sumber_perolehan'] . ' | ' . $data['kode_unit'] . ' | ' . $data['pic'] . ' | ' . $data['status_kondisi'] . ' | ' . $user . '';

            $this->db('mlite_tracksql')->save([
              'log_id' => null,
              'log_modul' => 'logistik_non_medis_aset',
              'log_waktu' => $tanggal_log,
              'log_location' => $log_lokasi,
              'log_data' => $logdata,
              'log_status' => empty($id) ? 'I' : 'U',
              'log_username' => $user
            ]);

            $message = empty($id) && $jumlah_registrasi > 1
              ? 'Berhasil membuat ' . $jumlah_registrasi . ' aset inventaris, masing-masing 1 ' . ($data['satuan'] ?: 'unit') . '.'
              : 'Data Registrasi Aset berhasil disimpan.';
            echo json_encode(['status' => 'success', 'message' => $message]);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan data ke database']);
        }
        exit();
    }

    public function anyDetailGroupAsetRegistrasi()
    {
        $this->_initAset();
        $group_id = (int)($_POST['group_id'] ?? 0);
        $group = $this->db('rsns_custom_logistik_non_medis_asset_groups')->where('id', $group_id)->oneArray();
        if (!$group) {
            echo '<div class="alert alert-danger">Kelompok aset tidak ditemukan.</div>';
            exit();
        }

        $stmt = $this->db()->pdo()->prepare("SELECT a.*,
                 COALESCE(NULLIF(a.harga_beli,0),NULLIF(a.harga_referensi_import,0),NULLIF(im.harga_referensi,0),0) harga_tampil,
                 CASE WHEN COALESCE(a.harga_beli,0)>0 THEN 'Harga Perolehan'
                      WHEN COALESCE(a.harga_referensi_import,0)>0 THEN 'Referensi Import'
                      WHEN COALESCE(im.harga_referensi,0)>0 THEN 'Harga Referensi'
                      ELSE 'Belum Tersedia' END sumber_harga_tampil
          FROM rsns_custom_logistik_non_medis_aset a
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im
            ON im.jenis_master='BARANG' AND im.kode_kategori=COALESCE(NULLIF(a.kode_kategori_aset,''),'2') AND im.kode=a.kode_item
          WHERE a.asset_group_id=? AND a.status='Aktif'
          ORDER BY a.nomor_inventaris ASC");
        $stmt->execute([$group_id]);
        $items = $stmt->fetchAll(\PDO::FETCH_ASSOC);

        $unit = $this->db('rsns_custom_logistik_non_medis_inventaris_master')
          ->where('jenis_master', 'UNIT')->where('kode_kategori', '')->where('kode', $group['kode_unit'])->oneArray();
        $group['nama_unit'] = $unit['nama'] ?? $group['kode_unit'];
        $group['jumlah_aktif'] = count($items);
        $group['jumlah_baik'] = count(array_filter($items, function ($item) { return $item['status_kondisi'] === 'Baik'; }));
        $group['jumlah_rusak_ringan'] = count(array_filter($items, function ($item) { return $item['status_kondisi'] === 'Rusak Ringan'; }));
        $group['jumlah_rusak_berat'] = count(array_filter($items, function ($item) { return $item['status_kondisi'] === 'Rusak Berat'; }));
        $group['tahun_beli_referensi'] = count(array_filter($items, function ($item) { return !empty($item['tahun_beli_referensi']); })) > 0 ? 1 : 0;

        echo $this->draw('aset.registrasi.group.detail.html', [
          'group' => $group,
          'items' => $items,
          'q' => '',
          'page' => 1,
          'perpage' => max(1, count($items)),
          'offset' => 0,
          'filtered_total' => count($items),
          'total_pages' => 1,
          'pagination' => '',
          'return_url' => url([ADMIN, 'logistik_non_medis', 'asetregistrasi'])
        ]);
        exit();
    }

    public function getAsetGroupPage()
    {
        $this->_initAset();
        $this->_addHeaderFiles();
        $group_id = (int)($_GET['group_id'] ?? 0);
        $group = $this->db('rsns_custom_logistik_non_medis_asset_groups')->where('id', $group_id)->oneArray();
        if (!$group) {
            return $this->draw('aset.registrasi.notfound.html', [
              'message' => 'Kelompok aset tidak ditemukan.',
              'return_url' => url([ADMIN, 'logistik_non_medis', 'asetregistrasi'])
            ]);
        }

        $q = trim((string)($_GET['q'] ?? ''));
        $page = max(1, (int)($_GET['page'] ?? 1));
        $perpage = 50;
        $where = ["a.asset_group_id = ?", "a.status = 'Aktif'"];
        $params = [$group_id];
        if ($q !== '') {
            $where[] = '(a.nomor_inventaris LIKE ? OR a.kode_aset LIKE ? OR a.serial_number LIKE ? OR a.lokasi_fisik LIKE ? OR a.status_kondisi LIKE ?)';
            $like = '%' . $q . '%';
            for ($i = 0; $i < 5; $i++) {
                $params[] = $like;
            }
        }

        $countStmt = $this->db()->pdo()->prepare('SELECT COUNT(*) FROM rsns_custom_logistik_non_medis_aset a WHERE ' . implode(' AND ', $where));
        $countStmt->execute($params);
        $filteredTotal = (int)$countStmt->fetchColumn();
        $totalPages = max(1, (int)ceil($filteredTotal / $perpage));
        $page = min($page, $totalPages);
        $offset = ($page - 1) * $perpage;

        $sql = "SELECT a.*,
                 COALESCE(NULLIF(a.harga_beli,0),NULLIF(a.harga_referensi_import,0),NULLIF(im.harga_referensi,0),0) harga_tampil,
                 CASE WHEN COALESCE(a.harga_beli,0)>0 THEN 'Harga Perolehan'
                      WHEN COALESCE(a.harga_referensi_import,0)>0 THEN 'Referensi Import'
                      WHEN COALESCE(im.harga_referensi,0)>0 THEN 'Harga Referensi'
                      ELSE 'Belum Tersedia' END sumber_harga_tampil
          FROM rsns_custom_logistik_non_medis_aset a
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im
            ON im.jenis_master='BARANG' AND im.kode_kategori=COALESCE(NULLIF(a.kode_kategori_aset,''),'2') AND im.kode=a.kode_item
          WHERE " . implode(' AND ', $where) . "
          ORDER BY a.nomor_inventaris ASC LIMIT " . (int)$perpage . " OFFSET " . (int)$offset;
        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute($params);
        $items = $stmt->fetchAll(\PDO::FETCH_ASSOC);

        $statsStmt = $this->db()->pdo()->prepare("SELECT COUNT(*) jumlah_aktif,
          SUM(status_kondisi='Baik') jumlah_baik,
          SUM(status_kondisi='Rusak Ringan') jumlah_rusak_ringan,
          SUM(status_kondisi='Rusak Berat') jumlah_rusak_berat,
          SUM(CASE WHEN tahun_beli_referensi IS NOT NULL AND tahun_beli_referensi<>'' THEN 1 ELSE 0 END) jumlah_tahun_referensi
          FROM rsns_custom_logistik_non_medis_aset WHERE asset_group_id=? AND status='Aktif'");
        $statsStmt->execute([$group_id]);
        $stats = $statsStmt->fetch(\PDO::FETCH_ASSOC) ?: [];
        $unit = $this->db('rsns_custom_logistik_non_medis_inventaris_master')
          ->where('jenis_master', 'UNIT')->where('kode_kategori', '')->where('kode', $group['kode_unit'])->oneArray();
        $group['nama_unit'] = $unit['nama'] ?? $group['kode_unit'];
        $group['jumlah_aktif'] = (int)($stats['jumlah_aktif'] ?? 0);
        $group['jumlah_baik'] = (int)($stats['jumlah_baik'] ?? 0);
        $group['jumlah_rusak_ringan'] = (int)($stats['jumlah_rusak_ringan'] ?? 0);
        $group['jumlah_rusak_berat'] = (int)($stats['jumlah_rusak_berat'] ?? 0);
        $group['tahun_beli_referensi'] = (int)($stats['jumlah_tahun_referensi'] ?? 0) > 0 ? 1 : 0;

        $baseUrl = url([ADMIN, 'logistik_non_medis', 'asetgrouppage']) . '&group_id=' . $group_id . '&q=' . rawurlencode($q);
        $pagination = '';
        if ($totalPages > 1) {
            $start = max(1, $page - 2);
            $end = min($totalPages, $page + 2);
            $pagination .= $page > 1 ? '<li><a href="' . $baseUrl . '&page=' . ($page - 1) . '">&laquo; Sebelumnya</a></li>' : '<li class="disabled"><span>&laquo; Sebelumnya</span></li>';
            for ($i = $start; $i <= $end; $i++) {
                $pagination .= '<li' . ($i === $page ? ' class="active"' : '') . '><a href="' . $baseUrl . '&page=' . $i . '">' . $i . '</a></li>';
            }
            $pagination .= $page < $totalPages ? '<li><a href="' . $baseUrl . '&page=' . ($page + 1) . '">Berikutnya &raquo;</a></li>' : '<li class="disabled"><span>Berikutnya &raquo;</span></li>';
        }

        return $this->draw('aset.registrasi.group.detail.html', [
          'group' => $group,
          'items' => $items,
          'q' => $q,
          'page' => $page,
          'perpage' => $perpage,
          'offset' => $offset,
          'filtered_total' => $filteredTotal,
          'total_pages' => $totalPages,
          'pagination' => $pagination,
          'return_url' => url([ADMIN, 'logistik_non_medis', 'asetregistrasi'])
        ]);
    }

    private function _simpanTandaTanganPengambilanSppb(string $no_sppb, string $penerima, string $petugas, array $signature): void
    {
        $existing = $this->db('rsns_custom_logistik_non_medis_serah_terima')
                         ->where('no_sppb', $no_sppb)
                         ->oneArray();
        $data = [
          'tanggal_serah' => date('Y-m-d H:i:s'),
          'petugas_pengirim' => $petugas,
          'penerima_nama' => $penerima,
          'tanda_terima' => $signature['data'],
          'tanda_terima_format' => 'STROKES_V1',
          'tanda_terima_hash' => $signature['hash'],
          'tanda_terima_ip' => substr((string)($_SERVER['REMOTE_ADDR'] ?? ''), 0, 45),
          'tanda_terima_user_agent' => substr((string)($_SERVER['HTTP_USER_AGENT'] ?? ''), 0, 255)
        ];
        if ($existing) {
            $saved = $this->db('rsns_custom_logistik_non_medis_serah_terima')
                          ->where('id', $existing['id'])
                          ->update($data);
        } else {
            $data['no_serah_terima'] = $this->_generateNoSerahTerima();
            $data['no_sppb'] = $no_sppb;
            $saved = $this->db('rsns_custom_logistik_non_medis_serah_terima')->save($data);
        }
        if (!$saved) {
            throw new \RuntimeException('Tanda tangan pengambil gagal disimpan.');
        }
    }

    public function postUpdateKondisiAsetGroup()
    {
        $this->_initAset();
        $id = (int)($_POST['id'] ?? 0);
        $kondisi = trim((string)($_POST['kondisi'] ?? ''));
        if (!$id || !in_array($kondisi, ['Baik', 'Rusak Ringan', 'Rusak Berat'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Data kondisi tidak valid.']);
            exit();
        }
        $aset = $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->where('status', 'Aktif')->oneArray();
        if (!$aset) {
            echo json_encode(['status' => 'error', 'message' => 'Aset tidak ditemukan.']);
            exit();
        }
        $saved = $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->update(['status_kondisi' => $kondisi]);
        echo json_encode($saved
          ? ['status' => 'success', 'message' => 'Kondisi aset diperbarui.']
          : ['status' => 'error', 'message' => 'Kondisi aset gagal diperbarui.']);
        exit();
    }

    public function anyDetailAsetRegistrasi()
    {
        $id = $_POST['id'] ?? '';
        $data = $this->_getAsetRegistrasiDetailData($id);
        if (!$data) {
            echo '<div class="alert alert-danger">Data aset tidak ditemukan!</div>';
            exit();
        }
        $data['standalone'] = false;
        $data['return_url'] = url([ADMIN, 'logistik_non_medis', 'asetregistrasi']);
        echo $this->draw('aset.registrasi.detail.html', $data);
        exit();
    }

    private function _getAsetRegistrasiDetailData($id)
    {
        $this->_initAset();
        $aset = $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->oneArray();
        if (!$aset) {
            return null;
        }

        $unit = $this->db('rsns_custom_logistik_non_medis_unit')->where('kode_unit', $aset['kode_unit'])->oneArray();
        $aset['nama_unit'] = $unit['nama_unit'] ?? '-';

        $item = $this->db('rsns_custom_logistik_non_medis_master_barang')->where('kode_item', $aset['kode_item'])->oneArray();
        $aset['nama_item'] = $item['nama_barang'] ?? '-';
        $aset['satuan_dasar'] = $item['satuan_dasar'] ?? '-';
        $masterInventaris = $this->db('rsns_custom_logistik_non_medis_inventaris_master')
          ->where('jenis_master', 'BARANG')
          ->where('kode_kategori', $aset['kode_kategori_aset'] ?: '2')
          ->where('kode', $aset['kode_item'])
          ->oneArray();
        $aset['harga_tampil'] = (double)($aset['harga_beli'] ?? 0) > 0
          ? (double)$aset['harga_beli']
          : ((double)($aset['harga_referensi_import'] ?? 0) > 0
              ? (double)$aset['harga_referensi_import']
              : (double)($masterInventaris['harga_referensi'] ?? 0));
        $aset['sumber_harga_tampil'] = (double)($aset['harga_beli'] ?? 0) > 0
          ? 'Harga Perolehan'
          : ((double)($aset['harga_referensi_import'] ?? 0) > 0
              ? 'Referensi Import'
              : ($aset['harga_tampil'] > 0 ? 'Harga Referensi' : 'Belum Tersedia'));
        $tahun_beli = (int)($aset['tahun_beli'] ?? 0);
        if ($tahun_beli < 1900 || $tahun_beli > 2100) {
            $tanggal_perolehan = (string)($aset['tanggal_perolehan'] ?? '');
            $tahun_dari_tanggal = preg_match('/^(19|20)\d{2}-\d{2}-\d{2}$/', $tanggal_perolehan)
              ? (int)substr($tanggal_perolehan, 0, 4)
              : 0;
            $tahun_beli = ($tahun_dari_tanggal >= 1900 && $tahun_dari_tanggal <= 2100) ? $tahun_dari_tanggal : 0;
        }
        $aset['tahun_perolehan'] = $tahun_beli > 0 ? $tahun_beli : '-';

        $mutasi = $this->db('rsns_custom_logistik_non_medis_aset_mutasi')
                     ->where('kode_aset', $aset['kode_aset'])
                     ->desc('tanggal_mutasi')
                     ->toArray();

        foreach ($mutasi as &$m) {
            $unit_asal = $this->db('rsns_custom_logistik_non_medis_unit')->where('kode_unit', $m['kode_unit_asal'])->oneArray();
            $m['nama_unit_asal'] = $unit_asal['nama_unit'] ?? '-';

            $unit_tujuan = $this->db('rsns_custom_logistik_non_medis_unit')->where('kode_unit', $m['kode_unit_tujuan'])->oneArray();
            $m['nama_unit_tujuan'] = $unit_tujuan['nama_unit'] ?? '-';
        }

        return [
          'aset' => $aset,
          'mutasi' => $mutasi
        ];
    }

    public function getAsetDetailPage()
    {
        $this->_addHeaderFiles();
        $id = (int)($_GET['id'] ?? 0);
        $from = (($_GET['from'] ?? '') === 'kib') ? 'kib' : 'registrasi';
        $groupId = max(0, (int)($_GET['group_id'] ?? 0));
        if ($from === 'kib') {
            $returnUrl = url([ADMIN, 'logistik_non_medis', 'asetkib']);
        } elseif ($groupId > 0) {
            $returnUrl = url([ADMIN, 'logistik_non_medis', 'asetgrouppage']) . '&group_id=' . $groupId;
        } else {
            $returnUrl = url([ADMIN, 'logistik_non_medis', 'asetregistrasi']);
        }
        $data = $this->_getAsetRegistrasiDetailData($id);
        if (!$data) {
            return $this->draw('aset.registrasi.notfound.html', [
              'message' => 'Data aset tidak ditemukan.',
              'return_url' => $returnUrl
            ]);
        }
        $data['standalone'] = true;
        $data['from'] = $from;
        $data['group_id'] = $groupId;
        $data['return_url'] = $returnUrl;
        return $this->draw('aset.registrasi.detail.html', $data);
    }

    public function postHapusAsetRegistrasi()
    {
        $this->_initAset();
        $id = $_POST['id'] ?? '';

        $existing = $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->oneArray();
        if ($existing) {
            $query = $this->db('rsns_custom_logistik_non_medis_aset')
                        ->where('id', $id)
                        ->update(['status' => 'Dihapuskan']);

            if ($query) {
                // Log to mlite_tracksql
                $user = $this->core->getUserInfo('username', null, true);
                $tanggal_log = date('Y-m-d H:i:s');
                $ip = $_SERVER['REMOTE_ADDR'] ?? 'Localhost';
                $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
                $hostname = $cek_hostname['hostname'] ?? 'Unknown';
                $log_lokasi = '' . $hostname . ' | ' . $ip . '';
                $logdata = '' . $existing['kode_aset'] . ' | ' . $existing['nama_aset'] . ' | Status changed to Dihapuskan | ' . $user . '';

                $this->db('mlite_tracksql')->save([
                  'log_id' => null,
                  'log_modul' => 'logistik_non_medis_aset',
                  'log_waktu' => $tanggal_log,
                  'log_location' => $log_lokasi,
                  'log_data' => $logdata,
                  'log_status' => 'D',
                  'log_username' => $user
                ]);

                echo json_encode(['status' => 'success']);
            } else {
                echo json_encode(['status' => 'error', 'message' => 'Gagal menghapus aset dari database.']);
            }
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Data tidak ditemukan.']);
        }
        exit();
    }

    public function postBulkHapusAsetRegistrasi()
    {
        $this->_initAset();
        $ids = $_POST['ids'] ?? [];
        if (!is_array($ids) || empty($ids)) {
            echo json_encode(['status' => 'error', 'message' => 'Tidak ada aset yang dipilih.']);
            exit();
        }

        $user = $this->core->getUserInfo('username', null, true);
        $tanggal_log = date('Y-m-d H:i:s');
        $ip = $_SERVER['REMOTE_ADDR'] ?? 'Localhost';
        $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
        $hostname = $cek_hostname['hostname'] ?? 'Unknown';
        $log_lokasi = '' . $hostname . ' | ' . $ip . '';

        $success_count = 0;
        foreach ($ids as $id) {
            $existing = $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->oneArray();
            if ($existing && $existing['status'] !== 'Dihapuskan') {
                $query = $this->db('rsns_custom_logistik_non_medis_aset')
                            ->where('id', $id)
                            ->update(['status' => 'Dihapuskan']);
                if ($query) {
                    $success_count++;
                    $logdata = '' . $existing['kode_aset'] . ' | ' . $existing['nama_aset'] . ' | Status changed to Dihapuskan | ' . $user . '';
                    $this->db('mlite_tracksql')->save([
                      'log_id' => null,
                      'log_modul' => 'logistik_non_medis_aset',
                      'log_waktu' => $tanggal_log,
                      'log_location' => $log_lokasi,
                      'log_data' => $logdata,
                      'log_status' => 'D',
                      'log_username' => $user
                    ]);
                }
            }
        }

        echo json_encode(['status' => 'success', 'message' => $success_count . ' aset berhasil dihapus.']);
        exit();
    }

    public function getAsetPrintLabel($kode_aset = '')
    {
        $this->_initAset();
        if (empty($kode_aset)) {
            $kode_aset = $_GET['kode_aset'] ?? '';
        }

        $kode_aset = urldecode($kode_aset);

        $aset = $this->db('rsns_custom_logistik_non_medis_aset')->where('kode_aset', $kode_aset)->oneArray();
        if (!$aset) {
            echo 'Data aset tidak ditemukan.';
            exit();
        }

        $unit = $this->db('rsns_custom_logistik_non_medis_inventaris_master')
          ->where('jenis_master', 'UNIT')
          ->where('kode', $aset['kode_unit'])
          ->oneArray();
        if (!$unit) {
            $unit = $this->db('rsns_custom_logistik_non_medis_unit')->where('kode_unit', $aset['kode_unit'])->oneArray();
            $aset['nama_unit'] = $unit['nama_unit'] ?? '-';
        } else {
            $aset['nama_unit'] = $unit['nama'] ?? '-';
        }
        $aset['kode_label_inventaris'] = !empty($aset['nomor_inventaris'])
          ? $aset['nomor_inventaris']
          : preg_replace('/^AST-?/i', '', $aset['kode_aset']);

        $scan_url = url('plugins/logistik_non_medis/public/aset-info.php') . '?kode=' . urlencode($kode_aset);
        $qr_image_url = url('plugins/logistik_non_medis/public/aset-qr.php') . '?kode=' . urlencode($kode_aset);
        $logo_url = url('plugins/logistik_non_medis/public/rsunurussyifa-logo.png');

        echo $this->draw('aset.registrasi.label.html', [
          'aset' => $aset,
          'scan_url' => $scan_url,
          'qr_image_url' => $qr_image_url,
          'logo_url' => $logo_url
        ]);
        exit();
    }

