    public function anyDisplayKib()
    {
        $this->_initAset();
        $halaman = $_POST['halaman'] ?? 1;
        $cari = $_POST['cari'] ?? '';
        $filter_unit = $_POST['filter_unit'] ?? '';
        $filter_kelompok = $_POST['filter_kelompok'] ?? '';
        $filter_jenis = $_POST['filter_jenis'] ?? '';
        $filter_harga = $_POST['filter_harga'] ?? '';

        $halaman = (int) $halaman;
        if ($halaman < 1) {
            $halaman = 1;
        }

        $perpage = 25;
        $_offset = ($halaman - 1) * $perpage;

        $where = ["a.status = 'Aktif'"];
        $params = [];
        if (!empty($cari)) {
            $where[] = "(a.kode_aset LIKE ? OR a.nomor_inventaris LIKE ? OR a.nama_aset LIKE ? OR b.nama_barang LIKE ? OR im.nama LIKE ?)";
            for ($i = 0; $i < 5; $i++) {
                $params[] = '%' . $cari . '%';
            }
        }
        if (!empty($filter_unit)) {
            $where[] = "a.kode_unit = ?";
            $params[] = $filter_unit;
        }
        if (!empty($filter_kelompok)) {
            $where[] = "im.kode_kelompok = ?";
            $params[] = $filter_kelompok;
        }
        if (!empty($filter_jenis)) {
            $where[] = "CONCAT(im.kode_kelompok, '.', im.kode_jenis) = ?";
            $params[] = $filter_jenis;
        }
        if ($filter_harga === 'tersedia') {
            $where[] = "a.harga_beli > 0";
        } elseif ($filter_harga === 'kosong') {
            $where[] = "a.harga_beli <= 0";
        }

        $where_sql = implode(' AND ', $where);
        $count_join_sql = '';
        if ($cari !== '') {
            $count_join_sql .= " LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = a.kode_item ";
        }
        if ($cari !== '' || $filter_kelompok !== '' || $filter_jenis !== '') {
            $count_join_sql .= " LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im ON im.jenis_master='BARANG' AND im.kode_kategori=COALESCE(NULLIF(a.kode_kategori_aset,''),'2') AND im.kode=a.kode_item ";
        }
        $count_sql = "FROM rsns_custom_logistik_non_medis_aset a {$count_join_sql} WHERE {$where_sql}";
        $join_sql = "
          FROM rsns_custom_logistik_non_medis_aset a
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = a.kode_item
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master iu
            ON iu.jenis_master = 'UNIT' AND iu.kode = a.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = a.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im
            ON im.jenis_master = 'BARANG'
           AND im.kode_kategori = COALESCE(NULLIF(a.kode_kategori_aset, ''), '2')
           AND im.kode = a.kode_item
          WHERE {$where_sql}
      ";

        $stmt_count = $this->db()->pdo()->prepare("SELECT COUNT(*) {$count_sql}");
        $stmt_count->execute($params);
        $jumlah_data = (int) $stmt_count->fetchColumn();
        $total_halaman = $jumlah_data > 0 ? ceil($jumlah_data / $perpage) : 1;

        $stmt_rows = $this->db()->pdo()->prepare("
          SELECT a.*, COALESCE(iu.nama, u.nama_unit) nama_unit, b.nama_barang,
                 im.kode kode_inventaris_master, im.nama nama_master_inventaris,
                 im.kode_kelompok, im.nama_kelompok, im.kode_jenis, im.nama_jenis
          {$join_sql}
          ORDER BY a.kode_aset DESC
          LIMIT {$perpage} OFFSET {$_offset}
      ");
        $stmt_rows->execute($params);
        $asets = $stmt_rows->fetchAll(\PDO::FETCH_ASSOC);

        $stmt_kelompok = $this->db()->pdo()->prepare("
          SELECT COALESCE(im.nama_kelompok, 'Belum Terhubung Master') label, COUNT(*) total
          FROM rsns_custom_logistik_non_medis_aset a
          " . ($cari !== '' ? "LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item=a.kode_item" : "") . "
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im
            ON im.jenis_master='BARANG' AND im.kode_kategori=COALESCE(NULLIF(a.kode_kategori_aset,''),'2') AND im.kode=a.kode_item
          WHERE {$where_sql}
          GROUP BY COALESCE(im.nama_kelompok, 'Belum Terhubung Master')
          ORDER BY total DESC
          LIMIT 8
      ");
        $stmt_kelompok->execute($params);
        $chart_kelompok = $stmt_kelompok->fetchAll(\PDO::FETCH_ASSOC);

        $stmt_tahun = $this->db()->pdo()->prepare("
          SELECT CASE
                   WHEN a.tahun_beli BETWEEN 1900 AND 2100 THEN CAST(a.tahun_beli AS CHAR)
                   WHEN a.tanggal_perolehan BETWEEN '1900-01-01' AND '2100-12-31' THEN CAST(YEAR(a.tanggal_perolehan) AS CHAR)
                   ELSE 'Belum Diisi'
                 END label,
                 COUNT(*) total
          FROM rsns_custom_logistik_non_medis_aset a
          " . ($cari !== '' ? "LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item=a.kode_item" : "") . "
          " . (($cari !== '' || $filter_kelompok !== '' || $filter_jenis !== '') ? "LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im ON im.jenis_master='BARANG' AND im.kode_kategori=COALESCE(NULLIF(a.kode_kategori_aset,''),'2') AND im.kode=a.kode_item" : "") . "
          WHERE {$where_sql}
          GROUP BY label
          ORDER BY (label = 'Belum Diisi'), CAST(label AS UNSIGNED) DESC
      ");
        $stmt_tahun->execute($params);
        $chart_tahun = $stmt_tahun->fetchAll(\PDO::FETCH_ASSOC);

        $stmt_unit = $this->db()->pdo()->prepare("
          SELECT COALESCE(iu.nama, u.nama_unit, 'Tanpa Unit') label, COUNT(*) total
          FROM rsns_custom_logistik_non_medis_aset a
          " . ($cari !== '' ? "LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item=a.kode_item" : "") . "
          " . (($cari !== '' || $filter_kelompok !== '' || $filter_jenis !== '') ? "LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im ON im.jenis_master='BARANG' AND im.kode_kategori=COALESCE(NULLIF(a.kode_kategori_aset,''),'2') AND im.kode=a.kode_item" : "") . "
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master iu
            ON iu.jenis_master='UNIT' AND iu.kode_kategori='' AND iu.kode=a.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit=a.kode_unit
          WHERE {$where_sql}
          GROUP BY COALESCE(iu.nama, u.nama_unit, 'Tanpa Unit')
          ORDER BY total DESC
          LIMIT 8
      ");
        $stmt_unit->execute($params);
        $chart_unit = $stmt_unit->fetchAll(\PDO::FETCH_ASSOC);

        $stmt_kondisi = $this->db()->pdo()->prepare("
          SELECT
            COUNT(DISTINCT CASE WHEN a.status_kondisi = 'Baik' THEN a.id END) AS baik,
            COUNT(DISTINCT CASE WHEN a.status_kondisi = 'Rusak Ringan' THEN a.id END) AS rusak_ringan,
            COUNT(DISTINCT CASE WHEN a.status_kondisi = 'Rusak Berat' THEN a.id END) AS rusak_berat
          {$join_sql}
      ");
        $stmt_kondisi->execute($params);
        $chart_kondisi = $stmt_kondisi->fetch(\PDO::FETCH_ASSOC) ?: [];
        $chart_kondisi_data = [
          (int)($chart_kondisi['baik'] ?? 0),
          (int)($chart_kondisi['rusak_ringan'] ?? 0),
          (int)($chart_kondisi['rusak_berat'] ?? 0)
        ];

        $stmt_total = $this->db()->pdo()->prepare("SELECT SUM(a.harga_beli) {$count_sql}");
        $stmt_total->execute($params);
        $total_nilai = (double) $stmt_total->fetchColumn();

        $stmt_missing_price = $this->db()->pdo()->prepare("SELECT COUNT(*) {$count_sql} AND a.harga_beli <= 0");
        $stmt_missing_price->execute($params);
        $harga_kosong = (int)$stmt_missing_price->fetchColumn();

        // Build pagination HTML
        $pagination_html = '';
        if ($total_halaman > 1) {
            if ($halaman > 1) {
                $pagination_html .= '<li><a href="#" data-page="' . ($halaman - 1) . '" aria-label="Previous">&laquo;</a></li>';
            } else {
                $pagination_html .= '<li class="disabled"><span aria-hidden="true">&laquo;</span></li>';
            }

            $pages = array_unique(array_filter([1, 2, $halaman - 2, $halaman - 1, $halaman, $halaman + 1, $halaman + 2, $total_halaman - 1, $total_halaman], function ($page) use ($total_halaman) {
                return $page >= 1 && $page <= $total_halaman;
            }));
            sort($pages);
            $previous_page = 0;
            foreach ($pages as $i) {
                if ($previous_page && $i > $previous_page + 1) {
                    $pagination_html .= '<li class="disabled"><span>&hellip;</span></li>';
                }
                $pagination_html .= $i == $halaman
                  ? '<li class="active"><span>' . $i . '</span></li>'
                  : '<li><a href="#" data-page="' . $i . '">' . $i . '</a></li>';
                $previous_page = $i;
            }

            if ($halaman < $total_halaman) {
                $pagination_html .= '<li><a href="#" data-page="' . ($halaman + 1) . '" aria-label="Next">&raquo;</a></li>';
            } else {
                $pagination_html .= '<li class="disabled"><span aria-hidden="true">&raquo;</span></li>';
            }
        }

        echo $this->draw('aset.kib.display.html', [
          'asets' => $asets,
          'offset' => $_offset,
          'halaman' => $pagination_html,
          'jumlah_data' => $jumlah_data,
          'total_nilai' => $total_nilai,
          'harga_kosong' => $harga_kosong,
          'chart_kondisi_data' => json_encode($chart_kondisi_data),
          'chart_kelompok_labels' => json_encode(array_column($chart_kelompok, 'label')),
          'chart_kelompok_data' => json_encode(array_map('intval', array_column($chart_kelompok, 'total'))),
          'chart_tahun_labels' => json_encode(array_column($chart_tahun, 'label')),
          'chart_tahun_data' => json_encode(array_map('intval', array_column($chart_tahun, 'total'))),
          'chart_unit_labels' => json_encode(array_column($chart_unit, 'label')),
          'chart_unit_data' => json_encode(array_map('intval', array_column($chart_unit, 'total')))
        ]);
        exit();
    }

