            if ($halaman > 1) {
                $pagination_html .= '<li><a href="#" data-page="' . ($halaman - 1) . '" aria-label="Previous">&laquo;</a></li>';
            } else {
                $pagination_html .= '<li class="disabled"><span aria-hidden="true">&laquo;</span></li>';
            }

            $pages = array_unique(array_filter([1, 2, $halaman - 2, $halaman - 1, $halaman, $halaman + 1, $halaman + 2, $total_halaman - 1, $total_halaman], function ($page) use ($total_halaman) {
                return $page >= 1 && $page <= $total_halaman;
            }));
            sort($pages);
            $previous_page = 0;
            foreach ($pages as $i) {
                if ($previous_page && $i > $previous_page + 1) {
                    $pagination_html .= '<li class="disabled"><span>&hellip;</span></li>';
                }
                $pagination_html .= $i == $halaman
                  ? '<li class="active"><span>' . $i . '</span></li>'
                  : '<li><a href="#" data-page="' . $i . '">' . $i . '</a></li>';
                $previous_page = $i;
            }

            if ($halaman < $total_halaman) {
                $pagination_html .= '<li><a href="#" data-page="' . ($halaman + 1) . '" aria-label="Next">&raquo;</a></li>';
            } else {
                $pagination_html .= '<li class="disabled"><span aria-hidden="true">&raquo;</span></li>';
            }
        }

        echo $this->draw('laporan.inventaris.display.html', [
          'asets' => $asets,
          'offset' => $_offset,
          'halaman' => $pagination_html,
          'jumlah_data' => $jumlah_data,
          'total_nilai' => $total_nilai,
          'harga_kosong' => $harga_kosong,
          'chart_kelompok_labels' => json_encode(array_column($chart_kelompok, 'label')),
          'chart_kelompok_data' => json_encode(array_map('intval', array_column($chart_kelompok, 'total'))),
          'chart_tahun_labels' => json_encode(array_column($chart_tahun, 'label')),
          'chart_tahun_data' => json_encode(array_map('intval', array_column($chart_tahun, 'total'))),
          'chart_unit_labels' => json_encode(array_column($chart_unit, 'label')),
          'chart_unit_data' => json_encode(array_map('intval', array_column($chart_unit, 'total')))
        ]);
        exit();
    }

    
    public function anyAsetKibExportXlsx()
    {
        $this->_initAset();

        $cari = trim((string)($_GET['cari'] ?? ''));
        $filter_unit = trim((string)($_GET['filter_unit'] ?? ''));
        $filter_kelompok = trim((string)($_GET['filter_kelompok'] ?? ''));
        $filter_jenis = trim((string)($_GET['filter_jenis'] ?? ''));
        $filter_harga = trim((string)($_GET['filter_harga'] ?? ''));

        $where = ["a.status = 'Aktif'"];
        $params = [];
        if ($cari !== '') {
            $where[] = "(a.kode_aset LIKE ? OR a.nomor_inventaris LIKE ? OR a.nama_aset LIKE ? OR b.nama_barang LIKE ? OR im.nama LIKE ?)";
            for ($i = 0; $i < 5; $i++) {
                $params[] = '%' . $cari . '%';
            }
        }
        if ($filter_unit !== '') {
            $where[] = 'a.kode_unit = ?';
            $params[] = $filter_unit;
        }
        if ($filter_kelompok !== '') {
            $where[] = 'im.kode_kelompok = ?';
            $params[] = $filter_kelompok;
        }
        if ($filter_jenis !== '') {
            $where[] = "CONCAT(im.kode_kelompok, '.', im.kode_jenis) = ?";
            $params[] = $filter_jenis;
        }
        if ($filter_harga === 'tersedia') {
            $where[] = 'a.harga_beli > 0';
        } elseif ($filter_harga === 'kosong') {
            $where[] = 'a.harga_beli <= 0';
        }

        $sql = "
          SELECT COALESCE(a.asset_group_id,-a.id) group_key,
                 MIN(a.nomor_inventaris) nomor_awal, MAX(a.nomor_inventaris) nomor_akhir,
                 MAX(COALESCE(im.nama,b.nama_barang,a.nama_aset)) nama_barang,
                 MAX(a.merk_type) merk_type, MAX(a.satuan) satuan,
                 COUNT(DISTINCT a.id) jumlah_aset,
                 SUM(a.status_kondisi='Baik') jumlah_baik,
                 SUM(a.status_kondisi='Rusak Ringan') jumlah_rusak_ringan,
                 SUM(a.status_kondisi='Rusak Berat') jumlah_rusak_berat,
                 MAX(COALESCE(NULLIF(a.tahun_beli,0),CASE WHEN a.tanggal_perolehan>='1900-01-01' THEN YEAR(a.tanggal_perolehan) END)) tahun_beli,
                 MAX(a.sumber_perolehan) sumber_perolehan,
                 MAX(COALESCE(iu.nama,u.nama_unit,a.kode_unit,'-')) nama_unit,
                 MAX(COALESCE(NULLIF(a.harga_beli,0),NULLIF(a.harga_referensi_import,0),NULLIF(im.harga_referensi,0),0)) harga_unit,
                 SUM(COALESCE(NULLIF(a.harga_beli,0),NULLIF(a.harga_referensi_import,0),NULLIF(im.harga_referensi,0),0)) total_harga
          FROM rsns_custom_logistik_non_medis_aset a
          LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = a.kode_item
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master iu
            ON iu.jenis_master = 'UNIT' AND iu.kode_kategori = '' AND iu.kode = a.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = a.kode_unit
          LEFT JOIN rsns_custom_logistik_non_medis_inventaris_master im
            ON im.jenis_master = 'BARANG'
           AND im.kode_kategori = COALESCE(NULLIF(a.kode_kategori_aset, ''), '2')
           AND im.kode = a.kode_item
          WHERE " . implode(' AND ', $where) . "
          GROUP BY COALESCE(a.asset_group_id,-a.id)
          ORDER BY nama_unit ASC, nama_barang ASC, nomor_awal ASC
      ";
        $stmt = $this->db()->pdo()->prepare($sql);
        $stmt->execute($params);
        $rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);

        $filter_labels = [];
        if ($cari !== '') {
            $filter_labels[] = 'Pencarian: ' . $cari;
        }
        if ($filter_unit !== '') {
            $filter_labels[] = 'Unit: ' . $filter_unit;
        }
        if ($filter_kelompok !== '') {
            $filter_labels[] = 'Kelompok: ' . $filter_kelompok;
        }
        if ($filter_jenis !== '') {
            $filter_labels[] = 'Jenis: ' . $filter_jenis;
        }
        if ($filter_harga === 'tersedia') {
            $filter_labels[] = 'Harga: Terisi';
        }
        if ($filter_harga === 'kosong') {
            $filter_labels[] = 'Harga: Belum diisi';
        }
        $filter_summary = $filter_labels ? implode(' | ', $filter_labels) : 'Semua aset aktif';

        $this->_outputAsetKibXlsx($rows, $filter_summary);
    }

    private function _outputAsetKibXlsx(array $rows, string $filter_summary)
    {
        if (!class_exists('ZipArchive')) {
            http_response_code(500);
            echo 'Ekstensi ZIP PHP diperlukan untuk membuat file XLSX.';
            exit();
        }

        $headers = [
          'No', 'Nama Barang', 'No Inventaris', 'Kondisi', 'Merk / Ukuran',
          'Jumlah', 'Satuan', 'Harga / Unit', 'Total Harga', 'Thn Beli',
          'Asal', 'Unit', 'Produsen'
        ];
        $bulan = [1=>'JANUARI',2=>'FEBRUARI',3=>'MARET',4=>'APRIL',5=>'MEI',6=>'JUNI',7=>'JULI',8=>'AGUSTUS',9=>'SEPTEMBER',10=>'OKTOBER',11=>'NOVEMBER',12=>'DESEMBER'];
        $periode = $bulan[(int)date('n')] . ' ' . date('Y');
        $sheet_rows = [];
        $sheet_rows[] = '<row r="1" ht="24"><c r="A1" s="1" t="inlineStr"><is><t>LIST INVENTARIS NON MEDIS RSU NURUSYIFA PER ' . $periode . '</t></is></c></row>';
        $sheet_rows[] = '<row r="2" ht="20"><c r="A2" s="2" t="inlineStr"><is><t>' . $this->_xlsxEscape($filter_summary . ' | Total: ' . count($rows) . ' kelompok inventaris | Diekspor: ' . date('d-m-Y H:i')) . '</t></is></c></row>';
        $sheet_rows[] = '<row r="3"></row>';

        $header_cells = '';
        foreach ($headers as $index => $header) {
            $cell = $this->_xlsxColumnName($index + 1) . '4';
            $header_cells .= '<c r="' . $cell . '" s="3" t="inlineStr"><is><t>' . $this->_xlsxEscape($header) . '</t></is></c>';
        }
        $sheet_rows[] = '<row r="4" ht="28">' . $header_cells . '</row>';

        foreach ($rows as $index => $row) {
            $row_number = $index + 5;
            $harga = (float)($row['harga_unit'] ?? 0);
            $total_harga = (float)($row['total_harga'] ?? 0);
            $kondisi = $this->_formatAsetExportCondition($row);
            $values = [
              $index + 1,
              $row['nama_barang'] ?? '',
              $this->_compactAsetInventoryRange($row['nomor_awal'] ?? '', $row['nomor_akhir'] ?? ''),
              $kondisi,
              $row['merk_type'] ?? '',
              (int)($row['jumlah_aset'] ?? 0),
              $row['satuan'] ?? '',
              $harga > 0 ? $harga : null,
              $total_harga > 0 ? $total_harga : null,
              $row['tahun_beli'] ?? '',
              $row['sumber_perolehan'] ?? '',
              $row['nama_unit'] ?? '',
              ''
            ];

            $cells = '';
            foreach ($values as $column_index => $value) {
                $column_number = $column_index + 1;
                $reference = $this->_xlsxColumnName($column_number) . $row_number;
                $style = 4;
                if ($column_number === 8 || $column_number === 9) {
                    $style = 5;
                }

                if ($value === null || $value === '') {
                    $cells .= '<c r="' . $reference . '" s="' . $style . '"/>';
                } elseif (in_array($column_number, [1,6,8,9,10], true) && is_numeric($value)) {
                    $cells .= '<c r="' . $reference . '" s="' . $style . '"><v>' . (0 + $value) . '</v></c>';
                } else {
                    $cells .= '<c r="' . $reference . '" s="' . $style . '" t="inlineStr"><is><t xml:space="preserve">' . $this->_xlsxEscape($value) . '</t></is></c>';
                }
            }
            $sheet_rows[] = '<row r="' . $row_number . '">' . $cells . '</row>';
        }

        $last_row = count($rows) + 4;
        $sheet_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          . '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
          . '<sheetViews><sheetView workbookViewId="0"><pane ySplit="4" topLeftCell="A5" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>'
          . '<cols>'
          . '<col min="1" max="1" width="6" customWidth="1"/><col min="2" max="2" width="32" customWidth="1"/>'
          . '<col min="3" max="3" width="28" customWidth="1"/><col min="4" max="5" width="22" customWidth="1"/>'
          . '<col min="6" max="7" width="12" customWidth="1"/><col min="8" max="9" width="18" customWidth="1"/>'
          . '<col min="10" max="11" width="14" customWidth="1"/><col min="12" max="13" width="24" customWidth="1"/></cols>'
          . '<sheetData>' . implode('', $sheet_rows) . '</sheetData>'
          . '<autoFilter ref="A4:M' . max(4, $last_row) . '"/><mergeCells count="2"><mergeCell ref="A1:M1"/><mergeCell ref="A2:M2"/></mergeCells>'
          . '</worksheet>';

        $styles_xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          . '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
          . '<numFmts count="1"><numFmt numFmtId="164" formatCode="&quot;Rp&quot; #,##0"/></numFmts>'
          . '<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts>'
          . '<fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF337AB7"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFFFD7D7"/><bgColor indexed="64"/></patternFill></fill></fills>'
          . '<borders count="2"><border/><border><left style="thin"><color rgb="FFD9D9D9"/></left><right style="thin"><color rgb="FFD9D9D9"/></right><top style="thin"><color rgb="FFD9D9D9"/></top><bottom style="thin"><color rgb="FFD9D9D9"/></bottom></border></borders>'
          . '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
          . '<cellXfs count="7">'
          . '<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>'
          . '<xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf>'
          . '<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf>'
          . '<xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf>'
          . '<xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf>'
          . '<xf numFmtId="164" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyAlignment="1"><alignment horizontal="right" vertical="top"/></xf>'
          . '<xf numFmtId="0" fontId="0" fillId="3" borderId="1" xfId="0" applyAlignment="1"><alignment vertical="top"/></xf>'
          . '</cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>'
          . '</styleSheet>';

        $temporary_file = tempnam(sys_get_temp_dir(), 'kib_xlsx_');
        $zip = new \ZipArchive();
        if (!$temporary_file || $zip->open($temporary_file, \ZipArchive::CREATE | \ZipArchive::OVERWRITE) !== true) {
            http_response_code(500);
            echo 'File XLSX tidak dapat dibuat.';
            exit();
        }

        $zip->addFromString('[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/></Types>');
        $zip->addFromString('_rels/.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>');
        $zip->addFromString('xl/workbook.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="List Inventaris" sheetId="1" r:id="rId1"/></sheets></workbook>');
        $zip->addFromString('xl/_rels/workbook.xml.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
        $zip->addFromString('xl/worksheets/sheet1.xml', $sheet_xml);
        $zip->addFromString('xl/styles.xml', $styles_xml);
        $zip->addFromString('docProps/core.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>List Inventaris Non Medis RSU Nurusyifa</dc:title><dc:creator>mLITE RSU Nurusyifa</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">' . gmdate('Y-m-d\TH:i:s\Z') . '</dcterms:created></cp:coreProperties>');
        $zip->close();

        while (ob_get_level() > 0) {
            ob_end_clean();
        }
        $filename = 'List_Inventaris_Non_Medis_RSU_Nurusyifa_' . date('Ymd_His') . '.xlsx';
        header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        header('Content-Disposition: attachment; filename="' . $filename . '"');
        header('Content-Length: ' . filesize($temporary_file));
        header('Cache-Control: max-age=0, must-revalidate');
        readfile($temporary_file);
        unlink($temporary_file);
        exit();
    }

    private function _compactAsetInventoryRange($start, $end)
    {
        $start = trim((string)$start);
        $end = trim((string)$end);
        if ($start === '' || $end === '' || $start === $end) {
            return $start !== '' ? $start : $end;
        }
        if (ctype_digit($start) && ctype_digit($end) && strlen($start) === strlen($end)) {
            foreach ([2, 3] as $suffixLength) {
                if (strlen($start) > $suffixLength && substr($start, 0, -$suffixLength) === substr($end, 0, -$suffixLength)) {
                    return $start . ' - ' . substr($end, -$suffixLength);
                }
            }
        }
        return $start . ' - ' . $end;
    }

    private function _formatAsetExportCondition(array $row)
    {
        $parts = [];
        $conditions = [
          'Baik' => (int)($row['jumlah_baik'] ?? 0),
          'Rusak Ringan' => (int)($row['jumlah_rusak_ringan'] ?? 0),
          'Rusak Berat' => (int)($row['jumlah_rusak_berat'] ?? 0)
        ];
        foreach ($conditions as $label => $count) {
            if ($count > 0) {
                $parts[] = count(array_filter($conditions)) > 1 ? $label . ': ' . $count : $label;
            }
        }
        return $parts ? implode('; ', $parts) : '-';
    }

    private function _xlsxColumnName(int $column_number)
    {
        $name = '';
        while ($column_number > 0) {
            $column_number--;
            $name = chr(65 + ($column_number % 26)) . $name;
            $column_number = (int)floor($column_number / 26);
        }
        return $name;
    }

    private function _xlsxEscape($value)
    {
        $value = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/', '', (string)$value);
        return htmlspecialchars($value, ENT_QUOTES | ENT_XML1, 'UTF-8');
    }

    public function postUpdateHargaAset()
    {
        $this->_initAset();
        $id = (int)($_POST['id'] ?? 0);
        $harga = (double)preg_replace('/[^0-9]/', '', (string)($_POST['harga'] ?? '0'));
        if ($id <= 0 || $harga <= 0) {
            echo json_encode(['status' => 'error', 'message' => 'Harga harus lebih dari nol.']);
            exit();
        }

        $aset = $this->db('rsns_custom_logistik_non_medis_aset')->where('id', $id)->oneArray();
        if (!$aset) {
            echo json_encode(['status' => 'error', 'message' => 'Aset tidak ditemukan.']);
            exit();
        }
        if ((double)$aset['harga_beli'] > 0) {
            echo json_encode(['status' => 'error', 'message' => 'Harga aset sudah terisi. Gunakan menu Registrasi Aset untuk mengubahnya.']);
            exit();
        }

        $note = 'Harga dilengkapi manual oleh ' . $this->core->getUserInfo('username', null, true) . ' pada ' . date('d/m/Y H:i') . '.';
        $stmt = $this->db()->pdo()->prepare("UPDATE rsns_custom_logistik_non_medis_aset
          SET harga_beli=?, nilai_buku=?, keterangan_inventaris=CONCAT_WS('\n',NULLIF(keterangan_inventaris,''),?)
          WHERE id=? AND harga_beli<=0");
        $stmt->execute([$harga, $harga, $note, $id]);
        if ($stmt->rowCount() > 0) {
            $this->_logAction('logistik_non_medis_aset', 'Isi harga aset ' . $aset['kode_aset'] . ': Rp ' . number_format($harga, 0, ',', '.'), 'U');
            echo json_encode(['status' => 'success', 'message' => 'Harga aset berhasil disimpan.']);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Harga gagal disimpan atau sudah diperbarui pengguna lain.']);
        }
        exit();
    }

    public function anyDisplayRekapKib()
    {
        $this->_initAset();

        $kib_categories = [
          'A' => ['nama' => 'Tanah', 'nama_singkat' => 'Tanah'],
          'B' => ['nama' => 'Peralatan & Mesin', 'nama_singkat' => 'Peralatan'],
          'C' => ['nama' => 'Gedung & Bangunan', 'nama_singkat' => 'Gedung'],
          'D' => ['nama' => 'Jalan, Irigasi & Jaringan', 'nama_singkat' => 'Jalan/Jaringan'],
          'E' => ['nama' => 'Aset Tetap Lainnya', 'nama_singkat' => 'Aset Lainnya'],
          'F' => ['nama' => 'Konstruksi Dalam Pengerjaan', 'nama_singkat' => 'Konstruksi']
        ];

        $rekap_data = [];
        $kpi = [];

        $grand_total_barang = 0;
        $grand_total_baik = 0;
        $grand_total_ringan = 0;
        $grand_total_berat = 0;
        $grand_total_nilai = 0.0;

        foreach ($kib_categories as $jenis => $meta) {
            $assets_in_cat = $this->db('rsns_custom_logistik_non_medis_aset')
                                ->where('kib_jenis', $jenis)
                                ->where('status', 'Aktif')
                                ->toArray();

            $total_count = count($assets_in_cat);

            $total_nilai = 0.0;
            $baik = 0;
            $ringan = 0;
            $berat = 0;

            foreach ($assets_in_cat as $asset) {
                $total_nilai += (double) ($asset['harga_beli'] ?? 0);
                if ($asset['status_kondisi'] === 'Baik') {
                    $baik++;
                } elseif ($asset['status_kondisi'] === 'Rusak Ringan') {
                    $ringan++;
                } elseif ($asset['status_kondisi'] === 'Rusak Berat') {
                    $berat++;
                }
            }

            $rekap_data[] = [
              'jenis' => $jenis,
              'nama' => $meta['nama'],
              'nama_singkat' => $meta['nama_singkat'],
              'jumlah' => $total_count,
              'kondisi_baik' => $baik,
              'kondisi_rusak_ringan' => $ringan,
              'kondisi_rusak_berat' => $berat,
              'total_nilai' => $total_nilai
            ];

            $kpi[$jenis] = [
              'jumlah' => $total_count,
              'total_nilai' => $total_nilai
            ];

            $grand_total_barang += $total_count;
            $grand_total_baik += $baik;
            $grand_total_ringan += $ringan;
            $grand_total_berat += $berat;
            $grand_total_nilai += $total_nilai;
        }

        echo $this->draw('aset.kib.rekap.html', [
          'rekap_data' => $rekap_data,
          'kpi' => $kpi,
          'grand_total_barang' => $grand_total_barang,
          'grand_total_baik' => $grand_total_baik,
          'grand_total_ringan' => $grand_total_ringan,
          'grand_total_berat' => $grand_total_berat,
          'grand_total_nilai' => $grand_total_nilai
        ]);
        exit();
    }

    public function getAsetPenyusutan()
    {
        $this->_initPenyusutan();
        $this->_addHeaderFiles();

        // Get all accounts in mlite_rekening for dropdown mapping
        $rekening = $this->db('mlite_rekening')->toArray();

        // Read current settings for useful life & COA
        $settings_array = $this->db('mlite_settings')->where('module', 'logistik_non_medis')->toArray();
        $settings = [];
        foreach ($settings_array as $row) {
            $settings[$row['field']] = $row['value'];
        }

        // Generate current years for the calculation filter
        $years = [];
        $curr_year = (int)date('Y');
        for ($y = $curr_year - 5; $y <= $curr_year + 5; $y++) {
            $years[] = $y;
        }

        return $this->draw('aset.penyusutan.html', [
          'rekening' => $rekening,
          'settings' => $settings,
          'years' => $years,
          'current_month' => date('m'),
          'current_year' => date('Y')
        ]);
    }

    public function anyDisplayAsetPenyusutan()
    {
        $this->_initPenyusutan();
        $periode_bulan = $_POST['bulan'] ?? date('m');
        $periode_tahun = $_POST['tahun'] ?? date('Y');
        $periode = $periode_tahun . '-' . str_pad($periode_bulan, 2, '0', STR_PAD_LEFT);

        // Fetch settings
        $settings_array = $this->db('mlite_settings')->where('module', 'logistik_non_medis')->toArray();
        $settings = [];
        foreach ($settings_array as $row) {
            $settings[$row['field']] = $row['value'];
        }

        // Fetch assets (Exclude Tanah KIB A and Konstruksi KIB F)
        $assets = $this->db('rsns_custom_logistik_non_medis_aset')
                     ->where('status', 'Aktif')
                     ->where('kib_jenis', 'IN', ['B', 'C', 'D', 'E'])
                     ->toArray();

        $units_array = $this->db('rsns_custom_logistik_non_medis_unit')->toArray();
        $units = [];
        foreach ($units_array as $u) {
            $units[$u['kode_unit']] = $u['nama_unit'];
        }

        $data_aset = [];
        $grand_total_harga = 0;
        $grand_total_residu = 0;
        $grand_total_bulanan = 0;
        $grand_total_akumulasi = 0;
        $grand_total_buku = 0;

        // Check if already processed
        $check_processed = $this->db('rsns_custom_logistik_non_medis_aset_penyusutan')
                              ->where('periode', $periode)
                              ->toArray();
        $is_processed = !empty($check_processed);

        // Create map of existing log
        $processed_map = [];
        foreach ($check_processed as $p) {
            $processed_map[$p['kode_aset']] = $p;
        }

        foreach ($assets as $asset) {
            $kib = $asset['kib_jenis'];

            // 1. Determine Useful Life (Masa Manfaat)
            $manfaat_tahun = (int) ($asset['masa_manfaat_tahun'] ?? 0);
            if ($manfaat_tahun <= 0) {
                $manfaat_tahun = (int) ($settings["depr_manfaat_{$kib}"] ?? 0);
            }

            if ($manfaat_tahun <= 0) {
                continue;
            }

            // 2. Determine Nilai Residu
            $nilai_residu = (double) ($asset['nilai_residu'] ?? 0);
            if ($nilai_residu <= 0) {
                $persen_residu = (double) ($settings["depr_residu_{$kib}"] ?? 0);
                $nilai_residu = $asset['harga_beli'] * ($persen_residu / 100);
            }

            // 3. Determine Depreciable Amount
            $depreciable_amount = $asset['harga_beli'] - $nilai_residu;
            if ($depreciable_amount <= 0) {
                continue;
            }

            // 4. Monthly Straight Line Depreciation Cost
            $monthly_cost = $depreciable_amount / ($manfaat_tahun * 12);
            $monthly_cost = round($monthly_cost, 2);

            // 5. Evaluate calculations
            if ($is_processed) {
                if (!isset($processed_map[$asset['kode_aset']])) {
                    continue;
                }
                $log = $processed_map[$asset['kode_aset']];
                $monthly_cost_run = $log['biaya_penyusutan'];
                $akumulasi_run = $log['akumulasi_penyusutan'];
                $nilai_buku_run = $log['nilai_buku'];
            } else {
                if ($asset['nilai_buku'] <= $nilai_residu) {
                    $monthly_cost_run = 0;
                } else {
                    $remaining_above_residu = $asset['nilai_buku'] - $nilai_residu;
                    $monthly_cost_run = min($monthly_cost, $remaining_above_residu);
                }

                $monthly_cost_run = round($monthly_cost_run, 2);
                $akumulasi_run = $asset['akumulasi_penyusutan'] + $monthly_cost_run;
                $nilai_buku_run = $asset['harga_beli'] - $akumulasi_run;
            }

            $grand_total_harga += $asset['harga_beli'];
            $grand_total_residu += $nilai_residu;
            $grand_total_bulanan += $monthly_cost_run;
            $grand_total_akumulasi += $akumulasi_run;
            $grand_total_buku += $nilai_buku_run;

            $data_aset[] = [
              'kode_aset' => $asset['kode_aset'],
              'nama_aset' => $asset['nama_aset'],
              'kib_jenis' => $asset['kib_jenis'],
              'nama_unit' => $units[$asset['kode_unit']] ?? '-',
              'tanggal_perolehan' => $asset['tanggal_perolehan'],
              'harga_beli' => $asset['harga_beli'],
              'nilai_residu' => $nilai_residu,
              'masa_manfaat' => $manfaat_tahun,
              'biaya_penyusutan' => $monthly_cost_run,
              'akumulasi_penyusutan' => $akumulasi_run,
              'nilai_buku' => $nilai_buku_run
            ];
        }

        echo $this->draw('aset.penyusutan.display.html', [
          'asets' => $data_aset,
          'is_processed' => $is_processed,
          'periode' => $periode,
          'totals' => [
              'harga' => $grand_total_harga,
              'residu' => $grand_total_residu,
              'bulanan' => $grand_total_bulanan,
              'akumulasi' => $grand_total_akumulasi,
              'buku' => $grand_total_buku
          ]
        ]);
        exit();
    }

    public function postProsesPenyusutan()
    {
        $this->_initPenyusutan();
        $periode_bulan = $_POST['bulan'] ?? date('m');
        $periode_tahun = $_POST['tahun'] ?? date('Y');
        $periode = $periode_tahun . '-' . str_pad($periode_bulan, 2, '0', STR_PAD_LEFT);
        $user = $this->core->getUserInfo('username', null, true);

        // Check if already processed
        $check = $this->db('rsns_custom_logistik_non_medis_aset_penyusutan')
                    ->where('periode', $periode)
                    ->oneArray();
        if ($check) {
            echo json_encode(['status' => 'error', 'message' => 'Penyusutan periode ini sudah pernah diproses!']);
            exit();
        }

        // Fetch configurations
        $settings_array = $this->db('mlite_settings')->where('module', 'logistik_non_medis')->toArray();
        $settings = [];
        foreach ($settings_array as $row) {
            $settings[$row['field']] = $row['value'];
        }

        // Fetch assets
        $assets = $this->db('rsns_custom_logistik_non_medis_aset')
                     ->where('status', 'Aktif')
                     ->where('kib_jenis', 'IN', ['B', 'C', 'D', 'E'])
                     ->toArray();

        $calculated_assets = [];
        $depreciation_by_kib = [];
        $total_biaya_penyusutan = 0;

        foreach ($assets as $asset) {
            $kib = $asset['kib_jenis'];

            // 1. Determine Useful Life
            $manfaat_tahun = (int) ($asset['masa_manfaat_tahun'] ?? 0);
            if ($manfaat_tahun <= 0) {
                $manfaat_tahun = (int) ($settings["depr_manfaat_{$kib}"] ?? 0);
            }

            if ($manfaat_tahun <= 0) {
                continue;
            }

            // 2. Determine Nilai Residu
            $nilai_residu = (double) ($asset['nilai_residu'] ?? 0);
            if ($nilai_residu <= 0) {
                $persen_residu = (double) ($settings["depr_residu_{$kib}"] ?? 0);
                $nilai_residu = $asset['harga_beli'] * ($persen_residu / 100);
            }

            // 3. Determine Depreciable Amount
            $depreciable_amount = $asset['harga_beli'] - $nilai_residu;
            if ($depreciable_amount <= 0) {
                continue;
            }

            // 4. Calculate Monthly Cost
            $monthly_cost = $depreciable_amount / ($manfaat_tahun * 12);
            $monthly_cost = round($monthly_cost, 2);

            // Skip if already fully depreciated
            if ($asset['nilai_buku'] <= $nilai_residu) {
                continue;
            }

            $remaining_above_residu = $asset['nilai_buku'] - $nilai_residu;
            $monthly_cost_run = min($monthly_cost, $remaining_above_residu);
            $monthly_cost_run = round($monthly_cost_run, 2);

            if ($monthly_cost_run <= 0) {
                continue;
            }

            $akumulasi_run = $asset['akumulasi_penyusutan'] + $monthly_cost_run;
            $nilai_buku_run = $asset['harga_beli'] - $akumulasi_run;

            $calculated_assets[] = [
              'asset' => $asset,
              'biaya' => $monthly_cost_run,
              'akumulasi' => $akumulasi_run,
              'nilai_buku' => $nilai_buku_run,
              'nilai_residu' => $nilai_residu
            ];

            if (!isset($depreciation_by_kib[$kib])) {
                $depreciation_by_kib[$kib] = 0;
            }
            $depreciation_by_kib[$kib] += $monthly_cost_run;
            $total_biaya_penyusutan += $monthly_cost_run;
        }

        if (empty($calculated_assets)) {
            echo json_encode(['status' => 'error', 'message' => 'Tidak ada aset yang layak disusutkan untuk periode ini!']);
            exit();
        }

        // Validate COA Mappings for all involved KIB categories
        foreach (array_keys($depreciation_by_kib) as $kib) {
            $rek_beban = $settings["depr_rek_beban_{$kib}"] ?? '';
            $rek_akum = $settings["depr_rek_akum_{$kib}"] ?? '';

            if (empty($rek_beban) || empty($rek_akum)) {
                echo json_encode(['status' => 'error', 'message' => "Pemetaan COA untuk KIB {$kib} belum lengkap! Akun Beban & Akumulasi wajib diatur di Tab COA Mapping."]);
                exit();
            }

            // Check if these accounts exist in mlite_rekening
            $chk_beban = $this->db('mlite_rekening')->where('kd_rek', $rek_beban)->oneArray();
            $chk_akum = $this->db('mlite_rekening')->where('kd_rek', $rek_akum)->oneArray();

            if (!$chk_beban || !$chk_akum) {
                echo json_encode(['status' => 'error', 'message' => "Kode Akun Rekening COA KIB {$kib} di modul Keuangan tidak valid!"]);
                exit();
            }
        }

        // Start Database Transaction
        $pdo = $this->db()->pdo();
        $pdo->beginTransaction();

        try {
            // 1. Generate Journal Entry
            $no_jurnal = $this->core->setNoJurnal();
            $no_bukti = 'DEP-' . $periode_tahun . str_pad($periode_bulan, 2, '0', STR_PAD_LEFT);
            $nama_bulan = [
              '01' => 'Januari', '02' => 'Februari', '03' => 'Maret', '04' => 'April',
              '05' => 'Mei', '06' => 'Juni', '07' => 'Juli', '08' => 'Agustus',
              '09' => 'September', '10' => 'Oktober', '11' => 'November', '12' => 'Desember'
            ][$periode_bulan] ?? $periode_bulan;

            $keterangan = "Penyusutan Aset Non-Medis Periode " . $nama_bulan . " " . $periode_tahun . ". Diposting otomatis oleh sistem.";

            // Save to mlite_jurnal
            $this->db('mlite_jurnal')->save([
              'no_jurnal' => $no_jurnal,
              'no_bukti' => $no_bukti,
              'tgl_jurnal' => date('Y-m-d'),
              'jenis' => 'P', // Penyesuaian
              'keterangan' => $keterangan
            ]);

            // Save detail journals per KIB group
            foreach ($depreciation_by_kib as $kib => $amount) {
                $rek_beban = $settings["depr_rek_beban_{$kib}"];
                $rek_akum = $settings["depr_rek_akum_{$kib}"];

                // Debit: Depreciation Expense
                $this->db('mlite_detailjurnal')->save([
                  'no_jurnal' => $no_jurnal,
                  'kd_rek' => $rek_beban,
                  'debet' => $amount,
                  'kredit' => 0
                ]);

                // Credit: Accumulated Depreciation
                $this->db('mlite_detailjurnal')->save([
                    'no_jurnal' => $no_jurnal,
                    'kd_rek' => $rek_akum,
                    'debet' => 0,
                    'kredit' => $amount
                ]);
            }

            // 2. Save Log and update Main Assets table
            foreach ($calculated_assets as $item) {
                $asset = $item['asset'];

                // Insert to rsns_custom_logistik_non_medis_aset_penyusutan
                $this->db('rsns_custom_logistik_non_medis_aset_penyusutan')->save([
                  'kode_aset' => $asset['kode_aset'],
                  'periode' => $periode,
                  'tanggal_proses' => date('Y-m-d H:i:s'),
                  'harga_perolehan' => $asset['harga_beli'],
                  'nilai_residu' => $item['nilai_residu'],
                  'biaya_penyusutan' => $item['biaya'],
                  'akumulasi_penyusutan' => $item['akumulasi'],
                  'nilai_buku' => $item['nilai_buku'],
                  'no_jurnal' => $no_jurnal,
                  'user_proses' => $user
                ]);

                // Update Cache on Aset
                $this->db('rsns_custom_logistik_non_medis_aset')
                   ->where('kode_aset', $asset['kode_aset'])
                   ->update([
                       'akumulasi_penyusutan' => $item['akumulasi'],
                       'nilai_buku' => $item['nilai_buku'],
                       'tgl_penyusutan_terakhir' => date('Y-m-d')
                   ]);
            }

            // Log to mlite_tracksql
            $tanggal_log = date('Y-m-d H:i:s');
            $ip = $_SERVER['REMOTE_ADDR'] ?? 'Localhost';
            $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
            $hostname = $cek_hostname['hostname'] ?? 'Unknown';
            $log_lokasi = '' . $hostname . ' | ' . $ip . '';
            $logdata = 'Processed depreciation for period: ' . $periode . ' | Total assets: ' . count($calculated_assets) . ' | Total cost: ' . $total_biaya_penyusutan . ' | Journal: ' . $no_jurnal;

            $this->db('mlite_tracksql')->save([
              'log_id' => null,
              'log_modul' => 'logistik_non_medis_aset_penyusutan',
              'log_waktu' => $tanggal_log,
              'log_location' => $log_lokasi,
              'log_data' => $logdata,
              'log_status' => 'I',
              'log_username' => $user
            ]);

            $pdo->commit();
            echo json_encode(['status' => 'success']);
        } catch (\Exception $e) {
            $pdo->rollBack();
            echo json_encode(['status' => 'error', 'message' => 'Terjadi kesalahan saat memproses data: ' . $e->getMessage()]);
        }
        exit();
    }

    public function postRollbackPenyusutan()
    {
        $this->_initPenyusutan();
        $periode = $_POST['periode'] ?? '';

        if (empty($periode)) {
            echo json_encode(['status' => 'error', 'message' => 'Periode tidak boleh kosong!']);
            exit();
        }

        // Fetch all logs for this period
        $logs = $this->db('rsns_custom_logistik_non_medis_aset_penyusutan')
                   ->where('periode', $periode)
                   ->toArray();

        if (empty($logs)) {
            echo json_encode(['status' => 'error', 'message' => 'Riwayat penyusutan untuk periode ini tidak ditemukan!']);
            exit();
        }

        $no_jurnal = $logs[0]['no_jurnal'] ?? null;

        $pdo = $this->db()->pdo();
        $pdo->beginTransaction();

        try {
            // Revert each asset cache
            foreach ($logs as $log) {
                $asset = $this->db('rsns_custom_logistik_non_medis_aset')
                           ->where('kode_aset', $log['kode_aset'])
                           ->oneArray();
                if ($asset) {
                    $prev_akumulasi = max(0, $asset['akumulasi_penyusutan'] - $log['biaya_penyusutan']);
                    $prev_nilai_buku = $asset['nilai_buku'] + $log['biaya_penyusutan'];

                    // If it's 0 accumulated, tgl_penyusutan_terakhir is set to null
                    $tgl_terakhir = ($prev_akumulasi <= 0) ? null : date('Y-m-d');

                    $this->db('rsns_custom_logistik_non_medis_aset')
                       ->where('kode_aset', $log['kode_aset'])
                       ->update([
                           'akumulasi_penyusutan' => $prev_akumulasi,
                           'nilai_buku' => $prev_nilai_buku,
                           'tgl_penyusutan_terakhir' => $tgl_terakhir
                       ]);
                }
            }

            // Delete detail journals and journal in Keuangan
            if (!empty($no_jurnal)) {
                $this->db('mlite_detailjurnal')->where('no_jurnal', $no_jurnal)->delete();
                $this->db('mlite_jurnal')->where('no_jurnal', $no_jurnal)->delete();
            }

            // Delete log entries
            $this->db('rsns_custom_logistik_non_medis_aset_penyusutan')
               ->where('periode', $periode)
               ->delete();

            // Log to mlite_tracksql
            $user = $this->core->getUserInfo('username', null, true);
            $tanggal_log = date('Y-m-d H:i:s');
            $ip = $_SERVER['REMOTE_ADDR'] ?? 'Localhost';
            $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
            $hostname = $cek_hostname['hostname'] ?? 'Unknown';
            $log_lokasi = '' . $hostname . ' | ' . $ip . '';
            $logdata = 'Rolled back depreciation for period: ' . $periode . ' | Journal reverted: ' . $no_jurnal;

            $this->db('mlite_tracksql')->save([
              'log_id' => null,
              'log_modul' => 'logistik_non_medis_aset_penyusutan',
              'log_waktu' => $tanggal_log,
              'log_location' => $log_lokasi,
              'log_data' => $logdata,
              'log_status' => 'D',
              'log_username' => $user
            ]);

            $pdo->commit();
            echo json_encode(['status' => 'success']);
        } catch (\Exception $e) {
            $pdo->rollBack();
            echo json_encode(['status' => 'error', 'message' => 'Gagal melakukan rollback: ' . $e->getMessage()]);
        }
        exit();
    }

    public function postSavePenyusutanSettings()
    {
        $this->_initPenyusutan();

        $post_settings = $_POST['settings'] ?? [];

        $pdo = $this->db()->pdo();
        $pdo->beginTransaction();

        try {
            foreach ($post_settings as $key => $val) {
                $check = $this->db('mlite_settings')->where('module', 'logistik_non_medis')->where('field', $key)->oneArray();
                if ($check) {
                    $this->db('mlite_settings')
                       ->where('module', 'logistik_non_medis')
                       ->where('field', $key)
                       ->update(['value' => $val]);
                } else {
                    $this->db('mlite_settings')->save([
                      'module' => 'logistik_non_medis',
                      'field' => $key,
                      'value' => $val
                    ]);
                }
            }
            // Log to mlite_tracksql
            $user = $this->core->getUserInfo('username', null, true);
            $tanggal_log = date('Y-m-d H:i:s');
            $ip = $_SERVER['REMOTE_ADDR'] ?? 'Localhost';
            $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
            $hostname = $cek_hostname['hostname'] ?? 'Unknown';
            $log_lokasi = '' . $hostname . ' | ' . $ip . '';
            $logdata = 'Saved depreciation settings: ' . json_encode($post_settings);

            $this->db('mlite_tracksql')->save([
              'log_id' => null,
              'log_modul' => 'logistik_non_medis_aset_penyusutan_settings',
              'log_waktu' => $tanggal_log,
              'log_location' => $log_lokasi,
              'log_data' => $logdata,
              'log_status' => 'U',
              'log_username' => $user
            ]);

            $pdo->commit();
            echo json_encode(['status' => 'success']);
        } catch (\Exception $e) {
            $pdo->rollBack();
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan pengaturan: ' . $e->getMessage()]);
        }
        exit();
    }

    public function anyRiwayatPenyusutan()
    {
        $this->_initPenyusutan();

        // Get periodic groups of calculations
        $query = $this->db()->pdo()->query("
          SELECT periode, tanggal_proses, no_jurnal, user_proses, 
                 SUM(harga_perolehan) as total_harga,
                 SUM(biaya_penyusutan) as total_penyusutan,
                 COUNT(kode_aset) as total_aset
          FROM rsns_custom_logistik_non_medis_aset_penyusutan
          GROUP BY periode
          ORDER BY periode DESC
      ");
        $query->execute();
        $riwayat = $query->fetchAll(\PDO::FETCH_ASSOC);

        echo $this->draw('aset.penyusutan.riwayat.html', [
          'riwayat' => $riwayat
        ]);
        exit();
    }

    public function anyDetailRiwayatPenyusutan()
    {
        $this->_initPenyusutan();
        $periode = $_POST['periode'] ?? '';

        $details = $this->db('rsns_custom_logistik_non_medis_aset_penyusutan')
                      ->join('rsns_custom_logistik_non_medis_aset', 'rsns_custom_logistik_non_medis_aset.kode_aset=rsns_custom_logistik_non_medis_aset_penyusutan.kode_aset')
                      ->where('periode', $periode)
                      ->toArray();

        $units_array = $this->db('rsns_custom_logistik_non_medis_unit')->toArray();
        $units = [];
        foreach ($units_array as $u) {
            $units[$u['kode_unit']] = $u['nama_unit'];
        }

        foreach ($details as &$d) {
            $d['nama_unit'] = $units[$d['kode_unit']] ?? '-';
        }

        echo $this->draw('aset.penyusutan.riwayat.detail.html', [
          'details' => $details,
          'periode' => $periode
        ]);
        exit();
    }

    private function _initAsetPemeliharaan()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_aset_pemeliharaan` (
        `id` int(11) NOT NULL AUTO_INCREMENT,
        `kode_pemeliharaan` varchar(50) NOT NULL,
        `kode_aset` varchar(50) NOT NULL,
        `jenis_pemeliharaan` enum('Preventive','Corrective') NOT NULL,
        `tanggal_direncanakan` date NOT NULL,
        `tanggal_pelaksanaan` datetime DEFAULT NULL,
        `nama_kegiatan` varchar(200) NOT NULL,
        `deskripsi` text DEFAULT NULL,
        `frekuensi` enum('Sekali Saja','1 Bulan','3 Bulan','6 Bulan','1 Tahun','Kustom') DEFAULT 'Sekali Saja',
        `hari_kustom` int(11) DEFAULT 0,
        `prioritas` enum('Rendah','Sedang','Tinggi','Darurat') DEFAULT 'Sedang',
        `kode_rekanan` varchar(50) DEFAULT NULL,
        `nama_teknisi` varchar(150) DEFAULT NULL,
        `tindakan_perbaikan` text DEFAULT NULL,
        `status_kondisi_akhir` enum('Baik','Rusak Ringan','Rusak Berat') DEFAULT NULL,
        `biaya_jasa` double DEFAULT 0,
        `biaya_sparepart` double DEFAULT 0,
        `detail_sparepart` text DEFAULT NULL,
        `total_biaya` double DEFAULT 0,
        `status` enum('Jadwal','Menunggu','Diproses','Selesai','Dibatalkan') DEFAULT 'Jadwal',
        `user_input` varchar(50) NOT NULL,
        `tgl_input` datetime NOT NULL,
        PRIMARY KEY (`id`),
        UNIQUE KEY `kode_pemeliharaan` (`kode_pemeliharaan`),
        KEY `kode_aset` (`kode_aset`),
        KEY `status` (`status`),
        KEY `tanggal_direncanakan` (`tanggal_direncanakan`)
      ) ENGINE=InnoDB DEFAULT CHARSET=latin1;");
    }

    private function _generateKodeJadwal()
    {
        $prefix = 'PMJ-' . date('Ym') . '-';
        $last = $this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')
                   ->where('kode_pemeliharaan', 'LIKE', $prefix . '%')
                   ->desc('kode_pemeliharaan')
                   ->limit(1)
                   ->oneArray();

        if ($last) {
            $last_num = (int) substr($last['kode_pemeliharaan'], -4);
            $next_num = str_pad($last_num + 1, 4, '0', STR_PAD_LEFT);
        } else {
            $next_num = '0001';
        }

        return $prefix . $next_num;
    }

    private function _generateKodeWO()
    {
        $prefix = 'WO-' . date('Ym') . '-';
        $last = $this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')
                   ->where('kode_pemeliharaan', 'LIKE', $prefix . '%')
                   ->desc('kode_pemeliharaan')
                   ->limit(1)
                   ->oneArray();

        if ($last) {
            $last_num = (int) substr($last['kode_pemeliharaan'], -4);
            $next_num = str_pad($last_num + 1, 4, '0', STR_PAD_LEFT);
        } else {
            $next_num = '0001';
        }

        return $prefix . $next_num;
    }

    private function _generateKodeAsetPemeliharaan()
    {
        $prefix = 'LOG-' . date('Ym') . '-';
        $last = $this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')
                   ->where('kode_pemeliharaan', 'LIKE', $prefix . '%')
                   ->desc('kode_pemeliharaan')
                   ->limit(1)
                   ->oneArray();

        $last_num = $last ? (int) substr($last['kode_pemeliharaan'], -4) : 0;
        return $prefix . str_pad($last_num + 1, 4, '0', STR_PAD_LEFT);
    }

    public function getAsetPemeliharaan()
    {
        $this->_initAsetPemeliharaan();
        $this->_addHeaderFiles();

        $rekanan = $this->db('rsns_custom_logistik_non_medis_rekanan_jasa')->where('status', 'Aktif')->toArray();

        return $this->draw('aset.pemeliharaan.html', [
          'rekanan' => $rekanan,
          'current_date' => date('Y-m-d')
        ]);
    }

    public function anyDisplayAsetPemeliharaanDashboard()
    {
        $this->_initAsetPemeliharaan();
        $today = date('Y-m-d');
        $year = date('Y');
        $month = date('m');

        // Count PM Overdue
        $overdue_pm_count = count($this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')
                                     ->where('status', 'Jadwal')
                                     ->where('tanggal_direncanakan', '<=', $today)
                                     ->toArray());

        // Count Active WOs
        $active_wo_count = count($this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')
                                    ->where('status', 'IN', ['Menunggu', 'Diproses'])
                                    ->toArray());

        // Count Corrective Completed this Month
        $corrective_count = count($this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')
                                     ->where('status', 'Selesai')
                                     ->where('jenis_pemeliharaan', 'Corrective')
                                     ->where('tanggal_pelaksanaan', 'LIKE', $year . '-' . $month . '%')
                                     ->toArray());

        // Sum Maintenance Cost this Year
        $cost_query = $this->db()->pdo()->prepare("SELECT SUM(total_biaya) as total FROM rsns_custom_logistik_non_medis_aset_pemeliharaan WHERE status = 'Selesai' AND YEAR(tanggal_pelaksanaan) = :year");
        $cost_query->execute(['year' => $year]);
        $cost_res = $cost_query->fetch(\PDO::FETCH_ASSOC);
        $total_cost = $cost_res['total'] ?? 0;

        // Fetch Overdue PM schedules
        $overdue_pms = $this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')
                           ->join('rsns_custom_logistik_non_medis_aset', 'rsns_custom_logistik_non_medis_aset.kode_aset=rsns_custom_logistik_non_medis_aset_pemeliharaan.kode_aset')
                           ->select('rsns_custom_logistik_non_medis_aset_pemeliharaan.*')
                           ->select('rsns_custom_logistik_non_medis_aset.nama_aset')
                           ->where('rsns_custom_logistik_non_medis_aset_pemeliharaan.status', 'Jadwal')
                           ->where('rsns_custom_logistik_non_medis_aset_pemeliharaan.tanggal_direncanakan', '<=', $today)
                           ->desc('rsns_custom_logistik_non_medis_aset_pemeliharaan.tanggal_direncanakan')
                           ->toArray();

        // Fetch active WOs
        $active_wos = $this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')
                         ->join('rsns_custom_logistik_non_medis_aset', 'rsns_custom_logistik_non_medis_aset.kode_aset=rsns_custom_logistik_non_medis_aset_pemeliharaan.kode_aset')
                         ->select('rsns_custom_logistik_non_medis_aset_pemeliharaan.*')
                         ->select('rsns_custom_logistik_non_medis_aset.nama_aset')
                         ->where('rsns_custom_logistik_non_medis_aset_pemeliharaan.status', 'IN', ['Menunggu', 'Diproses'])
                         ->desc('rsns_custom_logistik_non_medis_aset_pemeliharaan.prioritas')
                         ->toArray();

        echo $this->draw('aset.pemeliharaan.dashboard.html', [
          'overdue_count' => $overdue_pm_count,
          'active_count' => $active_wo_count,
          'corrective_count' => $corrective_count,
          'total_cost' => $total_cost,
          'overdue_pms' => $overdue_pms,
          'active_wos' => $active_wos
        ]);
        exit();
    }
    public function anyAjaxSelect2Aset()
    {
        $q = $_GET['q'] ?? '';
        $query = $this->db('rsns_custom_logistik_non_medis_aset')
                      ->where('status', 'Aktif');
        if (!empty($q)) {
            $like = '%' . $q . '%';
            $query->where(function ($builder) use ($like) {
                $builder->like('nama_aset', $like)
                        ->orLike('kode_aset', $like);
            });
        }
        $assets = $query->asc('nama_aset')->limit(20)->toArray();
        $results = [];
        foreach ($assets as $asset) {
            $results[] = [
                'id' => $asset['kode_aset'],
                'text' => ($asset['nama_aset'] ?: $asset['kode_aset']) . ' (' . $asset['kode_aset'] . ')'
            ];
        }
        echo json_encode($results);
        exit();
    }

    public function anyDisplayBukuMaintenance()
    {
        $this->_initAsetPemeliharaan();
        $kode_aset = $_POST['kode_aset'] ?? '';

        if (empty($kode_aset)) {
            echo '<div class="alert alert-warning">Pilih aset terlebih dahulu.</div>';
            exit();
        }

        $logs = $this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')
            ->where('kode_aset', $kode_aset)
            ->where('status', 'Selesai')
            ->desc('tanggal_pelaksanaan')
            ->toArray();

        $aset = $this->db('rsns_custom_logistik_non_medis_aset')->where('kode_aset', $kode_aset)->oneArray();
        $nama_aset = $aset['nama_aset'] ?? $kode_aset;

        $html = '<div class="panel panel-default">';
        $html .= '<div class="panel-heading"><i class="fa fa-book"></i> Riwayat Perbaikan: <strong>' . htmlspecialchars($nama_aset) . '</strong></div>';
        $html .= '<div class="panel-body"><div class="table-responsive"><table class="table table-bordered table-striped table-hover">';
        $html .= '<thead><tr><th style="width:50px;">NO</th><th style="width:120px;">TANGGAL</th><th>KETERANGAN PERBAIKAN</th><th>PARAF TEKNISI</th></tr></thead>';
        $html .= '<tbody>';
        
        if (empty($logs)) {
            $html .= '<tr><td colspan="4" class="text-center text-muted">Belum ada catatan perbaikan untuk mesin ini.</td></tr>';
        } else {
            foreach ($logs as $i => $log) {
                $tanggal = date('d/m/Y', strtotime($log['tanggal_pelaksanaan']));
                $ket = htmlspecialchars($log['tindakan_perbaikan'] ?: $log['nama_kegiatan']);
                $teknisi = htmlspecialchars($log['nama_teknisi']);
                $no = $i + 1;
                $html .= "<tr><td class='text-center'>{$no}</td><td>{$tanggal}</td><td>{$ket}</td><td>{$teknisi}</td></tr>";
            }
        }
        
        $html .= '</tbody></table></div></div></div>';
        echo $html;
        exit();
    }

