    public function postSaveBukuMaintenance()
    {
        $this->_initAsetPemeliharaan();
        $kode_aset = $_POST['kode_aset'] ?? '';
        $tanggal = $_POST['tanggal'] ?? date('Y-m-d');
        $keterangan = $_POST['keterangan'] ?? '';
        $teknisi = $_POST['teknisi'] ?? '';

        if (empty($kode_aset) || empty($keterangan)) {
            echo json_encode(['status' => 'error', 'message' => 'Data tidak lengkap.']);
            exit();
        }

        $kode_pemeliharaan = $this->_generateKodeAsetPemeliharaan();

        $data = [
            'kode_pemeliharaan' => $kode_pemeliharaan,
            'kode_aset' => $kode_aset,
            'jenis_pemeliharaan' => 'Corrective',
            'tanggal_direncanakan' => $tanggal,
            'tanggal_pelaksanaan' => $tanggal . ' ' . date('H:i:s'),
            'nama_kegiatan' => 'Perbaikan Cepat / Harian',
            'tindakan_perbaikan' => $keterangan,
            'nama_teknisi' => $teknisi,
            'status' => 'Selesai',
            'user_input' => $this->core->getUserInfo('fullname'),
            'tgl_input' => date('Y-m-d H:i:s')
        ];

        if ($this->db('rsns_custom_logistik_non_medis_aset_pemeliharaan')->save($data)) {
            echo json_encode(['status' => 'success']);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan ke database.']);
        }
        exit();
    }

