    public function postSimpanHasilSensusUnit()
    {
        $this->_initAsetSensus();
        $nama_sensus = trim((string)($_POST['nama_sensus'] ?? ''));
        $kode_aset = trim((string)($_POST['kode_aset'] ?? ''));
        $keberadaan = trim((string)($_POST['keberadaan'] ?? ''));
        $kondisi = trim((string)($_POST['kondisi'] ?? 'Baik'));
        $catatan = trim((string)($_POST['catatan_temuan'] ?? ''));
        if ($nama_sensus === '' || $kode_aset === '' || !in_array($keberadaan, ['Ada', 'Tidak Ada'], true)) {
            echo json_encode(['status'=>'error', 'message'=>'Periode, aset, dan keberadaan wajib diisi.']); exit();
        }
        if ($keberadaan === 'Tidak Ada' && $catatan === '') {
            echo json_encode(['status'=>'error', 'message'=>'Catatan wajib diisi jika aset tidak ditemukan.']); exit();
        }
        if (!in_array($kondisi, ['Baik', 'Rusak Ringan', 'Rusak Berat'], true)) {
            echo json_encode(['status'=>'error', 'message'=>'Kondisi aset tidak valid.']); exit();
        }
        $row = $this->db('rsns_custom_logistik_non_medis_aset_sensus')->where('nama_sensus', $nama_sensus)->where('kode_aset', $kode_aset)->oneArray();
        if (!$row || ($row['status_sensus_periode'] ?? '') === 'Selesai') {
            echo json_encode(['status'=>'error', 'message'=>'Kertas kerja tidak ditemukan atau periode sudah selesai.']); exit();
        }
        $user = $this->core->getUserInfo('username', null, true);
        $update = ['catatan_temuan'=>$catatan, 'tanggal_scan'=>date('Y-m-d H:i:s'), 'petugas_scan'=>$user, 'status_penyesuaian'=>'Belum Disesuaikan'];
        if ($keberadaan === 'Tidak Ada') {
            $update += ['status_sensus_item'=>'Tidak Ditemukan', 'fisik_kode_unit'=>null, 'fisik_kode_lokasi'=>null, 'fisik_status_kondisi'=>null];
        } else {
            $status = $kondisi === ($row['sistem_status_kondisi'] ?? 'Baik') ? 'Sesuai' : 'Selisih Kondisi';
            $update += ['status_sensus_item'=>$status, 'fisik_kode_unit'=>$row['sistem_kode_unit'], 'fisik_kode_lokasi'=>$row['sistem_kode_lokasi'], 'fisik_status_kondisi'=>$kondisi];
            if ($status === 'Sesuai') $update['status_penyesuaian'] = 'Sudah Disesuaikan';
        }
        $ok = $this->db('rsns_custom_logistik_non_medis_aset_sensus')->where('id', $row['id'])->update($update);
        if ($ok) {
            $this->_logAction('logistik_non_medis_aset_sensus', $nama_sensus . ' | ' . $kode_aset . ' | Keberadaan: ' . $keberadaan . ' | Kondisi: ' . $kondisi . ' | ' . $catatan, 'U');
            echo json_encode(['status'=>'success', 'message'=>'Hasil pemeriksaan aset berhasil disimpan.']);
        } else echo json_encode(['status'=>'error', 'message'=>'Hasil pemeriksaan gagal disimpan.']);
        exit();
    }

    public function postSimpanCatatanSensusUnit()
    {
        $this->_initAsetSensus();
        $nama_sensus = trim((string)($_POST['nama_sensus'] ?? ''));
        $catatan = trim((string)($_POST['catatan_tambahan'] ?? ''));
        if ($nama_sensus === '') { echo json_encode(['status'=>'error','message'=>'Pilih periode sensus.']); exit(); }
        $ok = $this->db('rsns_custom_logistik_non_medis_aset_sensus')->where('nama_sensus', $nama_sensus)->update(['catatan_tambahan'=>$catatan]);
        echo json_encode($ok ? ['status'=>'success','message'=>'Catatan unit berhasil disimpan.'] : ['status'=>'error','message'=>'Catatan gagal disimpan.']);
        exit();
    }

    public function postEksekusiPenyesuaian()
    {
        $this->_initAsetSensus();
        $nama_sensus = $_POST['nama_sensus'] ?? '';
        $kode_aset = $_POST['kode_aset'] ?? '';

        if (empty($nama_sensus)) {
            echo json_encode(['status' => 'error', 'message' => 'Nama Sensus wajib ditentukan!']);
            exit();
        }

        $query = $this->db('rsns_custom_logistik_non_medis_aset_sensus')
                    ->where('nama_sensus', $nama_sensus)
                    ->where('status_penyesuaian', 'Belum Disesuaikan')
                    ->where('status_sensus_item', '!=', 'Belum Sensus');

        if (!empty($kode_aset)) {
            $query->where('kode_aset', $kode_aset);
        }

        $items = $query->toArray();
        if (empty($items)) {
            echo json_encode(['status' => 'error', 'message' => 'Tidak ada temuan sensus yang perlu disesuaikan untuk kriteria ini.']);
            exit();
        }

        $user = $this->core->getUserInfo('username', null, true);
        $tgl_sekarang = date('Y-m-d H:i:s');

        $pdo = $this->db()->pdo();
        $pdo->beginTransaction();

        try {
            foreach ($items as $item) {
                if ($item['status_sensus_item'] == 'Tidak Ditemukan') {
                    throw new \RuntimeException('Aset ' . $item['kode_aset'] . ' tidak ditemukan. Lakukan investigasi dan proses penghapusan aset terpisah; data master tidak diubah otomatis.');
                } elseif (in_array($item['status_sensus_item'], ['Sesuai', 'Selisih Lokasi', 'Selisih Kondisi', 'Aset Baru'])) {
                    $update_master = [];
                    if (!empty($item['fisik_kode_unit'])) {
                        $update_master['kode_unit'] = $item['fisik_kode_unit'];
                    }
                    if (!empty($item['fisik_kode_lokasi'])) {
                        $update_master['kode_lokasi'] = $item['fisik_kode_lokasi'];
                    }
                    if (!empty($item['fisik_status_kondisi'])) {
                        $update_master['status_kondisi'] = $item['fisik_status_kondisi'];
                    }

                    if (!empty($update_master)) {
                        $this->db('rsns_custom_logistik_non_medis_aset')
                           ->where('kode_aset', $item['kode_aset'])
                           ->update($update_master);
                    }
                }

                $this->db('rsns_custom_logistik_non_medis_aset_sensus')
                   ->where('id', $item['id'])
                   ->update([
                       'status_penyesuaian' => 'Sudah Disesuaikan',
                       'tgl_penyesuaian' => $tgl_sekarang,
                       'user_penyesuaian' => $user
                   ]);

                $this->db('mlite_tracksql')->save([
                  'log_id' => null,
                  'log_modul' => 'logistik_non_medis_aset_sensus_penyesuaian',
                  'log_waktu' => $tgl_sekarang,
                  'log_location' => $_SERVER['REMOTE_ADDR'] ?? 'Localhost',
                  'log_data' => $item['kode_aset'] . ' | Adjusted to: Unit=' . $item['fisik_kode_unit'] . ', Cond=' . $item['fisik_status_kondisi'] . ' via ' . $nama_sensus,
                  'log_status' => 'U',
                  'log_username' => $user
                ]);
            }

            $pdo->commit();
            echo json_encode(['status' => 'success']);
        } catch (\Exception $e) {
            $pdo->rollBack();
            echo json_encode(['status' => 'error', 'message' => 'Gagal mengeksekusi penyesuaian: ' . $e->getMessage()]);
        }
        exit();
    }

    public function postSignSertifikat()
    {
        $this->_initAsetSensus();
        $nama_sensus = $_POST['nama_sensus'] ?? '';
        $role_sign = $_POST['role_sign'] ?? '';
        $signature_name = $_POST['signature_name'] ?? '';

        if (empty($nama_sensus) || empty($role_sign) || empty($signature_name)) {
            echo json_encode(['status' => 'error', 'message' => 'Data tandatangan tidak lengkap!']);
            exit();
        }

        $update_fields = [];
        if ($role_sign == 'petugas') {
            $update_fields['ttd_petugas'] = $signature_name;
        } elseif ($role_sign == 'ka_unit') {
            $update_fields['ttd_ka_unit'] = $signature_name;
            $update_fields['status_sertifikasi'] = 'Disetujui Ka Unit';
        } elseif ($role_sign == 'ka_logistik') {
            $update_fields['ttd_ka_logistik'] = $signature_name;
            $update_fields['status_sertifikasi'] = 'Sertifikasi Selesai';
            $update_fields['status_sensus_periode'] = 'Selesai';
            $update_fields['no_sertifikat'] = 'BAHS/' . date('Ymd') . '/' . mt_rand(100, 999);
            $update_fields['tanggal_sertifikat'] = date('Y-m-d');
        }

        $query = $this->db('rsns_custom_logistik_non_medis_aset_sensus')
                   ->where('nama_sensus', $nama_sensus)
                   ->update($update_fields);

        if ($query) {
            // Log to mlite_tracksql
            $user = $this->core->getUserInfo('username', null, true) ?: ($_SESSION['mlite_user'] ?? 'admin');
            $tanggal_log = date('Y-m-d H:i:s');
            $ip = $_SERVER['REMOTE_ADDR'] ?? 'Localhost';
            $cek_hostname = $this->db('rsns_custom_hostsname_pc')->where('ip', $ip)->oneArray();
            $hostname = $cek_hostname['hostname'] ?? 'Unknown';
            $log_lokasi = '' . $hostname . ' | ' . $ip . '';
            $logdata = '' . $nama_sensus . ' | Role Sign: ' . $role_sign . ' | Signature: ' . $signature_name;

            $this->db('mlite_tracksql')->save([
              'log_id' => null,
              'log_modul' => 'logistik_non_medis_aset_sensus',
              'log_waktu' => $tanggal_log,
              'log_location' => $log_lokasi,
              'log_data' => $logdata,
              'log_status' => 'U',
              'log_username' => $user
            ]);

            echo json_encode(['status' => 'success']);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Gagal menyimpan persetujuan tanda tangan digital.']);
        }
        exit();
    }

    public function anyCetakKertasKerjaSensus()
    {
        $this->_initAsetSensus();
        $nama_sensus = trim((string)($_GET['nama_sensus'] ?? ''));
        $items = $this->db('rsns_custom_logistik_non_medis_aset_sensus')->where('nama_sensus', $nama_sensus)->asc('kode_aset')->toArray();
        if ($nama_sensus === '' || empty($items)) { echo 'Data sensus tidak ditemukan.'; exit(); }
        $belum = count(array_filter($items, function ($row) { return ($row['status_sensus_item'] ?? '') === 'Belum Sensus'; }));
        if ($belum > 0) { echo '<div style="font-family:Arial;padding:30px"><h3>Kertas kerja belum dapat dicetak</h3><p>Masih ada ' . $belum . ' aset yang belum ditandai Ada atau Tidak Ada.</p><button onclick="history.back()">Kembali</button></div>'; exit(); }
        $meta = $items[0];
        $nama_unit = $this->_namaUnitAset((string)($meta['kode_unit_sensus'] ?: $meta['sistem_kode_unit']));
        foreach ($items as &$row) {
            $aset = $this->db('rsns_custom_logistik_non_medis_aset')->where('kode_aset', $row['kode_aset'])->oneArray();
            $row['nama_aset'] = $aset['nama_aset'] ?? 'Aset Tidak Dikenal';
            $row['serial_number'] = $aset['serial_number'] ?? '-';
            $row['keberadaan'] = $row['status_sensus_item'] === 'Tidak Ditemukan' ? 'Tidak Ada' : 'Ada';
        }
        echo $this->draw('aset.sensus.kertas_kerja.print.html', ['meta'=>$meta, 'items'=>$items, 'nama_unit'=>$nama_unit, 'logo'=>$this->settings->get('settings.logo')]);
        exit();
    }

    public function anyCetakBAHS()
    {
        $this->_initAsetSensus();
        $nama_sensus = $_GET['nama_sensus'] ?? '';

        if (empty($nama_sensus)) {
            echo "Nama Sensus tidak valid.";
            exit();
        }

        $items = $this->db('rsns_custom_logistik_non_medis_aset_sensus')
                    ->where('nama_sensus', $nama_sensus)
                    ->toArray();

        if (empty($items)) {
            echo "Tidak ada data sensus.";
            exit();
        }

        $meta = $items[0];

        $total_terdaftar = count($items);
        $total_sesuai = count(array_filter($items, function ($i) {
            return $i['status_sensus_item'] == 'Sesuai';
        }));
        $total_selisih_lokasi = count(array_filter($items, function ($i) {
            return $i['status_sensus_item'] == 'Selisih Lokasi';
        }));
        $total_selisih_kondisi = count(array_filter($items, function ($i) {
            return $i['status_sensus_item'] == 'Selisih Kondisi';
        }));
        $total_tidak_ditemukan = count(array_filter($items, function ($i) {
            return $i['status_sensus_item'] == 'Tidak Ditemukan';
        }));
        $total_aset_baru = count(array_filter($items, function ($i) {
            return $i['status_sensus_item'] == 'Aset Baru';
        }));

        foreach ($items as &$row) {
            $aset = $this->db('rsns_custom_logistik_non_medis_aset')->where('kode_aset', $row['kode_aset'])->oneArray();
            $row['nama_aset'] = $aset['nama_aset'] ?? 'Aset Tidak Dikenal';

            $row['sistem_nama_unit'] = $this->_namaUnitAset((string)$row['sistem_kode_unit']);

            if (!empty($row['fisik_kode_unit'])) {
                $row['fisik_nama_unit'] = $this->_namaUnitAset((string)$row['fisik_kode_unit']);
            } else {
                $row['fisik_nama_unit'] = '-';
            }
        }

        echo $this->draw('aset.sensus.bahs.html', [
          'meta' => $meta,
          'items' => $items,
          'total_terdaftar' => $total_terdaftar,
          'total_sesuai' => $total_sesuai,
          'total_selisih_lokasi' => $total_selisih_lokasi,
          'total_selisih_kondisi' => $total_selisih_kondisi,
          'total_tidak_ditemukan' => $total_tidak_ditemukan,
          'total_aset_baru' => $total_aset_baru,
          'logo' => $this->settings->get('settings.logo')
        ]);
        exit();
    }

