    private function _initOpnameV2()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_opname_v2_penyesuaian` (
          `id` bigint NOT NULL AUTO_INCREMENT,
          `no_referensi` varchar(80) NOT NULL,
          `tgl_penyesuaian` datetime NOT NULL,
          `kode_item` varchar(50) NOT NULL,
          `stok_sistem` double NOT NULL DEFAULT 0,
          `stok_fisik` double NOT NULL DEFAULT 0,
          `selisih` double NOT NULL DEFAULT 0,
          `catatan` text DEFAULT NULL,
          `user_input` varchar(100) DEFAULT NULL,
          PRIMARY KEY (`id`),
          KEY `kode_item` (`kode_item`),
          KEY `tgl_penyesuaian` (`tgl_penyesuaian`)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");
    }

    public function anyDisplayOpnameV2()
    {
        $tgl_awal = $_POST['tgl_awal'] ?? date('Y-m-01');
        $tgl_akhir = $_POST['tgl_akhir'] ?? date('Y-m-d');
        $kategori = trim((string)($_POST['kategori'] ?? ''));
        $cari = trim((string)($_POST['cari'] ?? ''));
        $halaman = max(1, (int)($_POST['halaman'] ?? 1));
        $perpage = 30;
        $offset = ($halaman - 1) * $perpage;
        $db = $this->db()->pdo();
        // Placeholder untuk input barang baru bukan persediaan master dan tidak boleh ikut opname/penyesuaian.
        $where = " WHERE (b.status = 'Aktif' OR b.status IS NULL OR b.status = '')
                   AND b.kode_item <> 'BRG-BARU'
                   AND UPPER(COALESCE(b.nama_barang, '')) <> '*** BARANG BARU / LAINNYA ***' ";
        $params = [':tgl_awal' => $tgl_awal, ':tgl_akhir' => $tgl_akhir];
        if ($kategori !== '') {
            $where .= ' AND b.kode_kategori = :kategori';
            $params[':kategori'] = $kategori;
        }
        if ($cari !== '') {
            $where .= ' AND (b.kode_item LIKE :cari OR b.nama_barang LIKE :cari)';
            $params[':cari'] = '%' . $cari . '%';
        }
        $count = $db->prepare("SELECT COUNT(*) FROM rsns_custom_logistik_non_medis_master_barang b {$where}");
        $count->execute(array_filter($params, function ($key) { return !in_array($key, [':tgl_awal', ':tgl_akhir'], true); }, ARRAY_FILTER_USE_KEY));
        $jumlah_data = (int)$count->fetchColumn();
        $jml_halaman = max(1, (int)ceil($jumlah_data / $perpage));
        $halaman = min($halaman, $jml_halaman);
        $offset = ($halaman - 1) * $perpage;
        $sql = "SELECT b.kode_item, b.nama_barang, b.satuan_dasar AS satuan,
                  COALESCE(b.harga_referensi, 0) AS harga_satuan,
                  COALESCE(NULLIF(k.nama_kategori, ''), 'Tanpa Kategori') AS kategori,
                  COALESCE(SUM(CASE WHEN DATE(ks.tgl_transaksi) < :tgl_awal THEN ks.qty_masuk - ks.qty_keluar ELSE 0 END), 0) AS stok_awal_jml,
                  COALESCE(SUM(CASE WHEN DATE(ks.tgl_transaksi) BETWEEN :tgl_awal AND :tgl_akhir THEN ks.qty_masuk ELSE 0 END), 0) AS masuk_jml,
                  COALESCE(SUM(CASE WHEN DATE(ks.tgl_transaksi) BETWEEN :tgl_awal AND :tgl_akhir THEN ks.qty_keluar ELSE 0 END), 0) AS keluar_jml,
                  COALESCE((SELECT SUM(sb.stok) FROM rsns_custom_logistik_non_medis_stok_batch sb WHERE sb.kode_item = b.kode_item), 0) AS stok_sistem_saat_ini
                FROM rsns_custom_logistik_non_medis_master_barang b
                LEFT JOIN rsns_custom_logistik_non_medis_kategori k ON k.kode_kategori = b.kode_kategori
                LEFT JOIN rsns_custom_logistik_non_medis_kartu_stok ks ON ks.kode_item = b.kode_item AND DATE(ks.tgl_transaksi) <= :tgl_akhir
                {$where}
                GROUP BY b.kode_item, b.nama_barang, b.satuan_dasar, b.harga_referensi, k.nama_kategori
                ORDER BY k.nama_kategori ASC, b.nama_barang ASC
                LIMIT {$offset}, {$perpage}";
        $stmt = $db->prepare($sql);
        $stmt->execute($params);
        $results = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        foreach ($results as &$item) {
            $item['stok_akhir_jml'] = (float)$item['stok_awal_jml'] + (float)$item['masuk_jml'] - (float)$item['keluar_jml'];
            foreach (['stok_awal_jml', 'masuk_jml', 'keluar_jml', 'stok_akhir_jml'] as $field) {
                $item[str_replace('_jml', '_harga', $field)] = (float)$item[$field] * (float)$item['harga_satuan'];
            }
        }
        echo $this->draw('gudang.opnamev2.display.html', compact('results', 'tgl_awal', 'tgl_akhir', 'halaman', 'jml_halaman', 'jumlah_data', 'perpage'));
        exit();
    }

    public function postSimpanPenyesuaianOpnameV2()
    {
        $this->_initStok();
        $this->_initOpnameV2();
        $kode_item = trim((string)($_POST['kode_item'] ?? ''));
        $stok_fisik = $_POST['stok_fisik'] ?? null;
        $catatan = trim((string)($_POST['catatan'] ?? ''));
        $user = $this->core->getUserInfo('username', null, true);
        $roleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $user)->oneArray();
        if (!in_array($roleData['role'] ?? '', ['admin', 'logistik', 'gudang'], true)) {
            echo json_encode(['status' => 'error', 'message' => 'Hanya Admin, Logistik, atau Gudang yang dapat melakukan penyesuaian stok.']); exit();
        }
        if ($kode_item === '' || $stok_fisik === null || !is_numeric($stok_fisik) || (float)$stok_fisik < 0) {
            echo json_encode(['status' => 'error', 'message' => 'Jumlah fisik wajib berupa angka nol atau lebih.']); exit();
        }
        if ($catatan === '') {
            echo json_encode(['status' => 'error', 'message' => 'Catatan penyesuaian wajib diisi untuk kebutuhan audit.']); exit();
        }
        $pdo = $this->db()->pdo();
        try {
            $pdo->beginTransaction();
            $itemStmt = $pdo->prepare('SELECT kode_item, nama_barang, COALESCE(harga_referensi, 0) harga FROM rsns_custom_logistik_non_medis_master_barang WHERE kode_item = ? FOR UPDATE');
            $itemStmt->execute([$kode_item]);
            $item = $itemStmt->fetch(\PDO::FETCH_ASSOC);
            if (!$item) throw new \RuntimeException('Barang tidak ditemukan.');
            $batchStmt = $pdo->prepare('SELECT * FROM rsns_custom_logistik_non_medis_stok_batch WHERE kode_item = ? AND stok > 0 ORDER BY tgl_terima ASC, kode_lokasi ASC, batch_no ASC FOR UPDATE');
            $batchStmt->execute([$kode_item]);
            $batches = $batchStmt->fetchAll(\PDO::FETCH_ASSOC);
            $stok_sistem = array_sum(array_map(function ($row) { return (float)$row['stok']; }, $batches));
            $target = (float)$stok_fisik;
            $selisih = $target - $stok_sistem;
            $no_ref = 'OPV2/' . date('YmdHis') . '/' . substr(preg_replace('/[^A-Za-z0-9]/', '', $kode_item), 0, 20);
            if (abs($selisih) > 0.00001) {
                if ($selisih > 0) {
                    $lokasi = 'OPNAME-V2'; $batch_no = 'ADJ-' . date('Ymd');
                    $check = $pdo->prepare('SELECT stok, harga_beli FROM rsns_custom_logistik_non_medis_stok_batch WHERE kode_item=? AND kode_lokasi=? AND batch_no=? FOR UPDATE');
                    $check->execute([$kode_item, $lokasi, $batch_no]);
                    $existing = $check->fetch(\PDO::FETCH_ASSOC);
                    $akhir = (float)($existing['stok'] ?? 0) + $selisih;
                    if ($existing) {
                        $pdo->prepare('UPDATE rsns_custom_logistik_non_medis_stok_batch SET stok=? WHERE kode_item=? AND kode_lokasi=? AND batch_no=?')->execute([$akhir, $kode_item, $lokasi, $batch_no]);
                    } else {
                        $pdo->prepare('INSERT INTO rsns_custom_logistik_non_medis_stok_batch (kode_item,kode_lokasi,batch_no,tgl_terima,harga_beli,stok) VALUES (?,?,?,?,?,?)')->execute([$kode_item, $lokasi, $batch_no, date('Y-m-d'), (float)$item['harga'], $akhir]);
                    }
                    $this->_recordKartuStok($kode_item, $lokasi, $batch_no, 'Opname', $no_ref, $selisih, 0, $akhir, (float)$item['harga']);
                } else {
                    $sisa = abs($selisih);
                    foreach ($batches as $batch) {
                        if ($sisa <= 0) break;
                        $ambil = min($sisa, (float)$batch['stok']);
                        $akhir = (float)$batch['stok'] - $ambil;
                        $pdo->prepare('UPDATE rsns_custom_logistik_non_medis_stok_batch SET stok=? WHERE kode_item=? AND kode_lokasi=? AND batch_no=?')->execute([$akhir, $kode_item, $batch['kode_lokasi'], $batch['batch_no']]);
                        $this->_recordKartuStok($kode_item, $batch['kode_lokasi'], $batch['batch_no'], 'Opname', $no_ref, 0, $ambil, $akhir, (float)($batch['harga_beli'] ?? $item['harga']));
                        $sisa -= $ambil;
                    }
                }
            }
            $this->db('rsns_custom_logistik_non_medis_opname_v2_penyesuaian')->save(['no_referensi'=>$no_ref, 'tgl_penyesuaian'=>date('Y-m-d H:i:s'), 'kode_item'=>$kode_item, 'stok_sistem'=>$stok_sistem, 'stok_fisik'=>$target, 'selisih'=>$selisih, 'catatan'=>$catatan, 'user_input'=>$user]);
            $pdo->commit();
            $this->_logAction('logistik_non_medis_opname_v2', 'Penyesuaian ' . $kode_item . ' | Sistem: ' . $stok_sistem . ' | Fisik: ' . $target . ' | ' . $catatan, 'U');
            echo json_encode(['status'=>'success', 'message'=>'Penyesuaian ' . $item['nama_barang'] . ' tersimpan. Selisih: ' . $this->_formatQty($selisih) . '.']);
        } catch (\Throwable $e) {
            if ($pdo->inTransaction()) $pdo->rollBack();
            echo json_encode(['status'=>'error', 'message'=>$e->getMessage()]);
        }
        exit();
    }

    private function _notifyUser(string $username, string $message, string $type, string $no_sppb = ''): array
    {
        $username = trim($username);
        if ($username === '') {
            return [
              'username' => '',
              'in_app' => false,
              'wa' => ['status' => 'skipped', 'message' => 'Username penerima belum disetel.']
            ];
        }
        $this->_initNotifikasi();
        $approvalTypes = ['approval_ka_unit', 'approval_kasie', 'approval_kabid', 'konsul_kabid_umum', 'approval_selesai', 'approval_ditolak'];
        $notificationRoute = 'distribusisppb';
        if ($no_sppb !== '' && in_array($type, $approvalTypes, true)) {
            $requestType = $this->db('rsns_custom_logistik_non_medis_sppb')->where('no_sppb', $no_sppb)->oneArray();
            if (($requestType['jenis_permintaan'] ?? '') === 'Non Rutin') {
                $notificationRoute = 'distribusinonrutin';
            }
        }
        $notification = [
          'user_target' => $username,
          'pesan' => $message,
          'tipe' => $type,
          'url' => url(ADMIN . '/logistik_non_medis/' . $notificationRoute) . ($no_sppb !== '' ? '#sppb-' . rawurlencode($no_sppb) : ''),
          'is_read' => 0,
          'tgl_dibuat' => date('Y-m-d H:i:s')
        ];
        $inAppSaved = (bool)$this->db('rsns_custom_logistik_non_medis_notifikasi')->save($notification);
        if ($inAppSaved) {
            $this->_broadcastNotification($notification);
        }
        return [
          'username' => $username,
          'in_app' => $inAppSaved,
          'wa' => $this->_sendWaApprovalNotification($username, $type, $no_sppb)
        ];
    }

    private function _sendWaApprovalNotification(string $username, string $type, string $noSppb = ''): array
    {
        // WA hanya untuk event persetujuan dan nomor penerima harus aktif di Hak Akses.
        $allowed = ['approval_ka_unit', 'approval_kasie', 'approval_kabid', 'konsul_kabid_umum', 'approval_selesai', 'approval_ditolak'];
        if (!in_array($type, $allowed, true)) {
            return ['status' => 'skipped', 'message' => 'Jenis notifikasi ini tidak memakai WhatsApp.'];
        }

        $contact = $this->db('rsns_custom_logistik_non_medis_wa_contact')
                      ->where('username', $username)
                      ->where('aktif', 1)
                      ->oneArray();
        if (!$contact || empty($contact['nomor_wa'])) {
            return ['status' => 'skipped', 'message' => 'Nomor WhatsApp ' . $username . ' belum disetel atau belum diaktifkan di Hak Akses.'];
        }

        $number = preg_replace('/[^0-9]/', '', (string)$contact['nomor_wa']);
        if (strpos($number, '0') === 0) {
            $number = '62' . substr($number, 1);
        }
        if (strlen($number) < 10) {
            return ['status' => 'failed', 'message' => 'Nomor WhatsApp ' . $username . ' tidak valid.'];
        }
        $maskedNumber = substr($number, 0, 4) . str_repeat('*', max(0, strlen($number) - 7)) . substr($number, -3);

        // CEK WAHA DULU
        $wahaConfig = $this->db('rsns_custom_logistik_non_medis_waha_config')->where('id', 1)->oneArray() ?: [];
        if (!empty($wahaConfig['aktif'])) {
            $template = $this->db('rsns_custom_logistik_non_medis_waha_template')->where('tipe', $type)->oneArray() ?: [];
            if (empty($template['aktif'])) {
                return ['status' => 'skipped', 'message' => 'Template pesan WAHA ' . $type . ' sedang dinonaktifkan.'];
            }
            $message = trim((string)($template['pesan'] ?? ''));
            if ($message === '') {
                $message = '[RSNS] Ada permintaan logistik yang menunggu persetujuan. Silakan buka SIMRS untuk melihat detail.';
            }
            $detailMessage = $this->_buildWaApprovalDetailMessage($noSppb);
            $message = str_replace(['{no_sppb}', '{username}', '{detail_permintaan}'], [$noSppb !== '' ? $noSppb : '-', $username, $detailMessage], $message);
            if (strpos($message, 'Detail Permintaan Barang') === false) {
                $message .= $detailMessage;
            }

            $baseUrl = rtrim(trim((string)($wahaConfig['base_url'] ?? '')), '/');
            $apiKey = trim((string)($wahaConfig['api_key'] ?? ''));
            $session = trim((string)($wahaConfig['session_name'] ?? 'default'));

            if ($baseUrl === '') {
                return ['status' => 'failed', 'message' => 'URL WAHA belum disetel.'];
            }

            $recent = $this->db()->pdo()->prepare("SELECT COUNT(*) FROM rsns_custom_logistik_non_medis_waha_send_log WHERE username = :username AND tipe = :tipe AND COALESCE(no_sppb, '') = :no_sppb AND tgl_kirim >= DATE_SUB(NOW(), INTERVAL 15 MINUTE)");
            $recent->execute([':username' => $username, ':tipe' => $type, ':no_sppb' => $noSppb]);
            if ((int)$recent->fetchColumn() > 0) {
                return ['status' => 'skipped', 'message' => 'Pesan WAHA ke ' . $username . ' tidak dikirim ulang karena sudah terkirim dalam 15 menit terakhir.'];
            }

            $payload = [
              'chatId' => $number . '@c.us',
              'text' => $message,
              'session' => $session
            ];

            error_log("WAHA Debug Payload: " . json_encode($payload));

            $ch = curl_init($baseUrl . '/api/sendText');
            curl_setopt_array($ch, [
              CURLOPT_POST => true,
              CURLOPT_POSTFIELDS => json_encode($payload),
              CURLOPT_HTTPHEADER => [
                  'Content-Type: application/json',
                  'Accept: application/json',
                  'X-Api-Key: ' . $apiKey
              ],
              CURLOPT_RETURNTRANSFER => true,
              CURLOPT_CONNECTTIMEOUT => 2,
              CURLOPT_TIMEOUT => 2
            ]);
            $raw = curl_exec($ch);
            $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);

            error_log("WAHA Debug Response (HTTP $httpCode): " . $raw);

            if ($httpCode >= 200 && $httpCode < 300) {
                $this->db('rsns_custom_logistik_non_medis_waha_send_log')->save([
                  'username' => $username,
                  'tipe' => $type,
                  'no_sppb' => $noSppb !== '' ? $noSppb : null,
                  'tgl_kirim' => date('Y-m-d H:i:s'),
                  'status' => 'success',
                  'keterangan' => 'Sent to ' . $maskedNumber
                ]);
                return ['status' => 'success', 'message' => 'Notifikasi WAHA berhasil dikirim ke ' . $maskedNumber];
            } else {
                return ['status' => 'failed', 'message' => 'Pesan WAHA ke ' . $username . ' gagal dikirim (HTTP ' . $httpCode . ')'];
            }
        }

        // CEK FONNTE
        $template = $this->db('rsns_custom_logistik_non_medis_fonnte_template')->where('tipe', $type)->oneArray() ?: [];
        if (empty($template['aktif'])) {
            return ['status' => 'skipped', 'message' => 'Template pesan ' . $type . ' sedang dinonaktifkan.'];
        }
        $message = trim((string)($template['pesan'] ?? ''));
        if ($message === '') {
            $message = '[RSNS] Ada permintaan logistik yang menunggu persetujuan. Silakan buka SIMRS untuk melihat detail.';
        }
        $detailMessage = $this->_buildWaApprovalDetailMessage($noSppb);
        $message = str_replace(['{no_sppb}', '{username}', '{detail_permintaan}'], [$noSppb !== '' ? $noSppb : '-', $username, $detailMessage], $message);
        if (strpos($message, 'Detail Permintaan Barang') === false) {
            $message .= $detailMessage;
        }
        $config = $this->db('rsns_custom_logistik_non_medis_fonnte_config')->where('id', 1)->oneArray() ?: [];
        if (empty($config['aktif'])) {
            return ['status' => 'skipped', 'message' => 'Fonnte belum diaktifkan pada konfigurasi.'];
        }
        $fonnteToken = trim((string)($config['token'] ?? ''));
        if ($fonnteToken === '' || $fonnteToken === '-') {
            return ['status' => 'failed', 'message' => 'Token Fonnte belum disetel.'];
        }
        $recent = $this->db()->pdo()->prepare("SELECT COUNT(*) FROM rsns_custom_logistik_non_medis_fonnte_send_log WHERE username = :username AND tipe = :tipe AND COALESCE(no_sppb, '') = :no_sppb AND tgl_kirim >= DATE_SUB(NOW(), INTERVAL 15 MINUTE)");
        $recent->execute([':username' => $username, ':tipe' => $type, ':no_sppb' => $noSppb]);
        if ((int)$recent->fetchColumn() > 0) {
            return ['status' => 'skipped', 'message' => 'Pesan ke ' . $username . ' tidak dikirim ulang karena sudah terkirim dalam 15 menit terakhir.'];
        }
        $ch = curl_init('https://api.fonnte.com/send');
        if ($ch === false) {
            return ['status' => 'failed', 'message' => 'Gagal menyiapkan koneksi ke Fonnte.'];
        }
        $sendOptions = ['duration' => max(0, min(10, (int)($config['duration'] ?? 1))), 'delay' => max(0, min(10, (int)($config['delay'] ?? 0)))];
        curl_setopt_array($ch, [
          CURLOPT_POST => true,
          CURLOPT_POSTFIELDS => http_build_query(array_merge(['target' => $number, 'message' => $message], $sendOptions)),
          CURLOPT_HTTPHEADER => ['Authorization: ' . $fonnteToken],
          CURLOPT_RETURNTRANSFER => true,
          CURLOPT_CONNECTTIMEOUT => 5,
          CURLOPT_TIMEOUT => 10
        ]);
        $raw = curl_exec($ch);
        $curlError = curl_error($ch);
        $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
        if ($raw === false) {
            return ['status' => 'failed', 'message' => 'Fonnte tidak dapat dihubungi: ' . ($curlError !== '' ? $curlError : 'kesalahan koneksi.')];
        }
        $result = json_decode((string)$raw, true);
        $apiStatus = is_array($result) ? ($result['status'] ?? false) : false;
        $apiOk = $apiStatus === true || $apiStatus === 1 || $apiStatus === '1'
          || (is_string($apiStatus) && in_array(strtolower($apiStatus), ['true', 'success'], true));
        if ($httpCode < 200 || $httpCode >= 300 || !$apiOk) {
            $apiMessage = is_array($result) ? trim((string)($result['reason'] ?? $result['message'] ?? '')) : '';
            if ($apiMessage === '') {
                $apiMessage = 'respons API tidak valid (HTTP ' . $httpCode . ').';
            }
            return ['status' => 'failed', 'message' => 'Pesan ke ' . $username . ' gagal: ' . mb_substr($apiMessage, 0, 180)];
        }
        $this->db('rsns_custom_logistik_non_medis_fonnte_send_log')->save([
          'username' => $username,
          'tipe' => $type,
          'no_sppb' => $noSppb,
          'nomor' => $number,
          'tgl_kirim' => date('Y-m-d H:i:s')
        ]);
        return ['status' => 'sent', 'message' => 'Pesan WhatsApp terkirim ke ' . $username . ' (' . $maskedNumber . ').'];
    }

    private function _buildWaApprovalDetailMessage(string $noSppb): string
    {
        if ($noSppb === '') {
            return '';
        }

        $sppb = $this->db()->pdo()->prepare("SELECT s.no_sppb, s.tgl_sppb, s.kode_unit, s.jenis_permintaan, s.status, u.nama_unit
            FROM rsns_custom_logistik_non_medis_sppb s
            LEFT JOIN rsns_custom_logistik_non_medis_unit u ON u.kode_unit = s.kode_unit
            WHERE s.no_sppb = ? LIMIT 1");
        $sppb->execute([$noSppb]);
        $header = $sppb->fetch(\PDO::FETCH_ASSOC);
        if (!$header) {
            return "\n\nBuka daftar permintaan:\n" . url(ADMIN . '/logistik_non_medis/distribusisppb');
        }

        $itemsStmt = $this->db()->pdo()->prepare("SELECT s.kode_item, s.jumlah, s.jumlah_disetujui, s.satuan,
                COALESCE(NULLIF(s.nama_barang_manual, ''), b.nama_barang, s.kode_item) AS nama_barang
            FROM rsns_custom_logistik_non_medis_sppb s
            LEFT JOIN rsns_custom_logistik_non_medis_master_barang b ON b.kode_item = s.kode_item
            WHERE s.no_sppb = ? ORDER BY s.id ASC LIMIT 20");
        $itemsStmt->execute([$noSppb]);
        $items = $itemsStmt->fetchAll(\PDO::FETCH_ASSOC);

        $notificationRoute = (($header['jenis_permintaan'] ?? '') === 'Non Rutin') ? 'distribusinonrutin' : 'distribusisppb';
        $detail = "\n\n*Detail Permintaan Barang*"
            . "\nNo. SPPB: " . $noSppb
            . "\nUnit: " . ($header['nama_unit'] ?: ($header['kode_unit'] ?: '-'))
            . "\nTanggal: " . (!empty($header['tgl_sppb']) ? date('d/m/Y', strtotime($header['tgl_sppb'])) : '-')
            . "\nStatus: " . ($header['status'] ?: '-');

        if ($items) {
            $detail .= "\nBarang:";
            foreach ($items as $index => $item) {
                $jumlah = (float)($item['jumlah'] ?? 0);
                $jumlahText = rtrim(rtrim(number_format($jumlah, 2, ',', '.'), '0'), ',');
                $satuan = trim((string)($item['satuan'] ?? ''));
                $detail .= "\n" . ($index + 1) . '. ' . ($item['nama_barang'] ?: $item['kode_item']) . ' - ' . $jumlahText . ($satuan !== '' ? ' ' . $satuan : '');
            }
            if (count($items) >= 20) {
                $detail .= "\n...dan item lainnya.";
            }
        }

        $link = url(ADMIN . '/logistik_non_medis/' . $notificationRoute);
        return $detail . "\n\nBuka daftar permintaan:\n" . $link;
    }

    private function _notificationSummary(array $results): array
    {
        $sent = 0;
        $failed = 0;
        $skipped = 0;
        $inApp = 0;
        $details = [];
        foreach ($results as $result) {
            if (!empty($result['in_app'])) {
                $inApp++;
            }
            $wa = is_array($result['wa'] ?? null) ? $result['wa'] : ['status' => 'skipped', 'message' => 'Hasil WhatsApp tidak tersedia.'];
            $waStatus = (string)($wa['status'] ?? 'skipped');
            if ($waStatus === 'sent') {
                $sent++;
            } elseif ($waStatus === 'failed') {
                $failed++;
            } else {
                $skipped++;
            }
            $detail = trim((string)($wa['message'] ?? ''));
            if ($detail !== '' && !in_array($detail, $details, true)) {
                $details[] = $detail;
            }
        }
        if (!$results) {
            $details[] = 'Penerima notifikasi tidak ditemukan.';
        }
        $waStatus = $sent > 0 && ($failed > 0 || $skipped > 0)
          ? 'partial'
          : ($failed > 0 ? 'failed' : ($sent > 0 ? 'sent' : 'skipped'));
        $inAppMessage = $inApp > 0
          ? 'Notifikasi aplikasi tersimpan untuk ' . $inApp . ' penerima.'
          : 'Notifikasi aplikasi tidak tersimpan.';
        return [
          'wa_status' => $waStatus,
          'wa_sent' => $sent,
          'wa_failed' => $failed,
          'wa_skipped' => $skipped,
          'in_app_sent' => $inApp,
          'details' => array_slice($details, 0, 6),
          'message' => $inAppMessage . ' ' . implode(' | ', array_slice($details, 0, 6))
        ];
    }

    private function _notifyApprovalRecipients(string $targetRole, string $kodeUnit, string $noSppb, string $message, string $type): array
    {
        $this->_initNotifikasi();
        $roleRows = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('role', $targetRole)->toArray();
        $recipients = [];
        foreach ($roleRows as $roleRow) {
            $username = trim((string)($roleRow['username'] ?? ''));
            $scopes = array_values(array_filter(array_map('trim', explode(',', (string)($roleRow['kode_unit'] ?? '')))));
            if ($username === '' || !$scopes) {
                continue;
            }
            $allowedUnits = $this->getChildUnitCodes($scopes);
            if (in_array($kodeUnit, $allowedUnits, true)) {
                $recipients[$username] = true;
            }
        }

        // Admin tetap menjadi fallback agar pengajuan tidak senyap ketika mapping
        // pejabat belum disiapkan.
        if (!$recipients) {
            $admins = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('role', 'admin')->toArray();
            foreach ($admins as $admin) {
                $username = trim((string)($admin['username'] ?? ''));
                if ($username !== '') {
                    $recipients[$username] = true;
                }
            }
            if (!$recipients) {
                $recipients['admin'] = true;
            }
        }

        $results = [];
        foreach (array_keys($recipients) as $username) {
            $results[] = $this->_notifyUser($username, $message, $type, $noSppb);
        }
        return $this->_notificationSummary($results);
    }

    private function _notifyKabidUmum(string $noSppb, string $message): array
    {
        $sql = "SELECT DISTINCT r.username
              FROM rsns_custom_logistik_non_medis_user_roles r
              JOIN rsns_custom_logistik_non_medis_unit u
                ON FIND_IN_SET(u.kode_unit, REPLACE(r.kode_unit, ' ', '')) > 0
              WHERE r.role = 'kepala_bidang'
                AND LOWER(u.nama_unit) LIKE '%umum%'";
        $rows = $this->db()->pdo()->query($sql)->fetchAll(\PDO::FETCH_ASSOC);
        if (!$rows) {
            $rows = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('role', 'admin')->toArray();
        }
        $results = [];
        foreach ($rows as $row) {
            $username = trim((string)($row['username'] ?? ''));
            if ($username !== '') {
                $results[] = $this->_notifyUser($username, $message, 'konsul_kabid_umum', $noSppb);
            }
        }
        return $this->_notificationSummary($results);
    }

    private function _recordNotifierEvent(string $noSppb, string $kodeUnit)
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_notifier_event` (
          `id` bigint(20) NOT NULL AUTO_INCREMENT,
          `no_sppb` varchar(100) NOT NULL,
          `kode_unit` varchar(100) DEFAULT NULL,
          `tgl_dibuat` datetime NOT NULL,
          PRIMARY KEY (`id`),
          UNIQUE KEY `no_sppb` (`no_sppb`),
          KEY `tgl_dibuat` (`tgl_dibuat`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        $stmt = $this->db()->pdo()->prepare("INSERT IGNORE INTO rsns_custom_logistik_non_medis_notifier_event (no_sppb,kode_unit,tgl_dibuat) VALUES (?,?,NOW())");
        $stmt->execute([$noSppb, $kodeUnit]);
    }

    private function _canAccessRekapNonRutin(): bool
    {
        $username = $this->core->getUserInfo('username', null, true);
        if (!$username) {
            return false;
        }
        $roleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = strtolower((string)($roleData['role'] ?? 'unit'));
        if (in_array($role, ['admin', 'logistik'], true)) {
            return true;
        }
        if ($role !== 'kepala_bidang' || empty($roleData['kode_unit'])) {
            return false;
        }

        $unitKodes = array_values(array_filter(array_map('trim', explode(',', (string)$roleData['kode_unit']))));
        if (empty($unitKodes)) {
            return false;
        }
        $marks = implode(',', array_fill(0, count($unitKodes), '?'));
        $stmt = $this->db()->pdo()->prepare("SELECT COUNT(*) FROM rsns_custom_logistik_non_medis_unit WHERE kode_unit IN ($marks) AND LOWER(nama_unit) LIKE '%umum%'");
        $stmt->execute($unitKodes);
        return (int)$stmt->fetchColumn() > 0;
    }

    private function _ensureLogistikSetting(string $field, string $value)
    {
        $exists = $this->db('mlite_settings')->where('module', 'logistik_non_medis')->where('field', $field)->oneArray();
        if (!$exists) {
            $this->db('mlite_settings')->save([
              'module' => 'logistik_non_medis',
              'field' => $field,
              'value' => $value
            ]);
        }
    }

  /**
   * Kirim event realtime. Workerman selalu dicoba, Pusher aktif jika setting lengkap.
   * Polling database tetap menjadi fallback.
   */
    private function _broadcastNotification(array $notification)
    {
        $event = json_encode([
          'type' => 'logistik_notification',
          'target' => $notification['user_target'] ?? '',
          'tipe' => $notification['tipe'] ?? '',
          'pesan' => $notification['pesan'] ?? '',
          'url' => $notification['url'] ?? '',
          'id' => $notification['id'] ?? null,
          'time' => time()
        ]);
        if (!$event) {
            return;
        }

        $queue = BASE_DIR . '/tmp/logistik_notifications.queue';
        @file_put_contents($queue, $event . PHP_EOL, FILE_APPEND | LOCK_EX);

        $this->_triggerPusherNotification((array) json_decode($event, true));
        $this->_sendWebPushNotification($notification);
    }

    private function _sendWebPushNotification(array $notification)
    {
        if (!class_exists('Minishlink\\WebPush\\WebPush')) {
            return;
        }

        $target = trim((string)($notification['user_target'] ?? ''));
        if ($target === '') {
            return;
        }
        $publicKey = trim((string)$this->settings->get('logistik_non_medis.webpush_public_key'));
        $privateKey = trim((string)$this->settings->get('logistik_non_medis.webpush_private_key'));
        if ($publicKey === '' || $privateKey === '') {
            return;
        }

        $stmt = $this->db()->pdo()->prepare("SELECT * FROM rsns_custom_logistik_non_medis_push_subscription WHERE username=? AND aktif=1");
        $stmt->execute([$target]);
        $subscriptions = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        if (!$subscriptions) {
            return;
        }

        $payload = json_encode([
          'title' => 'Persetujuan Logistik RSU Nurusyifa',
          'body' => (string)($notification['pesan'] ?? 'Ada notifikasi logistik baru.'),
          'url' => (string)($notification['url'] ?? url(ADMIN . '/logistik_non_medis/distribusisppb')),
          'tag' => 'logistik-' . (string)($notification['tipe'] ?? 'notification'),
          'icon' => url('plugins/logistik_non_medis/public/rsunurussyifa-logo.png'),
          'badge' => url('plugins/logistik_non_medis/public/rsunurussyifa-logo.png')
        ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);

        try {
            $webPush = new \Minishlink\WebPush\WebPush([
              'VAPID' => [
                  'subject' => 'mailto:admin@rsunurussyifa.local',
                  'publicKey' => $publicKey,
                  'privateKey' => $privateKey
              ]
            ], ['TTL' => 259200, 'urgency' => 'high']);

            foreach ($subscriptions as $row) {
                try {
                    $subscription = \Minishlink\WebPush\Subscription::create([
                      'endpoint' => $row['endpoint'],
                      'publicKey' => $row['p256dh'],
                      'authToken' => $row['auth_token'],
                      'contentEncoding' => $row['content_encoding'] ?: 'aesgcm'
                    ]);
                    $report = $webPush->sendOneNotification($subscription, $payload);
                    if ($report && $report->isSuccess()) {
                          $this->db()->pdo()->prepare("UPDATE rsns_custom_logistik_non_medis_push_subscription SET terakhir_berhasil=NOW(), terakhir_error=NULL WHERE id=?")->execute([$row['id']]);
                    } else {
                        $reason = $report ? (string)$report->getReason() : 'Push gagal tanpa laporan.';
                        $this->db()->pdo()->prepare("UPDATE rsns_custom_logistik_non_medis_push_subscription SET terakhir_error=? WHERE id=?")->execute([$reason, $row['id']]);
                        if ($report && ($report->isSubscriptionExpired() || in_array($report->getResponse()->getStatusCode(), [404, 410], true))) {
                            $this->db()->pdo()->prepare("UPDATE rsns_custom_logistik_non_medis_push_subscription SET aktif=0 WHERE id=?")->execute([$row['id']]);
                        }
                    }
                } catch (\Throwable $e) {
                    $this->db()->pdo()->prepare("UPDATE rsns_custom_logistik_non_medis_push_subscription SET terakhir_error=? WHERE id=?")->execute([substr($e->getMessage(), 0, 500), $row['id']]);
                }
            }
        } catch (\Throwable $e) {
            error_log('Web Push Logistik: ' . $e->getMessage());
        }
    }

    private function _triggerPusherNotification(array $payload)
    {
        $mode = $this->settings->get('logistik_non_medis.notif_realtime');
        if ($mode !== 'pusher') {
            return;
        }

        $appId = trim((string) $this->settings->get('logistik_non_medis.pusher_app_id'));
        $key = trim((string) $this->settings->get('logistik_non_medis.pusher_key'));
        $secret = trim((string) $this->settings->get('logistik_non_medis.pusher_secret'));
        $cluster = trim((string) $this->settings->get('logistik_non_medis.pusher_cluster'));
        if ($appId === '' || $key === '' || $secret === '' || $cluster === '') {
            return;
        }

        $channel = 'logistik-' . preg_replace('/[^A-Za-z0-9_\\-]/', '_', (string) ($payload['target'] ?? 'general'));
        $eventName = 'logistik-notification';
        $body = json_encode([
          'name' => $eventName,
          'channel' => $channel,
          'data' => json_encode($payload)
        ]);
        if (!$body) {
            return;
        }

        $path = '/apps/' . rawurlencode($appId) . '/events';
        $query = [
          'auth_key' => $key,
          'auth_timestamp' => time(),
          'auth_version' => '1.0',
          'body_md5' => md5($body)
        ];
        ksort($query);
        $queryString = http_build_query($query, '', '&', PHP_QUERY_RFC3986);
        $signature = hash_hmac('sha256', "POST\n{$path}\n{$queryString}", $secret);
        $url = 'https://api-' . $cluster . '.pusher.com' . $path . '?' . $queryString . '&auth_signature=' . $signature;

        $ch = curl_init($url);
        curl_setopt_array($ch, [
          CURLOPT_POST => true,
          CURLOPT_POSTFIELDS => $body,
          CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
          CURLOPT_RETURNTRANSFER => true,
          CURLOPT_CONNECTTIMEOUT => 3,
          CURLOPT_TIMEOUT => 5
        ]);
        curl_exec($ch);
        curl_close($ch);
    }

    private function _initNotifikasi()
    {
        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_notifikasi` (
        `id` int(11) NOT NULL AUTO_INCREMENT,
        `user_target` varchar(100) NOT NULL,
        `pesan` text NOT NULL,
        `tipe` varchar(50) DEFAULT NULL,
        `url` varchar(255) DEFAULT NULL,
        `is_read` tinyint(1) NOT NULL DEFAULT 0,
        `tgl_dibuat` datetime NOT NULL,
        PRIMARY KEY (`id`),
        KEY `user_target` (`user_target`),
        KEY `is_read` (`is_read`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");

        $this->db()->pdo()->exec("CREATE TABLE IF NOT EXISTS `rsns_custom_logistik_non_medis_push_subscription` (
        `id` int(11) NOT NULL AUTO_INCREMENT,
        `username` varchar(100) NOT NULL,
        `endpoint` text NOT NULL,
        `endpoint_hash` char(64) NOT NULL,
        `p256dh` text NOT NULL,
        `auth_token` text NOT NULL,
        `content_encoding` varchar(30) NOT NULL DEFAULT 'aesgcm',
        `nama_perangkat` varchar(150) DEFAULT NULL,
        `user_agent` varchar(500) DEFAULT NULL,
        `aktif` tinyint(1) NOT NULL DEFAULT 1,
        `tgl_dibuat` datetime NOT NULL,
        `tgl_diperbarui` datetime NOT NULL,
        `terakhir_berhasil` datetime DEFAULT NULL,
        `terakhir_error` varchar(500) DEFAULT NULL,
        PRIMARY KEY (`id`),
        UNIQUE KEY `endpoint_hash` (`endpoint_hash`),
        KEY `username_aktif` (`username`,`aktif`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");

        $this->_ensureLogistikSetting('notif_realtime', 'workerman');
        $this->_ensureLogistikSetting('pusher_app_id', '');
        $this->_ensureLogistikSetting('pusher_key', '');
        $this->_ensureLogistikSetting('pusher_secret', '');
        $this->_ensureLogistikSetting('pusher_cluster', 'ap1');
        $this->_ensureLogistikSetting('webpush_public_key', '');
        $this->_ensureLogistikSetting('webpush_private_key', '');
        $publicKey = trim((string)$this->settings->get('logistik_non_medis.webpush_public_key'));
        $privateKey = trim((string)$this->settings->get('logistik_non_medis.webpush_private_key'));
        if (($publicKey === '' || $privateKey === '') && class_exists('Minishlink\\WebPush\\VAPID')) {
            try {
                $opensslConfig = dirname(PHP_BINARY) . '/extras/ssl/openssl.cnf';
                if (is_file($opensslConfig)) {
                    putenv('OPENSSL_CONF=' . $opensslConfig);
                }
                $keys = \Minishlink\WebPush\VAPID::createVapidKeys();
                $this->db('mlite_settings')->where('module', 'logistik_non_medis')->where('field', 'webpush_public_key')->update(['value' => $keys['publicKey']]);
                $this->db('mlite_settings')->where('module', 'logistik_non_medis')->where('field', 'webpush_private_key')->update(['value' => $keys['privateKey']]);
            } catch (\Throwable $e) {
                error_log('Gagal membuat VAPID key: ' . $e->getMessage());
            }
        }
    }

    private function _getNotificationTargets()
    {
        $username = $this->core->getUserInfo('username', null, true);
        $roleData = $this->db('rsns_custom_logistik_non_medis_user_roles')->where('username', $username)->oneArray();
        $role = strtolower($roleData['role'] ?? $this->core->getUserInfo('role', null, true));
        if (in_array($role, ['admin', 'logistik'], true)) {
            return ['ADMIN', $username];
        }

        $unitValue = $roleData['kode_unit'] ?? $this->core->getUserInfo('cap', null, true);
        $targets = array_values(array_filter(array_map('trim', explode(',', (string) $unitValue))));
        $targets[] = $username;
        return array_values(array_unique($targets ?: ['__NO_UNIT__']));
    }

