    public function postSimpanWebPush()
    {
        $this->_initNotifikasi();
        $username = (string)$this->core->getUserInfo('username', null, true);
        $raw = (string)($_POST['subscription'] ?? '');
        $data = json_decode($raw, true);
        $endpoint = trim((string)($data['endpoint'] ?? ''));
        $p256dh = trim((string)($data['keys']['p256dh'] ?? ''));
        $auth = trim((string)($data['keys']['auth'] ?? ''));
        if ($username === '' || $endpoint === '' || $p256dh === '' || $auth === '') {
            echo json_encode(['status' => 'error', 'message' => 'Subscription perangkat tidak valid.']);
            exit();
        }

        $encoding = trim((string)($data['contentEncoding'] ?? 'aesgcm')) ?: 'aesgcm';
        $device = trim((string)($_POST['nama_perangkat'] ?? 'Browser'));
        $hash = hash('sha256', $endpoint);
        $sql = "INSERT INTO rsns_custom_logistik_non_medis_push_subscription
          (username,endpoint,endpoint_hash,p256dh,auth_token,content_encoding,nama_perangkat,user_agent,aktif,tgl_dibuat,tgl_diperbarui)
          VALUES (?,?,?,?,?,?,?,?,1,NOW(),NOW())
          ON DUPLICATE KEY UPDATE username=VALUES(username),endpoint=VALUES(endpoint),p256dh=VALUES(p256dh),
          auth_token=VALUES(auth_token),content_encoding=VALUES(content_encoding),nama_perangkat=VALUES(nama_perangkat),
          user_agent=VALUES(user_agent),aktif=1,tgl_diperbarui=NOW(),terakhir_error=NULL";
        $this->db()->pdo()->prepare($sql)->execute([$username, $endpoint, $hash, $p256dh, $auth, $encoding, substr($device, 0, 150), substr($_SERVER['HTTP_USER_AGENT'] ?? '', 0, 500)]);
        echo json_encode(['status' => 'success', 'message' => 'Notifikasi perangkat berhasil diaktifkan.']);
        exit();
    }

    public function postHapusWebPush()
    {
        $this->_initNotifikasi();
        $username = (string)$this->core->getUserInfo('username', null, true);
        $endpoint = trim((string)($_POST['endpoint'] ?? ''));
        if ($endpoint !== '') {
            $this->db()->pdo()->prepare("UPDATE rsns_custom_logistik_non_medis_push_subscription SET aktif=0,tgl_diperbarui=NOW() WHERE username=? AND endpoint_hash=?")->execute([$username, hash('sha256', $endpoint)]);
        }
        echo json_encode(['status' => 'success', 'message' => 'Notifikasi perangkat dinonaktifkan.']);
        exit();
    }

